-- ===================== FACELESS LOG =====================
-- Тихая консоль + понятный лог ошибок: что сломалось, где, почему и как.
-- print молча уходит в лог; warn/error дедуплицируются — одна строка вместо спама.
-- На экране: счётчик LOG внизу справа, клик — панель с причинами.
local FLLog = { uiTried = false, entries = {}, seen = {}, max = 160, chip = nil, panel = nil, list = nil, toasts = {} }
local rawWarn = warn

local function flContainer()
    if gethui then local ok, hui = pcall(gethui); if ok and hui then return hui end end
    local ok, core = pcall(function() return game:GetService("CoreGui") end)
    if ok and core then return core end
    return LocalPlayer:WaitForChild("PlayerGui")
end

local KIND_COLOR = {
    error = Color3.fromRGB(255, 92, 92),
    warn = Color3.fromRGB(255, 176, 92),
    info = Color3.fromRGB(148, 170, 190),
}

local function flBuildUI()
    if FLLog.chip or FLLog.uiTried then return end
    FLLog.uiTried = true
    local ok, err = pcall(function()
        local sg = Instance.new("ScreenGui")
        sg.Name = "FaceLessLog"; sg.ResetOnSpawn = false; sg.IgnoreGuiInset = true; sg.DisplayOrder = 9999
        if not pcall(function() sg.Parent = flContainer() end) then sg.Parent = LocalPlayer:WaitForChild("PlayerGui") end
        local chip = Instance.new("TextButton")
        chip.Name = "LogChip"; chip.AnchorPoint = Vector2.new(1, 1)
        chip.Position = UDim2.new(1, -12, 1, -12); chip.Size = UDim2.fromOffset(64, 20)
        chip.BackgroundColor3 = Color3.fromRGB(24, 22, 26); chip.BackgroundTransparency = 0.25
        chip.BorderSizePixel = 0; chip.Font = Enum.Font.GothamBold; chip.TextSize = 10
        chip.TextColor3 = Color3.fromRGB(200, 205, 215); chip.Text = "LOG 0"; chip.AutoButtonColor = false
        chip.Parent = sg
        Instance.new("UICorner", chip).CornerRadius = UDim.new(0, 6)
        local panel = Instance.new("Frame")
        panel.Name = "LogPanel"; panel.AnchorPoint = Vector2.new(1, 1)
        panel.Position = UDim2.new(1, -12, 1, -38); panel.Size = UDim2.fromOffset(430, 240)
        panel.BackgroundColor3 = Color3.fromRGB(18, 16, 20); panel.BackgroundTransparency = 0.12
        panel.BorderSizePixel = 0; panel.Visible = false; panel.Parent = sg
        Instance.new("UICorner", panel).CornerRadius = UDim.new(0, 10)
        local head = Instance.new("TextLabel")
        head.BackgroundTransparency = 1; head.Position = UDim2.fromOffset(12, 6)
        head.Size = UDim2.new(1, -24, 0, 18); head.Font = Enum.Font.GothamBold; head.TextSize = 11
        head.TextColor3 = Color3.fromRGB(225, 215, 215); head.TextXAlignment = Enum.TextXAlignment.Left
        head.Text = "FACELESS LOG — ошибки и причины"; head.Parent = panel
        local list = Instance.new("ScrollingFrame")
        list.BackgroundTransparency = 1; list.Position = UDim2.fromOffset(8, 28)
        list.Size = UDim2.new(1, -16, 1, -36); list.ScrollBarThickness = 3
        list.ScrollBarImageColor3 = Color3.fromRGB(160, 60, 60)
        list.CanvasSize = UDim2.new(0, 0, 0, 0)
        list.Parent = panel
        local lay = Instance.new("UIListLayout", list)
        lay.Padding = UDim.new(0, 3); lay.SortOrder = Enum.SortOrder.LayoutOrder
        chip.MouseButton1Click:Connect(function()
            panel.Visible = not panel.Visible
            if panel.Visible then FLLog.refresh(true) end
        end)
        FLLog.chip, FLLog.panel, FLLog.list = chip, panel, list
    end)
    if not ok then FLLog.uiTried = false end
    if not ok and rawWarn then rawWarn("[FaceLess:LOG] UI не создан: " .. tostring(err)) end
end

function FLLog.refresh(full)
    if not FLLog.chip then return end
    pcall(function()
        local n = 0
        for _, e in ipairs(FLLog.entries) do if e.kind ~= "info" then n = n + 1 end end
        FLLog.chip.Text = "LOG " .. n
        FLLog.chip.TextColor3 = (n > 0) and Color3.fromRGB(255, 150, 130) or Color3.fromRGB(200, 205, 215)
        if not full or not FLLog.panel or not FLLog.panel.Visible then return end
        local list = FLLog.list
        list.CanvasSize = UDim2.new(0, 0, 0, #FLLog.entries * 32)
        for _, ch in ipairs(list:GetChildren()) do if ch:IsA("TextLabel") then ch:Destroy() end end
        for i = math.max(1, #FLLog.entries - 60), #FLLog.entries do
            local e = FLLog.entries[i]
            local lbl = Instance.new("TextLabel")
            lbl.BackgroundTransparency = 1; lbl.Size = UDim2.new(1, -8, 0, 28)
            lbl.Font = Enum.Font.Code; lbl.TextSize = 11
            lbl.TextWrapped = true; lbl.TextXAlignment = Enum.TextXAlignment.Left
            lbl.TextYAlignment = Enum.TextYAlignment.Top
            lbl.TextColor3 = KIND_COLOR[e.kind] or KIND_COLOR.info
            local rep = (e.n > 1) and ("  x" .. e.n) or ""
            lbl.Text = string.format("[%s] %s | %s%s%s", e.kind, e.where, e.why, (e.how ~= "" and (" | " .. e.how) or ""), rep)
            lbl.LayoutOrder = i; lbl.Parent = list
        end
    end)
end

local function flToast(e)
    if not FLLog.chip then return end
    pcall(function()
        local t = Instance.new("TextLabel")
        t.AnchorPoint = Vector2.new(1, 1)
        t.Position = UDim2.new(1, -12, 1, -44 - (#FLLog.toasts) * 26)
        t.Size = UDim2.fromOffset(340, 22)
        t.BackgroundColor3 = Color3.fromRGB(22, 18, 22); t.BackgroundTransparency = 0.2
        t.BorderSizePixel = 0; t.Font = Enum.Font.GothamMedium; t.TextSize = 11
        t.TextTruncate = Enum.TextTruncate.AtEnd; t.TextXAlignment = Enum.TextXAlignment.Left
        t.TextColor3 = KIND_COLOR[e.kind] or KIND_COLOR.info
        t.Text = "  " .. e.where .. " | " .. e.why
        t.Parent = FLLog.chip.Parent
        Instance.new("UICorner", t).CornerRadius = UDim.new(0, 6)
        table.insert(FLLog.toasts, t)
        task.delay(6, function()
            pcall(function() t:Destroy() end)
            for i, x in ipairs(FLLog.toasts) do if x == t then table.remove(FLLog.toasts, i); break end end
        end)
    end)
end

function FLLog.push(kind, where, why, how)
    local key = tostring(kind) .. "|" .. tostring(where):sub(1, 60) .. "|" .. tostring(why):sub(1, 60)
    local e = FLLog.seen[key]
    if e then
        e.n = e.n + 1
        if how and how ~= "" then e.how = tostring(how) end
        return e
    end
    e = {
        t = os.clock(), kind = tostring(kind), where = tostring(where),
        why = tostring(why), how = (how and how ~= "") and tostring(how) or "", n = 1,
    }
    FLLog.seen[key] = e
    table.insert(FLLog.entries, e)
    while #FLLog.entries > FLLog.max do table.remove(FLLog.entries, 1) end
    -- Тихая консоль: ничего не печатаем — ошибки видны в панели LOG и тостах.
    if e.kind ~= "info" and e.where ~= "runtime" then
        flToast(e)
    end
    if not FLLog.chip then flBuildUI() end
    FLLog.refresh(true)
    return e
end

function FLLog.info(where, what) return FLLog.push("info", where, what, "") end
function FLLog.announce(msg) if rawWarn then rawWarn(msg) end end

-- Тихие замены: print — только в лог, warn — дедуплицированно.
local function print(...)
    local parts = {}
    for i = 1, select("#", ...) do parts[#parts + 1] = tostring((select(i, ...))) end
    FLLog.push("info", "print", table.concat(parts, " "), "")
end
local function warn(...)
    local parts = {}
    for i = 1, select("#", ...) do parts[#parts + 1] = tostring((select(i, ...))) end
    FLLog.push("warn", "warn", table.concat(parts, " "), "")
end

-- Перехват runtime-ошибок: в лог падает сообщение и стек — видно, ГДЕ и ПОЧЕМУ.
pcall(function()
    local sc = game:GetService("ScriptContext")
    local ev = sc.Error
    if ev then
        ev:Connect(function(msg, stack)
            FLLog.push("error", "runtime", tostring(msg), tostring(stack):sub(1, 300))
        end)
    end
end)

function getParent()
    if gethui then local ok, hui = pcall(gethui); if ok and hui then return hui end end
    local ok, core = pcall(function() return game:GetService("CoreGui") end)
    if ok and core then return core end
    return LocalPlayer:WaitForChild("PlayerGui")
end

-- If this UI is executed again, clean the previous instance first. This prevents
-- duplicate RenderStepped/Heartbeat loops from silently halving FPS after reruns.
local RuntimeControl = {Environment = _G, CleanupCallbacks = {}}
do
    pcall(function()
        if type(getgenv) == "function" then
            local sharedEnv = getgenv()
            if type(sharedEnv) == "table" then RuntimeControl.Environment = sharedEnv end
        end
    end)
    local previous = RuntimeControl.Environment and RuntimeControl.Environment.__SATANIC_RUNTIME_CLEANUP
    if type(previous) == "function" then pcall(previous) end
end

