-- Registry for every stateful control. Configs store values by stable section/control keys;
-- applying a config runs each control's setter so feature callbacks and UI visuals stay in sync.
Theme.ConfigRegistry = {entries = {}, values = {}, pendingByLabel = {}, nextOrder = 0, applying = false, cleanupPending = false}
do
    local registry = Theme.ConfigRegistry
    function registry:MakeKey(scope, label, counts)
        counts[label] = (counts[label] or 0) + 1
        local n = counts[label]
        return tostring(scope) .. "::" .. tostring(label) .. "::" .. tostring(n), n
    end
    function registry:Register(key, label, kind, getter, setter, scope, occurrence)
        local entry = self.entries[key]
        -- Do not re-read a getter from a destroyed settings window here. Its closure can
        -- contain a stale value and overwrite a value just loaded from a config. Live UI
        -- changes are written to self.values by Store(); Capture() still samples live getters.
        if not entry then
            self.nextOrder = self.nextOrder + 1
            entry = {order = self.nextOrder}
        end
        entry.key, entry.label, entry.kind = key, label, kind
        entry.get, entry.set = getter, setter
        entry.scope, entry.occurrence = scope, occurrence or 1
        self.entries[key] = entry
        local pendingKey = tostring(scope) .. "::" .. tostring(label) .. "::" .. tostring(occurrence or 1)
        local wildcardKey = "*::" .. tostring(label) .. "::" .. tostring(occurrence or 1)
        local saved = self.values[key]
        if saved == nil then saved = self.pendingByLabel[pendingKey] end
        if saved == nil then saved = self.pendingByLabel[wildcardKey] end
        if saved ~= nil then
            self.values[key] = saved
            if type(setter) == "function" then pcall(setter, saved, true) end
        elseif type(getter) == "function" and self.values[key] == nil then
            -- Store defaults at creation time. Otherwise a settings window closed before
            -- the first click loses its default value because its getter becomes stale.
            local initialOk, initialValue = pcall(getter)
            if initialOk and initialValue ~= nil then self.values[key] = initialValue end
        end
        return entry
    end
    function registry:Store(key, value)
        if type(key) ~= "string" or value == nil then return end
        self.values[key] = value
    end

    function registry:Capture()
        local result = {}
        local controlList = {}
        for key, entry in pairs(self.entries) do
            local value = nil
            if type(entry.get) == "function" then
                local ok, currentValue = pcall(entry.get)
                if ok and currentValue ~= nil then value = currentValue end
            end
            -- Destroyed settings windows no longer have a live getter. In that case
            -- self.values is authoritative; don't overwrite it with a stale closure.
            if value == nil then value = self.values[key] end
            if value ~= nil then
                result[key] = value
                self.values[key] = value
                controlList[#controlList + 1] = {
                    key = key,
                    scope = entry.scope,
                    label = entry.label,
                    occurrence = entry.occurrence or 1,
                    kind = entry.kind,
                    value = value,
                }
            end
        end
        -- Keep saved values for controls in settings windows which are currently closed.
        for key, value in pairs(self.values) do
            if result[key] == nil and type(key) == "string" and string.sub(key, 1, 2) ~= "__" then
                result[key] = value
            end
        end
        table.sort(controlList, function(a, b)
            local as = tostring(a.scope) .. "::" .. tostring(a.label) .. "::" .. tostring(a.occurrence)
            local bs = tostring(b.scope) .. "::" .. tostring(b.label) .. "::" .. tostring(b.occurrence)
            return as < bs
        end)
        result.__controlList = controlList -- stable label/scope fallback across UI revisions
        if next(self.pendingByLabel) then result.__pendingLabels = self.pendingByLabel end
        return result
    end

    function registry:Apply(values)
        if type(values) ~= "table" then return end
        if type(values.__pendingLabels) == "table" then
            for key, value in pairs(values.__pendingLabels) do self.pendingByLabel[key] = value end
        end

        local incoming = {}
        -- Current schema: the direct key/value map. Ignore metadata tables as control values.
        for key, value in pairs(values) do
            if key ~= "__pendingLabels" and key ~= "__controlList" and type(key) == "string" then
                incoming[key] = value
                self.values[key] = value
            end
        end

        local function findEntry(saved)
            if type(saved) ~= "table" then return nil end
            if saved.key and self.entries[saved.key] then return self.entries[saved.key] end
            for _, entry in pairs(self.entries) do
                if entry.scope == saved.scope and entry.label == saved.label
                    and (entry.occurrence or 1) == (saved.occurrence or 1) then
                    return entry
                end
            end
            return nil
        end
        if type(values.__controlList) == "table" then
            for _, saved in ipairs(values.__controlList) do
                if type(saved) == "table" and saved.value ~= nil then
                    local entry = findEntry(saved)
                    if entry then
                        incoming[entry.key] = saved.value
                        self.values[entry.key] = saved.value
                    else
                        -- Keep values even when their setting panel has not been created yet.
                        if type(saved.key) == "string" then self.values[saved.key] = saved.value end
                        if saved.scope and saved.label then
                            local pendingKey = tostring(saved.scope) .. "::" .. tostring(saved.label) .. "::" .. tostring(saved.occurrence or 1)
                            self.pendingByLabel[pendingKey] = saved.value
                        end
                    end
                end
            end
        end

        local ordered = {}
        for key, entry in pairs(self.entries) do
            if incoming[key] ~= nil and type(entry.set) == "function" then
                ordered[#ordered + 1] = entry
            end
        end
        table.sort(ordered, function(a, b) return a.order < b.order end)
        local appliedCount = 0
        for _, entry in ipairs(ordered) do
            local ok, err = pcall(entry.set, incoming[entry.key], true)
            if ok then
                appliedCount = appliedCount + 1
            else
                warn("[Satanic Config] Failed to apply " .. tostring(entry.key) .. ": " .. tostring(err))
            end
        end
        return appliedCount
    end

    function registry:HasControlValue(values, label, scope, occurrence)
        if type(values) ~= "table" then return false end
        for key, entry in pairs(self.entries) do
            if entry.label == label and (scope == nil or entry.scope == scope)
                and (occurrence == nil or entry.occurrence == occurrence) and values[key] ~= nil then
                return true
            end
        end
        if type(values.__controlList) == "table" then
            for _, saved in ipairs(values.__controlList) do
                if type(saved) == "table" and saved.label == label
                    and (scope == nil or saved.scope == scope)
                    and (occurrence == nil or (saved.occurrence or 1) == occurrence)
                    and saved.value ~= nil then return true end
            end
        end
        return false
    end
    function registry:ApplyLabel(label, value, scope, occurrence)
        local matched = false
        for key, entry in pairs(self.entries) do
            if entry.label == label and (scope == nil or entry.scope == scope)
                and (occurrence == nil or entry.occurrence == occurrence) then
                self.values[key] = value
                if type(entry.set) == "function" then pcall(entry.set, value, true) end
                matched = true
            end
        end
        local exactScope = scope or "*"
        local suffix = tostring(label) .. "::" .. tostring(occurrence or 1)
        self.pendingByLabel[tostring(exactScope) .. "::" .. suffix] = value
        return matched
    end
end

local Connections = {}
