if old then old:Destroy() end

local ScreenGui = Instance.new("ScreenGui")
ScreenGui.Name = "SpringUI"
ScreenGui.ResetOnSpawn = false
ScreenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
ScreenGui.DisplayOrder = 999
ScreenGui.Parent = parent
do
local input = game:GetService("UserInputService")
local tweens = game:GetService("TweenService")


-- A single outline moves between controls. Click flashes reuse the same frame.
local outline = Instance.new("Frame")
outline.Name = "AuroraFeedback"
outline.BackgroundTransparency = 1
outline.BorderSizePixel = 0
outline.Size = UDim2.fromScale(1, 1)
outline.ZIndex = 100
outline.Active = false
local corner = Instance.new("UICorner", outline)
local stroke = Instance.new("UIStroke", outline)
stroke.Thickness = 1.5
stroke.Transparency = 0.35
local gradient = Instance.new("UIGradient", stroke)
gradient.Color = ColorSequence.new(Color3.fromRGB(103, 231, 255), Color3.fromRGB(192, 136, 255))
gradient.Rotation = 24
local target, flash
local function selectButton(button)
    if button == target then return end
    if flash then flash:Cancel() end
    target = button
    outline.Parent = button
    if button then
        local palette = Theme.Runtime and Theme.Runtime.GetPalette()
        if palette then gradient.Color = ColorSequence.new(palette.GradientA, palette.GradientB) end
        local shape = button:FindFirstChildOfClass("UICorner")
        corner.CornerRadius = shape and shape.CornerRadius or UDim.new(0, 0)
        stroke.Transparency = 0.35
        stroke.Thickness = 1.5
    end
end

local screenCleanup, removal, added
local wired = setmetatable({}, {__mode = "k"})
local function bind(screen)

    if screenCleanup then screenCleanup() end
    local function wire(button)
        if not button:IsA("GuiButton") or wired[button] then return end
        wired[button] = true
        button.SelectionGained:Connect(function() selectButton(button) end)
        button.SelectionLost:Connect(function() if target == button then selectButton(nil) end end)
        button.MouseEnter:Connect(function() selectButton(button) end)
        button.MouseLeave:Connect(function()
            if target == button then selectButton(nil) end
        end)
        button.Activated:Connect(function()
            selectButton(button)
            if flash then flash:Cancel() end
            stroke.Thickness = 3
            stroke.Transparency = 0
            local touch = input:GetLastInputType() == Enum.UserInputType.Touch
            flash = tweens:Create(stroke, TweenInfo.new(0.24, Enum.EasingStyle.Quad), {
                Thickness = 1.5, Transparency = touch and 1 or 0.35
            })
            flash:Play()
        end)
    end
    for _, child in screen:GetDescendants() do wire(child) end
    added = screen.DescendantAdded:Connect(wire)
    removal = screen.DescendantRemoving:Connect(function(child)
        if child == target then selectButton(nil) end
    end)
    screenCleanup = function()
        added:Disconnect()
        removal:Disconnect()
        selectButton(nil)
    end
end
bind(ScreenGui)
end


