    if startupInitializationComplete or Unloaded then return end
    pcall(function()
        local liveGui = parent and parent:FindFirstChild("SpringUI")
        local mainWindow = liveGui and liveGui:FindFirstChild("Main")
        if mainWindow and mainWindow:IsA("GuiObject") then
            mainWindow.Visible = true
            mainWindow.Active = true
        end
        if blur and blur.Parent then blur.Size = 0 end
    end)
    warn("[Satanic UI] Startup did not finish; fallback cleared the blur. Check the executor/Roblox console for the first error.")
end)

