-- Shared vector brand emblem: a fine pentagram within a cut-corner frame.
-- No external images; every accent follows the current theme.
Theme.MakeBrandMark = function(parent, size, z)
    local function segment(x1, y1, x2, y2, width, transparency)
        local a, b = Vector2.new(x1 * size, y1 * size), Vector2.new(x2 * size, y2 * size)
        local d = b - a
        local line = Instance.new("Frame")
        line.Name = "FaceLessMark"
        line.BorderSizePixel = 0
        line.BackgroundColor3 = Theme.BloodRed
        line.BackgroundTransparency = transparency or 0
        line.AnchorPoint = Vector2.new(0.5, 0.5)
        line.Position = UDim2.fromOffset((a.X+b.X)/2, (a.Y+b.Y)/2)
        line.Size = UDim2.fromOffset(d.Magnitude, width)
        line.Rotation = math.deg(math.atan2(d.Y, d.X))
        line.ZIndex = z
        line.Parent = parent
    end
    -- Inset corner marks give the symbol a technical frame without a heavy circle.
    local corners = {{.14,.28,.14,.16},{.14,.16,.27,.16},{.73,.16,.86,.16},{.86,.16,.86,.28},
        {.14,.72,.14,.84},{.14,.84,.27,.84},{.73,.84,.86,.84},{.86,.72,.86,.84}}
    for _, p in ipairs(corners) do segment(p[1],p[2],p[3],p[4],1,0.35) end
    local points = {}
    for i = 0, 4 do
        local a = math.rad(-90 + i*72)
        points[i+1] = {0.5 + math.cos(a)*0.30, 0.5 + math.sin(a)*0.30}
    end
    for i = 1, 5 do
        local a, b = points[i], points[(i+1)%5+1]
        segment(a[1],a[2],b[1],b[2],1.25,0.03)
    end
end
