    if wmDragging and input.UserInputType == Enum.UserInputType.MouseMovement and wmDragStart and wmStartPosition then
        local delta = input.Position - wmDragStart
        local vp = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1920, 1080)
        local x = math.clamp(wmStartPosition.X.Offset + delta.X, 0, math.max(0, vp.X - Watermark.AbsoluteSize.X))
        local y = math.clamp(wmStartPosition.Y.Offset + delta.Y, 0, math.max(0, vp.Y - Watermark.AbsoluteSize.Y))
        Watermark.Position = UDim2.new(0, x, 0, y)
    end
end))

local fpsVal = 0; local pingVal = nil; local frameCount = 0; local lastTime = tick()
function wmRefresh()
    local pieces = {}
    if wmShowFPS then table.insert(pieces, tostring(fpsVal) .. " FPS") end
    if wmShowClock then table.insert(pieces, os.date("%H:%M")) end
    if wmShowPing then table.insert(pieces, (pingVal and tostring(pingVal) or "—") .. " MS") end
    local txt = table.concat(pieces, "  ·  ")
    wmInfo.Text = txt
    wmSignal.Visible = wmShowSignal
    Watermark.BackgroundColor3 = wmBackgroundColor
    wmStroke.Color = wmOutlineColor
    wmStroke.Transparency = wmOutlineTransparency
    wmStroke.Thickness = wmOutlineThickness
    local w = TextService:GetTextSize(txt, 11, Enum.Font.GothamMedium, Vector2.new(1000, 40)).X
    wmInfo.Size = UDim2.new(0, math.max(0, w + 8), 1, 0)
    Watermark.Size = UDim2.new(0, math.clamp(126 + w + (wmShowSignal and 37 or 12), 190, 330), 0, 40)
    for _, mark in ipairs(wmIconBox:GetChildren()) do
        if mark:IsA("Frame") and mark.Name == "FaceLessMark" then mark.BackgroundColor3 = Theme.BloodRed end
    end
    wmIconStroke.Color = Theme.BloodRed
end
wmRefresh()

track(RunService.RenderStepped:Connect(function()
    frameCount = frameCount + 1
    local now = tick()
    if now - lastTime >= 1 then
        fpsVal = math.floor(frameCount / (now - lastTime))
        pcall(function() local pingStat = Stats.Network.ServerStatsItem["Data Ping"]; if pingStat then pingVal = math.floor(pingStat:GetValue()) end end)
        wmRefresh(); frameCount = 0; lastTime = now
    end
end))

