do
    -- Responsive sizing: keep the full rounded border inside the viewport, including after resize.
    local function updateMainScale()
        local cameraForScale = workspace.CurrentCamera
        if not cameraForScale then return end
        local viewport = cameraForScale.ViewportSize
        uiScale.Scale = math.clamp(math.min((viewport.X - 32) / 1050, (viewport.Y - 32) / 690, 1), 0.25, 1)
    end
    local viewportConnection
    local function watchCamera()
        if viewportConnection then viewportConnection:Disconnect(); viewportConnection = nil end
        local current = workspace.CurrentCamera
        if current then viewportConnection = current:GetPropertyChangedSignal("ViewportSize"):Connect(updateMainScale) end
        updateMainScale()
    end
    watchCamera()
    track(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(watchCamera))
    registerCleanup(function() if viewportConnection then viewportConnection:Disconnect() end end)
end
