-- ================= CYBERPUNK NEON BACKGROUND =================
-- Lightweight procedural grid, drifting neon traces and a scanning beam; no character/figure silhouettes.
-- All objects are created once; the animation loop only updates existing instances.
Theme.BgBats = {}

do
    local cyberAccumulator = 0
    track(RunService.RenderStepped:Connect(function(dt)
        if Unloaded then return end
        local list = Theme.BgBats
        if #list == 0 then return end
        cyberAccumulator = cyberAccumulator + dt
        if cyberAccumulator < (1 / 24) then return end
        local step = math.min(cyberAccumulator, 0.08)
        cyberAccumulator = 0
        local now = os.clock()
        for i = #list, 1, -1 do
            local item = list[i]
            local obj = item.object
            if not obj or not obj.Parent then
                table.remove(list, i)
            elseif item.root ~= Main or Main.Visible then
                if item.kind == "trace" then
                    item.x = item.x + item.vx * step
                    if item.x > 1.08 then item.x = -0.14 end
                    obj.Position = UDim2.new(item.x, 0,
                        item.y + math.sin(now * 1.4 + item.phase) * 0.012, 0)
                    obj.BackgroundTransparency = 0.25 + 0.18 * (0.5 + 0.5 * math.sin(now * 2 + item.phase))
                elseif item.kind == "node" then
                    local pulse = 0.5 + 0.5 * math.sin(now * 2.2 + item.phase)
                    obj.Position = UDim2.new(item.x + math.sin(now * 0.45 + item.phase) * 0.006, 0,
                        item.y + math.sin(now * 0.8 + item.phase) * 0.012, 0)
                    obj.BackgroundTransparency = 0.22 + pulse * 0.52
                elseif item.kind == "scan" then
                    obj.Position = UDim2.new(0, 0, (now * 0.055) % 1, 0)
                    obj.BackgroundTransparency = 0.56 + 0.18 * math.sin(now * 1.8)
                end
            end
        end
    end))
end
-- Traceless: no grid, scanlines or cyberpunk background.

