    local closeBtn = Instance.new("TextButton", topBar); closeBtn.Size = UDim2.new(0, 28, 0, 28); closeBtn.Position = UDim2.new(1, -34, 0.5, -14); closeBtn.BackgroundColor3 = Theme.Element; closeBtn.Text = "X"; closeBtn.Font = Enum.Font.GothamBold; closeBtn.TextSize = 12; closeBtn.TextColor3 = Theme.Text; closeBtn.ZIndex = 102
    Instance.new("UICorner", closeBtn).CornerRadius = UDim.new(0, 6)
    
    local container = Instance.new("ScrollingFrame", win); container.Size = UDim2.new(1, -28, 1, -80); container.Position = UDim2.new(0, 14, 0, 68); container.BackgroundTransparency = 1; container.BorderSizePixel = 0; container.ScrollBarThickness = 3; container.ScrollBarImageColor3 = Theme.BloodRed; container.ZIndex = 101
    local listLayout = Instance.new("UIListLayout", container); listLayout.Padding = UDim.new(0, 8); listLayout.SortOrder = Enum.SortOrder.LayoutOrder
    track(listLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function() container.CanvasSize = UDim2.new(0, 0, 0, listLayout.AbsoluteContentSize.Y + 20) end))
    
