    function SetAPI:AddToggle(text, default, callback)
        local row = Instance.new("Frame", container); row.Size = UDim2.new(1, 0, 0, 26); row.BackgroundTransparency = 1; row.ZIndex = 102
        local lbl = Instance.new("TextLabel", row); lbl.Size = UDim2.new(1, -45, 1, 0); lbl.BackgroundTransparency = 1; lbl.Text = text; lbl.Font = Enum.Font.GothamMedium; lbl.TextSize = 12; lbl.TextColor3 = Theme.Text; lbl.TextXAlignment = Enum.TextXAlignment.Left; lbl.ZIndex = 102
        local state = default == true
        local btn = Instance.new("TextButton", row); btn.Size = UDim2.new(0, 36, 0, 18); btn.Position = UDim2.new(1, -36, 0.5, -9); btn.BackgroundColor3 = state and Theme.BloodRed or Theme.Element; btn.Text = ""; btn.AutoButtonColor = false; btn.ZIndex = 102
        Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 5)
        local btnStroke = Instance.new("UIStroke", btn); btnStroke.Color = state and Theme.BloodGlow or Theme.Stroke; btnStroke.Thickness = 1
        local knob = Instance.new("Frame", btn); knob.Size = UDim2.new(0, 12, 0, 12); knob.Position = state and UDim2.new(1, -15, 0.5, -6) or UDim2.new(0, 3, 0.5, -6); knob.BackgroundColor3 = state and Color3.fromRGB(255, 255, 255) or Theme.TextDark; knob.BorderSizePixel = 0; knob.ZIndex = 103
        Instance.new("UICorner", knob).CornerRadius = UDim.new(1, 0)
        local function render()
            TweenService:Create(btn, TweenInfo.new(0.15), {BackgroundColor3 = state and Theme.BloodRed or Theme.Element}):Play()
            TweenService:Create(btnStroke, TweenInfo.new(0.15), {Color = state and Theme.BloodGlow or Theme.Stroke}):Play()
            TweenService:Create(knob, TweenInfo.new(0.15), {Position = state and UDim2.new(1, -15, 0.5, -6) or UDim2.new(0, 3, 0.5, -6), BackgroundColor3 = state and Color3.fromRGB(255, 255, 255) or Theme.TextDark}):Play()
        end
        local key, occurrence
        local function setState(value)
            state = (value == true); render()
            if key then Theme.ConfigRegistry:Store(key, state) end
            if callback then pcall(callback, state) end
        end
        track(btn.MouseButton1Click:Connect(function() setState(not state) end))
        key, occurrence = makeSettingConfigKey(text)
        if key then Theme.ConfigRegistry:Register(key, text, "toggle", function()
            if not row.Parent or not row:IsDescendantOf(ScreenGui) then return nil end
            return state
        end,
            function(value) setState(type(value) == "table" and value.enabled == true or value == true) end,
            settingScope, occurrence) end
        return {Set = setState, Get = function() return state end}
    end
