    function SetAPI:AddSlider(text, min, max, default, callback, step)
        step = step or 1
        local frame = Instance.new("Frame", container); frame.Size = UDim2.new(1, 0, 0, 36); frame.BackgroundTransparency = 1; frame.ZIndex = 102
        local lbl = Instance.new("TextLabel", frame); lbl.Size = UDim2.new(1, -50, 0, 16); lbl.BackgroundTransparency = 1; lbl.Text = text; lbl.Font = Enum.Font.GothamMedium; lbl.TextSize = 12; lbl.TextColor3 = Theme.Text; lbl.TextXAlignment = Enum.TextXAlignment.Left; lbl.ZIndex = 102
        local valLbl = Instance.new("TextLabel", frame); valLbl.Size = UDim2.new(0, 50, 0, 16); valLbl.Position = UDim2.new(1, -50, 0, 0); valLbl.BackgroundTransparency = 1; valLbl.Text = string.format("%g", default); valLbl.Font = Enum.Font.GothamMedium; valLbl.TextSize = 12; valLbl.TextColor3 = Theme.TextDark; valLbl.TextXAlignment = Enum.TextXAlignment.Right; valLbl.ZIndex = 102
        local sliderBg = Instance.new("Frame", frame); sliderBg.Size = UDim2.new(1, 0, 0, 6); sliderBg.Position = UDim2.new(0, 0, 0, 22); sliderBg.BackgroundColor3 = Theme.Element; sliderBg.BorderSizePixel = 0; sliderBg.ZIndex = 102
        Instance.new("UICorner", sliderBg).CornerRadius = UDim.new(0, 3)
        local fill = Instance.new("Frame", sliderBg); fill.Size = UDim2.new(math.clamp((default - min) / math.max(max - min, 1e-6), 0, 1), 0, 1, 0); fill.BackgroundColor3 = Theme.BloodRed; fill.BorderSizePixel = 0; fill.ZIndex = 103
        Instance.new("UICorner", fill).CornerRadius = UDim.new(0, 3)
        local dragging = false; local last = default
        local dragStartX, startFraction, bgW = 0, (default - min) / math.max(max - min, 1e-6), 0
        local key, occurrence
        local function setValue(value, force)
            local numeric = tonumber(value)
            if not numeric then return end
            local steps = math.floor((numeric - min) / step + 0.5)
            local val = math.clamp(min + steps * step, min, max)
            local pos = math.clamp((val - min) / math.max(max - min, 1e-6), 0, 1)
            fill.Size = UDim2.new(pos, 0, 1, 0); valLbl.Text = string.format("%g", val)
            local changed = math.abs(val - last) > 1e-6
            last = val
            if key then Theme.ConfigRegistry:Store(key, last) end
            if (changed or force) and callback then pcall(callback, val) end
        end
        local function setFromPos(pos) setValue(min + (max - min) * math.clamp(pos, 0, 1), false) end
        track(sliderBg.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true; dragStartX = input.Position.X; bgW = math.max(sliderBg.AbsoluteSize.X, 1)
                startFraction = math.clamp((input.Position.X - sliderBg.AbsolutePosition.X) / bgW, 0, 1)
                setFromPos(startFraction)
            end
        end))
        track(UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then dragging = false end
        end))
        track(UserInputService.InputChanged:Connect(function(input)
            if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                setFromPos(math.clamp(startFraction + (input.Position.X - dragStartX) / bgW, 0, 1))
            end
        end))
        key, occurrence = makeSettingConfigKey(text)
        if key then Theme.ConfigRegistry:Register(key, text, "slider", function()
            if not frame.Parent or not frame:IsDescendantOf(ScreenGui) then return nil end
            return last
        end,
            function(value) setValue(value, true) end, settingScope, occurrence) end
        return {Set = function(value) setValue(value, true) end, Get = function() return last end}
    end
    function SetAPI:AddColorPicker(h, s, v, callback)
        local H, S, V = h, s, v
        local SQ_H = 142
        local holder = Instance.new("Frame", container)
        holder.Size = UDim2.new(1, 0, 0, SQ_H + 8 + 14 + 8 + 24)
        holder.BackgroundTransparency = 1; holder.ZIndex = 102

        -- квадрат: слева белый, справа чистый оттенок, снизу чёрный
        local sq = Instance.new("Frame", holder)
        sq.Size = UDim2.new(1, 0, 0, SQ_H); sq.BorderSizePixel = 0; sq.ZIndex = 102
        sq.BackgroundColor3 = Color3.fromHSV(H, 1, 1)
        Instance.new("UICorner", sq).CornerRadius = UDim.new(0, 6)
        local sqStroke = Instance.new("UIStroke", sq); sqStroke.Color = Theme.Stroke; sqStroke.Thickness = 1

        local whiteLayer = Instance.new("Frame", sq)
        whiteLayer.Size = UDim2.new(1, 0, 1, 0); whiteLayer.BorderSizePixel = 0; whiteLayer.ZIndex = 103
        whiteLayer.BackgroundColor3 = Color3.new(1, 1, 1)
        Instance.new("UICorner", whiteLayer).CornerRadius = UDim.new(0, 6)
        local wg = Instance.new("UIGradient", whiteLayer)
        wg.Transparency = NumberSequence.new{NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1)}

        local blackLayer = Instance.new("Frame", sq)
        blackLayer.Size = UDim2.new(1, 0, 1, 0); blackLayer.BorderSizePixel = 0; blackLayer.ZIndex = 104
        blackLayer.BackgroundColor3 = Color3.new(0, 0, 0)
        Instance.new("UICorner", blackLayer).CornerRadius = UDim.new(0, 6)
        local bgGrad = Instance.new("UIGradient", blackLayer)
        bgGrad.Rotation = 90
        bgGrad.Transparency = NumberSequence.new{NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0)}

        local marker = Instance.new("Frame", sq)
        marker.Size = UDim2.new(0, 14, 0, 14); marker.AnchorPoint = Vector2.new(0.5, 0.5)
        marker.BackgroundTransparency = 1; marker.ZIndex = 106
        Instance.new("UICorner", marker).CornerRadius = UDim.new(1, 0)
        local mOuter = Instance.new("UIStroke", marker); mOuter.Color = Color3.new(0, 0, 0); mOuter.Thickness = 3
        local markerIn = Instance.new("Frame", marker)
        markerIn.Size = UDim2.new(1, 0, 1, 0); markerIn.BackgroundTransparency = 1; markerIn.ZIndex = 107
        Instance.new("UICorner", markerIn).CornerRadius = UDim.new(1, 0)
        local mInner = Instance.new("UIStroke", markerIn); mInner.Color = Color3.new(1, 1, 1); mInner.Thickness = 1.5

        -- полоса оттенка (радуга) и ползунок
        local hueBar = Instance.new("Frame", holder)
        hueBar.Position = UDim2.new(0, 0, 0, SQ_H + 8); hueBar.Size = UDim2.new(1, 0, 0, 14)
        hueBar.BorderSizePixel = 0; hueBar.ZIndex = 102; hueBar.BackgroundColor3 = Color3.new(1, 1, 1)
        Instance.new("UICorner", hueBar).CornerRadius = UDim.new(0, 5)
        local hg = Instance.new("UIGradient", hueBar)
        hg.Color = ColorSequence.new{
            ColorSequenceKeypoint.new(0,     Color3.fromHSV(0, 1, 1)),
            ColorSequenceKeypoint.new(1 / 6, Color3.fromHSV(1 / 6, 1, 1)),
            ColorSequenceKeypoint.new(2 / 6, Color3.fromHSV(2 / 6, 1, 1)),
            ColorSequenceKeypoint.new(3 / 6, Color3.fromHSV(3 / 6, 1, 1)),
            ColorSequenceKeypoint.new(4 / 6, Color3.fromHSV(4 / 6, 1, 1)),
            ColorSequenceKeypoint.new(5 / 6, Color3.fromHSV(5 / 6, 1, 1)),
            ColorSequenceKeypoint.new(1,     Color3.fromHSV(0, 1, 1)),
        }
        local knob = Instance.new("Frame", hueBar)
        knob.Size = UDim2.new(0, 6, 1, 8); knob.AnchorPoint = Vector2.new(0.5, 0.5)
        knob.BackgroundColor3 = Color3.new(1, 1, 1); knob.BorderSizePixel = 0; knob.ZIndex = 103
        Instance.new("UICorner", knob).CornerRadius = UDim.new(0, 3)
        local knobStroke = Instance.new("UIStroke", knob); knobStroke.Color = Color3.new(0, 0, 0); knobStroke.Thickness = 1

        -- превью выбранного цвета
        local previewY = SQ_H + 8 + 14 + 8
        local preview = Instance.new("Frame", holder)
        preview.Position = UDim2.new(0, 0, 0, previewY); preview.Size = UDim2.new(0, 44, 0, 24)
        preview.BorderSizePixel = 0; preview.ZIndex = 102
        Instance.new("UICorner", preview).CornerRadius = UDim.new(0, 5)
        local pStroke = Instance.new("UIStroke", preview); pStroke.Color = Theme.Stroke; pStroke.Thickness = 1
        local hexLbl = Instance.new("TextLabel", holder)
        hexLbl.Position = UDim2.new(0, 52, 0, previewY); hexLbl.Size = UDim2.new(1, -52, 0, 24)
        hexLbl.BackgroundTransparency = 1; hexLbl.Font = Enum.Font.GothamMedium; hexLbl.TextSize = 12
        hexLbl.TextColor3 = Theme.Text; hexLbl.TextXAlignment = Enum.TextXAlignment.Left; hexLbl.ZIndex = 102

        local function refresh()
            local c = Color3.fromHSV(H, S, V)
            sq.BackgroundColor3 = Color3.fromHSV(H, 1, 1)
            marker.Position = UDim2.new(S, 0, 1 - V, 0)
            knob.Position = UDim2.new(H, 0, 0.5, 0)
            preview.BackgroundColor3 = c
            local r, g, b = math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5)
            hexLbl.Text = string.format("#%02X%02X%02X   (%d, %d, %d)", r, g, b, r, g, b)
        end
        refresh()

        local key, occurrence
        local function fire()
            if key then Theme.ConfigRegistry:Store(key, {H, S, V}) end
            if callback then pcall(callback, H, S, V) end
        end
        local function pressed(input)
            return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
        end
        local function moved(input)
            return input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch
        end
        local function setFromSquare(pos)
            S = math.clamp((pos.X - sq.AbsolutePosition.X) / math.max(sq.AbsoluteSize.X, 1), 0, 1)
            V = 1 - math.clamp((pos.Y - sq.AbsolutePosition.Y) / math.max(sq.AbsoluteSize.Y, 1), 0, 1)
            refresh(); fire()
        end
        local function setFromHue(pos)
            H = math.clamp((pos.X - hueBar.AbsolutePosition.X) / math.max(hueBar.AbsoluteSize.X, 1), 0, 0.999)
            refresh(); fire()
        end
        local function setHSV(nh, ns, nv, invokeCallback)
            H = math.clamp(tonumber(nh) or H, 0, 0.999)
            S = math.clamp(tonumber(ns) or S, 0, 1)
            V = math.clamp(tonumber(nv) or V, 0, 1)
            refresh()
            if invokeCallback then fire() end
        end

        local mode = nil
        track(sq.InputBegan:Connect(function(input)
            if pressed(input) then mode = "sq"; setFromSquare(input.Position) end
        end))
        track(hueBar.InputBegan:Connect(function(input)
            if pressed(input) then mode = "hue"; setFromHue(input.Position) end
        end))

        local conns = {}
        local function alive()
            if holder.Parent and holder:IsDescendantOf(ScreenGui) then return true end
            for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
            conns = {}
            return false
        end
        conns[#conns + 1] = track(UserInputService.InputChanged:Connect(function(input)
            if not mode or not moved(input) or not alive() then return end
            if mode == "sq" then setFromSquare(input.Position) else setFromHue(input.Position) end
        end))
        conns[#conns + 1] = track(UserInputService.InputEnded:Connect(function(input)
            if pressed(input) then mode = nil end
        end))

        key, occurrence = makeSettingConfigKey("Color Picker")
        if key then Theme.ConfigRegistry:Register(key, "Color Picker", "color3hsv", function()
            if not holder.Parent or not holder:IsDescendantOf(ScreenGui) then return nil end
            return {H, S, V}
        end,
            function(value)
                if type(value) == "table" then setHSV(value[1] or value.h, value[2] or value.s, value[3] or value.v, true) end
            end, settingScope, occurrence) end
        return {
            Set = function(nh, ns, nv) setHSV(nh, ns, nv, false) end,
            Get = function() return H, S, V end,
            Alive = alive,
        }
    end

    if builderFunc then
        local registry = Theme.ConfigRegistry
        local wasApplying = registry.applying
        registry.applying = true
        local okB, errB = pcall(builderFunc, SetAPI)
        registry.applying = wasApplying
        if not okB then warn("[Halloween UI] settings window error: " .. tostring(errB)) end
        if not wasApplying and registry.cleanupPending then
            registry.cleanupPending = false
            task.defer(function()
                if registry.FlushCleanup then registry.FlushCleanup() end
            end)
        end
    end
    if Theme.Runtime then
        if Theme.Runtime.Decorate then pcall(Theme.Runtime.Decorate, win) end
        if Theme.Runtime.Rebuild then pcall(Theme.Runtime.Rebuild) end
        if Theme.Runtime.AfterSettingsBuild then pcall(Theme.Runtime.AfterSettingsBuild) end
    end
    track(closeBtn.MouseButton1Click:Connect(function() win:Destroy(); activeSettingsWindow = nil end))
end

