        thumb.BackgroundTransparency = 0.15
        thumb.BorderSizePixel = 0
        thumb.ZIndex = 61

        Nav.cardWidth = math.max(240, math.floor((Main.Size.X.Offset - 30) / 2))
        Nav.pager = { rail = rail, thumb = thumb }

        local function currentPage()
            local pg = ActiveTab and Tabs[ActiveTab]
            if not pg or not pg.Visible then return nil end
            if pg:GetAttribute("FullWidthColumns") == true or pg.Name == "Themes" or pg.Name == "Configs" then return nil end
            return pg
        end
        local function maxScrollX(pg)
            return math.max(0, pg.CanvasSize.X.Offset - pg.AbsoluteSize.X)
        end

        -- МАКСИМАЛЬНО плавный «перелёт» по одному холсту.
        -- 1) Желаемая позиция от колеса.
        -- 2) Цель плавно догоняет её (первое сглаживание).
        -- 3) CanvasPosition идёт к цели критически затухающим SmoothDamp (второе).
        local scrollWantedX = nil
        local scrollTargetX = nil
        local scrollVel = 0
        local SMOOTH_TIME = 0.55
        local TARGET_EASE = 0.16
        local WHEEL_STEP = 120
        Nav.cancelPager = function()
            scrollWantedX = nil
            scrollTargetX = nil
            scrollVel = 0
        end
        local function nudge(delta)
            local pg = currentPage()
            if not pg then return end
            local maxX = maxScrollX(pg)
            if maxX <= 1 then return end
            local base = scrollWantedX or pg.CanvasPosition.X
            scrollWantedX = math.clamp(base + delta, 0, maxX)
        end
        track(RunService.RenderStepped:Connect(function(dt)
            if scrollWantedX == nil then return end
            local pg = currentPage()
            if not pg or not Main.Visible then Nav.cancelPager(); return end
            local maxX = maxScrollX(pg)
            if maxX <= 1 then Nav.cancelPager(); return end
            scrollWantedX = math.clamp(scrollWantedX, 0, maxX)
            local step = math.min(math.max(dt, 0.001), 0.05)
            local x, y = pg.CanvasPosition.X, pg.CanvasPosition.Y
            if scrollTargetX == nil then scrollTargetX = x end
            scrollTargetX = scrollTargetX + (scrollWantedX - scrollTargetX) * (1 - math.exp(-step / TARGET_EASE))
            local omega = 2 / SMOOTH_TIME
            local xx = omega * step
            local expo = 1 / (1 + xx + 0.48 * xx * xx + 0.235 * xx * xx * xx)
            local change = x - scrollTargetX
            local temp = (scrollVel + omega * change) * step
            scrollVel = (scrollVel - omega * temp) * expo
            local nx = scrollTargetX + (change + temp) * expo
            if math.abs(scrollWantedX - nx) < 0.3 and math.abs(scrollVel) < 1.5 then
                pg.CanvasPosition = Vector2.new(scrollWantedX, y)
                Nav.cancelPager()
                return
            end
            nx = math.clamp(nx, 0, maxX)
            if nx <= 0 or nx >= maxX then scrollVel = 0 end
            pg.CanvasPosition = Vector2.new(nx, y)
        end))

        Nav.updateContentPager = function()
            local ui = Nav.pager
            if not ui then return end
            local pg = currentPage()
            if not pg or not Main.Visible then ui.rail.Visible = false; return end
            local maxX = maxScrollX(pg)
            if maxX <= 1 then ui.rail.Visible = false; return end
            ui.rail.Visible = true
            local viewW = math.max(1, pg.AbsoluteSize.X)
            local totalW = math.max(viewW, pg.CanvasSize.X.Offset)
            local frac = math.clamp(viewW / totalW, 0.12, 1)
            ui.thumb.Size = UDim2.new(frac, 0, 1, 0)
            ui.thumb.Position = UDim2.new((1 - frac) * math.clamp(pg.CanvasPosition.X / maxX, 0, 1), 0, 0, 0)
        end

        -- Колесо только добавляет импульс к общему «перелёту». ПКМ по функции
        -- по-прежнему открывает openSettingsWindow и нигде не перехватывается.
        track(UserInputService.InputChanged:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseWheel then return end
            if not Main.Visible then return end
            local page = currentPage()
            if not page then return end
            local m = UserInputService:GetMouseLocation()
            local ap, as = content.AbsolutePosition, content.AbsoluteSize
            if m.X < ap.X or m.X > ap.X + as.X or m.Y < ap.Y or m.Y > ap.Y + as.Y then return end
            if activeSettingsWindow and activeSettingsWindow.Parent then
                local p, size = activeSettingsWindow.AbsolutePosition, activeSettingsWindow.AbsoluteSize
                if m.X >= p.X and m.X <= p.X + size.X and m.Y >= p.Y and m.Y <= p.Y + size.Y then return end
            end
            local dropdowns = Theme.OpenDropdownScrollLists
            if dropdowns then
                for list in pairs(dropdowns) do
                    if list.Parent and list.Visible and list:IsDescendantOf(page) then
                        local p, size = list.AbsolutePosition, list.AbsoluteSize
                        if m.X >= p.X and m.X <= p.X + size.X and m.Y >= p.Y and m.Y <= p.Y + size.Y then return end
                    end
                end
            end
            if page.ScrollingDirection == Enum.ScrollingDirection.Y then return end
            local z = -input.Position.Z
            if z == 0 then return end
            nudge(math.clamp(z, -1, 1) * WHEEL_STEP)
        end))
    end

