                ref.btn.AnchorPoint = Vector2.new(0, 0.5)
                ref.btn.Size = UDim2.new(0, cell, 0, 36)
                ref.btn.Position = UDim2.new(0, x0 + (i - 1) * (cell + gap), 0.5, 0)
