    local searchBox = Instance.new("TextBox", footer)
    searchBox.Name = "Search"; searchBox.Size = UDim2.new(0, 170, 0, 22); searchBox.Position = UDim2.new(0, 40, 0.5, -11)
    searchBox.BackgroundColor3 = Theme.Element; searchBox.BackgroundTransparency = 0.4; searchBox.BorderSizePixel = 0
    searchBox.Text = ""; searchBox.PlaceholderText = "Search features  /"; searchBox.PlaceholderColor3 = Theme.TextDark
    searchBox.ClearTextOnFocus = false; searchBox.Font = Enum.Font.GothamMedium; searchBox.TextSize = 11
    searchBox.TextColor3 = Theme.Text; searchBox.TextXAlignment = Enum.TextXAlignment.Left; searchBox.ZIndex = 82
    Instance.new("UICorner", searchBox).CornerRadius = UDim.new(0, 6)
    local sbPad = Instance.new("UIPadding", searchBox); sbPad.PaddingLeft = UDim.new(0, 8); sbPad.PaddingRight = UDim.new(0, 8)
    local sbStroke = Instance.new("UIStroke", searchBox); sbStroke.Color = Theme.Stroke; sbStroke.Thickness = 1
    local hintLbl = Instance.new("TextLabel", footer)
    hintLbl.Size = UDim2.new(0, 220, 1, 0); hintLbl.Position = UDim2.new(1, -244, 0, 0); hintLbl.BackgroundTransparency = 1
    hintLbl.Text = "RightShift  ·  menu      /  ·  search"; hintLbl.Font = Enum.Font.GothamMedium; hintLbl.TextSize = 10
    hintLbl.TextColor3 = Theme.TextDark; hintLbl.TextXAlignment = Enum.TextXAlignment.Right; hintLbl.ZIndex = 82
    local footerStroke = Instance.new("Frame", footer)
    footerStroke.Name = "FooterLine"; footerStroke.Position = UDim2.new(0, 0, 0, 0); footerStroke.Size = UDim2.new(1, 0, 0, 1)
    footerStroke.BackgroundColor3 = Theme.BloodRed; footerStroke.BackgroundTransparency = 1; footerStroke.BorderSizePixel = 0; footerStroke.ZIndex = 81

    local function runSearch(raw)
        local q = string.lower((string.gsub(raw or "", "^%s*(.-)%s*$", "%1")))
        if q == "" then return false end
        for _, tabName in ipairs(Nav.tabOrder) do
            local page = Tabs[tabName]
            if page then
                local match = nil
                for _, d in ipairs(page:GetDescendants()) do
                    if (d:IsA("TextLabel") or d:IsA("TextButton")) and d.Text ~= "" and string.find(string.lower(d.Text), q, 1, true) then
                        match = d; break
                    end
                end
                if match or string.find(string.lower(tabName), q, 1, true) then
                    selectTab(tabName)
                    if match then
                        task.delay(0.4, function()
                            if Unloaded or ActiveTab ~= tabName or not match.Parent or not page.Parent then return end
                            local scale = math.max(uiScale.Scale, 0.1)
                            local target = (match.AbsolutePosition.Y - page.AbsolutePosition.Y) / scale + page.CanvasPosition.Y - 58
                            local limit = math.max(0, page.CanvasSize.Y.Offset - page.AbsoluteSize.Y / scale)
                            page.CanvasPosition = Vector2.new(0, math.clamp(target, 0, limit))
                        end)
                    end
                    return true
                end
            end
        end
        return false
    end
    track(UserInputService.InputBegan:Connect(function(input, processed)
        if processed or Unloaded or not Main.Visible or Theme.CapturingKey or UserInputService:GetFocusedTextBox() then return end
        if input.KeyCode == Enum.KeyCode.Slash then searchBox:CaptureFocus() end
    end))
    track(searchBox.FocusLost:Connect(function(enter)
        if not enter then return end
        if not runSearch(searchBox.Text) and searchBox.Text ~= "" then
            sbStroke.Color = Color3.fromRGB(255, 80, 80)
            task.delay(0.8, function() if sbStroke.Parent then sbStroke.Color = Theme.Stroke end end)
        end
    end))
end

-- Верхняя вкладка = категория (раньше был заголовок в сайдбаре)


-- ===================== ИКОНКИ =====================
-- У каждой функции свой силуэт. Категории нижней панели получают префикс cat_
-- через атрибут кнопки, поэтому не повторяют иконки страниц верхней панели.
local function clearIcon(btn)
    -- Удаляем ВСЕ вхождения: при повторной перерисовке темы один FindFirstChild
    -- оставлял бы второй GeoIcon, и иконки наслаивались бы друг на друга.
    for _, child in ipairs(btn:GetChildren()) do
        if child.Name == "GeoIcon" then child:Destroy() end
    end
end

local function paintIcon(btn, kind, color)
    local iconKey = tostring(kind or "") .. (btn:GetAttribute("SatanicCategoryIcon") == true and ":category" or ":page")
    local existing = btn:FindFirstChild("GeoIcon")
    if existing and existing:GetAttribute("FaceLessIconKey") == iconKey then
        for _, item in ipairs(existing:GetDescendants()) do
            if item:IsA("Frame") then item.BackgroundColor3 = color
            elseif item:IsA("UIStroke") then item.Color = color end
        end
        return existing
    end
    clearIcon(btn)
    btn.Text = ""
    local root = Instance.new("Frame")
    root.Name = "GeoIcon"
    root:SetAttribute("FaceLessIconKey", iconKey)
    root.BackgroundTransparency = 1
    root.Size = UDim2.fromOffset(22, 22)
    root.ZIndex = (btn.ZIndex or 1) + 1
    root.Parent = btn

    local labeled = btn:GetAttribute("SatanicIconLabel") == true
    if labeled then
        root.AnchorPoint = Vector2.new(0, 0.5)
        root.Position = UDim2.new(0, 9, 0.5, 0)
    else
        root.AnchorPoint = Vector2.new(0.5, 0.5)
        root.Position = UDim2.fromScale(0.5, 0.5)
    end

    local function F(props)
        local f = Instance.new("Frame")
        f.BorderSizePixel = 0
        f.BackgroundColor3 = color
        f.BackgroundTransparency = 0
        f.ZIndex = root.ZIndex
        for k, v in pairs(props) do f[k] = v end
        f.Parent = root
        return f
    end
    local function stroke(frame, thickness)
        local st = Instance.new("UIStroke", frame)
        st.Color = color
        st.Thickness = thickness or 1.5
        return st
    end
    local function outline(x, y, w, h, thickness, radius, rounded)
        local f = F({
            Size = UDim2.fromOffset(w, h),
            Position = UDim2.fromOffset(x, y),
            BackgroundTransparency = 1,
        })
        stroke(f, thickness)
        local c = Instance.new("UICorner", f)
        c.CornerRadius = rounded and UDim.new(1, 0) or UDim.new(0, radius or 0)
        return f
    end
    local function ring(x, y, s, thickness)
        return outline(x, y, s, s, thickness, 0, true)
    end
    local function dot(x, y, s)
        local f = F({Size = UDim2.fromOffset(s, s), Position = UDim2.fromOffset(x, y)})
        Instance.new("UICorner", f).CornerRadius = UDim.new(1, 0)
        return f
    end
    local function seg(x1, y1, x2, y2, thickness)
        local dx, dy = x2 - x1, y2 - y1
        local len = math.sqrt(dx * dx + dy * dy)
        return F({
            Size = UDim2.fromOffset(len, thickness or 1.6),
            Position = UDim2.fromOffset((x1 + x2) * 0.5, (y1 + y2) * 0.5),
            AnchorPoint = Vector2.new(0.5, 0.5),
            Rotation = math.deg(math.atan2(dy, dx)),
        })
    end

    kind = string.lower(tostring(kind or ""))
    if btn:GetAttribute("SatanicCategoryIcon") == true and string.sub(kind, 1, 4) ~= "cat_" then
        kind = "cat_" .. kind
    end

    -- ===== Нижняя панель: категории =====
    if kind == "cat_pvp" then
        -- Combat: segmented precision reticle.
        ring(5, 5, 12, 1.5); dot(10, 10, 2)
        seg(11, 1, 11, 5, 1.7); seg(11, 17, 11, 21, 1.7)
        seg(1, 11, 5, 11, 1.7); seg(17, 11, 21, 11, 1.7)
    elseif kind == "cat_movement" then
        -- Motion: twin directional chevrons.
        seg(3, 5, 9, 11, 1.8); seg(9, 11, 3, 17, 1.8)
        seg(10, 5, 16, 11, 1.8); seg(16, 11, 10, 17, 1.8)
        seg(19, 6, 19, 16, 1.4)
    elseif kind == "cat_visuals" then
        -- Visuals: camera aperture with corner accents.
        ring(5, 5, 12, 1.5); ring(9, 9, 4, 1.2)
        seg(2, 7, 2, 3, 1.4); seg(2, 3, 6, 3, 1.4)
        seg(20, 15, 20, 19, 1.4); seg(20, 19, 16, 19, 1.4)
    elseif kind == "cat_misc" then
        -- сетка 2×2
        outline(2, 2, 8, 8, 1.4, 1)
        outline(12, 2, 8, 8, 1.4, 1)
        outline(2, 12, 8, 8, 1.4, 1)
        F({Size = UDim2.fromOffset(4, 4), Position = UDim2.fromOffset(14, 14)})
    elseif kind == "cat_customization" or kind == "customization" then
        -- кисть
        seg(3, 19, 14, 8, 2)
        outline(12, 2, 8, 8, 1.4, 1)
        seg(12, 10, 20, 3, 1.4)
        dot(3, 17, 3)
    elseif kind == "cat_tab" then
        -- группа из трёх
        ring(3, 2, 5, 1.2); outline(2, 8, 7, 8, 1.2, 2)
        ring(15, 2, 5, 1.2); outline(14, 8, 7, 8, 1.2, 2)
        ring(9, 6, 5, 1.2); outline(8, 12, 7, 8, 1.2, 2)
    elseif kind == "cat_combat" then
        -- скрещённые клинки (запасной вариант для COMBAT)
        seg(3, 3, 18, 18, 1.8); seg(18, 3, 3, 18, 1.8)
        dot(9, 9, 4)

    -- ===== Верхняя панель: страницы =====
    elseif kind == "rage" then
        -- агрессивный прицел: ромб + угловые засечки
        seg(2, 2, 6, 6, 1.8); seg(16, 2, 12, 6, 1.8)
        seg(2, 16, 6, 12, 1.8); seg(16, 16, 12, 12, 1.8)
        seg(11, 5, 17, 11, 1.6); seg(17, 11, 11, 17, 1.6)
        seg(11, 17, 5, 11, 1.6); seg(5, 11, 11, 5, 1.6)
        dot(10, 10, 2)
    elseif kind == "legit" then
        -- мягкая мишень
        ring(3, 3, 16, 1.5); ring(7, 7, 8, 1.3); dot(10, 10, 2)
    elseif kind == "combatbot" then
        -- AI node / combat core icon for Combat Bot
        ring(4, 4, 14, 1.5); seg(11, 1, 11, 5, 1.6); seg(11, 17, 11, 21, 1.6)
        seg(1, 11, 5, 11, 1.6); seg(17, 11, 21, 11, 1.6); dot(10, 10, 2.2)
    elseif kind == "movement" then
        -- бегущая стрела
        seg(2, 11, 13, 11, 2); seg(10, 7, 16, 11, 2); seg(10, 15, 16, 11, 2)
        seg(2, 5, 7, 5, 1.3); seg(2, 17, 6, 17, 1.3)
    elseif kind == "sandevistan" then
        -- A segmented neural spine / cyberware icon.
        seg(11, 2, 11, 20, 1.3)
        seg(6, 5, 11, 7, 1.6); seg(16, 5, 11, 7, 1.6)
        seg(6, 10, 11, 12, 1.6); seg(16, 10, 11, 12, 1.6)
        seg(7, 15, 11, 17, 1.6); seg(15, 15, 11, 17, 1.6)
        dot(10, 1, 2)
    elseif kind == "visuals" then
        -- глаз-линза
        seg(2, 11, 7, 6, 1.5); seg(7, 6, 15, 6, 1.5); seg(15, 6, 20, 11, 1.5)
        seg(20, 11, 15, 16, 1.5); seg(15, 16, 7, 16, 1.5); seg(7, 16, 2, 11, 1.5)
        ring(8, 8, 6, 1.3); dot(10, 10, 2)
    elseif kind == "world" then
        -- солнце над горизонтом
        ring(7, 3, 8, 1.4)
        seg(11, 0, 11, 2, 1.2); seg(3, 4, 5, 6, 1.2); seg(19, 4, 17, 6, 1.2)
        seg(2, 15, 20, 15, 1.8)
        seg(3, 15, 8, 10, 1.4); seg(8, 10, 13, 15, 1.4); seg(13, 15, 18, 11, 1.4)
    elseif kind == "chams" then
        -- игрок в рамке захвата
        seg(2, 8, 2, 3, 1.5); seg(2, 3, 7, 3, 1.5)
        seg(20, 8, 20, 3, 1.5); seg(20, 3, 15, 3, 1.5)
        seg(2, 14, 2, 19, 1.5); seg(2, 19, 7, 19, 1.5)
        seg(20, 14, 20, 19, 1.5); seg(20, 19, 15, 19, 1.5)
        ring(8, 7, 6, 1.4)
    elseif kind == "menu" then
        -- окно с двумя панелями
        outline(2, 3, 18, 16, 1.5, 0)
        seg(2, 8, 20, 8, 1.4)
        seg(9, 8, 9, 19, 1.4)
        F({Size = UDim2.fromOffset(3, 3), Position = UDim2.fromOffset(4, 5)})
    elseif kind == "fflags" then
        -- три ползунка
        seg(2, 6, 20, 6, 1.3); ring(5, 4, 5, 1.2)
        seg(2, 11, 20, 11, 1.3); ring(13, 9, 5, 1.2)
        seg(2, 16, 20, 16, 1.3); ring(8, 14, 5, 1.2)
    elseif kind == "script" then
        -- < / >
        seg(7, 4, 3, 11, 1.6); seg(3, 11, 7, 18, 1.6)
        seg(15, 4, 19, 11, 1.6); seg(19, 11, 15, 18, 1.6)
        seg(13, 3, 9, 19, 1.4)
    elseif kind == "other" then
        -- три точки треугольником
        dot(3, 14, 4); dot(9, 5, 4); dot(15, 14, 4)
    elseif kind == "configs" then
        -- дискета / файл конфига
        outline(3, 3, 16, 16, 1.5, 1)
        F({Size = UDim2.fromOffset(9, 4), Position = UDim2.fromOffset(6, 4)})
        outline(7, 11, 8, 6, 1.2, 0)
        dot(15, 4, 2)
    elseif kind == "themes" then
        -- палитра
        ring(3, 3, 16, 1.5)
        dot(7, 7, 3); dot(12, 7, 3); dot(9, 12, 3)
        seg(16, 16, 21, 21, 2)
    elseif kind == "players" or kind == "tab" then
        -- два игрока
        ring(4, 3, 6, 1.3); outline(2, 10, 10, 9, 1.3, 2)
        ring(14, 3, 6, 1.3); outline(12, 10, 10, 9, 1.3, 2)
    elseif kind == "player_settings" then
        -- профиль + шестерёнка
        ring(7, 2, 6, 1.3); outline(4, 10, 12, 9, 1.3, 2)
        ring(15, 13, 6, 1.2); dot(17, 15, 2)
    elseif kind == "combat" or kind == "pvp" then
        -- перекрестие (запасной вариант)
        seg(2, 11, 20, 11, 1.6); seg(11, 2, 11, 20, 1.6)
        ring(7, 7, 8, 1.4)
    elseif kind == "misc" or kind == "system" then
        -- шестерёнка
        ring(3, 3, 16, 1.6); ring(8, 8, 6, 1.3)
        seg(11, 0, 11, 3, 1.5); seg(11, 19, 11, 22, 1.5)
        seg(0, 11, 3, 11, 1.5); seg(19, 11, 22, 11, 1.5)
    elseif kind == "binds" then
        -- клавиатура: клавиша с точками
        outline(2, 5, 18, 9, 1.4, 1)
        dot(6, 9, 2); dot(11, 9, 2); dot(16, 9, 2)
        seg(7, 17, 15, 17, 1.4)
    elseif kind == "interface" then
        -- три ползунка
        seg(2, 5, 20, 5, 1.4); dot(7, 5, 3)
        seg(2, 11, 20, 11, 1.4); dot(15, 11, 3)
        seg(2, 17, 20, 17, 1.4); dot(10, 17, 3)
    else
        -- аккуратный ромб по умолчанию
        seg(11, 3, 19, 11, 1.5); seg(19, 11, 11, 19, 1.5)
        seg(11, 19, 3, 11, 1.5); seg(3, 11, 11, 3, 1.5)
    end
    return root
end

local function iconKindForName(name)
    local n = string.lower(tostring(name or ""))
    if n == "pvp" or n == "combat" then return "pvp" end
    if n == "movement" or n == "move" then return "movement" end
    if n == "visuals" or n == "render" then return "visuals" end
    if n == "sandevistan" then return "sandevistan" end
    if n == "world" then return "world" end
    if n == "chams" then return "chams" end
    if n == "misc" or n == "system" then return "misc" end
    if n == "customization" then return "customization" end
    if n == "themes" then return "themes" end
    if n == "tab" then return "tab" end
    if n == "player settings" or n == "player_settings" then return "player_settings" end
    if n == "binds" or n == "keybinds" then return "binds" end
    if n == "interface" or n == "ui" then return "interface" end
    if n == "menu" then return "menu" end
    if n == "fflags" then return "fflags" end
    if n == "script" then return "script" end
    if n == "other" then return "other" end
    if n == "configs" then return "configs" end
    if n == "rage" then return "rage" end
    if n == "legit" then return "legit" end
    if n == "combat bot" or n == "combatbot" then return "combatbot" end
    return n
end

function createCategoryHeader(name)
    if Nav.categories[name] then Nav.currentCategory = name; return end
    local tipMap = {
        PvP = "PVP", Movement = "MOTION",
        VISUALS = "VISUALS", MISC = "TOOLS", CUSTOMIZATION = "THEMES", TAB = "PLAYERS",
    }
    local labelText = string.upper(tipMap[name] or (Nav.titles[name] or name))
    local btn = Instance.new("TextButton", Nav.topBar)
    btn.Name = name
    btn.Size = UDim2.fromOffset(112, 36)
    btn.AutomaticSize = Enum.AutomaticSize.None
    btn.BackgroundColor3 = Theme.Element
    btn.BackgroundTransparency = 1
    btn.BorderSizePixel = 0
    btn.AutoButtonColor = false
    btn.Text = ""
    btn.LayoutOrder = #Nav.categoryOrder + 1
    btn.ZIndex = 61
    btn:SetAttribute("SatanicCategoryIcon", true)
    btn:SetAttribute("SatanicIconLabel", false)
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 10)
    paintIcon(btn, iconKindForName(name), Theme.TextDark)
    local catLabel = Instance.new("TextLabel", btn)
    catLabel.Name = "CatLabel"
    catLabel.BackgroundTransparency = 1
    catLabel.AnchorPoint = Vector2.new(0.5, 0)
    catLabel.Position = UDim2.new(0.5, 0, 1, 4)
    catLabel.Size = UDim2.fromOffset(90, 18)
    catLabel.Visible = false
    catLabel.Font = Enum.Font.GothamMedium
    catLabel.TextSize = 10
    catLabel.Text = labelText
    catLabel.TextColor3 = Theme.TextDark
    catLabel.TextXAlignment = Enum.TextXAlignment.Center
    catLabel.TextTruncate = Enum.TextTruncate.AtEnd
    catLabel.ZIndex = 62
    local ind = Instance.new("Frame", btn)
    ind.Name = "Indicator"
    ind.Size = UDim2.new(0.55, 0, 0, 2)
    ind.Position = UDim2.new(0.225, 0, 1, -2)
    ind.BackgroundColor3 = Theme.BloodRed
    ind.BackgroundTransparency = 1
    ind.BorderSizePixel = 0
    ind.ZIndex = 63
    btn.MouseEnter:Connect(function()
        catLabel.Visible = true
        UITween(btn, {BackgroundTransparency = 0.2}, 0.12)
        paintIcon(btn, iconKindForName(name), Theme.BloodRed)
    end)
    btn.MouseLeave:Connect(function()
        catLabel.Visible = false
        local active = ActiveTab and Nav.tabCategory[ActiveTab] == name
        UITween(btn, {BackgroundTransparency = active and 0.15 or 1}, 0.12)
        paintIcon(btn, iconKindForName(name), active and Theme.BloodRed or Theme.TextDark)
    end)
    local cat = {name = name, btn = btn, pages = {}, last = nil}
    Nav.categories[name] = cat
    table.insert(Nav.categoryOrder, name)
    Nav.currentCategory = name
    if Nav.layoutCategories then pcall(Nav.layoutCategories) end
    track(btn.MouseButton1Click:Connect(function()
        local target = cat.last or cat.pages[1]
        if target then selectTab(target) end
    end))
end

-- Скользящий индикатор активной вкладки: старый бар уезжает к новой вкладке,
-- новый выезжает ему навстречу. Всё вручную через RenderStepped — без
-- TweenService, чтобы анимация работала в любом экзекуторе.
local slideState = nil
local function finishSlide()
    if not slideState then return end
    local s = slideState
    if s.oldInd then
        s.oldInd.BackgroundTransparency = 1
        s.oldInd.Position = UDim2.new(0, 4, 1, -2)
        s.oldInd.Size = UDim2.new(1, -8, 0, 2)
    end
    if s.oldGlow then s.oldGlow.BackgroundTransparency = 1 end
    if s.newInd then
        s.newInd.BackgroundTransparency = 0
        s.newInd.Position = UDim2.new(0, 4, 1, -2)
        s.newInd.Size = UDim2.new(1, -8, 0, 2)
    end
    if s.newGlow then
        s.newGlow.BackgroundTransparency = 0.72
        s.newGlow.Position = UDim2.new(0, 0, 1, -5)
        s.newGlow.Size = UDim2.new(1, 0, 0, 6)
    end
    slideState = nil
end

local function slideUnderline(oldBtn, newBtn)
    if not newBtn then return end
    if oldBtn == newBtn then oldBtn = nil end
    finishSlide()
    local newInd = newBtn:FindFirstChild("Indicator")
    if not newInd then return end
    local newGlow = newBtn:FindFirstChild("IndicatorGlow")
    if not newGlow then
        newGlow = Instance.new("Frame", newBtn)
        newGlow.Name = "IndicatorGlow"
        newGlow.BackgroundColor3 = Theme.BloodRed
        newGlow.BorderSizePixel = 0
        newGlow.ZIndex = 24
        Instance.new("UICorner", newGlow).CornerRadius = UDim.new(1, 0)
    end
    local oldInd, oldGlow
    if oldBtn then
        oldInd = oldBtn:FindFirstChild("Indicator")
        oldGlow = oldBtn:FindFirstChild("IndicatorGlow")
    end
    local dir = 1
    if oldBtn then
        dir = (newBtn.AbsolutePosition.X >= oldBtn.AbsolutePosition.X) and 1 or -1
    end
    newInd.BackgroundTransparency = 0
    newGlow.BackgroundTransparency = 0.72
    if oldInd then oldInd.BackgroundTransparency = 0 end
    if oldGlow then oldGlow.BackgroundTransparency = 0.72 end
    slideState = {
        t = 0, dur = 0.34, dir = dir,
        oldInd = oldInd, oldGlow = oldGlow,
        newInd = newInd, newGlow = newGlow,
    }
end

track(RunService.RenderStepped:Connect(function(dt)
    local ok, drvErr = pcall(function()
    if Unloaded or not slideState then return end
    local s = slideState
    s.t = math.min(s.dur, s.t + dt)
    local u = s.t / s.dur
    u = 1 - (1 - u) * (1 - u) * (1 - u)
    if s.dir == 1 then
        if s.oldInd then
            s.oldInd.Position = UDim2.new(u, 0, 1, -2)
            s.oldInd.Size = UDim2.new(1 - u, 0, 0, 2)
        end
        if s.oldGlow then
            s.oldGlow.Position = UDim2.new(u, 0, 1, -5)
            s.oldGlow.Size = UDim2.new(1 - u, 0, 0, 6)
        end
        s.newInd.Position = UDim2.new(0, 0, 1, -2)
        s.newInd.Size = UDim2.new(u, 0, 0, 2)
        s.newGlow.Position = UDim2.new(0, 0, 1, -5)
        s.newGlow.Size = UDim2.new(u, 0, 0, 6)
    else
        if s.oldInd then
            s.oldInd.Position = UDim2.new(0, 0, 1, -2)
            s.oldInd.Size = UDim2.new(1 - u, 0, 0, 2)
        end
        if s.oldGlow then
            s.oldGlow.Position = UDim2.new(0, 0, 1, -5)
            s.oldGlow.Size = UDim2.new(1 - u, 0, 0, 6)
        end
        s.newInd.Position = UDim2.new(1 - u, 0, 1, -2)
        s.newInd.Size = UDim2.new(u, 0, 0, 2)
        s.newGlow.Position = UDim2.new(1 - u, 0, 1, -5)
        s.newGlow.Size = UDim2.new(u, 0, 0, 6)
    end
    if s.t >= s.dur then finishSlide() end
    end)
    if not ok then FLLog.push("error", "tab-underline", tostring(drvErr), "слайд подчёркивания табов") end
end))

-- ===== Слайд таба v3: блок контента въезжает справа =====
-- Анимируем Position ОБЫЧНОГО Frame (Nav.content) — тот же класс объектов, что
-- и волны меню (они гарантированно рендерятся). ScrollingFrame больше не трогаем.
-- Каждый шаг логируется в FLLog — видно, был ли слайд вообще.
local contentSlide = nil

local function slideContentIn()
    local ok, err = pcall(function()
        local content = Nav.content
        if Unloaded or not content or not content.Parent then
            FLLog.push("warn", "tab-slide", "пропущено: контент недоступен", "Nav.content = " .. tostring(Nav.content))
            return
        end
        -- если слайд ещё идёт — берём его настоящую «базу», иначе смещение накопится
        local base = content.Position
        if contentSlide and contentSlide.base then
            base = contentSlide.base
            contentSlide = nil
            content.Position = base
        end
        local w = content.AbsoluteSize.X
        if w <= 1 then w = 620 end
        local dist = math.floor(w * 0.30 + 0.5)
        contentSlide = { t = 0, dur = 0.40, dist = dist, base = base, content = content }
        content.Position = UDim2.new(base.X.Scale, base.X.Offset + dist, base.Y.Scale, base.Y.Offset)
        FLLog.info("tab-slide", "start w=" .. tostring(w) .. " dist=" .. tostring(dist))
    end)
    if not ok then FLLog.push("error", "tab-slide", tostring(err), "slideContentIn") end
end

track(RunService.RenderStepped:Connect(function(dt)
    local ok, err = pcall(function()
        if Unloaded then return end
        local s = contentSlide
        if not s then return end
        local content = s.content
        if not content or not content.Parent then contentSlide = nil; return end
        s.t = math.min(s.dur, s.t + dt)
        local u = s.t / s.dur
        u = 1 - (1 - u) * (1 - u) * (1 - u) * (1 - u)
        content.Position = UDim2.new(s.base.X.Scale, s.base.X.Offset + s.dist * (1 - u), s.base.Y.Scale, s.base.Y.Offset)
        if s.t >= s.dur then
            content.Position = s.base
            contentSlide = nil
            FLLog.info("tab-slide", "end")
        end
    end)
    if not ok then FLLog.push("error", "tab-slide", tostring(err), "слайд контента табов") end
end))

function selectTab(name)
    if not Tabs[name] then return end
    if Theme.OpenDropdownScrollLists then
        for _, release in pairs(Theme.OpenDropdownScrollLists) do pcall(release) end
    end
    if Nav.cancelPager then pcall(Nav.cancelPager) end
    local cat = Nav.tabCategory[name]
    local info = TweenInfo.new(0.15)
    local prevName = ActiveTab
    for tabName, frame in pairs(Tabs) do
        local show = (tabName == name)
        frame.Visible = show
        if show then
            frame.CanvasPosition = Vector2.new(0, 0)
            if prevName ~= name then slideContentIn() end
        end
    end
    for catName, c in pairs(Nav.categories) do
        local active = (catName == cat)
        TweenService:Create(c.btn, info, {
            BackgroundTransparency = active and 0.12 or 1,
            BackgroundColor3 = active and Theme.ElementHover or Theme.Element,
        }):Play()
        paintIcon(c.btn, iconKindForName(catName), active and Theme.BloodRed or Theme.TextDark)
        local catLbl = c.btn:FindFirstChild("CatLabel")
        if catLbl then TweenService:Create(catLbl, info, {TextColor3 = active and Theme.Text or Theme.TextDark}):Play() end
        local ind = c.btn:FindFirstChild("Indicator")
        if ind then TweenService:Create(ind, info, {BackgroundTransparency = active and 0 or 1}):Play() end
    end
    for tabName, btn in pairs(TabButtons) do
        local active = (tabName == name)
        local inCat = (Nav.tabCategory[tabName] == cat)
        btn.Visible = inCat
        TweenService:Create(btn, info, {
            BackgroundTransparency = active and 0.12 or 1,
            BackgroundColor3 = active and Theme.ElementHover or Theme.Element,
        }):Play()
        paintIcon(btn, iconKindForName(tabName), active and Theme.BloodRed or Theme.TextDark)
        local tabLbl = btn:FindFirstChild("TabLabel")
        if tabLbl then TweenService:Create(tabLbl, info, {TextColor3 = active and Theme.Text or Theme.TextDark}):Play() end
        local indicator = btn:FindFirstChild("Indicator")
        if indicator then
            indicator.BackgroundTransparency = active and 0 or 1
            if not active then
                indicator.Position = UDim2.new(0, 4, 1, -2)
                indicator.Size = UDim2.new(1, -8, 0, 2)
            end
        end
        local st = btn:FindFirstChildOfClass("UIStroke")
        if st then
            TweenService:Create(st, info, {
                Transparency = active and 0.25 or 0.85,
                Color = active and Theme.BloodRed or Theme.Stroke,
            }):Play()
        end
    end
    slideUnderline(TabButtons[prevName], TabButtons[name])
    if cat and Nav.categories[cat] then Nav.categories[cat].last = name end
    ActiveTab = name
    if Nav.updateContentPager then pcall(Nav.updateContentPager) end
end

-- Страница = пункт левой навигации внутри текущей категории
function createTab(name, icon, configScopeName)
    local cat = Nav.currentCategory
    local shortNames = {
        Movement = "MOTION", Visuals = "VISUAL FX", FFlags = "PERFORMANCE",
        Configs = "PROFILES", ["Player Settings"] = "PLAYERS",
        Rage = "RAGE", Legit = "LEGIT", ["Combat Bot"] = "COMBAT BOT", World = "WORLD FX", Chams = "CHAMS",
        Menu = "HUD", Other = "UTILITIES", Script = "SCRIPTS",
    }
    local labelText = string.upper(shortNames[name] or name)
    local btn = Instance.new("TextButton", Nav.subList)
    btn.Name = name
    btn.Size = UDim2.fromOffset(108, 30)
    btn.AutomaticSize = Enum.AutomaticSize.None
    btn.BackgroundColor3 = Theme.Element
    btn.BackgroundTransparency = 1
    btn.Text = ""
    btn.LayoutOrder = #Nav.tabOrder + 1
    btn.AutoButtonColor = false
    btn.BorderSizePixel = 0
    btn.ZIndex = 23
    btn:SetAttribute("SatanicIconLabel", true)
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 0)
    local btnStroke = Instance.new("UIStroke", btn)
    btnStroke.Color = Theme.Stroke
    btnStroke.Thickness = 1
    btnStroke.Transparency = 1
    paintIcon(btn, iconKindForName(name), Theme.TextDark)
    local tabLabel = Instance.new("TextLabel", btn)
    tabLabel.Name = "TabLabel"
    tabLabel.BackgroundTransparency = 1
    tabLabel.Position = UDim2.new(0, 36, 0, 0)
    tabLabel.Size = UDim2.new(1, -42, 1, 0)
    tabLabel.Font = Enum.Font.GothamMedium
    tabLabel.TextSize = 10
    tabLabel.Text = labelText
    tabLabel.TextColor3 = Theme.TextDark
    tabLabel.TextXAlignment = Enum.TextXAlignment.Left
    tabLabel.TextTruncate = Enum.TextTruncate.AtEnd
    tabLabel.ZIndex = 24
    local indicator = Instance.new("Frame", btn)
    indicator.Name = "Indicator"
    indicator.Size = UDim2.new(1, -8, 0, 2)
    indicator.Position = UDim2.new(0, 4, 1, -2)
    indicator.BackgroundColor3 = Theme.BloodRed
    indicator.BorderSizePixel = 0
    indicator.BackgroundTransparency = 1
    indicator.ZIndex = 25
    btn.MouseEnter:Connect(function()
        if ActiveTab == name then return end
        UITween(btn, {BackgroundTransparency = 0.35}, 0.12)
        UITween(btnStroke, {Transparency = 0.4}, 0.12)
        paintIcon(btn, iconKindForName(name), Theme.BloodRed)
    end)
    btn.MouseLeave:Connect(function()
        if ActiveTab == name then return end
        UITween(btn, {BackgroundTransparency = 1}, 0.12)
        UITween(btnStroke, {Transparency = 0.85}, 0.12)
        paintIcon(btn, iconKindForName(name), Theme.TextDark)
    end)
    track(btn.MouseButton1Click:Connect(function() selectTab(name) end))
    local page = Instance.new("ScrollingFrame", Nav.content)
    -- configScopeName keeps old saved config identifiers compatible after a UI rename.
    page.Name = configScopeName or name; page:SetAttribute("DisplayTabName", name)
    page.Size = UDim2.new(1, 0, 1, 0); page.BackgroundTransparency = 1; page.BorderSizePixel = 0; page.ScrollBarThickness = 3; page.ScrollBarImageColor3 = Theme.BloodRed; page.Visible = false
    if name ~= "Configs" then
        -- Шапка страницы как у Configs: иконка, заголовок, подпись и линия-разделитель
        local hdr = Instance.new("Frame", page)
        hdr.Name = "PageHeader"; hdr.Size = UDim2.new(1, 0, 0, 62); hdr.BackgroundTransparency = 1; hdr.BorderSizePixel = 0
        local titleLbl = Instance.new("TextLabel", hdr)
        titleLbl.Position = UDim2.new(0, 16, 0, 11); titleLbl.Size = UDim2.new(1, -40, 0, 20); titleLbl.BackgroundTransparency = 1
        titleLbl.Text = string.upper(name); titleLbl.Font = Enum.Font.GothamBold; titleLbl.TextSize = 15
        titleLbl.TextColor3 = Theme.Text; titleLbl.TextXAlignment = Enum.TextXAlignment.Left
        local subLbl = Instance.new("TextLabel", hdr)
        subLbl.Position = UDim2.new(0, 16, 0, 31); subLbl.Size = UDim2.new(1, -40, 0, 14); subLbl.BackgroundTransparency = 1
        subLbl.Text = Nav.subtitles[name] or "Настройки"; subLbl.Font = Enum.Font.GothamMedium; subLbl.TextSize = 10
        subLbl.TextColor3 = Theme.TextDark; subLbl.TextXAlignment = Enum.TextXAlignment.Left
        local divLine = Instance.new("Frame", hdr)
        divLine.Position = UDim2.new(0, 15, 0, 58); divLine.Size = UDim2.new(1, -30, 0, 1)
        divLine.BackgroundColor3 = Theme.BloodRed; divLine.BorderSizePixel = 0
        local divGrad = Instance.new("UIGradient", divLine)
        divGrad.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0.15), NumberSequenceKeypoint.new(1, 1),
        })
    end
    local leftCol = Instance.new("Frame", page); leftCol.Name = "Left"; leftCol.Size = UDim2.new(0.5, -18, 0, 0); leftCol.Position = UDim2.new(0, 15, 0, 72); leftCol.BackgroundTransparency = 1
    local rightCol = Instance.new("Frame", page); rightCol.Name = "Right"; rightCol.Size = UDim2.new(0.5, -18, 0, 0); rightCol.Position = UDim2.new(0.5, 3, 0, 72); rightCol.BackgroundTransparency = 1
    local lLayout = Instance.new("UIListLayout", leftCol)
    lLayout.FillDirection = Enum.FillDirection.Horizontal
    lLayout.HorizontalAlignment = Enum.HorizontalAlignment.Left
    lLayout.VerticalAlignment = Enum.VerticalAlignment.Top
    lLayout.Padding = UDim.new(0, 18)
    lLayout.SortOrder = Enum.SortOrder.LayoutOrder
    local rLayout = Instance.new("UIListLayout", rightCol)
    rLayout.FillDirection = Enum.FillDirection.Horizontal
    rLayout.HorizontalAlignment = Enum.HorizontalAlignment.Left
    rLayout.VerticalAlignment = Enum.VerticalAlignment.Top
    rLayout.Padding = UDim.new(0, 18)
    rLayout.SortOrder = Enum.SortOrder.LayoutOrder
    local layoutBusy = false
    local function updateTabColumnLayout()
        if layoutBusy then return end
        if not lLayout.Parent or not rLayout.Parent then return end
        layoutBusy = true
        local fullWidth = page:GetAttribute("FullWidthColumns") == true or page.Name == "Themes"
        local viewW = math.max(320, Nav.content.AbsoluteSize.X)
        local viewH = math.max(240, Nav.content.AbsoluteSize.Y)
        local cardW = math.max(240, math.floor((viewW - 30 - 36) / 3))
        Nav.cardWidth = fullWidth and (viewW - 30) or cardW
        if fullWidth then
            -- Themes / широкие страницы остаются вертикальными.
            lLayout.FillDirection = Enum.FillDirection.Vertical
            rLayout.FillDirection = Enum.FillDirection.Vertical
            leftCol.Position = UDim2.new(0, 15, 0, 12)
            leftCol.Size = UDim2.new(1, -30, 0, lLayout.AbsoluteContentSize.Y + 20)
            rightCol.Visible = false
            rightCol.Size = UDim2.new(0, 0, 0, 0)
            page.CanvasSize = UDim2.new(0, 0, 0, lLayout.AbsoluteContentSize.Y + 100)
            page.ScrollingDirection = Enum.ScrollingDirection.Y
            page:SetAttribute("SatanicCardW", 0)
        else
            -- Ровная сетка: ДВЕ линии одинаковой ширины, равный зазор GAP.
            -- Высота КАЖДОЙ карточки фиксируется один раз по её реальному содержимому,
            -- а SatanicGridManaged запрещает createSection менять Size позже —
            -- поэтому карточки больше не накладываются и не «прячутся».
            local GAP = 18
            lLayout.FillDirection = Enum.FillDirection.Horizontal
            rLayout.FillDirection = Enum.FillDirection.Horizontal
            lLayout.Padding = UDim.new(0, GAP)
            rLayout.Padding = UDim.new(0, GAP)

            local function grab(from, bucket, seen)
                for _, c in ipairs(from:GetChildren()) do
                    if c:IsA("Frame") and c:GetAttribute("SatanicSectionCard") == true and not seen[c] then
                        seen[c] = true
                        table.insert(bucket, c)
                    end
                end
            end
            local seenPending, pendingL, pendingR = {}, {}, {}
            grab(leftCol, pendingL, seenPending); grab(rightCol, pendingR, seenPending)
            local baseOrder = 0
            for _, c in ipairs(page:GetChildren()) do
                local o = c:GetAttribute("SatanicCardOrder")
                if type(o) == "number" and o > baseOrder then baseOrder = o end
            end
            if #pendingL > 0 or #pendingR > 0 then
                local order = baseOrder
                local maxN = math.max(#pendingL, #pendingR)
                for i = 1, maxN do
                    if pendingL[i] then order = order + 1; pendingL[i]:SetAttribute("SatanicCardOrder", order) end
                    if pendingR[i] then order = order + 1; pendingR[i]:SetAttribute("SatanicCardOrder", order) end
                end
            end
            local cards, seen = {}, {}
            grab(leftCol, cards, seen); grab(rightCol, cards, seen); grab(page, cards, seen)
            table.sort(cards, function(a, b)
                return (a:GetAttribute("SatanicCardOrder") or 9999) < (b:GetAttribute("SatanicCardOrder") or 9999)
            end)
            leftCol.Visible = false
            rightCol.Visible = false
            leftCol.Size = UDim2.fromOffset(0, 0)
            rightCol.Size = UDim2.fromOffset(0, 0)

            local GAP = 18
            local heights = {12, 12, 12}
            local plates = {}
            for i = 1, 3 do
                local plate = page:FindFirstChild("TracelessColumn" .. i)
                if not plate then
                    plate = Instance.new("Frame")
                    plate.Name = "TracelessColumn" .. i
                    plate.BorderSizePixel = 0
                    plate.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
                    plate.BackgroundTransparency = 0.52
                    plate.ZIndex = 1
                    plate.Parent = page
                    Instance.new("UICorner", plate).CornerRadius = UDim.new(0, 22)
                    local edge = Instance.new("UIStroke", plate)
                    edge.Color = Color3.fromRGB(221, 208, 205)
                    edge.Transparency = 0.90
                    local wash = Instance.new("UIGradient", plate)
                    wash.Rotation = 90
                    wash.Color = ColorSequence.new(Theme.Section, Theme.ElementHover)
                end
                plate.Position = UDim2.fromOffset(15 + (i - 1) * (cardW + GAP), page.CanvasPosition.Y + 2)
                plates[i] = plate
            end
            for _, card in ipairs(cards) do
                if card.Parent ~= page then card.Parent = page end
                card:SetAttribute("SatanicGridManaged", true)
                if card:GetAttribute("SatanicGridSizeBound") ~= true then
                    card:SetAttribute("SatanicGridSizeBound", true)
                    track(card:GetPropertyChangedSignal("Size"):Connect(function()
                        task.defer(function() if not layoutBusy then updateTabColumnLayout() end end)
                    end))
                end
                local h = math.max(56, card.Size.Y.Offset)
                local cont = card:FindFirstChild("Container")
                if cont then
                    local lay = cont:FindFirstChildOfClass("UIListLayout")
                    if lay and lay.AbsoluteContentSize.Y > 0 then h = math.max(56, lay.AbsoluteContentSize.Y + 49) end
                end
                h = math.ceil(h)
                if card.Size.X.Offset ~= cardW or card.Size.Y.Offset ~= h or card.Size.X.Scale ~= 0 or card.Size.Y.Scale ~= 0 then
                    card.Size = UDim2.fromOffset(cardW, h)
                end
                local col = 1
                for i = 2, 3 do if heights[i] < heights[col] then col = i end end
                card.Position = UDim2.fromOffset(15 + (col - 1) * (cardW + GAP), heights[col])
                heights[col] = heights[col] + h + GAP
            end
            local columnHeight = math.max(viewH - 12, math.max(heights[1], heights[2], heights[3]) + 2)
            for _, plate in ipairs(plates) do plate.Size = UDim2.fromOffset(cardW, math.max(1, viewH - 10)) end
            page.CanvasSize = UDim2.fromOffset(0, math.max(viewH, columnHeight + 12))
            page.ScrollingDirection = Enum.ScrollingDirection.Y
            page.ScrollBarThickness = 3
            page:SetAttribute("SatanicCardW", cardW)
            if Nav.updateContentPager then pcall(Nav.updateContentPager) end
        end
        layoutBusy = false
    end
    track(lLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(updateTabColumnLayout))
    track(rLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(updateTabColumnLayout))
    track(Nav.content:GetPropertyChangedSignal("AbsoluteSize"):Connect(updateTabColumnLayout))
    track(page:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
        -- The three glass backplates stay fixed to the viewport while controls scroll.
        for i = 1, 3 do
            local plate = page:FindFirstChild("TracelessColumn" .. i)
            if plate then
                local pos = plate.Position
                plate.Position = UDim2.new(pos.X.Scale, pos.X.Offset, 0, page.CanvasPosition.Y + 2)
            end
        end
        if Nav.updateContentPager then pcall(Nav.updateContentPager) end
    end))
    task.defer(updateTabColumnLayout)
    task.delay(0.8, updateTabColumnLayout)
    local ph = page:FindFirstChild("PageHeader")
    if ph then ph.Visible = false; ph.Size = UDim2.new(1, 0, 0, 0) end
    -- columns sit under chip bar area
    local leftCol = page:FindFirstChild("Left")
    local rightCol = page:FindFirstChild("Right")
    if leftCol then leftCol.Position = UDim2.fromOffset(15, 12) end
    -- Правая строка ставится updateTabColumnLayout(): обе строки уходят вправо.
    if rightCol then rightCol.Visible = true end
    Tabs[name] = page; TabButtons[name] = btn
    table.insert(Nav.tabOrder, name)
    Nav.tabCategory[name] = cat
    if cat and Nav.categories[cat] then table.insert(Nav.categories[cat].pages, name) end
    return page
end

-- Реестр всех управляемых строк: из него собирается панель KEYBINDS на экране.
Theme.Bindables = Theme.Bindables or {}

function createSection(columnFrame, title, configScopeOverride)
    -- Защита от «мёртвой» колонки: если родитель не найден (обрезка/сдвиг при
    -- копировании кода в редактор экзекутора), секция не должна ронять загрузку
    -- всего скрипта — создаём невидимый резервный контейнер и пишем предупреждение.
    if not columnFrame then
        warn('[Satanic] createSection: нет колонки для карточки «' .. tostring(title) .. '» — использую резервную')
        columnFrame = Instance.new("Frame")
        columnFrame.Name = "SatanicOrphanColumn"
        columnFrame.Size = UDim2.new(0, 320, 0, 0)
        columnFrame.BackgroundTransparency = 1
        columnFrame.Visible = false
        pcall(function()
            columnFrame.Parent = Main or (LocalPlayer and LocalPlayer:FindFirstChild("PlayerGui"))
        end)
    end
    local scopePage = columnFrame.Parent
    local pageName = scopePage and (scopePage:GetAttribute("DisplayTabName") or scopePage.Name) or "General"
    local isThemesSection = (pageName == "Themes")
    local sectionDescriptions = {
        ["Watermark"] = "STATUS / PERFORMANCE DISPLAY",
        ["GUI"] = "INTERFACE / ACCESSIBILITY",
        ["Model Face Lock (T)"] = "TARGETING / CHARACTER LOCK",
        ["Neverlose Target Arrows"] = "TARGET INDICATORS / DIRECTION",
        ["Chams Settings"] = "PLAYER HIGHLIGHT / STYLE",
        ["Femboy Companion"] = "SITTING AVATAR / PASTEL IDLE POSE",
        ["Visual Bodies"] = "CHARACTER APPEARANCE",
        ["Custom Hats & Effects"] = "ACCESSORIES / COLOR / MATERIAL",
        ["Wings"] = "ANIMATED 3D / ANGELIC · DEMONIC",
        ["Militech / Apogee"] = "SPINAL CYBERWARE / LED PRESETS",
        ["Sandevistan Overdrive"] = "V KEY / CHROMATIC TIME DILATION",
        ["Custom Core Color"] = "CUSTOM NEURAL CORE / HSV",
        ["Optics & Kinetics"] = "GRADE / AUDIO / OPTIONAL SPEED",
        ["World"] = "WEATHER / ENVIRONMENT",
        ["Fog"] = "START / DISTANCE / DENSITY / PRESETS",
        ["Sky Atelier"] = "ARTWORK / LIGHTING / WORLD FX",
        ["Garou Recolor RED"] = "CHARACTER COLOR OVERRIDE",
        ["Trails"] = "MOTION / RIBBONS / STARDUST",
        ["TSB Visual Cleanup"] = "LOCAL VISUAL EFFECTS",
        ["Extreme Performance"] = "FPS / UPDATE BUDGET",
        ["External Scripts & Hubs"] = "QUICK ACCESS / UTILITIES",
        ["Movement Utility"] = "CHARACTER MOVEMENT",
        -- новые модули
        ["Aim Assist"] = "TARGET SELECTION / SMOOTHING",
        ["Hitbox & Reach"] = "HITBOX / LOCAL OVERLAY",
        ["Speed & Jump"] = "WALKSPEED / JUMP / BUNNYHOP",
        ["Fly & NoClip"] = "FLIGHT / COLLISION",
        ["Physics"] = "GRAVITY / FAST FALL / ANTI-FLING",
        ["Menu & Server"] = "JOB ID / REJOIN / UNLOAD",
        ["Utility"] = "ANTI-AFK / RESET",
        ["Menu Style"] = "OPACITY / SCALE / BLUR",
        ["Interface Colors"] = "ACCENT / BACKGROUND",
        ["HUD & Effects"] = "LAYERS / GLOW",
        ["Bot Master & Target"] = "AI CORE / TARGET / HUD",
        ["Combat · Block · Movement"] = "M1 / AUTO BLOCK / PATHING / 110MS",
        ["Bot Autonomous Techs"] = "LOOP / OREO / TWISTED / KYOTO",
    }
    local hasSubtitle = not isThemesSection
    local contentTop = hasSubtitle and 39 or 30
    local sec = Instance.new("Frame")
    local fixedW = math.max(240, math.floor((Main.Size.X.Offset - 30) / 2))
    local secW = isThemesSection and UDim2.new(1, 0, 0, contentTop + 14) or UDim2.new(0, fixedW, 0, contentTop + 14)
    sec.Name = title; sec.Size = secW
    sec.BackgroundColor3 = Color3.fromRGB(22, 14, 38)
    sec.BackgroundTransparency = 1
    sec.ZIndex = 3
    sec.BorderSizePixel = 0
    sec:SetAttribute("SatanicSectionCard", true)
    -- ВАЖНО: атрибут ставится ДО reparent — иначе первый сигнал грида
    -- ловит карточку без атрибута, и она навсегда остаётся неровной.
    sec.Parent = columnFrame
    Instance.new("UICorner", sec).CornerRadius = UDim.new(0, 12)
    local stroke = Instance.new("UIStroke", sec)
    stroke.Color = Theme.BloodRed
    stroke.Thickness = 1
    stroke.Transparency = 1
    local accent = Instance.new("Frame", sec)
    accent.Name = "AccentBar"
    accent.AnchorPoint = Vector2.new(0, 0)
    accent.Size = UDim2.new(0, 3, 1, -16)
    accent.Position = UDim2.new(0, 0, 0, 8)
    accent.BackgroundColor3 = Theme.BloodRed
    accent.BackgroundTransparency = 1
    accent.BorderSizePixel = 0
    accent.ZIndex = 3
    local secShadow = Instance.new("ImageLabel", sec)
    secShadow.Name = "CardShadow"
    secShadow.AnchorPoint = Vector2.new(0.5, 0.5)
    secShadow.Position = UDim2.new(0.5, 0, 0.5, 4)
    secShadow.Size = UDim2.new(1, 18, 1, 18)
    secShadow.BackgroundTransparency = 1
    secShadow.Image = "rbxassetid://5028857084"
    secShadow.ImageColor3 = Color3.fromRGB(0, 0, 0)
    secShadow.ImageTransparency = 1
    secShadow.ZIndex = 0
    -- The section itself is transparent; the column glass sits behind it.
    sec.BackgroundTransparency = 1
    stroke.Transparency = 1
    accent.BackgroundTransparency = 1
    secShadow.ImageTransparency = 1
    local header = Instance.new("TextLabel", sec)
    header.Name = "SectionTitle"
    header.Size = UDim2.new(1, -34, 0, hasSubtitle and 19 or 30); header.Position = UDim2.new(0, 24, 0, 4); header.BackgroundTransparency = 1; header.Text = title; header.Font = Enum.Font.GothamBold; header.TextSize = 13; header.TextColor3 = Theme.Text; header.TextXAlignment = Enum.TextXAlignment.Left
    if hasSubtitle then
        local subtitle = Instance.new("TextLabel", sec)
        subtitle.Name = "SectionSubtitle"
        subtitle.Position = UDim2.new(0, 24, 0, 22); subtitle.Size = UDim2.new(1, -36, 0, 11)
        subtitle.BackgroundTransparency = 1; subtitle.Text = sectionDescriptions[title] or "FEATURE SETTINGS"
        subtitle.Font = Enum.Font.GothamMedium; subtitle.TextSize = 8; subtitle.TextColor3 = Theme.TextDark
        subtitle.TextXAlignment = Enum.TextXAlignment.Left; subtitle.TextTruncate = Enum.TextTruncate.AtEnd
    end
    -- детализация: разделитель под шапкой и свечение карточки при наведении
    local hd = Instance.new("Frame", sec)
    hd.Name = "HeaderDivider"
    hd.Position = UDim2.new(0, 11, 0, hasSubtitle and 35 or 27)
    hd.Size = UDim2.new(1, -22, 0, 1)
    hd.BackgroundColor3 = Theme.BloodRed
    hd.BackgroundTransparency = 0.82
    hd.BorderSizePixel = 0
    hd.ZIndex = 3
    local hdg = Instance.new("UIGradient", hd)
    hdg.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 1),
        NumberSequenceKeypoint.new(0.25, 0.1),
        NumberSequenceKeypoint.new(0.75, 0.1),
        NumberSequenceKeypoint.new(1, 1),
    })
    track(sec.MouseEnter:Connect(function()
        UITween(stroke, {Transparency = 0.55}, 0.14)
        UITween(hd, {BackgroundTransparency = 0.62}, 0.14)
    end))
    track(sec.MouseLeave:Connect(function()
        UITween(stroke, {Transparency = 1}, 0.16)
        UITween(hd, {BackgroundTransparency = 0.82}, 0.16)
    end))
    local secBar = Instance.new("Frame", sec)
    secBar.Name = "AccentBar"; secBar.Position = UDim2.new(0, 11, 0, hasSubtitle and 8 or 12); secBar.Size = UDim2.new(0, 4, 0, hasSubtitle and 16 or 14)
    secBar.BackgroundColor3 = Theme.BloodRed; secBar.BackgroundTransparency = 0.25; secBar.BorderSizePixel = 0
    Instance.new("UICorner", secBar).CornerRadius = UDim.new(1, 0)
    local container = Instance.new("Frame", sec)
    container.Name = "Container"; container.Size = UDim2.new(1, -24, 1, -contentTop - 10); container.Position = UDim2.new(0, 12, 0, contentTop); container.BackgroundTransparency = 1
    local layout = Instance.new("UIListLayout", container); layout.Padding = UDim.new(0, isThemesSection and 10 or 1); layout.SortOrder = Enum.SortOrder.LayoutOrder
    track(layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
        local h = math.max(56, math.ceil(layout.AbsoluteContentSize.Y + contentTop + 10))
        if sec:GetAttribute("SatanicGridManaged") == true then
            if sec.Size.Y.Offset ~= h then sec.Size = UDim2.fromOffset(sec.Size.X.Offset, h) end
            return
        end
        sec.Size = isThemesSection and UDim2.new(1, 0, 0, h) or UDim2.new(0, math.max(240, math.floor((Main.Size.X.Offset - 30) / 2)), 0, h)
    end))

    local configScope = configScopeOverride or (tostring(scopePage and scopePage.Name or "General") .. "/" .. tostring(columnFrame.Name or "Column") .. "/" .. tostring(title))
    local configControlCounts = {}
    local function makeConfigKey(label)
        return Theme.ConfigRegistry:MakeKey(configScope, label, configControlCounts)
    end
    
    local ElementAPI = {}
    function ElementAPI:AddToggle(text, default, callback, settingsBuilder, defaultBind)
        local row = Instance.new("Frame", container)
        row.Name = "ControlRow"; row:SetAttribute("SatanicControlRow", true)
        row.Size = UDim2.new(1, 0, 0, 27); row.BackgroundColor3 = Theme.Element; row.BackgroundTransparency = 1; row.BorderSizePixel = 0
        Instance.new("UICorner", row).CornerRadius = UDim.new(0, 6)
        local rowStroke = Instance.new("UIStroke", row); rowStroke.Color = Theme.Stroke; rowStroke.Thickness = 1; rowStroke.Transparency = 1
        local lbl = Instance.new("TextLabel", row); lbl.Position = UDim2.new(0, 9, 0, 0); lbl.Size = UDim2.new(1, -115, 1, 0); lbl.BackgroundTransparency = 1; lbl.Text = text; lbl.Font = Enum.Font.GothamMedium; lbl.TextSize = 12; lbl.TextColor3 = Theme.Text; lbl.TextXAlignment = Enum.TextXAlignment.Left; lbl.TextTruncate = Enum.TextTruncate.AtEnd
        if settingsBuilder then
            local gear = Instance.new("TextButton", row)
            gear.Size = UDim2.new(0, 18, 0, 18); gear.Position = UDim2.new(1, -100, 0.5, -9); gear.BackgroundTransparency = 1
            gear.Text = "..."; gear.Font = Enum.Font.GothamBold; gear.TextSize = 13; gear.TextColor3 = Theme.TextDark; gear.AutoButtonColor = false
            track(gear.MouseButton1Click:Connect(function() openSettingsWindow(text, settingsBuilder) end))
        end
        -- ПКМ по строке: настройки открываются только если у контрола есть свой
        -- содержательный билдер (иначе ПКМ ничего не делает). Случайный
        -- color-picker на любую строку убран.
        track(row.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton2 then return end
            if settingsBuilder then
                openSettingsWindow(text, settingsBuilder)
            end
        end))
        local bindKey = defaultBind
        local bindBtn = Instance.new("TextButton", row)
        bindBtn.Size = UDim2.new(0, 42, 0, 20); bindBtn.Position = UDim2.new(1, -80, 0.5, -10); bindBtn.BackgroundColor3 = Theme.Background; bindBtn.BackgroundTransparency = 1; bindBtn.Text = bindKey and bindKey.Name or "None"; bindBtn.Font = Enum.Font.GothamBold; bindBtn.TextSize = 9; bindBtn.TextColor3 = Theme.TextDark; bindBtn.AutoButtonColor = false
        bindBtn.TextTruncate = Enum.TextTruncate.AtEnd
        Instance.new("UICorner", bindBtn).CornerRadius = UDim.new(0, 4)
        local bindStroke = Instance.new("UIStroke", bindBtn); bindStroke.Color = Theme.Stroke; bindStroke.Thickness = 1; bindStroke.Transparency = 1
        -- Compact pill toggle: avoids the awkward empty square at the end of every feature row.
        local btn = Instance.new("TextButton", row)
        btn.Name = "StateSwitch"
        btn.Size = UDim2.new(0, 16, 0, 16)
        btn.Position = UDim2.new(1, -20, 0.5, -8)
        btn.BackgroundColor3 = Theme.ElementHover
        btn.Text = ""
        btn.AutoButtonColor = false
        btn.BorderSizePixel = 0
        btn.ClipsDescendants = true
        Instance.new("UICorner", btn).CornerRadius = UDim.new(1, 0)
        local btnStroke = Instance.new("UIStroke", btn)
        btnStroke.Color = Theme.Stroke
        btnStroke.Thickness = 1
        btnStroke.Transparency = 0.35
        local switchKnob = Instance.new("Frame", btn)
        switchKnob.Name = "Knob"
        switchKnob.Size = UDim2.new(0, 8, 0, 8)
        switchKnob.Position = UDim2.new(0.5, -4, 0.5, -4)
        switchKnob.BackgroundTransparency = 1
        switchKnob.BackgroundColor3 = Theme.TextDark
        switchKnob.BorderSizePixel = 0
        Instance.new("UICorner", switchKnob).CornerRadius = UDim.new(1, 0)
        local state = default or false
        local toggleConfigKey, toggleOccurrence
        local rowHovered = false
        local function paintRowSurface()
            if not row or not row.Parent then return end
            row.BackgroundColor3 = state and Theme.ElementHover or Theme.Element
            row.BackgroundTransparency = rowHovered and 0.80 or 1
            rowStroke.Color = Theme.Stroke
            rowStroke.Transparency = 1
        end
        track(row.MouseEnter:Connect(function() rowHovered = true; paintRowSurface() end))
        track(row.MouseLeave:Connect(function() rowHovered = false; paintRowSurface() end))
        local function render()
            paintRowSurface()
            local switchBg = state and Theme.BloodRed or Theme.ElementHover
            local switchStroke = state and Theme.BloodGlow or Theme.Stroke
            local knobPosition = UDim2.new(0.5, -4, 0.5, -4)
            local knobColor = state and Color3.fromRGB(255, 255, 255) or Theme.TextDark
            TweenService:Create(btn, TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = switchBg}):Play()
            TweenService:Create(btnStroke, TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Color = switchStroke, Transparency = state and 0.12 or 0.35}):Play()
            TweenService:Create(switchKnob, TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Position = knobPosition, BackgroundColor3 = knobColor, BackgroundTransparency = state and 0 or 1}):Play()
            if callback then pcall(callback, state) end
        end
        local function setState(v)
            state = (v == true)
            if toggleConfigKey then Theme.ConfigRegistry:Store(toggleConfigKey, {enabled = state, bind = bindKey and bindKey.Name or ""}) end
            render()
        end
        track(btn.MouseButton1Click:Connect(function() setState(not state) end))
        if default then render() end
        local listening = false
        local function beginCapture()
            if Theme.CancelBindCapture then Theme.CancelBindCapture() end
            Theme.CaptureRevision = (Theme.CaptureRevision or 0) + 1
            local revision = Theme.CaptureRevision
            listening = true
            Theme.CapturingKey = true
            bindBtn.Text = "..."
            Theme.CancelBindCapture = function()
                listening = false
                if bindBtn.Parent then bindBtn.Text = bindKey and bindKey.Name or "None" end
                Theme.CapturingKey = false
                Theme.CancelBindCapture = nil
            end
            task.delay(10, function()
                if Theme.CaptureRevision == revision and listening and Theme.CancelBindCapture then Theme.CancelBindCapture() end
            end)
        end
        track(bindBtn.MouseButton1Click:Connect(beginCapture))
        -- Строка попадает в панель KEYBINDS: имя, клавиша, состояние, переключение.
        if Theme.Bindables then
            table.insert(Theme.Bindables, {
                name = text,
                getBind = function() return bindKey end,
                setBind = function(key)
                    bindKey = key
                    bindBtn.Text = bindKey and bindKey.Name or "None"
                    bindBtn.TextColor3 = bindKey and Theme.BloodGlow or Theme.TextDark
                    if toggleConfigKey then
                        Theme.ConfigRegistry:Store(toggleConfigKey, {enabled = state, bind = bindKey and bindKey.Name or ""})
                    end
                end,
                getState = function() return state end,
                toggle = function() if setState then setState(not state) end end,
                listen = beginCapture,
            })
        end
        toggleConfigKey, toggleOccurrence = makeConfigKey(text)
        Theme.ConfigRegistry:Register(toggleConfigKey, text, "toggle",
            function() return {enabled = state, bind = bindKey and bindKey.Name or ""} end,
            function(value)
                local enabled = type(value) == "table" and value.enabled == true or value == true
                if type(value) == "table" and value.bind ~= nil then
                    local newBind = nil
                    if value.bind ~= "" then pcall(function() newBind = Enum.KeyCode[value.bind] end) end
                    bindKey = newBind
                    bindBtn.Text = bindKey and bindKey.Name or "None"
                    bindBtn.TextColor3 = bindKey and Theme.BloodGlow or Theme.TextDark
                end
                setState(enabled)
            end, configScope, toggleOccurrence)
        track(UserInputService.InputBegan:Connect(function(input, gp)
            if Unloaded or input.UserInputType ~= Enum.UserInputType.Keyboard then return end
            if listening then
                if UserInputService:GetFocusedTextBox() then return end
                listening = false
                if input.KeyCode == Enum.KeyCode.Escape or input.KeyCode == Enum.KeyCode.Backspace then bindKey = nil
                elseif input.KeyCode ~= Enum.KeyCode.Unknown then bindKey = input.KeyCode end
                bindBtn.Text = bindKey and bindKey.Name or "None"
                bindBtn.TextColor3 = bindKey and Theme.BloodGlow or Theme.TextDark
                Theme.CancelBindCapture = nil
                local captureRevision = Theme.CaptureRevision
                task.defer(function()
                    if Theme.CaptureRevision == captureRevision then Theme.CapturingKey = false end
                end)
                if toggleConfigKey then Theme.ConfigRegistry:Store(toggleConfigKey, {enabled = state, bind = bindKey and bindKey.Name or ""}) end
                if Theme.Notify then Theme.Notify(text, bindKey and ("Bound to " .. bindKey.Name) or "Binding cleared") end
                return
            end
            if not gp and bindKey and input.KeyCode == bindKey and not Theme.CapturingKey and not UserInputService:GetFocusedTextBox() and not (Theme._BotSynthMap and (Theme._BotSynthMap[input.KeyCode] or 0) > os.clock()) then
                setState(not state)
                if Theme.Notify then Theme.Notify(text, state and "Enabled" or "Disabled") end
            end
        end))
        return { Set = function(v) setState(v) end, Get = function() return state end }
    end
    function ElementAPI:AddSlider(text, min, max, default, callback)
        local frame = Instance.new("Frame", container)
        frame.Name = "SliderRow"; frame:SetAttribute("SatanicControlRow", true)
        frame.Size = UDim2.new(1, 0, 0, 42); frame.BackgroundColor3 = Theme.Element; frame.BackgroundTransparency = 0.60; frame.BorderSizePixel = 0
        Instance.new("UICorner", frame).CornerRadius = UDim.new(0, 6)
        local rowStroke = Instance.new("UIStroke", frame); rowStroke.Color = Theme.Stroke; rowStroke.Thickness = 1; rowStroke.Transparency = 0.78
        local lbl = Instance.new("TextLabel", frame); lbl.Position = UDim2.new(0, 8, 0, 3); lbl.Size = UDim2.new(1, -66, 0, 16); lbl.BackgroundTransparency = 1; lbl.Text = text; lbl.Font = Enum.Font.GothamMedium; lbl.TextSize = 12; lbl.TextColor3 = Theme.Text; lbl.TextXAlignment = Enum.TextXAlignment.Left
        local valLbl = Instance.new("TextLabel", frame); valLbl.Size = UDim2.new(0, 50, 0, 16); valLbl.Position = UDim2.new(1, -58, 0, 3); valLbl.BackgroundTransparency = 1; valLbl.Text = tostring(default); valLbl.Font = Enum.Font.GothamMedium; valLbl.TextSize = 12; valLbl.TextColor3 = Theme.TextDark; valLbl.TextXAlignment = Enum.TextXAlignment.Right
        local sliderBg = Instance.new("Frame", frame); sliderBg.Size = UDim2.new(1, -16, 0, 6); sliderBg.Position = UDim2.new(0, 8, 0, 27); sliderBg.BackgroundColor3 = Theme.ElementHover; sliderBg.BorderSizePixel = 0
        Instance.new("UICorner", sliderBg).CornerRadius = UDim.new(0, 3)
        local fill = Instance.new("Frame", sliderBg); fill.Size = UDim2.new(math.clamp((default - min) / math.max(max - min, 1e-6), 0, 1), 0, 1, 0); fill.BackgroundColor3 = Theme.BloodRed; fill.BorderSizePixel = 0
        Instance.new("UICorner", fill).CornerRadius = UDim.new(0, 3)
        local dragging = false; local last = default
        local sliderConfigKey, sliderOccurrence
        local dragStartX, startFraction, bgW = 0, (default - min) / math.max(max - min, 1e-6), 0
        local function setValue(value, force)
            local numeric = tonumber(value)
            if not numeric then return end
            local val = math.clamp(math.floor(numeric + 0.5), min, max)
            local pos = math.clamp((val - min) / math.max(max - min, 1e-6), 0, 1)
            fill.Size = UDim2.new(pos, 0, 1, 0); valLbl.Text = tostring(val)
            local changed = val ~= last
            last = val
            if sliderConfigKey then Theme.ConfigRegistry:Store(sliderConfigKey, last) end
            if (changed or force) and callback then pcall(callback, val) end
        end
        local function setFromPos(pos) setValue(min + (max - min) * math.clamp(pos, 0, 1), false) end
        track(sliderBg.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true; dragStartX = input.Position.X; bgW = math.max(sliderBg.AbsoluteSize.X, 1)
                startFraction = math.clamp((input.Position.X - sliderBg.AbsolutePosition.X) / bgW, 0, 1)
                setFromPos(startFraction)
            end
        end))
        track(UserInputService.InputEnded:Connect(function(input) if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then dragging = false end end))
        track(UserInputService.InputChanged:Connect(function(input)
            if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                setFromPos(math.clamp(startFraction + (input.Position.X - dragStartX) / bgW, 0, 1))
            end
        end))
        sliderConfigKey, sliderOccurrence = makeConfigKey(text)
        Theme.ConfigRegistry:Register(sliderConfigKey, text, "slider", function() return last end,
            function(value) setValue(value, true) end, configScope, sliderOccurrence)
        return {Set = function(value) setValue(value, true) end, Get = function() return last end}
    end
    function ElementAPI:AddColorPicker(h, s, v, callback)
        local H, S, V = h, s, v
        local SQ_H = 142
        local holder = Instance.new("Frame", container)
        holder.Size = UDim2.new(1, 0, 0, SQ_H + 8 + 14 + 8 + 24)
        holder.BackgroundTransparency = 1; holder.ZIndex = 102

        -- квадрат: слева белый, справа чистый оттенок, снизу чёрный
        local sq = Instance.new("Frame", holder)
        sq.Size = UDim2.new(1, 0, 0, SQ_H); sq.BorderSizePixel = 0; sq.ZIndex = 102
        sq.BackgroundColor3 = Color3.fromHSV(H, 1, 1)
        Instance.new("UICorner", sq).CornerRadius = UDim.new(0, 6)
        local sqStroke = Instance.new("UIStroke", sq); sqStroke.Color = Theme.Stroke; sqStroke.Thickness = 1

        local whiteLayer = Instance.new("Frame", sq)
        whiteLayer.Size = UDim2.new(1, 0, 1, 0); whiteLayer.BorderSizePixel = 0; whiteLayer.ZIndex = 103
        whiteLayer.BackgroundColor3 = Color3.new(1, 1, 1)
        Instance.new("UICorner", whiteLayer).CornerRadius = UDim.new(0, 6)
        local wg = Instance.new("UIGradient", whiteLayer)
        wg.Transparency = NumberSequence.new{NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1)}

        local blackLayer = Instance.new("Frame", sq)
        blackLayer.Size = UDim2.new(1, 0, 1, 0); blackLayer.BorderSizePixel = 0; blackLayer.ZIndex = 104
        blackLayer.BackgroundColor3 = Color3.new(0, 0, 0)
        Instance.new("UICorner", blackLayer).CornerRadius = UDim.new(0, 6)
        local bgGrad = Instance.new("UIGradient", blackLayer)
        bgGrad.Rotation = 90
        bgGrad.Transparency = NumberSequence.new{NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0)}

        local marker = Instance.new("Frame", sq)
        marker.Size = UDim2.new(0, 14, 0, 14); marker.AnchorPoint = Vector2.new(0.5, 0.5)
        marker.BackgroundTransparency = 1; marker.ZIndex = 106
        Instance.new("UICorner", marker).CornerRadius = UDim.new(1, 0)
        local mOuter = Instance.new("UIStroke", marker); mOuter.Color = Color3.new(0, 0, 0); mOuter.Thickness = 3
        local markerIn = Instance.new("Frame", marker)
        markerIn.Size = UDim2.new(1, 0, 1, 0); markerIn.BackgroundTransparency = 1; markerIn.ZIndex = 107
        Instance.new("UICorner", markerIn).CornerRadius = UDim.new(1, 0)
        local mInner = Instance.new("UIStroke", markerIn); mInner.Color = Color3.new(1, 1, 1); mInner.Thickness = 1.5

        -- полоса оттенка (радуга) и ползунок
        local hueBar = Instance.new("Frame", holder)
        hueBar.Position = UDim2.new(0, 0, 0, SQ_H + 8); hueBar.Size = UDim2.new(1, 0, 0, 14)
        hueBar.BorderSizePixel = 0; hueBar.ZIndex = 102; hueBar.BackgroundColor3 = Color3.new(1, 1, 1)
        Instance.new("UICorner", hueBar).CornerRadius = UDim.new(0, 5)
        local hg = Instance.new("UIGradient", hueBar)
        hg.Color = ColorSequence.new{
            ColorSequenceKeypoint.new(0,     Color3.fromHSV(0, 1, 1)),
            ColorSequenceKeypoint.new(1 / 6, Color3.fromHSV(1 / 6, 1, 1)),
            ColorSequenceKeypoint.new(2 / 6, Color3.fromHSV(2 / 6, 1, 1)),
            ColorSequenceKeypoint.new(3 / 6, Color3.fromHSV(3 / 6, 1, 1)),
            ColorSequenceKeypoint.new(4 / 6, Color3.fromHSV(4 / 6, 1, 1)),
            ColorSequenceKeypoint.new(5 / 6, Color3.fromHSV(5 / 6, 1, 1)),
            ColorSequenceKeypoint.new(1,     Color3.fromHSV(0, 1, 1)),
        }
        local knob = Instance.new("Frame", hueBar)
        knob.Size = UDim2.new(0, 6, 1, 8); knob.AnchorPoint = Vector2.new(0.5, 0.5)
        knob.BackgroundColor3 = Color3.new(1, 1, 1); knob.BorderSizePixel = 0; knob.ZIndex = 103
        Instance.new("UICorner", knob).CornerRadius = UDim.new(0, 3)
        local knobStroke = Instance.new("UIStroke", knob); knobStroke.Color = Color3.new(0, 0, 0); knobStroke.Thickness = 1

        -- превью выбранного цвета
        local previewY = SQ_H + 8 + 14 + 8
        local preview = Instance.new("Frame", holder)
        preview.Position = UDim2.new(0, 0, 0, previewY); preview.Size = UDim2.new(0, 44, 0, 24)
        preview.BorderSizePixel = 0; preview.ZIndex = 102
        Instance.new("UICorner", preview).CornerRadius = UDim.new(0, 5)
        local pStroke = Instance.new("UIStroke", preview); pStroke.Color = Theme.Stroke; pStroke.Thickness = 1
        local hexLbl = Instance.new("TextLabel", holder)
        hexLbl.Position = UDim2.new(0, 52, 0, previewY); hexLbl.Size = UDim2.new(1, -52, 0, 24)
        hexLbl.BackgroundTransparency = 1; hexLbl.Font = Enum.Font.GothamMedium; hexLbl.TextSize = 12
        hexLbl.TextColor3 = Theme.Text; hexLbl.TextXAlignment = Enum.TextXAlignment.Left; hexLbl.ZIndex = 102

        local function refresh()
            local c = Color3.fromHSV(H, S, V)
            sq.BackgroundColor3 = Color3.fromHSV(H, 1, 1)
            marker.Position = UDim2.new(S, 0, 1 - V, 0)
            knob.Position = UDim2.new(H, 0, 0.5, 0)
            preview.BackgroundColor3 = c
            local r, g, b = math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5)
            hexLbl.Text = string.format("#%02X%02X%02X   (%d, %d, %d)", r, g, b, r, g, b)
        end
        refresh()

        local colorConfigKey, colorOccurrence
        local function fire()
            if colorConfigKey then Theme.ConfigRegistry:Store(colorConfigKey, {H, S, V}) end
            if callback then pcall(callback, H, S, V) end
        end
        local function pressed(input)
            return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
        end
        local function moved(input)
            return input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch
        end
        local function setFromSquare(pos)
            S = math.clamp((pos.X - sq.AbsolutePosition.X) / math.max(sq.AbsoluteSize.X, 1), 0, 1)
            V = 1 - math.clamp((pos.Y - sq.AbsolutePosition.Y) / math.max(sq.AbsoluteSize.Y, 1), 0, 1)
            refresh(); fire()
        end
        local function setFromHue(pos)
            H = math.clamp((pos.X - hueBar.AbsolutePosition.X) / math.max(hueBar.AbsoluteSize.X, 1), 0, 0.999)
            refresh(); fire()
        end
        local function setHSV(nh, ns, nv, invokeCallback)
            H = math.clamp(tonumber(nh) or H, 0, 0.999)
            S = math.clamp(tonumber(ns) or S, 0, 1)
            V = math.clamp(tonumber(nv) or V, 0, 1)
            refresh()
            if invokeCallback then fire() end
        end

        local mode = nil
        track(sq.InputBegan:Connect(function(input)
            if pressed(input) then mode = "sq"; setFromSquare(input.Position) end
        end))
        track(hueBar.InputBegan:Connect(function(input)
            if pressed(input) then mode = "hue"; setFromHue(input.Position) end
        end))

        local conns = {}
        local function alive()
            if holder.Parent and holder:IsDescendantOf(ScreenGui) then return true end
            for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
            conns = {}
            return false
        end
        conns[#conns + 1] = UserInputService.InputChanged:Connect(function(input)
            if not mode or not moved(input) or not alive() then return end
            if mode == "sq" then setFromSquare(input.Position) else setFromHue(input.Position) end
        end)
        conns[#conns + 1] = UserInputService.InputEnded:Connect(function(input)
            if pressed(input) then mode = nil end
        end)

        colorConfigKey, colorOccurrence = makeConfigKey("Color Picker")
        Theme.ConfigRegistry:Register(colorConfigKey, "Color Picker", "color3hsv", function() return {H, S, V} end,
            function(value)
                if type(value) == "table" then setHSV(value[1] or value.h, value[2] or value.s, value[3] or value.v, true) end
            end, configScope, colorOccurrence)
        return {
            Set = function(nh, ns, nv) setHSV(nh, ns, nv, false) end,
            Get = function() return H, S, V end,
            Alive = alive,
        }
    end

    function ElementAPI:AddButton(text, callback, settingsBuilder)
        local btn = Instance.new("TextButton", container)
        btn.Size = UDim2.new(1, 0, 0, 30); btn.BackgroundColor3 = Theme.Element; btn.Text = text
        btn.Font = Enum.Font.GothamBold; btn.TextSize = 12; btn.TextColor3 = Theme.Text; btn.AutoButtonColor = false; btn.BorderSizePixel = 0
        Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 6)
        local stroke = Instance.new("UIStroke", btn); stroke.Color = Theme.Stroke; stroke.Thickness = 1; stroke.Transparency = 0.38
        track(btn.MouseEnter:Connect(function()
            TweenService:Create(btn, TweenInfo.new(0.12), {BackgroundColor3 = Theme.ElementHover}):Play()
            TweenService:Create(stroke, TweenInfo.new(0.12), {Color = Theme.BloodRed, Transparency = 0.12}):Play()
        end))
        track(btn.MouseLeave:Connect(function()
            TweenService:Create(btn, TweenInfo.new(0.14), {BackgroundColor3 = Theme.Element}):Play()
            TweenService:Create(stroke, TweenInfo.new(0.14), {Color = Theme.Stroke, Transparency = 0.38}):Play()
        end))
        track(btn.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton2 then return end
            -- ПКМ открывает настройки, только когда у кнопки есть свой содержательный
            -- билдер (карточки Watermark / GUI и т.п.). Дефолтный color-picker на
            -- любую кнопку убран.
            if settingsBuilder then
                openSettingsWindow(text, settingsBuilder)
            end
        end))
        track(btn.MouseButton1Click:Connect(function() if callback then pcall(callback) end end))
        return btn
    end
    function ElementAPI:AddDropdown(text, options, defaultIndex, callback, maxVisibleOptions)
        defaultIndex = defaultIndex or 1
        local HEAD_H, OPT_H = 28, 26
        local wrapper = Instance.new("Frame", container)
        wrapper.Size = UDim2.new(1, 0, 0, HEAD_H); wrapper.BackgroundTransparency = 1; wrapper.ClipsDescendants = true

        local head = Instance.new("TextButton", wrapper)
        head.Size = UDim2.new(1, 0, 0, HEAD_H); head.BackgroundColor3 = Theme.Element; head.Text = ""; head.AutoButtonColor = false
        Instance.new("UICorner", head).CornerRadius = UDim.new(0, 6)
        local headStroke = Instance.new("UIStroke", head); headStroke.Color = Theme.Stroke; headStroke.Thickness = 1

        local headLbl = Instance.new("TextLabel", head)
        headLbl.Size = UDim2.new(1, -70, 1, 0); headLbl.Position = UDim2.new(0, 10, 0, 0); headLbl.BackgroundTransparency = 1
        headLbl.Font = Enum.Font.GothamMedium; headLbl.TextSize = 12; headLbl.TextColor3 = Theme.Text; headLbl.TextXAlignment = Enum.TextXAlignment.Left

        local headDot = Instance.new("Frame", head)
        headDot.Size = UDim2.new(0, 12, 0, 12); headDot.Position = UDim2.new(1, -46, 0.5, -6); headDot.BorderSizePixel = 0
        Instance.new("UICorner", headDot).CornerRadius = UDim.new(1, 0)
        local dotStroke = Instance.new("UIStroke", headDot); dotStroke.Color = Color3.fromRGB(255, 255, 255); dotStroke.Thickness = 1; dotStroke.Transparency = 0.6

        local arrow = Instance.new("TextLabel", head)
        arrow.Size = UDim2.new(0, 20, 1, 0); arrow.Position = UDim2.new(1, -26, 0, 0); arrow.BackgroundTransparency = 1
        arrow.Font = Enum.Font.GothamBold; arrow.TextSize = 11; arrow.TextColor3 = Theme.TextDark; arrow.Text = "v"

        local visibleRows = tonumber(maxVisibleOptions) and math.clamp(math.floor(maxVisibleOptions), 1, #options) or #options
        local isScrollable = visibleRows < #options
        local list = Instance.new(isScrollable and "ScrollingFrame" or "Frame", wrapper)
        list.Position = UDim2.new(0, 0, 0, HEAD_H + 4); list.Size = UDim2.new(1, 0, 0, visibleRows * OPT_H)
        list.BackgroundColor3 = Theme.Section; list.BorderSizePixel = 0
        if isScrollable then
            list.CanvasSize = UDim2.new(0, 0, 0, #options * OPT_H)
            list.ScrollBarThickness = 3; list.ScrollBarImageColor3 = Theme.BloodRed
            list.ScrollingDirection = Enum.ScrollingDirection.Y
        end
        Instance.new("UICorner", list).CornerRadius = UDim.new(0, 6)
        local listStroke = Instance.new("UIStroke", list); listStroke.Color = Theme.Stroke; listStroke.Thickness = 1
        local listLayout = Instance.new("UIListLayout", list); listLayout.SortOrder = Enum.SortOrder.LayoutOrder

        local selected = defaultIndex
        local dropdownConfigKey, dropdownOccurrence
        local isOpen = false
        local headHovered = false
        local optionButtons = {}
        local hoveredPage, savedPageScrolling
        local function releasePageScroll()
            if hoveredPage then
                pcall(function() if hoveredPage.Parent then hoveredPage.ScrollingEnabled = savedPageScrolling end end)
                hoveredPage, savedPageScrolling = nil, nil
            end
        end
        if isScrollable then
            list.Visible = false
            list.Active = true
            track(list.MouseEnter:Connect(function()
                if not isOpen or hoveredPage then return end
                if Nav.cancelPager then pcall(Nav.cancelPager) end
                local node = list.Parent
                while node do
                    if node:IsA("ScrollingFrame") then
                        hoveredPage, savedPageScrolling = node, node.ScrollingEnabled
                        node.ScrollingEnabled = false
                        break
                    end
                    node = node.Parent
                end
            end))
            track(list.MouseLeave:Connect(releasePageScroll))
            track(list.Destroying:Connect(releasePageScroll))
        end

        local function refreshHead()
            local o = options[selected]
            headLbl.Text = text .. ": " .. o.name
            headDot.BackgroundColor3 = o.color
        end

        local function setOpen(open)
            isOpen = open
            if isScrollable then
                list.Visible = open
                local lists = Theme.OpenDropdownScrollLists
                if open then
                    if not lists then lists = setmetatable({}, {__mode = "k"}); Theme.OpenDropdownScrollLists = lists end
                    lists[list] = releasePageScroll
                else
                    if lists then lists[list] = nil end
                    releasePageScroll()
                end
            end
            local h = open and (HEAD_H + 4 + visibleRows * OPT_H) or HEAD_H
            TweenService:Create(wrapper, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Size = UDim2.new(1, 0, 0, h)}):Play()
            arrow.Text = open and "^" or "v"
            headStroke.Color = open and Theme.BloodGlow or (headHovered and Theme.BloodRed or Theme.Stroke)
            head.BackgroundColor3 = (open or headHovered) and Theme.ElementHover or Theme.Element
        end
        track(head.MouseEnter:Connect(function()
            headHovered = true
            head.BackgroundColor3 = Theme.ElementHover
            headStroke.Color = isOpen and Theme.BloodGlow or Theme.BloodRed
        end))
        track(head.MouseLeave:Connect(function()
            headHovered = false
            head.BackgroundColor3 = isOpen and Theme.ElementHover or Theme.Element
            headStroke.Color = isOpen and Theme.BloodGlow or Theme.Stroke
        end))

        local function refreshOptions()
            for i, b in ipairs(optionButtons) do
                b.BackgroundColor3 = (i == selected) and Theme.ElementHover or Theme.Section
                b.TextColor3 = (i == selected) and Theme.Text or Theme.TextDark
            end
        end

        for i, o in ipairs(options) do
            local b = Instance.new("TextButton", list)
            b.Size = UDim2.new(1, 0, 0, OPT_H); b.LayoutOrder = i; b.BorderSizePixel = 0; b.AutoButtonColor = false
            b.BackgroundColor3 = Theme.Section; b.Font = Enum.Font.GothamMedium; b.TextSize = 12; b.TextColor3 = Theme.TextDark
            b.Text = "   " .. o.name; b.TextXAlignment = Enum.TextXAlignment.Left
            local dot = Instance.new("Frame", b)
            dot.Size = UDim2.new(0, 12, 0, 12); dot.Position = UDim2.new(1, -24, 0.5, -6); dot.BackgroundColor3 = o.color; dot.BorderSizePixel = 0
            Instance.new("UICorner", dot).CornerRadius = UDim.new(1, 0)
            local ds = Instance.new("UIStroke", dot); ds.Color = Color3.fromRGB(255, 255, 255); ds.Thickness = 1; ds.Transparency = 0.6
            optionButtons[i] = b
            track(b.MouseEnter:Connect(function() if i ~= selected then b.BackgroundColor3 = Theme.Element end end))
            track(b.MouseLeave:Connect(function() refreshOptions() end))
            track(b.MouseButton1Click:Connect(function()
                selected = i
                refreshHead(); refreshOptions(); setOpen(false)
                if callback then pcall(callback, o.name, o.color, i) end
            end))
        end

        track(head.MouseButton1Click:Connect(function() setOpen(not isOpen) end))
        refreshHead(); refreshOptions()
        if callback then pcall(callback, options[selected].name, options[selected].color, selected) end

        local function selectValue(value, silent)
            if type(value) == "string" then value = LegacyNames[value] or value end
            local idx = tonumber(value)
            if not idx then
                for i, option in ipairs(options) do if option.name == value then idx = i; break end end
            end
            if idx and options[idx] then
                selected = idx; refreshHead(); refreshOptions(); setOpen(false)
                if dropdownConfigKey then Theme.ConfigRegistry:Store(dropdownConfigKey, options[idx].name) end
                if callback and not silent then pcall(callback, options[idx].name, options[idx].color, idx) end
            end
        end
        dropdownConfigKey, dropdownOccurrence = makeConfigKey(text)
        Theme.ConfigRegistry:Register(dropdownConfigKey, text, "dropdown", function() return options[selected].name end,
            function(value) selectValue(value, false) end, configScope, dropdownOccurrence)
        return {
            Set = function(i, silent) selectValue(i, silent) end,
            Get = function() return selected end,
        }
    end
    return ElementAPI
end

