local guiSettingsBuilder = function(api)
    local mh, ms, mv = Theme.BloodRed:ToHSV()
    api:AddColorPicker(mh, ms, mv, function(h, sat, val)
        local c = Color3.fromHSV(h, sat, val)
        if Theme.Runtime and Theme.Runtime.SetCustomAccent then
            Theme.Runtime.SetCustomAccent(c)
        else
            Theme.BloodRed = c
            mainStroke.Color = c
            borderGlow.Color = c
        end
    end)
    api:AddSlider("UI Scale (Size %)", 70, 130, math.floor(uiScale.Scale * 100 + 0.5), function(v) uiScale.Scale = v / 100 end)
    -- Прозрачность меню: выключено по умолчанию. Сохраняем исходные значения,
    -- чтобы выключение возвращало интерфейс в первоначальный вид, а не осветляло его.
    local menuTransparencyEnabled = false
    local menuTransparencyAmount = 0
    local originalMenuTransparency = {}

    local function applyMenuTransparency()
        for _, obj in ipairs(Main:GetDescendants()) do
            if (obj:IsA("Frame") or obj:IsA("TextButton") or obj:IsA("TextBox") or obj:IsA("ScrollingFrame"))
                and obj.Name ~= "Shadow" then
                if originalMenuTransparency[obj] == nil then
                    originalMenuTransparency[obj] = obj.BackgroundTransparency
                end
                local baseTransparency = originalMenuTransparency[obj]
                if menuTransparencyEnabled then
                    -- Применяем именно прозрачность фона, сохраняя изначальную прозрачность элементов.
                    obj.BackgroundTransparency = baseTransparency + (1 - baseTransparency) * menuTransparencyAmount
                else
                    obj.BackgroundTransparency = baseTransparency
                end
            end
        end
    end

    api:AddToggle("Menu Transparency", false, function(enabled)
        menuTransparencyEnabled = enabled
        applyMenuTransparency()
    end)
    api:AddSlider("Transparency amount (%)", 0, 80, 35, function(v)
        menuTransparencyAmount = v / 100
        if menuTransparencyEnabled then
            applyMenuTransparency()
        end
    end)
end

