local thAvatar = Instance.new("ImageLabel", TargetHUD); thAvatar.Size = UDim2.new(0, 38, 0, 38); thAvatar.Position = UDim2.new(0, 9, 0, 9); thAvatar.BackgroundColor3 = Theme.Element; thAvatar.BorderSizePixel = 0; thAvatar.ZIndex = 51
