end))

function getClosestPlayerToCursor()
    local closestPlayer = nil; local shortestDistance = math.huge; local mousePos = UserInputService:GetMouseLocation()
    for _, player in ipairs(Players:GetPlayers()) do
                nTotal = nTotal + 1
        if player ~= LocalPlayer and player.Character and player.Character:FindFirstChild("Humanoid") and player.Character.Humanoid.Health > 0 then
            local targetPart = player.Character:FindFirstChild("Head") or player.Character:FindFirstChild("HumanoidRootPart")
            if targetPart then
                local screenPos, onScreen = Camera:WorldToViewportPoint(targetPart.Position)
                if onScreen then
                    local distance = (Vector2.new(screenPos.X, screenPos.Y) - mousePos).Magnitude
                    if distance < shortestDistance then shortestDistance = distance; closestPlayer = player end
                end
            end
        end
    end
    return closestPlayer
end

track(UserInputService.InputBegan:Connect(function(input, gp)
    if Unloaded or gp or Theme.CapturingKey or not aimbotEnabled then return end
    if input.KeyCode == aimLockKey then
        if isAimingAtTarget then isAimingAtTarget = false; currentTarget = nil; TargetHUD.Visible = false
        else
            currentTarget = getClosestPlayerToCursor()
            if currentTarget then isAimingAtTarget = true; TargetHUD.Visible = true; thName.Text = currentTarget.Name; pcall(function() thAvatar.Image = Players:GetUserThumbnailAsync(currentTarget.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size420x420) end) end
        end
    end
end))

function getOrCreateArrow(index)
    if not shadowsPool[index] then local shadow = Drawing.new("Triangle"); shadow.Filled = true; shadow.Thickness = 1; shadow.Transparency = arrowGlow and 0.18 or 0.65; shadow.Color = arrowGlow and arrowColor or Color3.fromRGB(0, 0, 0); shadow.Visible = false; shadowsPool[index] = shadow end
    if not arrowsPool[index] then local triangle = Drawing.new("Triangle"); triangle.Filled = true; triangle.Thickness = 1; triangle.Transparency = arrowTransparency; triangle.Color = arrowColor; triangle.Visible = false; arrowsPool[index] = triangle end
    return arrowsPool[index], shadowsPool[index]
end

local arrowUpdateAccumulator = 0
local arrowPoolWasVisible = false
track(RunService.RenderStepped:Connect(function(dt)
    if Unloaded then return end
    -- When both systems are idle, avoid repeated character/humanoid lookups every frame.
    if not arrowsEnabled and not isAimingAtTarget then
        if arrowPoolWasVisible then
            for _, arrow in ipairs(arrowsPool) do arrow.Visible = false end
            for _, shadow in ipairs(shadowsPool) do shadow.Visible = false end
            arrowPoolWasVisible = false
        end
        return
    end

    local myChar = LocalPlayer and LocalPlayer.Character
    if isAimingAtTarget then
        local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
        if not aimbotEnabled or not myHum or myHum.Health <= 0 then
            isAimingAtTarget = false
            currentTarget = nil
            TargetHUD.Visible = false
        end
    end

    -- Lock rotation and HUD still update each rendered frame when explicitly enabled.
    if aimbotEnabled and isAimingAtTarget and currentTarget and currentTarget.Character then
        local targetHum = currentTarget.Character:FindFirstChildOfClass("Humanoid")
        if targetHum and targetHum.Health > 0 then
            local targetRoot = currentTarget.Character:FindFirstChild("HumanoidRootPart")
            local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if myRoot and targetRoot then
                local aimCF = Theme.GetBacktrackRootCF and Theme.GetBacktrackRootCF(currentTarget)
                local aimPos = (aimCF and aimCF.Position) or targetRoot.Position
                local pos = myRoot.Position
                local flat = Vector3.new(aimPos.X, pos.Y, aimPos.Z)
                if (flat - pos).Magnitude > 0.5 then myRoot.CFrame = CFrame.lookAt(pos, flat) end
            end
            local hpPercent = math.clamp(targetHum.Health / math.max(targetHum.MaxHealth, 1), 0, 1)
            thHpBarFill.Size = UDim2.new(hpPercent, 0, 1, 0)
            thHpText.Text = math.floor(hpPercent * 100) .. "%"
        else
            isAimingAtTarget = false
            currentTarget = nil
            TargetHUD.Visible = false
        end
    elseif isAimingAtTarget then
        isAimingAtTarget = false
        currentTarget = nil
        TargetHUD.Visible = false
    end

    if arrowsEnabled then
        if not Camera then return end
        if not Drawing or type(Drawing.new) ~= "function" then
            if not Theme.WarnedDrawingMissing then
                Theme.WarnedDrawingMissing = true
                warn("[FaceLess] Target Arrows require Drawing API support in the executor.")
            end
            return
        end
        arrowUpdateAccumulator = arrowUpdateAccumulator + dt
        local arrowInterval = Theme.ExtremePerformance and (1 / 24) or (1 / 30)
        if arrowUpdateAccumulator < arrowInterval then return end
        arrowUpdateAccumulator = arrowUpdateAccumulator % arrowInterval
        local viewportSize = Camera.ViewportSize
        local center = viewportSize / 2
        local arrowIdx = 1
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer and player.Character then
                local hum = player.Character:FindFirstChildOfClass("Humanoid")
                if hum and hum.Health > 0 then
                    local targetPart = player.Character:FindFirstChild("Head") or player.Character:FindFirstChild("HumanoidRootPart")
                    if targetPart then
                        local screenPos = Camera:WorldToViewportPoint(targetPart.Position)
                        local angle = math.atan2(screenPos.Y - center.Y, screenPos.X - center.X)
                        local arrowCenter = center + Vector2.new(math.cos(angle), math.sin(angle)) * arrowRadius
                        local p1 = arrowCenter + Vector2.new(math.cos(angle), math.sin(angle)) * 11
                        local p2 = arrowCenter + Vector2.new(math.cos(angle + math.rad(125)), math.sin(angle + math.rad(125))) * 7
                        local p3 = arrowCenter + Vector2.new(math.cos(angle - math.rad(125)), math.sin(angle - math.rad(125))) * 7
                        local arrow, shadow = getOrCreateArrow(arrowIdx)
                        shadow.PointA = p1 + Vector2.new(1, 2)
                        shadow.PointB = p2 + Vector2.new(1, 2)
                        shadow.PointC = p3 + Vector2.new(1, 2)
                        shadow.Visible = true
                        arrow.PointA, arrow.PointB, arrow.PointC = p1, p2, p3
                        arrow.Color = (currentTarget == player and isAimingAtTarget) and Theme.BloodGlow or Color3.fromRGB(230, 230, 230)
                        arrow.Transparency = arrowTransparency
                        arrow.Visible = true
                        arrowIdx = arrowIdx + 1
                    end
                end
            end
        end
        for i = arrowIdx, #arrowsPool do
            arrowsPool[i].Visible = false
            if shadowsPool[i] then shadowsPool[i].Visible = false end
        end
        arrowPoolWasVisible = true
    elseif arrowPoolWasVisible then
        for _, arrow in ipairs(arrowsPool) do arrow.Visible = false end
        for _, shadow in ipairs(shadowsPool) do shadow.Visible = false end
        arrowPoolWasVisible = false
    end
end))

-- ===== PVP / MOVEMENT: карточки создаются здесь, чтобы занять первые позиции =====
-- Сами обработчики подключаются в конце файла (см. блоки initPvP / initMovement):
-- так новые локальные переменные не расходуют регистры основного чанка.
