-- 3. CHAMS
local secChamsSettings = createSection(espTab.Left, "Chams Settings")
local chamsEnabled = false
local chamsMode = "Fill" -- "Fill" | "Outline"
local chamsColor = Color3.fromRGB(255, 60, 60)
local chamsIntensity = 0.8
local chamsFillTrans = 0.55
local chamsOutlineTrans = 0

local function chamsShellColor()
    local h, s, v = chamsColor:ToHSV()
    local I = chamsIntensity
    return Color3.fromHSV(h, math.clamp(s * (0.35 + 0.65 * I), 0, 1), math.clamp(v * (0.45 + 0.55 * I), 0, 1))
end

local chamsCache = {}
local function chamsDestroy(cache)
    if cache.hl then pcall(function() cache.hl:Destroy() end) end
    if cache.folder then pcall(function() cache.folder:Destroy() end) end
end
function chamsDestroyAll()
    for pl, cache in pairs(chamsCache) do chamsDestroy(cache) end
    chamsCache = {}
end

local function applyChamsTo(player)
    local char = player.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local valid = chamsEnabled and hum and hum.Health > 0 and char:FindFirstChild("HumanoidRootPart") ~= nil
    local cache = chamsCache[player]
    if not valid then
        if cache and cache.hl then cache.hl.Enabled = false end
        return
    end
    if not cache or not cache.hl or not cache.hl.Parent then
        if cache then chamsDestroy(cache) end
        local hl = Instance.new("Highlight")
        hl.Name = "SatanicChams"
        hl.Adornee = char
        hl.DepthMode = Enum.HighlightDepthMode.Occluded
        hl.Parent = char
        cache = {hl = hl, folder = nil, core = nil}
        chamsCache[player] = cache
    end
    local hl = cache.hl
    hl.Enabled = true
    if hl.Adornee ~= char then hl.Adornee = char end
    if chamsMode == "Outline" then
        hl.FillTransparency = 1
        hl.OutlineTransparency = chamsOutlineTrans
        hl.OutlineColor = chamsColor
        hl.FillColor = chamsColor
    else
        hl.FillTransparency = chamsFillTrans
        hl.OutlineTransparency = 0.15
        hl.FillColor = chamsShellColor()
        hl.OutlineColor = chamsColor:Lerp(Color3.new(1, 1, 1), 0.35)
    end
end

secChamsSettings:AddToggle("Enable Chams", false, function(state)
    chamsEnabled = state
    if not state then chamsDestroyAll() end
end, function(api)
    local h0, s0, v0 = chamsColor:ToHSV()
    api:AddColorPicker(h0, s0, v0, function(h, s, v) chamsColor = Color3.fromHSV(h, s, v) end)
    api:AddSlider("Intensity (%)", 0, 100, 80, function(v) chamsIntensity = v / 100 end, 1)
    api:AddSlider("Fill Transparency (%)", 0, 100, 55, function(v) chamsFillTrans = v / 100 end, 1)
    api:AddSlider("Outline Transparency (%)", 0, 100, 0, function(v) chamsOutlineTrans = v / 100 end, 1)
end)
local chamsModeBtn
chamsModeBtn = secChamsSettings:AddButton("Mode: Fill", function()
    chamsMode = (chamsMode == "Fill") and "Outline" or "Fill"
    chamsModeBtn.Text = "Mode: " .. chamsMode
end)



local chamsUpdateAccumulator = 0
track(RunService.Heartbeat:Connect(function(dt)
    if Unloaded then
        if next(chamsCache) then chamsDestroyAll() end
        return
    end
    if not chamsEnabled then return end
    chamsUpdateAccumulator = chamsUpdateAccumulator + dt
    if chamsUpdateAccumulator < (Theme.ExtremePerformance and 0.20 or 0.08) then return end
    chamsUpdateAccumulator = 0
    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= LocalPlayer then applyChamsTo(player) end
    end
end))

-- 5. VISUALS & HATS & FOG
local leftVis = visualTab.Left; local rightVis = visualTab.Right
local secVisualBodies = createSection(leftVis, "Visual Bodies")
local korbloxEnabled = false; local headlessEnabled = false

function applyKorblox()
    local char = LocalPlayer.Character; if not char then return end
    local rightLeg = char:FindFirstChild("Right Leg") or char:FindFirstChild("RightUpperLeg"); if not rightLeg then return end
    local existing = rightLeg:FindFirstChild("KorbloxMesh"); if existing then existing:Destroy() end
    if not korbloxEnabled then return end
    local mesh = Instance.new("SpecialMesh", rightLeg); mesh.Name = "KorbloxMesh"; mesh.MeshType = Enum.MeshType.FileMesh; mesh.MeshId = "rbxassetid://139607718"
end

function applyHeadless()
    local char = LocalPlayer.Character; if not char then return end
    local head = char:FindFirstChild("Head"); if not head then return end
    for _, d in ipairs(head:GetChildren()) do if d:IsA("Decal") then d.Transparency = headlessEnabled and 1 or 0 end end
    local existing = head:FindFirstChild("HeadlessMesh"); if existing then existing:Destroy() end
    if headlessEnabled then
        local mesh = Instance.new("SpecialMesh", head); mesh.Name = "HeadlessMesh"; mesh.MeshType = Enum.MeshType.FileMesh; mesh.MeshId = "rbxassetid://15093053680"
    end
end

secVisualBodies:AddToggle("korblox", false, function(state) korbloxEnabled = state; applyKorblox() end)
secVisualBodies:AddToggle("headless", false, function(state) headlessEnabled = state; applyHeadless() end)

-- CUSTOM HATS & EFFECTS
print("[Satanic] ok: VISUALS — секции до Custom Hats")
local secCustomHats = createSection(leftVis, "Custom Hats & Effects")
local customHatEnabled = false; local hatMode = "China hat"
local hatSizeX, hatSizeY, hatSizeZ = 4, 2, 4
local hatR, hatG, hatB = 255, 0, 255
local hatGlow = true
local modesList = {"China hat", "Halo", "Horns", "Lightning"}; local modeIndex = 1
local hatFolder, hatParts, hatGroups = nil, {}, {}
local hatModeBtn = nil
local hatBuilders = {
    HeadMount = nil, HaloPointLight = nil,
    HornYOffset = 0.10, HatYOffset = 0.10, HaloYOffset = 0,
    HaloSpin = 0.55, HaloPhase = 0, HaloInnerPhase = 0,
    HeadRigPrefixes = {["China hat"] = "SatanicChinaHat", ["Halo"] = "SatanicHalo", ["Horns"] = "SatanicHorn"},
    HeadRigFolders = {["China hat"] = "SatanicChinaHatEffect", ["Halo"] = "SatanicHaloEffect", ["Horns"] = "SatanicHornsEffect"},
}
local hatStaticWelded, hatBoundAnchor, hatPhysicsRoot = false, nil, nil

function lighter(c, a) return c:Lerp(Color3.new(1, 1, 1), a) end

function newGroup(fn)
    local g = {fn = fn, cf = CFrame.new()}
    hatGroups[#hatGroups + 1] = g
    return g
end

function addPart(cf, size, color, opts)
    opts = opts or {}
    local p = Instance.new("Part")
    p.Anchored = true; p.CanCollide = false; p.CanQuery = false; p.CanTouch = false; p.Massless = true; p.CastShadow = false
    p.TopSurface = Enum.SurfaceType.Smooth; p.BottomSurface = Enum.SurfaceType.Smooth
    if opts.shape then p.Shape = opts.shape end
    p.Material = opts.material or (hatGlow and Enum.Material.Neon or Enum.Material.SmoothPlastic)
    p.Color = color
    p.Size = size
    p.Transparency = opts.transparency or 0
    p.Parent = hatFolder
    local entry = {part = p, cf = cf, group = opts.group or hatGroups[1], fn = opts.fn}
    hatParts[#hatParts + 1] = entry
    return entry
end

local CYL = CFrame.Angles(0, 0, math.rad(90))

-- CYBER RONIN: a layered metal conical hat with segmented illuminated rim,
-- radial armored ribs and an angular crown. The existing size/color/glow and
-- Hat Height Offset settings still apply; no bright ball is used for the tip.
hatBuilders["China hat"] = function(sx, sy, sz, col, base)
    local character = LocalPlayer and LocalPlayer.Character
    local head = character and character:FindFirstChild("Head")
    if not head or not head:IsA("BasePart") then return end
    local sx2, sz2 = math.clamp(sx, 0.25, 2.5), math.clamp(sz, 0.25, 2.5)
    local sy2 = math.clamp(sy, 0.5, 5)
    local h = 1.25 * sy2
    local baseY = head.Size.Y * 0.5 + (hatBuilders.HatYOffset or 0.10)
    local scale = math.clamp(math.sqrt((sx2 + sz2) * 0.5), 0.5, 1.6)
    local dark = Color3.fromRGB(19, 25, 33):Lerp(col, 0.08)
    local panel = Color3.fromRGB(46, 56, 67):Lerp(col, 0.12)
    local metal = Color3.fromRGB(94, 109, 120):Lerp(col, 0.14)
    local chrome = Color3.fromRGB(181, 194, 201):Lerp(col, 0.16)
    local accent = col:Lerp(Color3.fromRGB(245, 250, 255), 0.12)
    local lightMat = hatGlow and Enum.Material.Neon or Enum.Material.Metal
    local tau = math.pi * 2
    local function radius(t) return 1.50 * (1 - math.clamp(t, 0, 1))^0.92 + 0.08 end
    local function point(a, r, y)
        return Vector3.new(math.cos(a) * r * sx2, y, math.sin(a) * r * sz2)
    end
    local function piece(name, cf, wanted, color, material, shape, meshType)
        local actual = Vector3.new(math.max(0.06, wanted.X), math.max(0.06, wanted.Y), math.max(0.06, wanted.Z))
        local entry = addPart(cf, actual, color, {group = base, material = material, shape = shape})
        entry.part.Name = name
        if meshType or wanted.X < 0.06 or wanted.Y < 0.06 or wanted.Z < 0.06 then
            local mesh = Instance.new("SpecialMesh")
            mesh.Name = "RoninDetailMesh"
            mesh.MeshType = meshType or (shape == Enum.PartType.Cylinder and Enum.MeshType.Cylinder or Enum.MeshType.Brick)
            mesh.Scale = Vector3.new(wanted.X / actual.X, wanted.Y / actual.Y, wanted.Z / actual.Z)
            mesh.Parent = entry.part
        end
        return entry
    end
    local function bar(name, a, b, width, thickness, color, material)
        local d = b - a
        if d.Magnitude < 0.001 then return end
        piece(name, CFrame.lookAt((a + b) * 0.5, b),
            Vector3.new(width, thickness, d.Magnitude * 1.04), color, material)
    end

    -- Dark layered cone beneath all of the armor and circuitry.
    local layers = Theme.ExtremePerformance and 12 or 20
    local layerH = h / layers
    for i = 0, layers - 1 do
        local t = (i + 0.5) / layers
        local rad = radius(t)
        local shade = dark:Lerp(panel, i % 4 == 0 and 0.70 or 0.28)
        piece("RoninCone_" .. i, CFrame.new(0, baseY + layerH*(i + 0.5), 0) * CYL,
            Vector3.new(layerH*1.18, rad*2*sx2, rad*2*sz2), shade, Enum.Material.Metal, Enum.PartType.Cylinder)
    end
    piece("RoninBrim", CFrame.new(0, baseY + 0.035, 0) * CYL,
        Vector3.new(0.11, 3.45*sx2, 3.45*sz2), dark, Enum.Material.Metal, Enum.PartType.Cylinder)

    -- Metallic segmented rim, fine neon rim, plus a raised mid-cone trace.
    local steps = Theme.ExtremePerformance and 16 or 24
    for i = 0, steps - 1 do
        local a, b = (i + 0.02)*tau/steps, (i + 0.98)*tau/steps
        local edgeY = baseY + 0.08
        bar("RoninRim_" .. i, point(a,1.69,edgeY), point(b,1.69,edgeY),
            0.13*scale, 0.09, i%4==0 and metal or panel, Enum.Material.Metal)
        bar("RoninRimLight_" .. i, point(a,1.69,edgeY+0.052), point(b,1.69,edgeY+0.052),
            0.032*scale, 0.018, accent, lightMat)
        local midT = 0.37
        local midY = baseY + h*midT + 0.055
        bar("RoninMidCircuit_" .. i, point(a,radius(midT)+0.045,midY), point(b,radius(midT)+0.045,midY),
            0.024*scale, 0.018, i%3==0 and chrome or accent, i%3==0 and Enum.Material.Metal or lightMat)
    end

    -- Sloped armored ribs conform to the cone instead of floating over its top.
    local ribs = Theme.ExtremePerformance and 8 or 12
    for i = 0, ribs - 1 do
        local a = i*tau/ribs
        for j = 1, 4 do
            local t0, t1 = 0.04 + (j-1)*0.21, 0.04 + j*0.21
            local p0 = point(a,radius(t0)+0.055,baseY+h*t0+0.03)
            local p1 = point(a,radius(t1)+0.055,baseY+h*t1+0.03)
            bar("RoninRib_" .. i .. "_" .. j, p0, p1, 0.055*scale, 0.04*scale,
                i%2==0 and metal or chrome, Enum.Material.Metal)
            if i%2==0 then
                local q0 = point(a,radius(t0)+0.083,baseY+h*t0+0.055)
                local q1 = point(a,radius(t1)+0.083,baseY+h*t1+0.055)
                bar("RoninRibLight_" .. i .. "_" .. j, q0, q1, 0.014*scale, 0.014*scale, accent, lightMat)
            end
        end
    end

    -- Four narrow projecting blades and an angular, layered top cap.
    for i = 0, 3 do
        local a = i*tau/4
        bar("RoninBrimBlade_" .. i, point(a,1.57,baseY+0.12), point(a,1.86,baseY+0.12),
            0.14*scale, 0.055, metal, Enum.Material.Metal)
        bar("RoninBladeLight_" .. i, point(a,1.64,baseY+0.153), point(a,1.83,baseY+0.153),
            0.026*scale, 0.014, accent, lightMat)
    end
    local capCF = CFrame.new(0, baseY + h + 0.045, 0) * CFrame.Angles(0, math.rad(45), 0)
    piece("RoninCrownBase", capCF, Vector3.new(0.30*scale, 0.10, 0.30*scale), metal, Enum.Material.Metal)
    piece("RoninCrownCore", capCF * CFrame.new(0, 0.09, 0), Vector3.new(0.16*scale, 0.12, 0.16*scale), dark, Enum.Material.Metal)
    piece("RoninCrownSlit", capCF * CFrame.new(0, 0.157, 0), Vector3.new(0.10*scale, 0.016, 0.035*scale), accent, lightMat)
end

-- CELESTIAL CYBER HALO: two contra-rotating, segmented rings with fine light
-- tracks, four angular crown sigils, radial fins and pulsing instrument marks.
-- All geometry is grouped into two head-mounted physical orbit pivots below.
hatBuilders["Halo"] = function(sx, sy, sz, col, base)
    local character = LocalPlayer and LocalPlayer.Character
    local head = character and character:FindFirstChild("Head")
    if not head or not head:IsA("BasePart") then return end
    local sx2, sz2 = math.clamp(sx, 0.25, 2.5), math.clamp(sz, 0.25, 2.5)
    local yScale = math.sqrt(math.clamp(sy, 0.5, 5))
    local widthScale = math.clamp(math.sqrt((sx2 + sz2) * 0.5), 0.5, 1.6)
    local rx = math.clamp(head.Size.X * 0.66, 1.08, 1.65) * sx2
    local rz = math.clamp(head.Size.Z * 1.20, 1.08, 1.65) * sz2
    local haloY = head.Size.Y * 0.5 + 0.95 + (hatBuilders.HaloYOffset or 0)
    local dark = Color3.fromRGB(20, 25, 35):Lerp(col, 0.12)
    local metal = Color3.fromRGB(78, 91, 105):Lerp(col, 0.16)
    local chrome = Color3.fromRGB(182, 195, 205):Lerp(col, 0.18)
    local light = col:Lerp(Color3.fromRGB(245, 250, 255), 0.14)
    local hot = col:Lerp(Color3.fromRGB(255, 255, 255), 0.45)
    local lightMat = hatGlow and Enum.Material.Neon or Enum.Material.Metal
    local tau = math.pi * 2
    hatBuilders.HaloLights = {}

    local function orbitY(t) return haloY + math.sin(t * 1.5) * 0.04 end
    base.fn = function(t)
        return CFrame.new(0, orbitY(t), 0) * CFrame.Angles(0, hatBuilders.HaloPhase or 0, 0)
    end
    local inner = newGroup(function(t)
        return CFrame.new(0, orbitY(t) + 0.13 * yScale, 0) * CFrame.Angles(0, hatBuilders.HaloInnerPhase or 0, 0)
    end)
    local function point(angle, radius, y)
        return Vector3.new(math.cos(angle) * rx * radius, y or 0, math.sin(angle) * rz * radius)
    end
    local function piece(group, name, cf, wanted, color, material, alpha)
        local actual = Vector3.new(math.max(0.06, wanted.X), math.max(0.06, wanted.Y), math.max(0.06, wanted.Z))
        local entry = addPart(cf, actual, color, {group = group, material = material, transparency = alpha or 0})
        entry.part.Name = name
        if wanted.X < 0.06 or wanted.Y < 0.06 or wanted.Z < 0.06 then
            local mesh = Instance.new("SpecialMesh")
            mesh.Name = "HaloPrecisionMesh"; mesh.MeshType = Enum.MeshType.Brick
            mesh.Scale = Vector3.new(wanted.X / actual.X, wanted.Y / actual.Y, wanted.Z / actual.Z)
            mesh.Parent = entry.part
        end
        return entry
    end
    local function bar(group, name, a, b, width, depth, color, material, alpha)
        local direction = b - a
        if direction.Magnitude < 0.001 then return nil end
        local cf = CFrame.lookAt((a + b) * 0.5, b)
        return piece(group, name, cf, Vector3.new(width, depth, direction.Magnitude * 1.04), color, material, alpha)
    end
    local function pulse(entry, phase)
        if entry then hatBuilders.HaloLights[#hatBuilders.HaloLights + 1] = {part = entry.part, phase = phase} end
    end

    local outerSteps = Theme.ExtremePerformance and 16 or 24
    for i = 0, outerSteps - 1 do
        local a = (i + 0.025) * tau / outerSteps
        local b = (i + 0.975) * tau / outerSteps
        local pa, pb = point(a, 1, 0), point(b, 1, 0)
        bar(base, "HaloOuterArmor_" .. i, pa, pb, 0.145 * widthScale, 0.09 * yScale,
            i % 4 == 0 and metal or dark, Enum.Material.Metal)
        local ya = 0.056 * yScale
        local strip = bar(base, "HaloOuterLight_" .. i, point(a, 1, ya), point(b, 1, ya),
            0.036 * widthScale, 0.018 * yScale, light, lightMat)
        if i % 4 == 0 then pulse(strip, i * 0.55) end
        if i % 3 == 0 then
            local mid = (a + b) * 0.5
            bar(base, "HaloOuterNotch_" .. i, point(mid, 0.955, ya + 0.008), point(mid, 1.045, ya + 0.008),
                0.025 * widthScale, 0.02 * yScale, chrome, Enum.Material.Metal)
        end
    end

    local innerSteps = Theme.ExtremePerformance and 12 or 16
    for i = 0, innerSteps - 1 do
        local a = (i + 0.02) * tau / innerSteps
        local b = (i + 0.98) * tau / innerSteps
        bar(inner, "HaloInnerArmor_" .. i, point(a, 0.76, 0), point(b, 0.76, 0),
            0.08 * widthScale, 0.06 * yScale, metal, Enum.Material.Metal)
        local strip = bar(inner, "HaloInnerLight_" .. i, point(a, 0.76, 0.039*yScale), point(b, 0.76, 0.039*yScale),
            0.034 * widthScale, 0.018 * yScale, hot, lightMat)
        if i % 4 == 0 then pulse(strip, i * 0.65 + 1.1) end
    end
    for i = 0, 7 do
        local angle = i * tau / 8
        local marker = bar(inner, "HaloIndex_" .. i, point(angle, 0.64, 0.045*yScale), point(angle, 0.72, 0.045*yScale),
            0.034 * widthScale, 0.02*yScale, i % 2 == 0 and hot or light, lightMat)
        pulse(marker, i * 0.8 + 0.4)
    end

    -- Four raised diamond-shaped sigils remain legible from eye level.
    -- Each edge has a metallic bezel and a light filament on both sides.
    for i = 0, 3 do
        local angle = math.pi / 4 + i * tau / 4
        local top = point(angle, 1.075, 0.34*yScale)
        local bottom = point(angle, 1.075, -0.11*yScale)
        local left = point(angle, 0.965, 0.11*yScale)
        local right = point(angle, 1.185, 0.11*yScale)
        local tangent = Vector3.new(-math.sin(angle), 0, math.cos(angle)).Unit
        local vertices = {top, left, bottom, right, top}
        for j = 1, 4 do
            local p, q = vertices[j], vertices[j + 1]
            bar(base, "HaloCrownFrame_" .. i .. "_" .. j, p, q, 0.072*widthScale, 0.072*widthScale, chrome, Enum.Material.Metal)
            for _, side in ipairs({-1, 1}) do
                local offset = tangent * (side * 0.038 * widthScale)
                local filament = bar(base, "HaloCrownLight_" .. i .. "_" .. j .. "_" .. side,
                    p + offset, q + offset, 0.018*widthScale, 0.018*widthScale, light, lightMat)
                if j == 1 and side == 1 then pulse(filament, i * 1.5) end
            end
        end
    end
    -- Four low-profile radial blades add a sharp, layered sci-fi silhouette.
    for i = 0, 3 do
        local angle = i * tau / 4
        bar(base, "HaloBlade_" .. i, point(angle, 1.01, 0), point(angle, 1.27, 0),
            0.12*widthScale, 0.065*yScale, metal, Enum.Material.Metal)
        bar(base, "HaloBladeLight_" .. i, point(angle, 1.04, 0.042*yScale), point(angle, 1.24, 0.042*yScale),
            0.027*widthScale, 0.018*yScale, light, lightMat)
    end
end

-- CYBER / DEMON HORNS: two tapered swept horns with metallic plating and
-- fine colored inlays. No floating light-balls or oversized glowing collars.
-- The points are local to the current Head; the rig is physically welded below.
hatBuilders["Horns"] = function(sx, sy, sz, col, base)
    local character = LocalPlayer and LocalPlayer.Character
    local head = character and character:FindFirstChild("Head")
    if not head or not head:IsA("BasePart") then return end

    local widthScale = math.clamp(sx, 0.25, 2.5)
    local heightScale = math.clamp(sy, 0.5, 5)
    local depthScale = math.clamp(sz, 0.25, 2.5)
    local thicknessScale = math.clamp((widthScale + heightScale + depthScale) / 3, 0.45, 2.2)
    local halfHead = math.clamp(head.Size.X * 0.28, 0.28, 0.80)
    local baseX = halfHead * widthScale
    local baseY = head.Size.Y * 0.5 + (hatBuilders.HornYOffset or 0.10)
    local baseZ = -head.Size.Z * 0.08
    local dark = Color3.fromRGB(15, 19, 25):Lerp(col, 0.12)
    local metal = Color3.fromRGB(65, 75, 87):Lerp(col, 0.14)
    local trim = Color3.fromRGB(138, 151, 160):Lerp(col, 0.12)
    local accent = col:Lerp(Color3.fromRGB(245, 250, 255), 0.16)
    local accentMaterial = hatGlow and Enum.Material.Neon or Enum.Material.Metal

    -- Roblox clamps very small Part dimensions; a scaled mesh keeps thin seams
    -- and the pointed tips narrow without changing their collision footprint.
    local function piece(name, cf, wanted, color, material, shape, meshType)
        local actual = Vector3.new(math.max(0.06, wanted.X), math.max(0.06, wanted.Y), math.max(0.06, wanted.Z))
        local entry = addPart(cf, actual, color, {group = base, material = material, shape = shape})
        entry.part.Name = name
        if meshType or wanted.X < 0.06 or wanted.Y < 0.06 or wanted.Z < 0.06 then
            local mesh = Instance.new("SpecialMesh")
            mesh.Name = "HornMicroMesh"
            mesh.MeshType = meshType or (shape == Enum.PartType.Cylinder and Enum.MeshType.Cylinder or Enum.MeshType.Brick)
            mesh.Scale = Vector3.new(wanted.X / actual.X, wanted.Y / actual.Y, wanted.Z / actual.Z)
            mesh.Parent = entry.part
        end
        return entry
    end
    local function segment(name, a, b, diameter, color, material)
        local d = b - a
        if d.Magnitude < 0.001 then return end
        local cf = CFrame.lookAt((a + b) * 0.5, b) * CFrame.Angles(0, math.rad(90), 0)
        piece(name, cf, Vector3.new(d.Magnitude * 1.18, diameter, diameter), color, material, Enum.PartType.Cylinder)
    end
    local function stripe(name, a, b, width, color, material)
        local d = b - a
        if d.Magnitude < 0.001 then return end
        local cf = CFrame.lookAt((a + b) * 0.5, b)
        piece(name, cf, Vector3.new(width, width * 0.72, d.Magnitude * 1.07), color, material)
    end
    local function point(a, b, c, d, t)
        local u = 1 - t
        return a * (u*u*u) + b * (3*u*u*t) + c * (3*u*t*t) + d * (t*t*t)
    end

    local steps = Theme.ExtremePerformance and 20 or 28
    for _, side in ipairs({-1, 1}) do
        local sideName = side < 0 and "L" or "R"
        local p0 = Vector3.new(side * baseX, baseY, baseZ)
        local p1 = Vector3.new(side * (baseX + 0.40*widthScale), baseY + 0.20*heightScale, baseZ + 0.05*depthScale)
        local p2 = Vector3.new(side * (baseX + 0.62*widthScale), baseY + 0.98*heightScale, baseZ + 0.25*depthScale)
        local p3 = Vector3.new(side * (baseX + 0.24*widthScale), baseY + 1.48*heightScale, baseZ + 0.40*depthScale)
        local points = {}
        for i = 0, steps do points[i + 1] = point(p0, p1, p2, p3, i / steps) end

        -- Compact layered sockets sit against the crown instead of a floating ring.
        piece("HornSocket_" .. sideName, CFrame.new(p0) * CFrame.Angles(0, 0, side*math.rad(8)),
            Vector3.new(0.36*thicknessScale, 0.12*thicknessScale, 0.30*thicknessScale), dark, Enum.Material.Metal)
        piece("HornSocketPlate_" .. sideName, CFrame.new(p0 + Vector3.new(0, 0.065*thicknessScale, 0)) * CFrame.Angles(0, 0, side*math.rad(8)),
            Vector3.new(0.25*thicknessScale, 0.035*thicknessScale, 0.21*thicknessScale), metal, Enum.Material.Metal)
        piece("HornSocketSlit_" .. sideName, CFrame.new(p0 + Vector3.new(0, 0.07*thicknessScale, 0.12*thicknessScale)),
            Vector3.new(0.15*thicknessScale, 0.016*thicknessScale, 0.014*thicknessScale), accent, accentMaterial)

        for i = 1, steps do
            local a, b = points[i], points[i + 1]
            local t0, t1 = (i - 1) / steps, i / steps
            local t = (t0 + t1) * 0.5
            local dia0 = thicknessScale * (0.30 * (1 - t0)^0.86 + 0.018)
            local dia1 = thicknessScale * (0.30 * (1 - t1)^0.86 + 0.018)
            local diameter = (dia0 + dia1) * 0.5
            local shade = dark:Lerp(metal, t * 0.80)
            segment("HornCurve_" .. sideName .. "_" .. i, a, b, diameter, shade, Enum.Material.Metal)
            -- A slender contiguous light filament follows the outside surface.
            if i >= 3 and i <= steps - 2 then
                local lift0 = Vector3.new(side * dia0 * 0.30, 0, -dia0 * 0.39)
                local lift1 = Vector3.new(side * dia1 * 0.30, 0, -dia1 * 0.39)
                stripe("HornInlay_" .. sideName .. "_" .. i, a + lift0, b + lift1,
                    0.018*thicknessScale, accent, accentMaterial)
            end
            -- Three short side bevels break up the silhouette without ball tips.
            if i == math.floor(steps*0.25) or i == math.floor(steps*0.45) or i == math.floor(steps*0.65) then
                local offset = Vector3.new(side * diameter * 0.40, 0, diameter * 0.26)
                stripe("HornRidge_" .. sideName .. "_" .. i, a + offset, b + offset,
                    0.038*thicknessScale, trim, Enum.Material.Metal)
            end
        end
        local direction = points[#points] - points[#points - 1]
        if direction.Magnitude > 0.001 then
            local length = 0.13 * thicknessScale
            local center = points[#points] + direction.Unit * (length * 0.35)
            piece("HornTip_" .. sideName, CFrame.lookAt(center, center + direction),
                Vector3.new(0.036*thicknessScale, 0.036*thicknessScale, length),
                trim:Lerp(col, 0.15), Enum.Material.Metal, nil, Enum.MeshType.Wedge)
        end
    end
end

-- CLASSIC MINECRAFT-STYLE WINGS (Drawing API)
hatBuilders["Wings"] = function(sx, sy, sz, col, base)
    -- Эта функция больше не создает 3D-парты, а использует Drawing API
end

hatBuilders["Lightning"] = function(sx, sy, sz, col, base)
    local k=math.clamp((sx+sy+sz)/3,1,2.5)
    local rng=Random.new()
    local bolts={}
    local function makeBolt(index)
        local angle=rng:NextNumber(0,math.pi*2)
        local start=Vector3.new(rng:NextNumber(-0.38,0.38)*sx,rng:NextNumber(-0.48,0.55)*sy,rng:NextNumber(-0.32,0.32)*sz)
        local length=rng:NextNumber(0.75,1.55)*k
        local finish=start+Vector3.new(math.cos(angle)*length,rng:NextNumber(-0.45,0.45)*k,math.sin(angle)*length)
        local pts={}
        local steps=9
        local bend=Vector3.new(rng:NextNumber(-0.45,0.45),rng:NextNumber(-0.55,0.55),rng:NextNumber(-0.45,0.45))*k
        for j=0,steps do
            local f=j/steps
            local envelope=math.sin(math.pi*f)
            local jitter=Vector3.new(rng:NextNumber(-1,1),rng:NextNumber(-1,1),rng:NextNumber(-1,1))*0.16*k*envelope
            pts[j+1]=start:Lerp(finish,f)+bend*envelope+jitter
        end
        return {pts=pts,life=rng:NextNumber(0.12,0.30),born=os.clock(),index=index}
    end
    for bi=1,4 do
        local state={slice=-1,bolt=makeBolt(bi),parts={}}
        bolts[#bolts+1]=state
        for seg=1,9 do
            local entry
            entry=addPart(CFrame.new(),Vector3.new(0.045*k,0.045*k,0.1*k),col:Lerp(lighter(col,0.18),0.25),{material=Enum.Material.Neon,transparency=0.08,fn=function(t)
                local now=os.clock()
                if now-state.bolt.born>state.bolt.life then state.bolt=makeBolt(bi) end
                local a,b=state.bolt.pts[seg],state.bolt.pts[seg+1]
                local dir=b-a
                local fade=math.clamp(1-(now-state.bolt.born)/state.bolt.life,0,1)
                entry.part.Size=Vector3.new(0.045*k*fade,0.045*k*fade,math.max(dir.Magnitude*1.12,0.02))
                entry.part.Transparency=1-fade*0.9
                return CFrame.lookAt((a+b)*0.5,(a+b)*0.5+dir)
            end})
        end
    end
end

function getHatAnchor(char)
    if hatMode == "Wings" then
        return char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") or char:FindFirstChild("HumanoidRootPart")
    elseif hatMode == "Lightning" then
        return char:FindFirstChild("HumanoidRootPart")
    end
    return char:FindFirstChild("Head")
end

function positionHat(t)
    if not hatFolder or hatStaticWelded then return end
    local char = LocalPlayer.Character
    local anchor = char and getHatAnchor(char)
    if not anchor then return end
    local origin = anchor.CFrame
    for _, g in ipairs(hatGroups) do g.cf = origin * g.fn(t) end
    for _, e in ipairs(hatParts) do
        if e.fn then e.part.CFrame = origin * e.fn(t) else e.part.CFrame = e.group.cf * e.cf end
    end
    for _, e in ipairs(hatParts) do
        if e.mesh and e.baseScale then
            local pulse = 1 + math.sin(t * 2.2) * 0.03
            e.mesh.Scale = e.baseScale * pulse
        end
    end
end

function clearHat()
    if hatFolder then hatFolder:Destroy() end
    -- Remove our own joints/parts even if a game script reparented them outside
    -- the folder while ragdolling the character.
    if hatBuilders.HeadMount and hatBuilders.HeadMount.Parent then hatBuilders.HeadMount:Destroy() end
    if hatBuilders.HaloPointLight and hatBuilders.HaloPointLight.Parent then hatBuilders.HaloPointLight:Destroy() end
    if hatPhysicsRoot and hatPhysicsRoot.Parent then hatPhysicsRoot:Destroy() end
    for _, group in ipairs(hatGroups) do
        if group.haloMotor and group.haloMotor.Parent then group.haloMotor:Destroy() end
        if group.haloPivot and group.haloPivot.Parent then group.haloPivot:Destroy() end
    end
    for _, entry in ipairs(hatParts) do
        if entry.part and entry.part.Parent then entry.part:Destroy() end
    end
    hatFolder = nil; hatParts = {}; hatGroups = {}
    hatBuilders.HeadMount, hatBuilders.BoundHeadSize = nil, nil
    hatBuilders.HaloLights, hatBuilders.HaloPointLight = nil, nil
    hatStaticWelded, hatBoundAnchor, hatPhysicsRoot = false, nil, nil
end

local function bindStaticHatToCharacter()
    local prefix = hatBuilders.HeadRigPrefixes[hatMode]
    if not hatFolder or not prefix then return false end
    local char = LocalPlayer and LocalPlayer.Character
    local anchor = char and getHatAnchor(char)
    if not anchor or not anchor:IsA("BasePart") then return false end

    local function invisibleRoot(name, cf)
        local root = Instance.new("Part")
        root.Name = name
        root.Size = Vector3.new(0.12, 0.12, 0.12)
        root.Transparency = 1
        root.Anchored = false
        root.CanCollide = false; root.CanTouch = false; root.CanQuery = false
        root.Massless = true; root.CastShadow = false
        root.CFrame = cf; root.Parent = hatFolder
        return root
    end
    local root = invisibleRoot(prefix .. "Root", anchor.CFrame)
    local mount = Instance.new("Motor6D")
    mount.Name = prefix .. "Mount"; mount.Enabled = true
    mount.Part0 = anchor; mount.Part1 = root
    mount.C0 = CFrame.new(); mount.C1 = CFrame.new()
    mount.Parent = root
    hatBuilders.HeadMount = mount

    if hatMode == "Halo" then
        -- One rigid head mount plus two independently animated orbit pivots.
        -- The pivots, not every halo segment, are driven by Motor6Ds.
        for i, group in ipairs(hatGroups) do
            local pivot = invisibleRoot("HaloOrbitPivot_" .. i, group.cf)
            local motor = Instance.new("Motor6D")
            motor.Name = "HaloOrbitMotor_" .. i; motor.Enabled = true
            motor.Part0 = root; motor.Part1 = pivot
            motor.C0 = root.CFrame:ToObjectSpace(group.cf); motor.C1 = CFrame.new()
            motor.Parent = pivot
            group.haloPivot, group.haloMotor = pivot, motor
            if i == 1 and hatGlow then
                local aura = Instance.new("PointLight")
                aura.Name = "HaloAmbientLight"; aura.Color = Color3.fromRGB(hatR, hatG, hatB)
                aura.Enabled = true
                aura.Brightness = 0.8; aura.Range = 7; aura.Shadows = false
                aura.Parent = pivot
                hatBuilders.HaloPointLight = aura
            end
        end
    end
    for _, entry in ipairs(hatParts) do
        local part = entry.part
        local partRoot = hatMode == "Halo" and entry.group.haloPivot or root
        if part and part.Parent and partRoot then
            local localOffset = partRoot.CFrame:ToObjectSpace(part.CFrame)
            part.Anchored = false
            part.CanCollide = false; part.CanTouch = false; part.CanQuery = false
            part.Massless = true
            local weld = Instance.new("Weld")
            weld.Name = prefix .. "Weld"; weld.Enabled = true
            weld.Part0 = partRoot; weld.Part1 = part
            weld.C0 = localOffset; weld.C1 = CFrame.new()
            weld.Parent = part
        end
    end
    hatPhysicsRoot, hatBoundAnchor, hatStaticWelded = root, anchor, true
    hatBuilders.BoundHeadSize = anchor.Size
    return true
end

function applyHatBloom()
    local bloom = Lighting:FindFirstChild("SatanicHatBloom")
    if bloom then bloom:Destroy() end
end

function updateHat()
    clearHat()
    applyHatBloom()
    if not customHatEnabled then return end

    local char = LocalPlayer and LocalPlayer.Character
    local prefix = hatBuilders.HeadRigPrefixes[hatMode]
    if prefix then
        local head = char and char:FindFirstChild("Head")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        -- Never create anchored cosmetics at the world origin while a character
        -- is loading, without a head, or after its humanoid has died.
        if not char or not char.Parent or not head or not head:IsA("BasePart") or (hum and hum.Health <= 0) then return end
        -- Remove abandoned legacy world-space static hats from this character,
        -- without deleting unrelated effects or another player's hat.
        for _, old in ipairs(workspace:GetChildren()) do
            if old.Name == "CustomHatEffect" and old:IsA("Folder") then
                local oldRoot = old:FindFirstChild("HatAttachmentRoot")
                local oldJoint = oldRoot and oldRoot:FindFirstChildOfClass("WeldConstraint")
                local oldAnchor = oldJoint and oldJoint.Part0
                if oldRoot and (not oldAnchor or oldAnchor:IsDescendantOf(char)) then old:Destroy() end
            end
        end
        -- Previous interrupted copies of this script may have left a named rig.
        for _, old in ipairs(char:GetChildren()) do
            if old:IsA("Folder") then
                for _, folderName in pairs(hatBuilders.HeadRigFolders) do
                    if old.Name == folderName then old:Destroy(); break end
                end
            end
        end
    end
    hatFolder = Instance.new("Folder")
    hatFolder.Name = prefix and hatBuilders.HeadRigFolders[hatMode] or "CustomHatEffect"
    hatFolder.Parent = prefix and char or workspace
    local base = newGroup(function() return CFrame.new() end)
    local col = Color3.fromRGB(hatR, hatG, hatB)
    local builder = hatBuilders[hatMode]
    if builder then
        local ok, err = pcall(builder, hatSizeX / 4, hatSizeY / 2, hatSizeZ / 4, col, base)
        if not ok then
            warn("[Halloween UI] hat builder error (" .. tostring(hatMode) .. "): " .. tostring(err))
            if prefix then clearHat(); return end
        end
    end
    positionHat(os.clock())
    local ok, bound = pcall(bindStaticHatToCharacter)
    if prefix and (not ok or not bound) then
        clearHat()
        if not ok then warn("[Halloween UI] head accessory mount error: " .. tostring(bound)) end
    end
end

function hatSettings(api)
    api:AddSlider("Size X (width)", 1, 10, hatSizeX, function(v) hatSizeX = v; if not Theme.ConfigRegistry.applying then updateHat() end end, 0.5)
    api:AddSlider("Size Y (height)", 1, 10, hatSizeY, function(v) hatSizeY = v; if not Theme.ConfigRegistry.applying then updateHat() end end, 0.5)
    api:AddSlider("Size Z (depth)", 1, 10, hatSizeZ, function(v) hatSizeZ = v; if not Theme.ConfigRegistry.applying then updateHat() end end, 0.5)
    api:AddSlider("Hat Height Offset", -0.5, 2.0, hatBuilders.HatYOffset, function(v) hatBuilders.HatYOffset = v; if hatMode == "China hat" and not Theme.ConfigRegistry.applying then updateHat() end end, 0.05)
    api:AddSlider("Halo Height Offset", -0.5, 2.0, hatBuilders.HaloYOffset, function(v) hatBuilders.HaloYOffset = v; if hatMode == "Halo" and not Theme.ConfigRegistry.applying then updateHat() end end, 0.05)
    api:AddSlider("Halo Spin Speed", 0, 2, hatBuilders.HaloSpin, function(v) hatBuilders.HaloSpin = v end, 0.05)
    api:AddSlider("Horn Height Offset", -0.5, 2.0, hatBuilders.HornYOffset, function(v) hatBuilders.HornYOffset = v; if hatMode == "Horns" and not Theme.ConfigRegistry.applying then updateHat() end end, 0.05)
    do
        local hh, hs, hv = Color3.fromRGB(hatR, hatG, hatB):ToHSV()
        api:AddColorPicker(hh, hs, hv, function(h, s, v)
            local c = Color3.fromHSV(h, s, v)
            hatR = math.floor(c.R * 255 + 0.5); hatG = math.floor(c.G * 255 + 0.5); hatB = math.floor(c.B * 255 + 0.5)
            if not Theme.ConfigRegistry.applying then updateHat() end
        end)
    end
    api:AddToggle("Glow (neon + bloom)", hatGlow, function(state) hatGlow = state; if not Theme.ConfigRegistry.applying then updateHat() end end)
end

secCustomHats:AddToggle("Enable Hat / Effect", false, function(state)
    customHatEnabled = state
    if not Theme.ConfigRegistry.applying then updateHat() end
end, hatSettings)
hatModeBtn = secCustomHats:AddButton("Mode: " .. hatMode, function()
    modeIndex = modeIndex % #modesList + 1; hatMode = modesList[modeIndex]
    if hatModeBtn then hatModeBtn.Text = "Mode: " .. hatMode end
    updateHat()
end, hatSettings)

do
    -- Hat, horns and both halo rings follow the head through physical joints.
    -- Only the two halo orbit motors and small light accents are animated here.
    local hatUpdateAccumulator = 0
    track(RunService.RenderStepped:Connect(function(dt)
        if Unloaded or not customHatEnabled then return end
        hatUpdateAccumulator = hatUpdateAccumulator + dt
        local hatInterval = Theme.ExtremePerformance and (1 / 30) or (1 / 45)
        if hatUpdateAccumulator < hatInterval then return end
        local remainder = hatUpdateAccumulator % hatInterval
        local elapsed = hatUpdateAccumulator - remainder
        hatUpdateAccumulator = remainder
        if hatBuilders.HeadRigPrefixes[hatMode] then
            local char = LocalPlayer and LocalPlayer.Character
            local head = char and getHatAnchor(char)
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not char or not char.Parent or not head or not head:IsA("BasePart") or (hum and hum.Health <= 0) then
                if hatFolder then clearHat() end
                return
            end
            if not hatFolder or hatFolder.Parent ~= char or not hatStaticWelded or head ~= hatBoundAnchor then
                updateHat()
                return
            end
            if hatMode == "Halo" then
                local t = os.clock()
                local spin = elapsed * (hatBuilders.HaloSpin or 0)
                hatBuilders.HaloPhase = ((hatBuilders.HaloPhase or 0) + spin) % (math.pi * 2)
                hatBuilders.HaloInnerPhase = ((hatBuilders.HaloInnerPhase or 0) - spin * 1.45) % (math.pi * 2)
                for _, group in ipairs(hatGroups) do
                    if group.haloMotor and group.haloMotor.Parent then group.haloMotor.C0 = group.fn(t) end
                end
            end
            return
        end
        if not hatFolder or not hatFolder.Parent then updateHat(); return end
        if hatMode ~= "Wings" then positionHat(os.clock()) end
    end))
end

-- =========================================================================
-- WINGS: Angelic / Demonic / Prism (migrated rainbow feather style)
-- ПКМ по переключателю: палитра цвета, размер, скорость и амплитуда взмаха, раскрытие, прозрачность, свечение
-- =========================================================================
do
    local secWings = createSection(leftVis, "Wings")
    local W = {
        on = false, style = 1,
        size = 1, speed = 2, flap = 14, spread = 35, trans = 0, glow = true,
        color = Color3.fromRGB(37, 255, 204),
        folder = nil, items = {}, feathers = {}, q = false, picker = nil,
        -- Physical rig: two torso pivots plus one lightweight pivot per feather.
        -- Geometry is welded in local space, so the character never outruns world-CFrame updates.
        sideRoots = {}, rootJoints = {}, groupRoots = {}, groupJoints = {}, boundCharacter = nil, boundTorso = nil,
        toggleControl = nil, styleControl = nil,
        settingsControls = {}, settingsWindow = nil,
    }
    W.prismReference=true;W.prismTheme=true;W.prismBrightness=1
    W.prismX=0;W.prismY=0;W.prismZ=0
    Theme.WingsState = W
    local wingBuildToken = 0
    local V3, UP = Vector3.new, Vector3.new(0, 0, 1)
    local WHITE, BLACK = Color3.new(1, 1, 1), Color3.new(0, 0, 0)

    local function mk(size, color, shape, mat)
        local p = Instance.new("Part")
        p.Anchored = true; p.CanCollide = false; p.CanQuery = false; p.CanTouch = false
        p.Massless = true; p.CastShadow = false
        p.TopSurface = Enum.SurfaceType.Smooth; p.BottomSurface = Enum.SurfaceType.Smooth
        if shape then p.Shape = shape end
        p.Material = mat or (W.glow and Enum.Material.Neon or Enum.Material.SmoothPlastic)
        p.Color = color; p.Size = size; p.Transparency = W.trans
        p.Parent = W.folder
        return p
    end

    -- часть, жёстко закреплённая на крыле
    local function addFixed(side, cf, size, color, shape, mat)
        W.items[#W.items + 1] = {p = mk(size, color, shape, mat), cf = cf, side = side}
    end


    -- брусок от точки a до точки b (w = ширина в плоскости крыла, th = толщина)
    local function addBar(side, a, b, w, th, color, mat)
        local d = b - a
        local len = d.Magnitude
        if len < 0.02 then return end
        local mid = (a + b) / 2
        addFixed(side, CFrame.lookAt(mid, mid + d, UP), V3(w, th, len), color, nil, mat)
    end

    -- сужающаяся кость
    local function addTube(side, a, b, w0, w1, th, segs, color)
        for i = 1, segs do
            local p0, p1 = a:Lerp(b, (i - 1) / segs), a:Lerp(b, i / segs)
            addBar(side, p0, p1, w0 + (w1 - w0) * ((i - 0.5) / segs), th, color)
        end
    end

    local function lerpPoly(pts, u)
        local n = #pts - 1
        local f = math.clamp(u, 0, 1) * n
        local i = math.min(math.floor(f) + 1, n)
        local t = f - (i - 1)
        local a, b = pts[i], pts[i + 1]
        return a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t
    end

    -- Original feather geometry from the supplied script: three tapered body segments plus a shaft.
    local function addFeather(side, bx, by, bz, ang, L, w, c0, c1, ripple, groupId)
        local d = V3(math.cos(ang) * side, math.sin(ang), 0)
        local base = V3(bx * side, by, bz)
        local fe = {side = side, frame = CFrame.lookAt(base, base + d, UP), phase = math.random() * 6.28, amp = ripple, group = groupId or 1}
        W.feathers[#W.feathers + 1] = fe
        local segs = {{0.52, 1.0}, {0.30, 0.74}, {0.18, 0.40}}
        local off = 0
        for i, sg in ipairs(segs) do
            local len = L * sg[1]
            local p = mk(V3(w * sg[2], 0.05, len * 1.04), c0:Lerp(c1, (i - 1) / 2))
            W.items[#W.items + 1] = {p = p, cf = CFrame.new(0, 0, -(off + len / 2)), side = side, fe = fe}
            off = off + len
        end
        local shaft = mk(V3(0.05, 0.07, L), c1:Lerp(WHITE, 0.35))
        W.items[#W.items + 1] = {p = shaft, cf = CFrame.new(0, 0.035, -L / 2), side = side, fe = fe}
    end

    local function buildAngel(side)
        local k, col = W.size, W.color
        local bone = col:Lerp(WHITE, 0.2)
        local arm = {{0, 0}, {0.8, 0.9}, {2.0, 1.7}, {3.3, 2.1}}

        local function layer(n, u0, u1, half, lenMul, wid, z, tA, tB, rip, groupId)
            for i = 1, n do
                local u
                if half then u = u0 + (u1 - u0) * ((i - 0.5) / n)
                else u = u0 + (u1 - u0) * ((i - 1) / math.max(n - 1, 1)) end
                local ax, ay = lerpPoly(arm, u)
                local ang = math.rad(-112 + 92 * u ^ 0.85)
                local L = (1.7 + 1.9 * u) * lenMul * k
                local shade = (i % 2 == 0) and 0.07 or 0
                addFeather(side, ax * k, ay * k, z * k + i * 0.004, ang, L, wid * k,
                    col:Lerp(WHITE, tA + shade), col:Lerp(WHITE, tB + shade), rip * (0.4 + u), groupId)
            end
        end
        local extreme = Theme.ExtremePerformance == true
        layer(extreme and 7 or 11, 0.28, 1.00, false, 1.00, 0.46, 0.00, 0.00, 0.55, 1.0, 1)  -- маховые
        layer(extreme and 6 or 9,  0.10, 0.95, true,  0.64, 0.42, 0.05, 0.08, 0.60, 0.8, 2)  -- второй ряд
        layer(extreme and 6 or 10, 0.08, 0.95, false, 0.34, 0.34, 0.10, 0.18, 0.70, 0.6, 3)  -- кроющие

        -- кости крыла
        local zb = 0.16 * k
        local function P(x, y) return V3(x * k * side, y * k, zb) end
        for i = 1, #arm - 1 do
            local a, b = P(arm[i][1], arm[i][2]), P(arm[i + 1][1], arm[i + 1][2])
            addTube(side, a, b, (0.20 - 0.045 * (i - 1)) * k, (0.20 - 0.045 * i) * k, 0.12 * k, 2, bone)
            addFixed(side, CFrame.new(b), V3(0.24 * k, 0.24 * k, 0.24 * k), bone, Enum.PartType.Ball)
        end
        addFixed(side, CFrame.new(P(0, 0)), V3(0.5 * k, 0.5 * k, 0.5 * k), bone, Enum.PartType.Ball)
    end

    function W.facet(a, b, c, thickness, emit)
        local ab, ac, bc = b-a, c-a, c-b
        if ab.Magnitude >= math.max(ac.Magnitude, bc.Magnitude) then a,c=c,a
        elseif ac.Magnitude >= bc.Magnitude then a,b=b,a end
        ab,ac,bc=b-a,c-a,c-b
        local normal=ac:Cross(ab)
        if normal.Magnitude < 0.0001 then return end
        local right, back=normal.Unit,bc.Unit
        local up=back:Cross(right)
        local height=math.abs(ab:Dot(up))
        local function half(x,y,axis,depth)
            if depth > 0.008 then
                emit(CFrame.fromMatrix((x+y)/2,axis,up,axis:Cross(up)),V3(thickness,height,depth))
            end
        end
        half(a,b,right,math.abs(ab:Dot(back)))
        half(a,c,-right,math.abs(ac:Dot(back)))
    end

    local function buildDemon(side)
        local k = W.size
        local function P(x,y,z) return V3(side*x*k,y*k,z*k) end
        local shoulder, elbow, wrist=P(0,0,0),P(1.20,1.45,0.26),P(2.18,2.55,0.45)
        local fingers={P(5.55,2.05,0.70),P(5.12,0.24,1.02),P(4.05,-1.04,1.22),P(2.48,-1.62,0.85),P(0.32,-0.68,0.18)}
        local bone=W.color:Lerp(BLACK,0.68)
        local cloth=W.color:Lerp(BLACK,0.53)
        local function membrane(a,b,c,color)
            W.facet(a,b,c,0.036*k,function(cf,size)
                addFixed(side,cf,size,color,Enum.PartType.Wedge,Enum.Material.SmoothPlastic)
            end)
        end
        membrane(shoulder,elbow,fingers[5],cloth)
        membrane(elbow,wrist,fingers[5],cloth)
        for i=1,#fingers-1 do
            local a,b=fingers[i],fingers[i+1]
            local scallop=((a+b)/2):Lerp(wrist,0.23)+P(0,0,0.12)
            membrane(wrist,a,scallop,cloth)
            membrane(wrist,scallop,b,cloth:Lerp(W.color,0.17))
        end
        addTube(side,shoulder,elbow,0.22*k,0.17*k,0.15*k,2,bone)
        addTube(side,elbow,wrist,0.17*k,0.13*k,0.13*k,2,bone)
        for _,tip in ipairs(fingers) do
            addTube(side,wrist,tip,0.12*k,0.035*k,0.085*k,3,bone)
        end
        local hook=wrist+P(0.20,0.54,0.02)
        addTube(side,wrist,hook,0.18*k,0.09*k,0.12*k,2,bone)
        addTube(side,hook,hook+P(0.35,-0.12,0.04),0.09*k,0.025*k,0.08*k,2,W.color:Lerp(WHITE,0.38))
    end

    local function buildSolar(side)
        local k=W.size
        local armor=Color3.fromRGB(43,50,63)
        local steel=Color3.fromRGB(96,110,127)
        local accent=W.color
        local function P(x,y,z) return V3(side*x*k,y*k,z*k) end
        local function orbit(r,degrees,z)
            local a=math.rad(degrees)
            return P(1.93+r*math.cos(a),0.58+r*math.sin(a),0.28+z)
        end
        local function plate(a,b,c,tint)
            W.facet(a,b,c,0.075*k,function(cf,size)
                addFixed(side,cf,size,tint,Enum.PartType.Wedge,Enum.Material.Metal)
            end)
        end
        local base=P(0.02,0.0,0.04)
        local hinge=P(0.52,0.27,0.22)
        addBar(side,base,hinge,0.21*k,0.15*k,steel,Enum.Material.Metal)
        for _,angle in ipairs({146,213}) do
            addBar(side,hinge,orbit(1.40,angle,0),0.12*k,0.11*k,armor,Enum.Material.Metal)
        end
        addFixed(side,CFrame.new(hinge),V3(0.28,0.28,0.28)*k,steel,Enum.PartType.Ball,Enum.Material.Metal)
        -- Five separated armored rail modules leave the centre and shoulder opening clear.
        local steps=Theme.ExtremePerformance and 3 or 5
        for module=0,4 do
            local start=-143+module*59
            for j=0,steps-1 do
                local a=start+55*j/steps
                local b=start+55*(j+1)/steps
                addBar(side,orbit(1.43,a,0),orbit(1.43,b,0),0.16*k,0.12*k,armor,Enum.Material.Metal)
                addBar(side,orbit(1.34,a,0.07),orbit(1.34,b,0.07),0.035*k,0.035*k,accent)
            end
            local a=start+22
            local heel=orbit(1.47,a-5,0)
            local knuckle=orbit(1.78,a+4,0.05)
            local tail=orbit(1.48,a+20,0)
            local tip=orbit(module==2 and 2.48 or 2.18,a+19,0.15)
            plate(heel,knuckle,tail,armor)
            plate(knuckle,tip,tail,steel)
            addBar(side,knuckle+P(0,0,0.06),tip+P(0,0,0.06),0.032*k,0.03*k,accent)
        end
    end

    local function buildDragonfly(side)
        local k=W.size
        local function point(x,y,z) return V3(side*x*k,y*k,z*k) end
        for lobe=1,2 do
            local first=#W.items+1
            local root=point(0.05,0.08,0)
            local outline
            if lobe==1 then
                outline={root,point(1.8,1.31,0.15),point(4.7,1.75,0.37),point(5.3,1.43,0.4),point(3.80,0.72,0.37),point(1.15,0.24,0.12)}
            else
                outline={root,point(1.85,0.04,0.31),point(3.98,-0.66,0.54),point(4.16,-1.12,0.56),point(2.65,-1.42,0.48),point(0.89,-0.58,0.19)}
            end
            local hub=outline[2]:Lerp(outline[5],0.45)
            for i,a in ipairs(outline) do
                local b=outline[i%#outline+1]
                W.facet(hub,a,b,0.032*k,function(cf,size)
                    addFixed(side,cf,size,W.color:Lerp(WHITE,0.16+i*0.045),Enum.PartType.Wedge,Enum.Material.SmoothPlastic)
                    local item=W.items[#W.items]
                    item.baseTransparency=0.40
                    item.p.Transparency=0.40+0.60*W.trans
                end)
                addBar(side,a,b,0.045*k,0.045*k,W.color)
                if i%2==0 then addBar(side,hub,a,0.026*k,0.03*k,W.color:Lerp(WHITE,0.4)) end
            end
            local mount={group=lobe,frame=CFrame.identity}
            for i=first,#W.items do W.items[i].fe=mount end
        end
    end

    local function makeInvisibleAnchor(name, cf)
        local p = Instance.new("Part")
        p.Name = name
        p.Size = V3(0.12, 0.12, 0.12)
        p.Transparency = 1
        p.Anchored = true -- keep stable while the rig is assembled; unanchor after all joints exist
        p.CanCollide = false; p.CanTouch = false; p.CanQuery = false
        p.Massless = true; p.CastShadow = false
        p.CFrame = cf
        p.Parent = W.folder
        return p
    end

    local function makeMotor(name, part0, part1, c0)
        local joint = Instance.new("Motor6D")
        joint.Name = name
        joint.Part0 = part0
        joint.Part1 = part1
        joint.C0 = c0
        joint.C1 = CFrame.new()
        joint.Transform = CFrame.new()
        joint.Parent = part1
        return joint
    end

    local function weldLocalPart(part, anchor, localCF)
        part.CFrame = anchor.CFrame * localCF
        local weld = Instance.new("WeldConstraint")
        weld.Name = "SatanicWingFixedPart"
        weld.Part0 = anchor
        weld.Part1 = part
        weld.Parent = part
        return part
    end

    -- Convert the generated geometry from anchored world-space parts into a real character rig.
    -- Each complete wing follows the torso through a Motor6D. Each feather is its own small
    -- assembly so its subtle ripple can animate without moving hundreds of Parts per frame.
    local function attachWingRig(torso)
        W.sideRoots, W.rootJoints, W.groupRoots, W.groupJoints = {}, {}, {}, {}
        W.boundCharacter = LocalPlayer.Character
        W.boundTorso = torso

        -- Two torso-mounted wing pivots. The model follows the avatar through joints,
        -- so walking never requires each visible part to chase world-space coordinates.
        for _, side in ipairs({-1, 1}) do
            local offset = CFrame.new(side * 0.3, 0.35, 0.55)
            local root = makeInvisibleAnchor(side < 0 and "LeftWingRoot" or "RightWingRoot", torso.CFrame * offset)
            W.sideRoots[side] = root
            W.rootJoints[side] = makeMotor(side < 0 and "LeftWingPivot" or "RightWingPivot", torso, root, offset)
            W.groupRoots[side], W.groupJoints[side] = {}, {}

            -- Angel feathers are grouped into three rows. Each row gets one lightweight pivot;
            -- demon membrane/bones are fixed directly to the wing root.
            for groupId = 1, 3 do
                local groupCF = CFrame.new(0, 0, 0.035 * groupId)
                local rowRoot = makeInvisibleAnchor("WingFeatherRowPivot", root.CFrame * groupCF)
                W.groupRoots[side][groupId] = rowRoot
                W.groupJoints[side][groupId] = makeMotor("WingFeatherRowJoint", root, rowRoot, groupCF)
            end
        end

        for _, item in ipairs(W.items) do
            local anchor, localCF
            if item.fe and item.fe.group and W.groupRoots[item.side] then
                local groupId = math.clamp(item.fe.group, 1, 3)
                anchor = W.groupRoots[item.side][groupId]
                local groupCF = CFrame.new(0, 0, 0.035 * groupId)
                localCF = groupCF:Inverse() * item.fe.frame * item.cf
            else
                anchor = W.sideRoots[item.side]
                localCF = item.cf
            end
            if item.p and anchor then weldLocalPart(item.p, anchor, localCF) end
        end

        -- Unanchor after all joints/welds are ready to avoid a one-frame drop.
        for _, root in pairs(W.sideRoots) do root.Anchored = false end
        for _, byGroup in pairs(W.groupRoots) do
            for _, rowRoot in pairs(byGroup) do rowRoot.Anchored = false end
        end
        for _, item in ipairs(W.items) do
            if item.p and item.p.Parent then
                item.p.Anchored = false
                item.p.Massless = true
                item.p.CanCollide = false; item.p.CanTouch = false; item.p.CanQuery = false
            end
        end
    end

    local function update()
        if W.style==3 then return end
        if not W.on or not W.folder or not W.folder.Parent then return end
        local char = LocalPlayer and LocalPlayer.Character
        if not char or char ~= W.boundCharacter or not W.boundTorso or not W.boundTorso.Parent then return end

        local t = os.clock() * W.speed * 2
        local amp = math.rad(W.flap)
        local theta = math.rad(6) + amp * 0.78 * math.sin(t * 0.72)
        local phi = math.rad(-W.spread) + amp * 0.28 * math.cos(t * 0.72)
        if W.style == 4 then
            theta=math.rad(7)+amp*0.5*math.sin(t*0.48)
            phi=-math.rad(W.spread)+amp*0.62*math.cos(t*0.48)
        elseif W.style == 5 then
            theta=amp*0.17*math.sin(t*2)
            phi=-math.rad(W.spread)
        elseif W.style == 2 then
            local beat = t * 1.08
            theta = math.rad(9) + amp * (math.sin(beat) - 0.32 * math.sin(2 * beat))
            phi = math.rad(-W.spread) - amp * 0.68 * math.cos(beat - 0.48)
        end

        for _, side in ipairs({-1, 1}) do
            local joint = W.rootJoints[side]
            if joint and joint.Parent then
                joint.Transform = CFrame.Angles(0, side * phi, 0) * CFrame.Angles(0, 0, side * theta)
            end
            local rowJoints = W.groupJoints[side]
            if W.style == 5 and rowJoints then
                for lobe=1,2 do
                    local motor=rowJoints[lobe]
                    if motor then motor.Transform=CFrame.Angles(0,side*amp*math.sin(t*2.8-(lobe-1)*1.8),0) end
                end
            elseif W.style == 1 and rowJoints then
                for groupId, rowJoint in pairs(rowJoints) do
                    if rowJoint and rowJoint.Parent then
                        local phase = (groupId - 1) * 0.48
                        local ripple = side * math.sin(t * 0.72 - phase) * amp * 0.32
                        local pitch = math.cos(t * 0.72 - phase) * amp * 0.13
                        rowJoint.Transform = CFrame.Angles(pitch, ripple, ripple * 0.22)
                    end
                end
            end
        end
    end

    local function syncWingBloom()
        local bloom = Lighting:FindFirstChild("SatanicWingBloom")
        if W.on and W.glow and W.style~=3 and not Unloaded then
            if not bloom then
                bloom = Instance.new("BloomEffect")
                bloom.Name = "SatanicWingBloom"
                bloom.Parent = Lighting
            end
            bloom.Enabled = true
            bloom.Intensity = Theme.ExtremePerformance and 0.38 or 0.72
            bloom.Size = Theme.ExtremePerformance and 17 or 26
            bloom.Threshold = Theme.ExtremePerformance and 0.92 or 0.82
        elseif bloom then
            bloom:Destroy()
        end
    end

    local function clear()
        wingBuildToken = wingBuildToken + 1 -- cancel any delayed rebuild queued by a slider
        W.q = false
        if W.prismGroup and Theme.PremiumFX then Theme.PremiumFX.destroy(W.prismGroup);W.prismGroup=nil end
        if W.folder then W.folder:Destroy() end
        W.folder = nil; W.items = {}; W.feathers = {}
        W.sideRoots = {}; W.rootJoints = {}; W.groupRoots = {}; W.groupJoints = {}; W.boundCharacter = nil; W.boundTorso = nil
        syncWingBloom()
    end
    registerCleanup(function() W.on = false; clear() end)

    local function build()
        clear()
        if not W.on or Unloaded then return end
        local char = LocalPlayer and LocalPlayer.Character
        local torso = char and (char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") or char:FindFirstChild("HumanoidRootPart"))
        if not torso then return end

        if W.style==3 then
            if Theme.PrismWings then Theme.PrismWings.Build(W,torso) end
            syncWingBloom()
            return
        end
        W.folder = Instance.new("Folder")
        W.folder.Name = "CustomWingsEffect"
        W.folder.Parent = workspace

        for _, side in ipairs({-1, 1}) do
            if W.style == 1 then
                buildAngel(side)
            else
                if W.style == 4 then buildSolar(side)
                elseif W.style == 5 then buildDragonfly(side)
                else buildDemon(side) end
            end
        end

        -- Attach every generated part to the character rig in local space. This replaces
        -- per-part world CFrame chasing, which made the wings lag or visually detach while walking.
        attachWingRig(torso)
        update()
        syncWingBloom()
    end

    -- Coalesce slider changes and invalidate stale pending builds when a config loads.
    local function queueBuild()
        if not W.on or W.q or Theme.ConfigRegistry.applying then return end
        W.q = true
        wingBuildToken = wingBuildToken + 1
        local token = wingBuildToken
        task.delay(0.2, function()
            if token ~= wingBuildToken then return end
            W.q = false
            if W.on and not Unloaded then build() end
        end)
    end

    local function applyTrans()
        for _, item in ipairs(W.items) do
            if item.p and item.p.Parent then
                local base=item.baseTransparency or 0
                item.p.Transparency = base+(1-base)*W.trans
            end
        end
    end

    local names = {"Angelic", "Demonic", "Prism", "Solar Eclipse", "Dragonfly"}
    local defaults = {W.color, Color3.fromRGB(255,35,118), Color3.fromRGB(140,180,255), Color3.fromRGB(255,172,65), Color3.fromRGB(77,220,199)}
    local profiles = {}
    local limits = {size={0.5,2}, speed={0,6}, flap={0,50}, spread={0,70}, trans={0,0.8}}
    local function capture()
        local result = {glow=W.glow,color={W.color.R*255,W.color.G*255,W.color.B*255}}
        for key in pairs(limits) do result[key]=W[key] end
        return result
    end
    for i,name in ipairs(names) do
        local profile=capture()
        local c=defaults[i]
        profile.color={c.R*255,c.G*255,c.B*255}
        profiles[name]=profile
    end
    function W.ExportProfiles()
        profiles[names[W.style]]=capture()
        return profiles
    end
    local function restoreProfile(index)
        local profile=profiles[names[index]]
        for key in pairs(limits) do W[key]=profile[key] end
        W.glow=profile.glow
        W.color=Color3.fromRGB(table.unpack(profile.color))
    end
    local function loadProfiles(data)
        if type(data) ~= "table" then return end
        for name,profile in pairs(profiles) do
            local saved=data[name]
            if type(saved)=="table" then
                for key,range in pairs(limits) do
                    local n=tonumber(saved[key])
                    if n then profile[key]=math.clamp(n,range[1],range[2]) end
                end
                if type(saved.glow)=="boolean" then profile.glow=saved.glow end
                if type(saved.color)=="table" then
                    for i=1,3 do profile.color[i]=math.clamp(tonumber(saved.color[i]) or profile.color[i],0,255) end
                end
            end
        end
    end
    W.toggleControl = secWings:AddToggle("Enable Wings", false, function(state)
        W.on = state
        if Theme.ConfigRegistry.applying then return end
        if state then build() else clear() end
    end, function(api)
        W.settingsWindow = activeSettingsWindow
        W.reopenSettings=function() api:Reopen() end
        local styleName=names[W.style]
        api:Heading(styleName .. "  /  Appearance")
        W.settingsControls = {}
        local h, sat, val = W.color:ToHSV()
        W.picker = api:AddColorPicker(h, sat, val, function(h2, s2, v2)
            W.color = Color3.fromHSV(h2, s2, v2)
            queueBuild()
        end)
        W.settingsControls.color = W.picker
        if W.style == 3 then
        api:Heading("Crystal palette and position")
        W.settingsControls.prismReference=api:AddToggle("Prism: reference colors",W.prismReference,function(v)W.prismReference=v end)
        W.settingsControls.prismTheme=api:AddToggle("Prism: theme sync",W.prismTheme,function(v)W.prismTheme=v end)
        W.settingsControls.prismBrightness=api:AddSlider("Prism: brightness (%)",50,160,W.prismBrightness*100,function(v)W.prismBrightness=v/100 end)
        for _,axis in ipairs({"X","Y","Z"})do
            local key="prism"..axis
            W.settingsControls[key]=api:AddSlider("Prism Position "..axis,-100,100,W[key]*10,function(v)W[key]=v/10 end)
        end
        end
        api:Heading(styleName .. "  /  Shape and motion")
        W.settingsControls.size = api:AddSlider("Size", 0.5, 2, W.size, function(value) W.size = value; queueBuild() end, 0.1)
        W.settingsControls.speed = api:AddSlider("Flap speed", 0, 6, W.speed, function(value) W.speed = value end, 0.5)
        W.settingsControls.flap = api:AddSlider("Flap amplitude (°)", 0, 50, W.flap, function(value) W.flap = value end, 1)
        W.settingsControls.spread = api:AddSlider("Spread back (°)", 0, 70, W.spread, function(value) W.spread = value end, 1)
        W.settingsControls.trans = api:AddSlider("Transparency", 0, 0.8, W.trans, function(value) W.trans = value; if not Theme.ConfigRegistry.applying then applyTrans() end end, 0.05)
        W.settingsControls.glow = api:AddToggle("Glow (neon)", W.glow, function(state)
            W.glow = state
            queueBuild()
        end)
    end)

    W.styleControl = secWings:AddDropdown("Style", {
        {name = "Angelic",   color = Color3.fromRGB(37, 255, 204)},
        {name = "Demonic", color = Color3.fromRGB(255, 35, 118)},
        {name = "Prism", color = Color3.fromRGB(140, 180, 255)},
        {name = "Solar Eclipse", color = Color3.fromRGB(255,172,65)},
        {name = "Dragonfly", color = Color3.fromRGB(77,220,199)},
    }, 1, function(name, color, idx)
        if idx ~= W.style then
            profiles[names[W.style]]=capture()
            W.style=idx
            restoreProfile(idx)
            if W.settingsWindow and W.settingsWindow==activeSettingsWindow then
                W.reopenSettings()
            end
        end
        queueBuild()
    end)

    function W.LoadConfigValues(data)
        if type(data) ~= "table" then return end
        if type(data.enabled) == "boolean" then W.on = data.enabled end
        if type(data.prismReference)=="boolean" then W.prismReference=data.prismReference end
        if type(data.prismTheme)=="boolean" then W.prismTheme=data.prismTheme end
        do
            local value = tonumber(data.prismBrightness)
            if value then W.prismBrightness=math.clamp(data.prismBrightness,0.5,1.6) end
        end
        for _,axis in ipairs({"X","Y","Z"})do
            local name="prism"..axis
            if tonumber(data[name])then W[name]=math.clamp(data[name],-10,10)end
        end
        do
            local value = tonumber(data.style)
            if value then
                local index=math.clamp(math.floor(value+0.5),1,#names)
                if index~=W.style then
                    profiles[names[W.style]]=capture()
                    if W.settingsWindow and W.settingsWindow==activeSettingsWindow then W.settingsWindow:Destroy();W.settingsWindow=nil end
                end
                W.style=index
            end
            loadProfiles(data.profiles)
            restoreProfile(W.style)
        end
        do
            local value = tonumber(data.size)
            if value then W.size = math.clamp(value, 0.5, 2) end
        end
        do
            local value = tonumber(data.speed)
            if value then W.speed = math.clamp(value, 0, 6) end
        end
        do
            local value = tonumber(data.flap)
            if value then W.flap = math.clamp(value, 0, 50) end
        end
        do
            local value = tonumber(data.spread)
            if value then W.spread = math.clamp(value, 0, 70) end
        end
        do
            local value = tonumber(data.transparency)
            if value then W.trans = math.clamp(value, 0, 0.8) end
        end
        if type(data.glow) == "boolean" then W.glow = data.glow end
        if type(data.color) == "table" then
            local red = math.clamp(tonumber(data.color[1]) or 255, 0, 255)
            local green = math.clamp(tonumber(data.color[2]) or 236, 0, 255)
            local blue = math.clamp(tonumber(data.color[3]) or 190, 0, 255)
            W.color = Color3.fromRGB(math.floor(red + 0.5), math.floor(green + 0.5), math.floor(blue + 0.5))
        end
    end

    function W.SyncConfigControls()
        if W.styleControl then W.styleControl.Set(W.style, true) end
        if W.settingsWindow and W.settingsWindow == activeSettingsWindow and W.settingsWindow.Parent then
            local controls = W.settingsControls
            if controls.color and controls.color.Alive and controls.color.Alive() then
                local h, sat, val = W.color:ToHSV(); controls.color.Set(h, sat, val)
            end
            if controls.prismReference then controls.prismReference.Set(W.prismReference)end
            if controls.prismTheme then controls.prismTheme.Set(W.prismTheme)end
            if controls.prismBrightness then controls.prismBrightness.Set(W.prismBrightness*100)end
            for _,axis in ipairs({"X","Y","Z"})do local key="prism"..axis;if controls[key]then controls[key].Set(W[key]*10)end end
            if controls.size then controls.size.Set(W.size) end
            if controls.speed then controls.speed.Set(W.speed) end
            if controls.flap then controls.flap.Set(W.flap) end
            if controls.spread then controls.spread.Set(W.spread) end
            if controls.trans then controls.trans.Set(W.trans) end
            if controls.glow then controls.glow.Set(W.glow) end
        end
        if W.toggleControl then W.toggleControl.Set(W.on) end
    end

    function W.FinalizeConfig()
        wingBuildToken = wingBuildToken + 1
        W.q = false
        if W.on then build() else clear() end
    end


    -- Validates the actual attachment tree, not just the toggle/folder. Some hit/ragdoll
    -- handlers replace torso joints or delete local parts while the toggle stays enabled.
    function W.RepairIfNeeded(currentCharacter)
        if not W.on or Unloaded then return false end
        local char = LocalPlayer and LocalPlayer.Character
        if not char or (currentCharacter and currentCharacter ~= char) then return false end
        local torso = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") or char:FindFirstChild("HumanoidRootPart")
        if not torso then return false end
        if W.style==3 then
            if not W.prismGroup or W.prismGroup.dead or not W.folder or not W.folder.Parent or W.boundCharacter~=char or W.boundTorso~=torso then
                build();return true
            end
            return false
        end
        local broken = not W.folder or W.folder.Parent ~= workspace or W.boundCharacter ~= char or W.boundTorso ~= torso or not W.boundTorso.Parent or #W.items == 0
        if not broken then
            for _, side in ipairs({-1, 1}) do
                local root, joint = W.sideRoots[side], W.rootJoints[side]
                if not root or not root.Parent or not joint or not joint.Parent or joint.Part0 ~= torso or joint.Part1 ~= root then
                    broken = true
                    break
                end
                local rowRoots, rowJoints = W.groupRoots[side], W.groupJoints[side]
                for groupId = 1, 3 do
                    local rowRoot = rowRoots and rowRoots[groupId]
                    local rowJoint = rowJoints and rowJoints[groupId]
                    if not rowRoot or not rowRoot.Parent or not rowJoint or not rowJoint.Parent or rowJoint.Part0 ~= root or rowJoint.Part1 ~= rowRoot then
                        broken = true
                        break
                    end
                end
                if broken then break end
            end
        end
        if not broken then
            for _, item in ipairs(W.items) do
                local part = item.p
                local weld = part and part.Parent and part:FindFirstChild("SatanicWingFixedPart")
                if not part or not part.Parent or part.Anchored or not weld or not weld.Parent or not weld.Part0 or weld.Part1 ~= part then
                    broken = true
                    break
                end
            end
        end
        if broken then
            build()
            return true
        end
        return false
    end

    -- The rig is already welded to the torso, so only Motor6D.Transform values are updated.
    -- Keep this synced with simulation/character animation; no per-Part CFrame writes are needed.
    local wingRebuildAccumulator = 0
    local wingIntegrityAccumulator = 0
    track(RunService.PreSimulation:Connect(function(dt)
        if Unloaded then
            if W.folder then clear() end
            W.on = false
            return
        end
        if not W.on then return end

        local char = LocalPlayer and LocalPlayer.Character
        local torso = char and (char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") or char:FindFirstChild("HumanoidRootPart"))
        if not W.folder or not W.folder.Parent or char ~= W.boundCharacter or torso ~= W.boundTorso or not W.boundTorso or not W.boundTorso.Parent then
            wingRebuildAccumulator = wingRebuildAccumulator + dt
            if wingRebuildAccumulator >= 0.12 then
                wingRebuildAccumulator = 0
                if torso then build() end
            end
            return
        end
        wingIntegrityAccumulator = wingIntegrityAccumulator + dt
        if wingIntegrityAccumulator >= 0.30 then
            wingIntegrityAccumulator = 0
            if W.RepairIfNeeded(char) then return end
        end
        update()
    end))
end


-- WEATHER EFFECTS (client-side) - объёмные осадки, атмосферные пресеты и очистка эффектов
-- Общие данные вынесены в одну таблицу, чтобы не забивать лимит локальных регистров Lua.
local fogEnabled, fogBackup = false, nil
local function isCustomSkyboxActive()
    local controller = Theme and Theme.CustomSkyBoxState
    return controller ~= nil and type(controller.IsEnabled) == "function" and controller.IsEnabled() == true
end
local WeatherState = {
    enabled = false,
    mode = "Rain",
    button = nil,
    modes = {"Rain", "Drizzle", "Downpour", "Tropical Downpour", "Thunderstorm", "Heavy Thunderstorm", "Hail", "Snow", "Sleet", "Blizzard", "Fog", "Light Fog", "Overcast", "Windy", "Dust Storm", "Ash", "Sparks"},
    index = 1,
    runtime = {
        folder = nil, connection = nil, screenGui = nil, screenFx = nil,
        colorGrade = nil, bloom = nil, atmosphere = nil, atmosphereOverride = nil,
        atmosphereBackup = nil, atmosphereTween = nil, clouds = nil, cloudBackup = nil,
        cloudTween = nil, globalWindBackup = nil, globalWindBase = nil,
        ambience = nil, windAmbience = nil, worldGeometry = nil,
    },
}
-- Погодный движок теперь отдельная область видимости: его временные local-переменные
-- освобождаются до инициализации панели конфигов.
do
local secWeather = createSection(worldTab.Left, "World", "Visuals/Left/Weather")
WeatherState.weatherIntensity = 1.0
WeatherState.weatherWindScale = 1.0
WeatherState.weatherLightningFrequency = 1.0
WeatherState.weatherLightningBrightness = 8.0
WeatherState.weatherAudioEnabled = true
WeatherState.weatherAudioVolume = 0.55
local weatherRandom = Random.new()

local WEATHER_ATMOSPHERE_PROPERTIES = {"Density", "Offset", "Color", "Decay", "Glare", "Haze"}

WeatherState.restoreAtmosphereOverride = function(force)
    local atm = WeatherState.runtime.atmosphereOverride
    local backup = WeatherState.runtime.atmosphereBackup
    if atm and backup and atm.Parent and (force or not fogEnabled) then
        for property, value in pairs(backup) do
            pcall(function() atm[property] = value end)
        end
    end
    WeatherState.runtime.atmosphereOverride = nil
    WeatherState.runtime.atmosphereBackup = nil
    if WeatherState.runtime.atmosphereTween then
        pcall(function() WeatherState.runtime.atmosphereTween:Cancel() end)
        WeatherState.runtime.atmosphereTween = nil
    end
end

local function fadeOutWeatherSound(sound)
    if not sound then return end
    pcall(function()
        if sound.Parent then
            TweenService:Create(sound, TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Volume = 0}):Play()
            Debris:AddItem(sound, 0.28)
        else
            sound:Destroy()
        end
    end)
end

local function stopWeatherAudio()
    fadeOutWeatherSound(WeatherState.runtime.ambience)
    fadeOutWeatherSound(WeatherState.runtime.windAmbience)
    WeatherState.runtime.ambience = nil
    WeatherState.runtime.windAmbience = nil
end

local function startWeatherAudio(cfg, isThunderstorm)
    stopWeatherAudio()
    if not WeatherState.weatherAudioEnabled or not cfg then return end

    local wantsRain = cfg.kind == "rain" or cfg.kind == "drizzle" or cfg.kind == "hail" or cfg.kind == "sleet"
    local wantsWind = cfg.kind == "wind" or cfg.kind == "dust" or cfg.kind == "snow" or cfg.kind == "fog" or isThunderstorm or WeatherState.mode == "Tropical Downpour"

    local function createLoop(name, soundId, volumeScale, playbackSpeed)
        local sound = Instance.new("Sound")
        sound.Name = name
        sound.SoundId = soundId
        sound.Looped = true
        sound.Volume = 0
        sound.PlaybackSpeed = playbackSpeed or 1
        sound.Parent = SoundService
        if name == "SatanicRainAmbience" then
            local eq = Instance.new("EqualizerSoundEffect")
            eq.LowGain = 1.5
            eq.MidGain = 0
            eq.HighGain = -3.5
            eq.Parent = sound
        end
        sound:SetAttribute("SatanicWeatherVolumeScale", volumeScale)
        pcall(function() sound:Play() end)
        TweenService:Create(sound, TweenInfo.new(1.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Volume = WeatherState.weatherAudioVolume * volumeScale,
        }):Play()
        return sound
    end

    if wantsRain then
        local rainScale = WeatherState.mode == "Drizzle" and 0.23 or (WeatherState.mode == "Rain" and 0.38 or 0.62)
        if WeatherState.mode == "Downpour" or WeatherState.mode == "Tropical Downpour" or isThunderstorm then rainScale = 0.78 end
        WeatherState.runtime.ambience = createLoop("SatanicRainAmbience", "rbxassetid://1516791621", rainScale, weatherRandom:NextNumber(0.96, 1.03))
    end

    if wantsWind then
        local windScale = 0.20
        if isThunderstorm or WeatherState.mode == "Tropical Downpour" or WeatherState.mode == "Blizzard" or WeatherState.mode == "Dust Storm" then
            windScale = 0.34
        else
            windScale = 0.20
        end
        WeatherState.runtime.windAmbience = createLoop("SatanicWindAmbience", "rbxassetid://3308152153", windScale, weatherRandom:NextNumber(0.91, 1.06))
    end
end

local function clearWeather()
    if WeatherState.runtime.connection then
        WeatherState.runtime.connection:Disconnect()
        WeatherState.runtime.connection = nil
    end
    stopWeatherAudio()
    WeatherState.restoreAtmosphereOverride(false)
    if WeatherState.runtime.atmosphereTween then
        pcall(function() WeatherState.runtime.atmosphereTween:Cancel() end)
        WeatherState.runtime.atmosphereTween = nil
    end
    if WeatherState.runtime.globalWindBackup ~= nil then
        pcall(function() workspace.GlobalWind = WeatherState.runtime.globalWindBackup end)
        WeatherState.runtime.globalWindBackup = nil
        WeatherState.runtime.globalWindBase = nil
    end
    if WeatherState.runtime.bloom then
        WeatherState.runtime.bloom:Destroy()
        WeatherState.runtime.bloom = nil
    end
    if WeatherState.runtime.folder then
        WeatherState.runtime.folder:Destroy()
        WeatherState.runtime.folder = nil
    end
    WeatherState.runtime.worldGeometry = nil
    if WeatherState.runtime.screenGui then
        pcall(function() WeatherState.runtime.screenGui:Destroy() end)
        WeatherState.runtime.screenGui = nil
    end
    WeatherState.runtime.screenFx = nil
    if WeatherState.runtime.colorGrade then
        WeatherState.runtime.colorGrade:Destroy()
        WeatherState.runtime.colorGrade = nil
    end
    if WeatherState.runtime.cloudTween then
        pcall(function() WeatherState.runtime.cloudTween:Cancel() end)
        WeatherState.runtime.cloudTween = nil
    end
    if WeatherState.runtime.clouds then
        local clouds = WeatherState.runtime.clouds
        local backup = WeatherState.runtime.cloudBackup
        if clouds.Parent and backup then
            if backup.created then
                clouds:Destroy()
            else
                clouds.Cover = backup.Cover
                clouds.Density = backup.Density
                clouds.Color = backup.Color
            end
        end
        WeatherState.runtime.clouds = nil
        WeatherState.runtime.cloudBackup = nil
    end
    if WeatherState.runtime.atmosphere then
        local atm = WeatherState.runtime.atmosphere
        -- Если модуль Minecraft Fog уже взял созданную погодой Atmosphere под управление,
        -- оставляем её ему; restoreFog() удалит её при выключении тумана.
        if fogEnabled and fogBackup and fogBackup.atm == atm then
            fogBackup.created = true
            atm.Name = "SatanicFogAtmosphere"
        else
            atm:Destroy()
        end
        WeatherState.runtime.atmosphere = nil
    end
end

-- Пул погодных объектов в 3D-мире. Все координаты ниже — workspace-координаты,
-- а не пиксели интерфейса; существующие объекты свободно проходят перед/за геометрией.
local function createWeatherWorldGeometry(folder, cfg, mode, intensity, random, windScale)
    local kind = cfg.kind
    local rainLike = kind == "rain" or kind == "drizzle" or kind == "sleet"
    local hailLike = kind == "hail"
    local snowLike = kind == "snow"
    local movingLine = rainLike or hailLike or kind == "wind" or kind == "dust"
    -- Conservative object budget: weather uses real 3D Parts, so a small pool looks natural
    -- without thousands of transforms or excessive draw/physics bookkeeping.
    local baseCounts = {
        ["Drizzle"] = 14, ["Rain"] = 25, ["Downpour"] = 34,
        ["Tropical Downpour"] = 38, ["Thunderstorm"] = 30, ["Heavy Thunderstorm"] = 38,
        ["Hail"] = 16, ["Snow"] = 20, ["Sleet"] = 24,
        ["Blizzard"] = 28, ["Windy"] = 16, ["Dust Storm"] = 22,
        ["Ash"] = 12, ["Sparks"] = 10,
    }
    local requested = baseCounts[mode] or 0
    if kind == "fog" or kind == "overcast" or requested == 0 then
        return {items = {}, accumulator = 0, interval = Theme.ExtremePerformance and 1 / 18 or 1 / 24, covered = false, gustScale = 1, kind = kind}
    end

    -- sqrt keeps the density control useful without doubling render cost at its maximum.
    local qualityScale = Theme.ExtremePerformance and 0.35 or 1
    local count = math.clamp(math.floor(requested * math.sqrt(math.clamp(intensity, 0.5, 2)) * qualityScale), 4, Theme.ExtremePerformance and 18 or 48)
    local worldFolder = Instance.new("Folder")
    worldFolder.Name = "WorldWeatherGeometry"
    worldFolder.Parent = folder
    local pool = {
        items = {}, folder = worldFolder, accumulator = 0, interval = Theme.ExtremePerformance and 1 / 18 or 1 / 24,
        covered = false, gustScale = 1, kind = kind,
        wind = Vector3.new(cfg.wind.X * windScale, 0, cfg.wind.Z * windScale),
        windBaseMagnitude = math.max(Vector3.new(cfg.wind.X, 0, cfg.wind.Z).Magnitude, 1),
        radius = (rainLike or hailLike) and 72 or 58,
    }

    local function spawnPosition(item, cameraPosition)
        local angle = random:NextNumber(0, math.pi * 2)
        local radius = math.sqrt(random:NextNumber()) * pool.radius
        local yOffset
        if rainLike or hailLike then
            yOffset = random:NextNumber(24, 76)
        elseif snowLike then
            yOffset = random:NextNumber(-2, 36)
        elseif kind == "wind" or kind == "dust" then
            yOffset = random:NextNumber(-10, 27)
        elseif kind == "ash" then
            yOffset = random:NextNumber(-12, 28)
        else
            yOffset = random:NextNumber(-18, 6)
        end
        item.position = cameraPosition + Vector3.new(math.cos(angle) * radius, yOffset, math.sin(angle) * radius)
        item.phase = random:NextNumber(0, math.pi * 2)
        item.speed = cfg.speed and random:NextNumber(cfg.speed.Min, cfg.speed.Max) or random:NextNumber(5, 12)
        item.drift = Vector3.new(random:NextNumber(-2.5, 2.5), 0, random:NextNumber(-2.5, 2.5))
        if snowLike then
            item.size = random:NextNumber(0.10, 0.18)
            item.part.Size = Vector3.new(item.size, item.size, item.size)
        elseif hailLike then
            item.size = random:NextNumber(0.13, 0.23)
            item.part.Size = Vector3.new(item.size, item.size, item.size)
        elseif kind == "ash" or kind == "embers" then
            item.size = random:NextNumber(0.065, kind == "embers" and 0.12 or 0.11)
            item.part.Size = Vector3.new(item.size, item.size, item.size)
        elseif movingLine then
            local length
            if kind == "dust" or kind == "wind" then
                length = random:NextNumber(2.0, kind == "dust" and 5.8 or 4.7)
            else
                length = random:NextNumber(1.35, mode == "Drizzle" and 2.1 or 3.25)
            end
            item.size = random:NextNumber(0.025, rainLike and 0.055 or 0.07)
            item.part.Size = Vector3.new(item.size, item.size, length)
        end
        item.baseTransparency = rainLike and random:NextNumber(0.28, 0.57)
            or hailLike and random:NextNumber(0.12, 0.30)
            or snowLike and random:NextNumber(0.12, 0.32)
            or kind == "embers" and random:NextNumber(0.06, 0.20)
            or random:NextNumber(0.30, 0.56)
        item.part.Transparency = pool.covered and 1 or item.baseTransparency
        if movingLine then
            local direction
            if kind == "wind" or kind == "dust" then
                direction = pool.wind + item.drift + Vector3.new(0, 0.15, 0)
            else
                direction = pool.wind + item.drift + Vector3.new(0, -item.speed, 0)
            end
            if direction.Magnitude < 0.001 then direction = Vector3.new(0, -1, 0) end
            item.part.CFrame = CFrame.lookAt(item.position, item.position + direction.Unit)
        else
            item.part.CFrame = CFrame.new(item.position)
        end
    end

    local initialCamera = workspace.CurrentCamera
    local initialPosition = initialCamera and initialCamera.CFrame.Position or Vector3.zero
    for i = 1, count do
        local part = Instance.new("Part")
        part.Name = (kind == "snow" and "WorldSnowFlake") or (kind == "embers" and "WorldEmber") or (kind == "ash" and "WorldAsh") or "WorldWeatherStreak"
        part.Anchored = true
        part.CanCollide = false
        part.CanTouch = false
        part.CanQuery = false
        part.CastShadow = false
        part.Massless = true
        part.Locked = true
        part.Reflectance = 0
        part.Material = kind == "embers" and Enum.Material.Neon or Enum.Material.SmoothPlastic
        part.Color = cfg.tint:Lerp(Color3.new(1, 1, 1), rainLike and 0.22 or snowLike and 0.72 or kind == "embers" and 0.28 or 0.08)
        part.Shape = (snowLike or hailLike or kind == "ash" or kind == "embers") and Enum.PartType.Ball or Enum.PartType.Block
        part.Transparency = 1
        part.Parent = worldFolder
        local item = {part = part, position = Vector3.zero, speed = 1, size = 0.1, phase = 0, drift = Vector3.zero, baseTransparency = 0.4}
        pool.items[#pool.items + 1] = item
        spawnPosition(item, initialPosition)
    end
    return pool
end

local function setWeatherWorldCovered(pool, covered)
    if not pool or pool.covered == covered then return end
    pool.covered = covered
    for _, item in ipairs(pool.items) do
        if item.part and item.part.Parent then
            item.part.Transparency = covered and 1 or item.baseTransparency
        end
    end
end

local function updateWeatherWorldGeometry(pool, cameraPosition, dt, now)
    if not pool or #pool.items == 0 then return end
    pool.accumulator = pool.accumulator + math.min(dt, 0.10)
    if pool.accumulator < pool.interval then return end
    local step = math.min(pool.accumulator, 0.10)
    pool.accumulator = 0
    local wind = pool.wind * (pool.gustScale or 1)
    local isRainLike = pool.kind == "rain" or pool.kind == "drizzle" or pool.kind == "sleet"
    for _, item in ipairs(pool.items) do
        local part = item.part
        if part and part.Parent then
            if not pool.covered then
                local velocity
                if isRainLike or pool.kind == "hail" then
                    velocity = wind + item.drift + Vector3.new(0, -item.speed, 0)
                elseif pool.kind == "snow" then
                    velocity = wind * 0.36 + Vector3.new(math.sin(now * 1.25 + item.phase) * 1.8, -item.speed, math.cos(now * 0.92 + item.phase) * 1.8)
                elseif pool.kind == "wind" or pool.kind == "dust" then
                    local windDirection = wind.Magnitude > 0.01 and wind.Unit or Vector3.new(1, 0, 0)
                    local windRatio = math.clamp(wind.Magnitude / pool.windBaseMagnitude, 0.25, 2)
                    velocity = windDirection * item.speed * windRatio + item.drift + Vector3.new(0, math.sin(now * 2 + item.phase) * 0.35, 0)
                elseif pool.kind == "ash" then
                    velocity = wind * 0.42 + item.drift * 0.38 + Vector3.new(math.sin(now + item.phase) * 0.65, -item.speed * 0.28, math.cos(now * 0.8 + item.phase) * 0.65)
                else -- embers rise slowly and are carried by the local wind
                    velocity = wind * 0.20 + item.drift * 0.25 + Vector3.new(math.sin(now * 1.4 + item.phase) * 0.65, item.speed * 0.48, math.cos(now + item.phase) * 0.65)
                end
                item.position = item.position + velocity * step
                local offset = item.position - cameraPosition
                local horizontalSq = offset.X * offset.X + offset.Z * offset.Z
                local tooFar = horizontalSq > (pool.radius * 1.55) ^ 2
                local tooLow = item.position.Y < cameraPosition.Y - ((isRainLike or pool.kind == "hail") and 44 or 30)
                local tooHigh = item.position.Y > cameraPosition.Y + 96
                if tooFar or tooLow or tooHigh then
                    -- Recycle only after the streak leaves the 3D weather volume. Existing streaks
                    -- never follow the camera, so camera pans cannot make them slide across the view.
                    local angle = math.random() * math.pi * 2
                    local radius = math.sqrt(math.random()) * pool.radius
                    local yOffset
                    if isRainLike or pool.kind == "hail" then yOffset = 24 + math.random() * 52
                    elseif pool.kind == "snow" then yOffset = -2 + math.random() * 36
                    elseif pool.kind == "wind" or pool.kind == "dust" then yOffset = -10 + math.random() * 37
                    elseif pool.kind == "ash" then yOffset = -12 + math.random() * 40
                    else yOffset = -18 + math.random() * 24 end
                    item.position = cameraPosition + Vector3.new(math.cos(angle) * radius, yOffset, math.sin(angle) * radius)
                end
                if pool.kind == "snow" or pool.kind == "ash" or pool.kind == "embers" then
                    part.CFrame = CFrame.new(item.position)
                else
                    local direction = velocity.Magnitude > 0.001 and velocity.Unit or Vector3.new(0, -1, 0)
                    part.CFrame = CFrame.lookAt(item.position, item.position + direction)
                end
            end
        end
    end
end

WeatherState.apply = function()
    clearWeather()
    if not WeatherState.enabled or Unloaded then
        local sky = Theme and Theme.CustomSkyBoxState
        if sky and sky.RefreshBackdrop then pcall(sky.RefreshBackdrop) end
        return
    end

    local presets = {
        ["Drizzle"] = {kind="drizzle", rate=115, speed=NumberRange.new(28, 39), life=NumberRange.new(1.0, 1.45), wind=Vector3.new(1, -3, 0), tint=Color3.fromRGB(207, 216, 228), saturation=-0.08, contrast=0.025, brightness=-0.005, air=0.10, haze=0.45},
        ["Rain"] = {kind="rain", rate=300, speed=NumberRange.new(52, 66), life=NumberRange.new(0.72, 1.02), wind=Vector3.new(2, -7, 0), tint=Color3.fromRGB(198, 210, 224), saturation=-0.12, contrast=0.08, brightness=-0.025, air=0.20, haze=1.2},
        ["Downpour"] = {kind="rain", rate=430, speed=NumberRange.new(64, 82), life=NumberRange.new(0.68, 0.98), wind=Vector3.new(7, -10, 1), tint=Color3.fromRGB(174, 190, 207), saturation=-0.20, contrast=0.12, brightness=-0.055, air=0.28, haze=2.1},
        ["Tropical Downpour"] = {kind="rain", rate=520, speed=NumberRange.new(68, 86), life=NumberRange.new(0.65, 0.95), wind=Vector3.new(15, -10, 4), tint=Color3.fromRGB(164, 184, 202), saturation=-0.23, contrast=0.14, brightness=-0.06, air=0.30, haze=2.4},
        ["Thunderstorm"] = {kind="rain", rate=390, speed=NumberRange.new(62, 80), life=NumberRange.new(0.7, 1.0), wind=Vector3.new(12, -10, 2), tint=Color3.fromRGB(157, 174, 197), saturation=-0.24, contrast=0.17, brightness=-0.07, air=0.31, haze=2.7},
        ["Heavy Thunderstorm"] = {kind="rain", rate=500, speed=NumberRange.new(68, 88), life=NumberRange.new(0.62, 0.92), wind=Vector3.new(18, -11, 5), tint=Color3.fromRGB(139, 157, 181), saturation=-0.30, contrast=0.20, brightness=-0.09, air=0.34, haze=3.2},
        ["Hail"] = {kind="hail", rate=185, speed=NumberRange.new(36, 52), life=NumberRange.new(0.85, 1.15), wind=Vector3.new(5, -8, 1), tint=Color3.fromRGB(203, 218, 235), saturation=-0.18, contrast=0.12, brightness=-0.035, air=0.20, haze=1.25},
        ["Snow"] = {kind="snow", rate=125, speed=NumberRange.new(2.2, 4.2), life=NumberRange.new(5.5, 8.5), wind=Vector3.new(1.5, -0.5, 0.8), tint=Color3.fromRGB(220, 230, 242), saturation=-0.10, contrast=0.04, brightness=0.015, air=0.16, haze=0.8},
        ["Sleet"] = {kind="sleet", rate=160, speed=NumberRange.new(32, 48), life=NumberRange.new(0.8, 1.15), wind=Vector3.new(5, -6, 1.5), tint=Color3.fromRGB(205, 218, 232), saturation=-0.14, contrast=0.08, brightness=-0.02, air=0.20, haze=1.0},
        ["Blizzard"] = {kind="snow", rate=220, speed=NumberRange.new(5, 8), life=NumberRange.new(4.5, 7), wind=Vector3.new(12, -1.2, 4), tint=Color3.fromRGB(190, 207, 224), saturation=-0.23, contrast=0.08, brightness=-0.035, air=0.27, haze=2.0},
        ["Fog"] = {kind="fog", rate=34, speed=NumberRange.new(0.2, 0.9), life=NumberRange.new(5.5, 8.5), wind=Vector3.new(0.7, 0, 0.3), tint=Color3.fromRGB(208, 215, 223), saturation=-0.18, contrast=-0.025, brightness=-0.01, air=0.35, haze=5.8},
        ["Light Fog"] = {kind="fog", rate=18, speed=NumberRange.new(0.15, 0.65), life=NumberRange.new(6.5, 10), wind=Vector3.new(0.4, 0, 0.2), tint=Color3.fromRGB(220, 225, 231), saturation=-0.10, contrast=-0.015, brightness=0.005, air=0.20, haze=3.2},
        ["Overcast"] = {kind="overcast", rate=0, speed=NumberRange.new(0, 0), life=NumberRange.new(1, 1), wind=Vector3.new(1.2, 0, 0.4), tint=Color3.fromRGB(196, 204, 216), saturation=-0.10, contrast=0.025, brightness=-0.015, air=0.16, haze=0.8},
        ["Windy"] = {kind="wind", rate=100, speed=NumberRange.new(17, 30), life=NumberRange.new(1.5, 2.5), wind=Vector3.new(7, 0.2, 2), tint=Color3.fromRGB(226, 224, 216), saturation=-0.05, contrast=0.025, brightness=-0.005, air=0.08, haze=0.4},
        ["Dust Storm"] = {kind="dust", rate=170, speed=NumberRange.new(10, 22), life=NumberRange.new(2.1, 3.5), wind=Vector3.new(13, -0.1, 3), tint=Color3.fromRGB(203, 173, 132), saturation=-0.32, contrast=0.10, brightness=-0.045, air=0.30, haze=6.5},
        ["Ash"] = {kind="ash", rate=92, speed=NumberRange.new(2, 6), life=NumberRange.new(2.4, 4.5), wind=Vector3.new(3, -1.8, 0.6), tint=Color3.fromRGB(197, 186, 174), saturation=-0.28, contrast=0.06, brightness=-0.025, air=0.13, haze=0.8},
        ["Sparks"] = {kind="embers", rate=65, speed=NumberRange.new(2, 6), life=NumberRange.new(1.1, 2.2), wind=Vector3.new(0, 2.2, 0), tint=Color3.fromRGB(255, 223, 190), saturation=0.04, contrast=0.04, brightness=0.005, air=0.04, haze=0.2},
    }
    local cfg = presets[WeatherState.mode] or presets["Rain"]
    local isThunderstorm = WeatherState.mode == "Thunderstorm" or WeatherState.mode == "Heavy Thunderstorm"
    local isRain = cfg.kind == "rain" or cfg.kind == "drizzle" or cfg.kind == "sleet"
    local isSnow = cfg.kind == "snow" or cfg.kind == "sleet"
    local isHail = cfg.kind == "hail"
    local isRoofSensitive = isRain or isSnow or isHail
    local needsGroundSplashes = (isRain and WeatherState.mode ~= "Drizzle") or cfg.kind == "drizzle" or isHail

    local windOk, currentGlobalWind = pcall(function() return workspace.GlobalWind end)
    if windOk then
        WeatherState.runtime.globalWindBackup = currentGlobalWind
        WeatherState.runtime.globalWindBase = Vector3.new(cfg.wind.X, 0, cfg.wind.Z) * WeatherState.weatherWindScale
        pcall(function() workspace.GlobalWind = WeatherState.runtime.globalWindBase end)
    end

    local folder = Instance.new("Folder")
    folder.Name = "SatanicWeather"
    folder.Parent = workspace
    WeatherState.runtime.folder = folder

    -- Экранный слой отвечает только за мягкую цветовую атмосферу и вспышки.
    -- Дождь/снег/ветер больше НЕ рисуются в ScreenGui: они существуют в координатах workspace.
    local function createWeatherScreenFX()
        local gui = Instance.new("ScreenGui")
        gui.Name = "SatanicWeatherScreenFX"
        gui.ResetOnSpawn = false
        gui.IgnoreGuiInset = true
        gui.DisplayOrder = 50
        gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        gui.Parent = (ScreenGui and ScreenGui.Parent) or getParent()
        WeatherState.runtime.screenGui = gui

        local root = Instance.new("Frame")
        root.Name = "WeatherFXRoot"
        root.Size = UDim2.fromScale(1, 1)
        root.BackgroundTransparency = 1
        root.BorderSizePixel = 0
        root.Parent = gui

        local wash = Instance.new("Frame")
        wash.Name = "AtmosphericColorWash"
        wash.Size = UDim2.fromScale(1, 1)
        wash.BackgroundColor3 = cfg.tint
        wash.BorderSizePixel = 0
        wash.ZIndex = 1
        wash.Parent = root
        local washAlpha = 0.975
        if cfg.kind == "fog" then washAlpha = 0.945
        elseif cfg.kind == "dust" then washAlpha = 0.915
        elseif cfg.kind == "ash" then washAlpha = 0.958
        elseif cfg.kind == "overcast" then washAlpha = 0.985
        elseif isThunderstorm then washAlpha = 0.970
        elseif WeatherState.mode == "Tropical Downpour" then washAlpha = 0.965 end
        wash.BackgroundTransparency = washAlpha

        local haze = Instance.new("Frame")
        haze.Name = "CinematicHazeBand"
        haze.AnchorPoint = Vector2.new(0, 1)
        haze.Position = UDim2.new(0, 0, 1, 0)
        haze.Size = UDim2.new(1, 0, cfg.kind == "fog" and 0.44 or (cfg.kind == "dust" and 0.30 or 0.18), 0)
        haze.BackgroundColor3 = cfg.tint:Lerp(Color3.fromRGB(255, 255, 255), cfg.kind == "fog" and 0.13 or 0.035)
        haze.BackgroundTransparency = cfg.kind == "fog" and 0.86 or (cfg.kind == "dust" and 0.90 or 0.965)
        haze.BorderSizePixel = 0
        haze.ZIndex = 2
        haze.Parent = root
        local hazeGradient = Instance.new("UIGradient")
        hazeGradient.Rotation = 90
        hazeGradient.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1),
            NumberSequenceKeypoint.new(0.42, 0.72),
            NumberSequenceKeypoint.new(1, 0.12),
        })
        hazeGradient.Parent = haze

        local edgeColor = cfg.kind == "dust" and Color3.fromRGB(58, 43, 28) or Color3.fromRGB(9, 15, 25)
        local edgeAlpha = (cfg.kind == "fog" or cfg.kind == "dust") and 0.60 or 0.80
        local function edge(name, position, size, rotation, alpha)
            local frame = Instance.new("Frame")
            frame.Name = name
            frame.Position = position
            frame.Size = size
            frame.BackgroundColor3 = edgeColor
            frame.BackgroundTransparency = 0.35
            frame.BorderSizePixel = 0
            frame.ZIndex = 3
            frame.Parent = root
            local gradient = Instance.new("UIGradient")
            gradient.Rotation = rotation
            gradient.Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, alpha),
                NumberSequenceKeypoint.new(1, 1),
            })
            gradient.Parent = frame
        end
        edge("LeftAtmosphereVignette", UDim2.new(0, 0, 0, 0), UDim2.new(0, 100, 1, 0), 0, edgeAlpha)
        edge("RightAtmosphereVignette", UDim2.new(1, -100, 0, 0), UDim2.new(0, 100, 1, 0), 180, edgeAlpha)
        edge("TopAtmosphereVignette", UDim2.new(0, 0, 0, 0), UDim2.new(1, 0, 0, 54), 90, edgeAlpha + 0.06)
        edge("BottomAtmosphereVignette", UDim2.new(0, 0, 1, -74), UDim2.new(1, 0, 0, 74), 270, edgeAlpha + 0.03)

        local flash = Instance.new("Frame")
        flash.Name = "LightningScreenFlash"
        flash.Size = UDim2.fromScale(1, 1)
        flash.BackgroundColor3 = Color3.fromRGB(207, 227, 255)
        flash.BackgroundTransparency = 1
        flash.BorderSizePixel = 0
        flash.ZIndex = 10
        flash.Parent = root

        local fx = {
            gui = gui, root = root, wash = wash, haze = haze, flash = flash,
            streaks = {}, mode = cfg.kind, covered = false, gustScale = 1,
            hazeBase = haze.BackgroundTransparency,
        }
        WeatherState.runtime.screenFx = fx
        return fx
    end

    createWeatherScreenFX()
    WeatherState.runtime.worldGeometry = createWeatherWorldGeometry(folder, cfg, WeatherState.mode, WeatherState.weatherIntensity, weatherRandom, WeatherState.weatherWindScale)

    -- Капли на поверхности изображаются расширяющимися отражающимися дисками,
    -- а не разлетающимися частицами. Пул фиксированного размера не создаёт мусор.
    local splashNodes = {}
    if needsGroundSplashes then
        for i = 1, 7 do
            local ripple = Instance.new("Part")
            ripple.Name = "WeatherGroundRipple"
            ripple.Shape = Enum.PartType.Cylinder
            ripple.Anchored = true
            ripple.CanCollide = false
            ripple.CanTouch = false
            ripple.CanQuery = false
            ripple.CastShadow = false
            ripple.Material = Enum.Material.Glass
            ripple.Color = isHail and Color3.fromRGB(220, 236, 255) or Color3.fromRGB(145, 188, 224)
            ripple.Transparency = 1
            ripple.Size = Vector3.new(0.035, 0.3, 0.3)
            ripple.Parent = folder
            splashNodes[#splashNodes + 1] = {
                part = ripple, tween = nil,
                angle = (i / 7) * math.pi * 2,
                radius = 7 + (i % 3) * 7,
            }
        end
    end

    local grade = Instance.new("ColorCorrectionEffect")
    grade.Name = "SatanicWeatherColorGrade"
    local skyProtectedAtCreation = isCustomSkyboxActive()
    grade.TintColor = skyProtectedAtCreation and Color3.new(1, 1, 1) or cfg.tint
    grade.Saturation = skyProtectedAtCreation and 0 or cfg.saturation
    grade.Contrast = skyProtectedAtCreation and 0 or cfg.contrast
    grade.Brightness = skyProtectedAtCreation and 0 or cfg.brightness
    grade.Parent = Lighting
    WeatherState.runtime.colorGrade = grade

    if isThunderstorm or WeatherState.mode == "Tropical Downpour" or WeatherState.mode == "Downpour" then
        local bloom = Instance.new("BloomEffect")
        bloom.Name = "SatanicWeatherBloom"
        bloom.Intensity = isThunderstorm and 0.22 or 0.10
        bloom.Size = isThunderstorm and 28 or 20
        bloom.Threshold = 1.35
        bloom.Parent = Lighting
        WeatherState.runtime.bloom = bloom
    end

    -- Local overcast cover: snapshot existing Terrain.Clouds and restore it on disable.
    -- Clouds are deliberately left to the skybox controller while custom sky mode is active;
    -- this prevents a map/weather cloud sheet from covering the selected sky cube.
    local terrain = workspace.Terrain
    if terrain and not isCustomSkyboxActive() then
        local clouds = terrain:FindFirstChildOfClass("Clouds")
        local createdClouds = clouds == nil
        if not clouds then
            clouds = Instance.new("Clouds")
            clouds.Name = "SatanicWeatherClouds"
            clouds.Parent = terrain
        end
        WeatherState.runtime.clouds = clouds
        WeatherState.runtime.cloudBackup = {created = createdClouds}
        if not createdClouds then
            WeatherState.runtime.cloudBackup.Cover = clouds.Cover
            WeatherState.runtime.cloudBackup.Density = clouds.Density
            WeatherState.runtime.cloudBackup.Color = clouds.Color
        end
        local cloudPresets = {
            drizzle = {cover=0.58, density=0.42},
            rain = {cover=(isThunderstorm and 0.97 or (WeatherState.mode == "Tropical Downpour" and 0.95 or (WeatherState.mode == "Downpour" and 0.90 or 0.78))), density=(isThunderstorm and 0.94 or (WeatherState.mode == "Tropical Downpour" and 0.88 or 0.76))},
            hail = {cover=0.94, density=0.86},
            snow = {cover=(WeatherState.mode == "Blizzard" and 0.95 or 0.78), density=(WeatherState.mode == "Blizzard" and 0.86 or 0.68)},
            sleet = {cover=0.84, density=0.72},
            fog = {cover=(WeatherState.mode == "Light Fog" and 0.35 or 0.50), density=(WeatherState.mode == "Light Fog" and 0.23 or 0.34)},
            overcast = {cover=0.93, density=0.72},
            wind = {cover=0.26, density=0.22},
            dust = {cover=0.98, density=0.92},
            ash = {cover=0.82, density=0.70},
            embers = {cover=0.32, density=0.24},
        }
        local cloudCfg = cloudPresets[cfg.kind] or cloudPresets.rain
        local cloudTarget = {
            Cover = cloudCfg.cover,
            Density = cloudCfg.density,
            Color = cfg.tint:Lerp(Color3.fromRGB(255, 255, 255), 0.30),
        }
        WeatherState.runtime.cloudTween = TweenService:Create(clouds, TweenInfo.new(0.85, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), cloudTarget)
        WeatherState.runtime.cloudTween:Play()
    end

    -- Не перезаписываем Atmosphere, установленную самой игрой или Minecraft Fog.
    -- Если атмосферы нет, добавляем локальную на клиенте и удаляем её при выключении.
    local atmSettings = {
        Density = cfg.air, Haze = cfg.haze, Offset = -0.12,
        Color = cfg.tint, Decay = cfg.tint:Lerp(Color3.fromRGB(115, 125, 145), 0.25), Glare = 0.02,
    }
    local function ensureWeatherAtmosphere()
        -- A custom skybox suppresses atmospheric scattering so the selected cube remains fully visible.
        -- Precipitation, world-space wind and lightning continue as normal.
        if isCustomSkyboxActive() then return end
        if fogEnabled or WeatherState.runtime.atmosphere or WeatherState.runtime.atmosphereOverride then return end
        if cfg.kind == "embers" or cfg.kind == "ash" then return end
        local existing = Lighting:FindFirstChildOfClass("Atmosphere")
        if existing then
            local backup = {}
            for _, property in ipairs(WEATHER_ATMOSPHERE_PROPERTIES) do
                backup[property] = existing[property]
            end
            WeatherState.runtime.atmosphereOverride = existing
            WeatherState.runtime.atmosphereBackup = backup
            WeatherState.runtime.atmosphereTween = TweenService:Create(existing, TweenInfo.new(1.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), atmSettings)
            WeatherState.runtime.atmosphereTween:Play()
        else
            local atm = Instance.new("Atmosphere")
            atm.Name = "SatanicWeatherAtmosphere"
            for property, value in pairs(atmSettings) do atm[property] = value end
            atm.Parent = Lighting
            WeatherState.runtime.atmosphere = atm
        end
    end
    ensureWeatherAtmosphere()
    startWeatherAudio(cfg, isThunderstorm)
    do
        local sky = Theme and Theme.CustomSkyBoxState
        if sky and sky.RefreshBackdrop then pcall(sky.RefreshBackdrop) end
    end

    local nextRoofCheck = 0
    local nextAtmosphereCheck = 0
    local nextSplashUpdate = 0
    local nextGustChange = 0
    local gustScale = 1
    local currentlyCovered = false
    local nextLightning = os.clock() + weatherRandom:NextNumber(isThunderstorm and 4.5 or 7, isThunderstorm and 9.0 or 15) / math.max(WeatherState.weatherLightningFrequency, 0.1)
    local baseBrightness, baseContrast = grade.Brightness, grade.Contrast

    local function addLightningSegment(a, b, width, color, transparency)
        local delta = b - a
        if delta.Magnitude < 0.05 then return nil end
        local segment = Instance.new("Part")
        segment.Name = "WeatherLightningBolt"
        segment.Anchored = true
        segment.CanCollide = false
        segment.CanTouch = false
        segment.CanQuery = false
        segment.CastShadow = false
        segment.Material = Enum.Material.Neon
        segment.Color = color
        segment.Transparency = transparency
        segment.Size = Vector3.new(width, width, delta.Magnitude)
        segment.CFrame = CFrame.lookAt((a + b) * 0.5, b)
        segment.Parent = folder
        TweenService:Create(segment, TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Transparency = 1}):Play()
        Debris:AddItem(segment, 0.28)
        return segment
    end

    local function spawnLightningStrike(origin)
        local theta = weatherRandom:NextNumber(0, math.pi * 2)
        local radius = weatherRandom:NextNumber(105, 230)
        local strikeBase = origin + Vector3.new(math.cos(theta) * radius, 0, math.sin(theta) * radius)
        local rayParams = RaycastParams.new()
        rayParams.FilterType = Enum.RaycastFilterType.Exclude
        local exclude = {folder}
        if LocalPlayer.Character then table.insert(exclude, LocalPlayer.Character) end
        rayParams.FilterDescendantsInstances = exclude
        rayParams.IgnoreWater = true
        local hit = workspace:Raycast(strikeBase + Vector3.new(0, 105, 0), Vector3.new(0, -220, 0), rayParams)
        local finish = hit and (hit.Position + Vector3.new(0, 2, 0)) or (strikeBase + Vector3.new(0, 7, 0))
        local start = finish + Vector3.new(0, weatherRandom:NextNumber(115, 165), 0)
        local points = {start}
        local boltSteps = Theme.ExtremePerformance and 4 or 7
        for i = 1, boltSteps do
            local f = i / (boltSteps + 1)
            local envelope = math.sin(math.pi * f)
            local p = start:Lerp(finish, f) + Vector3.new(weatherRandom:NextNumber(-11, 11) * envelope, 0, weatherRandom:NextNumber(-11, 11) * envelope)
            points[#points + 1] = p
        end
        points[#points + 1] = finish
        for i = 1, #points - 1 do
            addLightningSegment(points[i], points[i + 1], 0.62, Color3.fromRGB(100, 178, 255), 0.32)
            addLightningSegment(points[i], points[i + 1], 0.20, Color3.fromRGB(241, 248, 255), 0.04)
        end
        -- Short side branches make the bolt less geometric.
        for branch = 1, (Theme.ExtremePerformance and 1 or 2) do
            local startIndex = weatherRandom:NextInteger(2, math.max(2, #points - 2))
            local branchStart = points[startIndex]
            local side = weatherRandom:NextNumber(-1, 1) >= 0 and 1 or -1
            local branchMid = branchStart + Vector3.new(side * weatherRandom:NextNumber(5, 11), -weatherRandom:NextNumber(7, 15), weatherRandom:NextNumber(-5, 5))
            local branchEnd = branchMid + Vector3.new(side * weatherRandom:NextNumber(3, 8), -weatherRandom:NextNumber(8, 14), weatherRandom:NextNumber(-4, 4))
            addLightningSegment(branchStart, branchMid, 0.34, Color3.fromRGB(115, 190, 255), 0.35)
            addLightningSegment(branchMid, branchEnd, 0.22, Color3.fromRGB(238, 248, 255), 0.08)
        end
        local glowPart = Instance.new("Part")
        glowPart.Name = "WeatherLightningGlow"
        glowPart.Anchored = true
        glowPart.CanCollide = false
        glowPart.CanTouch = false
        glowPart.CanQuery = false
        glowPart.Transparency = 1
        glowPart.Size = Vector3.new(1, 1, 1)
        glowPart.Position = finish + Vector3.new(0, 8, 0)
        glowPart.Parent = folder
        local light = Instance.new("PointLight")
        light.Color = Color3.fromRGB(176, 213, 255)
        light.Range = 90
        light.Brightness = 5.5
        light.Shadows = false
        light.Parent = glowPart
        TweenService:Create(light, TweenInfo.new(0.20), {Brightness = 0}):Play()
        Debris:AddItem(glowPart, 0.24)

        -- Sound arrives after the flash; farther strikes are quieter and later.
        local strikeDistance = (finish - origin).Magnitude
        local thunderDelay = math.clamp(strikeDistance / 343, 0.22, 1.7)
        task.delay(thunderDelay, function()
            if not folder.Parent or not WeatherState.enabled or not isThunderstorm or not WeatherState.weatherAudioEnabled or WeatherState.weatherAudioVolume <= 0 then return end
            local thunder = Instance.new("Sound")
            thunder.Name = "SatanicDistantThunder"
            thunder.SoundId = "rbxassetid://12222030"
            thunder.Volume = math.clamp(WeatherState.weatherAudioVolume * (1.15 - strikeDistance / 450), math.min(0.08, WeatherState.weatherAudioVolume), WeatherState.weatherAudioVolume)
            thunder.PlaybackSpeed = weatherRandom:NextNumber(0.88, 1.04)
            thunder.Parent = SoundService
            pcall(function() thunder:Play() end)
            Debris:AddItem(thunder, 8)
        end)
    end

    local weatherLogicAccumulator = 0
    -- Кэш для луча «под крышей»: раньше каждая проверка создавала новую таблицу
    -- и новый RaycastParams. Обновляем их только при смене персонажа.
    local roofParams = RaycastParams.new()
    roofParams.FilterType = Enum.RaycastFilterType.Exclude
    roofParams.IgnoreWater = true
    local roofExclusions = {folder}
    local roofChar = nil
    WeatherState.runtime.connection = RunService.Heartbeat:Connect(function(dt)
        if Unloaded then
            WeatherState.enabled = false
            clearWeather()
            return
        end
        local camera = workspace.CurrentCamera
        if not camera or not folder.Parent then return end
        weatherLogicAccumulator = weatherLogicAccumulator + dt
        if weatherLogicAccumulator < (Theme.ExtremePerformance and 1 / 20 or 1 / 30) then return end
        dt = weatherLogicAccumulator
        weatherLogicAccumulator = 0
        local camPos = camera.CFrame.Position

        local now = os.clock()
        if cfg.kind ~= "fog" and now >= nextGustChange then
            nextGustChange = now + weatherRandom:NextNumber(0.8, 1.7)
            gustScale = weatherRandom:NextNumber(0.68, 1.34)
            local screenFx = WeatherState.runtime.screenFx
            if screenFx then screenFx.gustScale = gustScale end
            if WeatherState.runtime.worldGeometry then WeatherState.runtime.worldGeometry.gustScale = gustScale end
            if WeatherState.runtime.globalWindBase then
                pcall(function() workspace.GlobalWind = WeatherState.runtime.globalWindBase * gustScale end)
            end
        end
        if now >= nextAtmosphereCheck then
            nextAtmosphereCheck = now + 0.5
            ensureWeatherAtmosphere()
        end
        if isRoofSensitive and now >= nextRoofCheck then
            nextRoofCheck = now + 0.18
            local char = LocalPlayer.Character
            if char ~= roofChar then
                roofChar = char
                roofExclusions = {folder}
                if char then table.insert(roofExclusions, char) end
                roofParams.FilterDescendantsInstances = roofExclusions
            end
            local ceiling = workspace:Raycast(camPos, Vector3.new(0, 110, 0), roofParams)
            local covered = ceiling ~= nil and ceiling.Distance < 100
            currentlyCovered = covered
            local screenFx = WeatherState.runtime.screenFx
            if screenFx then screenFx.covered = covered end
            setWeatherWorldCovered(WeatherState.runtime.worldGeometry, covered)
        end

        local screenFx = WeatherState.runtime.screenFx
        if screenFx and screenFx.haze and screenFx.haze.Parent then
            -- Only opacity breathes subtly; the haze band no longer translates across the screen.
            local wave = math.sin(now * 0.33) * (cfg.kind == "fog" and 0.018 or 0.005)
            screenFx.haze.BackgroundTransparency = math.clamp(screenFx.hazeBase + wave, 0.78, 0.985)
        end
        updateWeatherWorldGeometry(WeatherState.runtime.worldGeometry, camPos, dt, now)

        if #splashNodes > 0 and not currentlyCovered and now >= nextSplashUpdate then
            nextSplashUpdate = now + 0.32
            local rayParams = RaycastParams.new()
            rayParams.FilterType = Enum.RaycastFilterType.Exclude
            local exclude = {folder}
            if LocalPlayer.Character then table.insert(exclude, LocalPlayer.Character) end
            rayParams.FilterDescendantsInstances = exclude
            rayParams.IgnoreWater = true
            for _, node in ipairs(splashNodes) do
                local theta = node.angle + now * 0.15
                local sample = camPos + Vector3.new(math.cos(theta) * node.radius, 55, math.sin(theta) * node.radius)
                local hit = workspace:Raycast(sample, Vector3.new(0, -155, 0), rayParams)
                if hit and node.part.Parent then
                    local ripple = node.part
                    if node.tween then pcall(function() node.tween:Cancel() end) end
                    ripple.CFrame = CFrame.new(hit.Position + Vector3.new(0, 0.035, 0)) * CFrame.Angles(0, 0, math.rad(90))
                    ripple.Size = Vector3.new(0.035, 0.28, 0.28)
                    ripple.Transparency = 0.48
                    node.tween = TweenService:Create(ripple, TweenInfo.new(isHail and 0.34 or 0.48, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                        Size = Vector3.new(0.035, isHail and 1.45 or 2.2, isHail and 1.45 or 2.2),
                        Transparency = 1,
                    })
                    node.tween:Play()
                end
            end
        end

        if isThunderstorm and now >= nextLightning and WeatherState.runtime.colorGrade == grade then
            nextLightning = now + weatherRandom:NextNumber(isThunderstorm and 4.5 or 7, isThunderstorm and 9.0 or 15) / math.max(WeatherState.weatherLightningFrequency, 0.1)
            spawnLightningStrike(camPos)
            local fxFlash = WeatherState.runtime.screenFx and WeatherState.runtime.screenFx.flash
            if fxFlash and fxFlash.Parent then
                fxFlash.BackgroundTransparency = 0.43
                TweenService:Create(fxFlash, TweenInfo.new(0.24, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundTransparency = 1}):Play()
            end
            grade.Brightness = math.min(0.32, baseBrightness + math.clamp(WeatherState.weatherLightningBrightness * 0.025, 0.05, 0.28))
            grade.Contrast = math.min(0.42, baseContrast + 0.08)
            if WeatherState.runtime.bloom then WeatherState.runtime.bloom.Intensity = 0.85 end
            task.delay(0.075, function()
                if WeatherState.runtime.colorGrade == grade and grade.Parent and WeatherState.enabled and isThunderstorm then
                    TweenService:Create(grade, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                        Brightness = baseBrightness, Contrast = baseContrast,
                    }):Play()
                    if WeatherState.runtime.bloom then
                        TweenService:Create(WeatherState.runtime.bloom, TweenInfo.new(0.25), {Intensity = 0.22}):Play()
                    end
                end
            end)
            if weatherRandom:NextNumber() < 0.28 then
                task.delay(0.16, function()
                    if WeatherState.runtime.colorGrade == grade and grade.Parent and WeatherState.enabled and isThunderstorm then
                        local offset = Vector3.new(weatherRandom:NextNumber(-12, 12), 0, weatherRandom:NextNumber(-12, 12))
                        spawnLightningStrike(camPos + offset)
                        local chainFlash = WeatherState.runtime.screenFx and WeatherState.runtime.screenFx.flash
                        if chainFlash and chainFlash.Parent then
                            chainFlash.BackgroundTransparency = 0.58
                            TweenService:Create(chainFlash, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundTransparency = 1}):Play()
                        end
                        grade.Brightness = math.min(0.32, baseBrightness + math.clamp(WeatherState.weatherLightningBrightness * 0.018, 0.04, 0.20))
                        task.delay(0.06, function()
                            if WeatherState.runtime.colorGrade == grade and grade.Parent and WeatherState.enabled and isThunderstorm then
                                TweenService:Create(grade, TweenInfo.new(0.18), {Brightness = baseBrightness, Contrast = baseContrast}):Play()
                                if WeatherState.runtime.bloom then
                                    TweenService:Create(WeatherState.runtime.bloom, TweenInfo.new(0.22), {Intensity = 0.22}):Play()
                                end
                            end
                        end)
                    end
                end)
            end
        end
    end)
end

local weatherApplyToken = 0
local function scheduleWeatherApply()
    weatherApplyToken = weatherApplyToken + 1
    local token = weatherApplyToken
    task.delay(0.18, function()
        if token ~= weatherApplyToken or Unloaded or not WeatherState.enabled or Theme.ConfigRegistry.applying then return end
        WeatherState.apply()
    end)
end

secWeather:AddToggle("Enable Weather", false, function(v)
    WeatherState.enabled = v
    if not Theme.ConfigRegistry.applying then WeatherState.apply() end
end, function(api)
    api:AddSlider("Effect density", 0.5, 2.0, WeatherState.weatherIntensity, function(value)
        WeatherState.weatherIntensity = value
        if WeatherState.enabled and not Theme.ConfigRegistry.applying then scheduleWeatherApply() end
    end, 0.1)
    api:AddSlider("Wind strength", 0.25, 2.0, WeatherState.weatherWindScale, function(value)
        WeatherState.weatherWindScale = value
        local screenFx = WeatherState.runtime.screenFx
        if screenFx then screenFx.gustScale = WeatherState.weatherWindScale end
        if WeatherState.enabled and not Theme.ConfigRegistry.applying then scheduleWeatherApply() end
    end, 0.05)
    api:AddSlider("Lightning frequency", 0.5, 2.0, WeatherState.weatherLightningFrequency, function(value)
        WeatherState.weatherLightningFrequency = value
    end, 0.1)
    api:AddSlider("Lightning brightness", 2, 10, WeatherState.weatherLightningBrightness, function(value)
        WeatherState.weatherLightningBrightness = value
    end, 1)
    api:AddSlider("Weather volume", 0, 1, WeatherState.weatherAudioVolume, function(value)
        WeatherState.weatherAudioVolume = value
        local function refreshWeatherSound(sound)
            if sound and sound.Parent then
                sound.Volume = WeatherState.weatherAudioEnabled and WeatherState.weatherAudioVolume * (sound:GetAttribute("SatanicWeatherVolumeScale") or 0.2) or 0
            end
        end
        refreshWeatherSound(WeatherState.runtime.ambience)
        refreshWeatherSound(WeatherState.runtime.windAmbience)
    end, 0.05)
    api:AddToggle("Weather sound", WeatherState.weatherAudioEnabled, function(value)
        WeatherState.weatherAudioEnabled = value
        if not value then
            stopWeatherAudio()
        elseif WeatherState.enabled and not Theme.ConfigRegistry.applying then
            WeatherState.apply()
        end
    end)
end)
WeatherState.button = secWeather:AddButton("Weather: " .. WeatherState.mode, function()
    WeatherState.index = WeatherState.index % #WeatherState.modes + 1
    WeatherState.mode = WeatherState.modes[WeatherState.index]
    WeatherState.button.Text = "Weather: " .. WeatherState.mode
    if WeatherState.enabled then WeatherState.apply() end
end)
end -- завершение изолированного погодного модуля; его local-регистры больше не занимают основной chunk

-- DISTANCE / VOLUMETRIC FOG — переработано.
-- Roblox игнорирует FogStart/FogEnd, если в Lighting лежит Atmosphere, поэтому
-- «дистанционный» режим временно парковит атмосферы карты (не уничтожая их),
-- а «объёмный» режим создаёт собственную мягкую атмосферу.
secMinecraftFog = createSection(worldTab.Right, "Fog", "Visuals/Right/Minecraft Fog")
rFog, gFog, bFog = 176, 190, 206
currentFogDensity = 2600        -- «Fog Distance»: FogEnd в студах (совместимо со старыми конфигами)
currentFogStrength = 0.32       -- «Fog Density»: 0..1 (насколько близко начинается дымка)
currentFogStart = 180           -- «Fog Start»: базовая точка начала дымки

function prepareWeatherAtmosphereForFog()
    if not WeatherState then return end
    if WeatherState.restoreAtmosphereOverride then WeatherState.restoreAtmosphereOverride(true) end
    if WeatherState.runtime and WeatherState.runtime.atmosphere then
        pcall(function() WeatherState.runtime.atmosphere:Destroy() end)
        WeatherState.runtime.atmosphere = nil
    end
end

do
    local Fog = {
        preset = "Soft Daylight", mode = 1, syncing = false,
        applying = false, needsSync = false, foreignAtmos = false, deferQueued = false,
        targetStart = nil, targetEnd = nil, targetColor = nil, targetAtm = nil,
    }
    Theme.FogController = Fog
    local fogCard = worldTab.Right:FindFirstChild("Fog") or worldTab:FindFirstChild("Fog")
    local ownAtmosphere

    local function colorDiffers(a, b)
        if not a or not b then return true end
        return math.abs(a.R - b.R) > 0.004 or math.abs(a.G - b.G) > 0.004 or math.abs(a.B - b.B) > 0.004
    end

    local function fitExpandableCard(card)
        local cont = card and card:FindFirstChild("Container")
        local layout = cont and cont:FindFirstChildOfClass("UIListLayout")
        if not layout then return end
        track(layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
            if card.Parent and card:GetAttribute("SatanicGridManaged") == true then
                local height = math.max(56, math.ceil(layout.AbsoluteContentSize.Y + 49))
                if card.Size.Y.Offset ~= height then card.Size = UDim2.fromOffset(card.Size.X.Offset, height) end
            end
        end))
    end
    fitExpandableCard(fogCard)

    local function parkAtmosphere(atmosphere)
        local backup = fogBackup
        if not backup or not atmosphere or atmosphere.Parent ~= Lighting or not atmosphere:IsA("Atmosphere") then return end
        if ownAtmosphere and atmosphere == ownAtmosphere then return end
        if atmosphere.Name ~= "AtelierSkyAtmosphere" and atmosphere.Name ~= "SatanicWeatherAtmosphere" then
            if not backup.known[atmosphere] then
                backup.known[atmosphere] = true
                backup.atmospheres[#backup.atmospheres + 1] = {object = atmosphere, parent = Lighting}
            end
        end
        -- Parent=nil сохраняет инстанс и все его свойства для восстановления.
        pcall(function() atmosphere.Parent = nil end)
    end

    local function destroyOwnAtmosphere()
        if ownAtmosphere then
            pcall(function() ownAtmosphere:Destroy() end)
            ownAtmosphere = nil
        end
    end

    function restoreFog()
        Fog.applying = true
        Fog.needsSync = false
        Fog.foreignAtmos = false
        Fog.targetStart, Fog.targetEnd, Fog.targetColor, Fog.targetAtm = nil, nil, nil, nil
        local backup = fogBackup
        destroyOwnAtmosphere()
        if not backup then
            Fog.applying = false
            return
        end
        fogBackup = nil
        pcall(function()
            Lighting.FogStart = backup.FogStart
            Lighting.FogEnd = backup.FogEnd
            Lighting.FogColor = backup.FogColor
        end)
        for _, entry in ipairs(backup.atmospheres) do
            -- Не отбираем атмосферу, которую карта успела перенести в другое место,
            -- и не пытаемся «оживить» уже уничтоженный инстанс.
            pcall(function()
                if entry.object and entry.object.Parent == nil and entry.parent then
                    entry.object.Parent = entry.parent
                end
            end)
        end
        Fog.applying = false
        local sky = Theme and Theme.CustomSkyBoxState
        if sky and sky.RefreshBackdrop then pcall(sky.RefreshBackdrop) end
    end

    function applyFog()
        if not fogEnabled or Fog.applying then return end
        Fog.applying = true
        local ok, err = pcall(function()
            if not fogBackup then
                -- Останавливаем погодную атмосферу, чтобы она не спорила с туманом.
                prepareWeatherAtmosphereForFog()
                local baseStart, baseEnd, baseColor = Lighting.FogStart, Lighting.FogEnd, Lighting.FogColor
                local sky = Theme and Theme.CustomSkyBoxState
                if sky and sky.GetOriginalFog then
                    local os, oe, oc = sky.GetOriginalFog()
                    if os ~= nil and oe ~= nil and oc ~= nil then
                        baseStart, baseEnd, baseColor = os, oe, oc
                    end
                end
                fogBackup = {
                    FogStart = baseStart, FogEnd = baseEnd, FogColor = baseColor,
                    atmospheres = {}, known = {},
                }
            end
            local strength = math.clamp(tonumber(currentFogStrength) or 0.32, 0, 1)
            local distance = math.clamp(tonumber(currentFogDensity) or 2600, 200, 8000)
            local startAt = math.clamp(tonumber(currentFogStart) or 180, 0, distance - 20)
            local color = Color3.fromRGB(rFog, gFog, bFog)

            if Fog.mode == 2 then
                -- ОБЪЁМНЫЙ РЕЖИМ: собственная атмосфера + бесконечная дистанция.
                for _, child in ipairs(Lighting:GetChildren()) do
                    if child:IsA("Atmosphere") then parkAtmosphere(child) end
                end
                if not ownAtmosphere or ownAtmosphere.Parent ~= Lighting then
                    destroyOwnAtmosphere()
                    ownAtmosphere = Instance.new("Atmosphere")
                    ownAtmosphere.Name = "SatanicVolumetricFog"
                    ownAtmosphere.Parent = Lighting
                end
                local atmProps = {
                    Density = 0.04 + strength * 0.34,
                    Offset = math.clamp(distance / 8000, 0, 1) * 0.2,
                    Color = color,
                    Decay = color:Lerp(Color3.new(1, 1, 1), 0.45),
                    Glare = 0,
                    Haze = strength * 0.5,
                }
                pcall(function()
                    -- Мягкий пресет: плотность заметно ниже прежних 0.3..1.0
                    ownAtmosphere.Density = atmProps.Density
                    ownAtmosphere.Offset = atmProps.Offset
                    ownAtmosphere.Color = atmProps.Color
                    ownAtmosphere.Decay = atmProps.Decay
                    ownAtmosphere.Glare = atmProps.Glare
                    ownAtmosphere.Haze = atmProps.Haze
                end)
                Fog.targetStart = 0
                Fog.targetEnd = 100000
                Fog.targetColor = color
                Fog.targetAtm = atmProps
                pcall(function()
                    Lighting.FogStart = 0
                    Lighting.FogEnd = 100000
                    Lighting.FogColor = color
                end)
            else
                -- ДИСТАНЦИОННЫЙ РЕЖИМ: обычный туман Roblox, без «молока» на экране.
                destroyOwnAtmosphere()
                for _, child in ipairs(Lighting:GetChildren()) do
                    if child:IsA("Atmosphere") then parkAtmosphere(child) end
                end
                local startValue
                if strength <= 0.001 then
                    startValue = 0
                    distance = 100000
                else
                    -- Density подтягивает начало дымки ближе, но никогда не делает
                    -- туман плотнее, чем позволяет Fog Start.
                    startValue = math.clamp(startAt * (1 - strength), 0, math.max(distance * 0.85, 1))
                end
                Fog.targetStart = startValue
                Fog.targetEnd = distance
                Fog.targetColor = color
                Fog.targetAtm = nil
                pcall(function()
                    Lighting.FogStart = startValue
                    Lighting.FogEnd = distance
                    Lighting.FogColor = color
                end)
            end
        end)
        Fog.needsSync = false
        Fog.foreignAtmos = false
        Fog.applying = false
        if not ok then warn("[Fog] applyFog error: " .. tostring(err)) end
    end

    local function scheduleFogSync()
        if Unloaded or not fogEnabled or Fog.applying then return end
        Fog.needsSync = true
        if Fog.deferQueued then return end
        Fog.deferQueued = true
        task.defer(function()
            Fog.deferQueued = false
            if not Unloaded and fogEnabled and (Fog.needsSync or Fog.foreignAtmos) then
                applyFog()
            end
        end)
    end

    -- Карта может добавить свою атмосферу или переписать туман на ходу.
    -- Внутри ChildAdded Parent заблокирован движком, поэтому перенос выполняем через defer и RenderStepped.
    track(Lighting.ChildAdded:Connect(function(child)
        if Unloaded or not fogEnabled or not child:IsA("Atmosphere") then return end
        if Fog.mode == 2 and ownAtmosphere and child == ownAtmosphere then return end
        Fog.foreignAtmos = true
        scheduleFogSync()
    end))
    track(Lighting:GetPropertyChangedSignal("FogStart"):Connect(scheduleFogSync))
    track(Lighting:GetPropertyChangedSignal("FogEnd"):Connect(scheduleFogSync))
    track(Lighting:GetPropertyChangedSignal("FogColor"):Connect(scheduleFogSync))

    local fogRenderBinding = "SatanicFogEnforce"
    pcall(function() RunService:UnbindFromRenderStep(fogRenderBinding) end)
    local fogWatchAccum = 0
    RunService:BindToRenderStep(fogRenderBinding, Enum.RenderPriority.Last.Value, function(dt)
        if Unloaded then return end
        -- Проверка состояния тумана не требует каждого кадра: 16 Гц достаточно,
        -- чтобы дрейф был незаметен, и заметно дешевле для CPU.
        fogWatchAccum = fogWatchAccum + (dt or 0)
        if fogWatchAccum < 0.06 then return end
        fogWatchAccum = 0
        if Theme.ConfigRegistry and Theme.ConfigRegistry.applying then return end
        if not fogEnabled then
            if fogBackup then restoreFog() end
            return
        end
        if Fog.applying then return end
        if Fog.needsSync or Fog.foreignAtmos or not fogBackup or Fog.targetStart == nil then
            applyFog()
            return
        end
        if Fog.mode == 2 then
            if not ownAtmosphere or ownAtmosphere.Parent ~= Lighting or Lighting:FindFirstChildOfClass("Atmosphere") ~= ownAtmosphere then
                applyFog()
                return
            end
            local t = Fog.targetAtm
            if t and (math.abs(ownAtmosphere.Density - t.Density) > 0.002
                or math.abs(ownAtmosphere.Offset - t.Offset) > 0.002
                or math.abs(ownAtmosphere.Haze - t.Haze) > 0.002
                or math.abs(ownAtmosphere.Glare - t.Glare) > 0.002
                or colorDiffers(ownAtmosphere.Color, t.Color)
                or colorDiffers(ownAtmosphere.Decay, t.Decay)) then
                applyFog()
                return
            end
        else
            if ownAtmosphere ~= nil or Lighting:FindFirstChildOfClass("Atmosphere") ~= nil then
                applyFog()
                return
            end
            if math.abs(Lighting.FogStart - Fog.targetStart) > 0.05
                or math.abs(Lighting.FogEnd - Fog.targetEnd) > 0.05
                or colorDiffers(Lighting.FogColor, Fog.targetColor) then
                applyFog()
                return
            end
        end
    end)
    registerCleanup(function()
        pcall(function() RunService:UnbindFromRenderStep(fogRenderBinding) end)
    end)

    local fogRefreshTimer = 0
    track(RunService.Heartbeat:Connect(function(dt)
        if Unloaded then return end
        fogRefreshTimer = fogRefreshTimer + dt
        if fogRefreshTimer < 1 then return end
        fogRefreshTimer = 0
        if not fogEnabled then
            if fogBackup then restoreFog() end
            return
        end
        -- Страховка без лишней работы: пересобираем туман только если состояние
        -- реально разъехалось (раньше applyFog с письмом в Lighting шёл 4 раза в секунду).
        if Fog.needsSync or Fog.foreignAtmos or not fogBackup or Fog.targetStart == nil then
            applyFog()
        elseif Fog.mode == 2 then
            if not ownAtmosphere or ownAtmosphere.Parent ~= Lighting or Lighting:FindFirstChildOfClass("Atmosphere") ~= ownAtmosphere then
                applyFog()
            end
        elseif ownAtmosphere ~= nil or Lighting:FindFirstChildOfClass("Atmosphere") ~= nil then
            applyFog()
        end
    end))

    local fogScope = "Settings/Enable Minecraft Fog"
    local function syncPresetSettings()
        local registry = Theme.ConfigRegistry
        if not registry or not registry.ApplyLabel then return end
        Fog.syncing = true
        registry:ApplyLabel("Fog Distance", currentFogDensity, fogScope)
        registry:ApplyLabel("Fog Start", currentFogStart, fogScope)
        registry:ApplyLabel("Fog Density", math.floor(currentFogStrength * 100 + 0.5), fogScope)
        local h, s, v = Color3.fromRGB(rFog, gFog, bFog):ToHSV()
        registry:ApplyLabel("Color Picker", {h, s, v}, fogScope, 1)
        Fog.syncing = false
    end

    -- Пресеты намеренно лёгкие: туман должен читаться как дымка, а не как стена.
    local presets = {
        ["Soft Daylight"] = {rgb = {190, 205, 220}, distance = 3200, start = 260, strength = 0.24},
        ["City Haze"]     = {rgb = {150, 162, 178}, distance = 2400, start = 200, strength = 0.32},
        ["Evening Violet"] = {rgb = {128, 108, 158}, distance = 2200, start = 180, strength = 0.38},
        ["Ash & Smoke"]   = {rgb = {96, 100, 108},  distance = 1800, start = 150, strength = 0.45},
        ["Cold Night"]    = {rgb = {72, 88, 116},   distance = 1600, start = 120, strength = 0.52},
        ["Amber Dust"]    = {rgb = {186, 146, 108}, distance = 2600, start = 220, strength = 0.30},
        ["Custom"]        = {rgb = {176, 190, 206}, distance = 2600, start = 180, strength = 0.32},
    }
    local presetOrder = {"Custom", "Soft Daylight", "City Haze", "Evening Violet", "Ash & Smoke", "Cold Night", "Amber Dust"}

    secMinecraftFog:AddToggle("Enable Minecraft Fog", false, function(state)
        fogEnabled = state
        if not Theme.ConfigRegistry.applying then
            if state then applyFog() elseif fogBackup then restoreFog() end
        end
    end, function(api)
        -- Режим переключается кнопкой: в окне настроек нет выпадающих списков.
        local modeButton
        modeButton = api:AddButton("Mode: " .. ((Fog.mode == 2) and "Volumetric" or "Distance"), function()
            Fog.mode = (Fog.mode == 2) and 1 or 2
            Fog.preset = "Custom"
            modeButton.Text = "Mode: " .. ((Fog.mode == 2) and "Volumetric" or "Distance")
            if fogEnabled and not Theme.ConfigRegistry.applying then applyFog() end
        end)
        api:AddSlider("Fog Distance", 300, 8000, currentFogDensity, function(v)
            currentFogDensity = v
            if fogEnabled and not Fog.syncing and not Theme.ConfigRegistry.applying then applyFog() end
        end)
        api:AddSlider("Fog Start", 0, 2000, currentFogStart, function(v)
            currentFogStart = v
            if fogEnabled and not Fog.syncing and not Theme.ConfigRegistry.applying then applyFog() end
        end)
        api:AddSlider("Fog Density", 0, 100, math.floor(currentFogStrength * 100 + 0.5), function(v)
            currentFogStrength = v / 100
            if fogEnabled and not Fog.syncing and not Theme.ConfigRegistry.applying then applyFog() end
        end)
        local fh, fs, fv = Color3.fromRGB(rFog, gFog, bFog):ToHSV()
        api:AddColorPicker(fh, fs, fv, function(h, s, v)
            local c = Color3.fromHSV(h, s, v)
            rFog = math.floor(c.R * 255 + 0.5); gFog = math.floor(c.G * 255 + 0.5); bFog = math.floor(c.B * 255 + 0.5)
            if fogEnabled and not Fog.syncing and not Theme.ConfigRegistry.applying then applyFog() end
        end)
        api:AddButton("Reset to light fog", function()
            rFog, gFog, bFog = 176, 190, 206
            currentFogDensity, currentFogStart, currentFogStrength = 2600, 180, 0.32
            Fog.mode = 1
            Fog.preset = "Soft Daylight"
            if modeButton and modeButton.Parent then modeButton.Text = "Mode: Distance" end
            syncPresetSettings()
            if fogEnabled then applyFog() end
        end)
    end)

    local presetButton
    presetButton = secMinecraftFog:AddButton("Fog preset: " .. Fog.preset, function()
        local idx = table.find(presetOrder, Fog.preset) or 1
        idx = idx % #presetOrder + 1
        Fog.preset = presetOrder[idx]
        presetButton.Text = "Fog preset: " .. Fog.preset
        local preset = presets[Fog.preset]
        if not preset then return end
        rFog, gFog, bFog = preset.rgb[1], preset.rgb[2], preset.rgb[3]
        currentFogDensity = preset.distance
        currentFogStart, currentFogStrength = preset.start, preset.strength
        if Theme.ConfigRegistry.applying then return end
        syncPresetSettings()
        if fogEnabled then applyFog() end
    end)
end

-- ===== SKY DOME HIDER =====
-- Часть карт перекрывает небо огромным куполом/потолком или атмосферным
-- «щитом»: в этом случае собственный Sky физически не видно — на экране
-- остаются только эффекты освещения и цветокоррекции (именно так выглядел баг).
-- Пока включён кастомный скайбокс, такие объекты временно скрываются,
-- а при выключении возвращаются с исходной прозрачностью.
do
    local saved = setmetatable({}, {__mode = "k"})
    local lastScan = 0
    local function looksLikeSkyShell(part)
        local name = string.lower(part.Name)
        if not (string.find(name, "sky", 1, true) or string.find(name, "dome", 1, true)
            or string.find(name, "ceiling", 1, true) or string.find(name, "atmos", 1, true)) then
            return false
        end
        local size = part.Size
        if math.max(size.X, size.Y, size.Z) < 400 then return false end
        -- Купола/скайбокс-плоскости обычно не имеют коллизии; настоящие полы и
        -- потолки карты мы не трогаем, чтобы не провалиться сквозь геометрию.
        return part.CanCollide == false and part.Anchored == true
    end
    function Theme.HideSkyDomes(force)
        local now = os.clock()
        if not force and now - lastScan < 6 then return end
        lastScan = now
        local ok, list = pcall(function() return workspace:GetDescendants() end)
        if not ok then return end
        for _, obj in ipairs(list) do
            if obj:IsA("BasePart") and obj.Transparency < 1 and saved[obj] == nil and looksLikeSkyShell(obj) then
                saved[obj] = obj.Transparency
                pcall(function() obj.Transparency = 1 end)
            end
        end
    end
    function Theme.RestoreSkyDomes()
        for obj, transparency in pairs(saved) do
            pcall(function() if obj and obj.Parent then obj.Transparency = transparency end end)
            saved[obj] = nil
        end
        lastScan = 0
    end
end

