        local ownSky, fxFolder, grade, atmos, emitter, emitterPart, original
        local fogAtStart = false
        local skyObjects, atmosObjects, cloudObjects, postObjects = {}, {}, {}, {}
        local motes = {}
        local cache = {}
        local revision = 0
        local lightProperties = {
            "Brightness", "ExposureCompensation", "ClockTime",
            "Ambient", "OutdoorAmbient", "ColorShift_Top", "ColorShift_Bottom",
            "EnvironmentDiffuseScale", "EnvironmentSpecularScale", "ShadowSoftness",
            "FogStart", "FogEnd", "FogColor",
        }

        local function valid(ticket)
            return ticket == revision and S.enabled and not Unloaded
        end

        local function isOwnOrOptInPost(object)
            if object == grade then return true end
            local n = object.Name
            if string.sub(n, 1, 13) == "FaceLessPost_" then return true end
            if n == "SatanicWingBloom" or n == "SatanicSandevistanColor" or n == "SatanicSandevistanBloom"
                or n == "SatanicCinematicColor" or n == "SatanicCinematicBloom" then
                return true
            end
            return false
        end

        local function isOwnOrOptInAtmos(object)
            if object == atmos then return true end
            local n = object.Name
            return n == "SatanicVolumetricFog" or n == "SatanicCinematicAtmosphere"
        end

        local function destroyVisuals()
            if ownSky then pcall(function() ownSky:Destroy() end) end
            if fxFolder then pcall(function() fxFolder:Destroy() end) end
            if grade then pcall(function() grade:Destroy() end) end
            if atmos then pcall(function() atmos:Destroy() end) end
            ownSky, fxFolder, grade, atmos, emitter, emitterPart = nil, nil, nil, nil, nil, nil
            table.clear(motes)
            S.active = false
        end

        local function weatherOverlay(hide)
            local fx = WeatherState and WeatherState.runtime and WeatherState.runtime.screenFx
            local root = fx and fx.root
            if not root then return end
            for _, node in ipairs(root:GetChildren()) do
                local n = node.Name
                if n == "AtmosphericColorWash" or n == "CinematicHazeBand" or string.find(n, "AtmosphereVignette", 1, true) then
                    if hide then
                        if node:GetAttribute("AtelierSkyVisible") == nil then
                            node:SetAttribute("AtelierSkyVisible", node.Visible)
                        end
                        node.Visible = false
                    else
                        local old = node:GetAttribute("AtelierSkyVisible")
                        if old ~= nil then
                            node.Visible = old
                            node:SetAttribute("AtelierSkyVisible", nil)
                        end
                    end
                end
            end
        end

        local function restore()
            local wasActive = S.active or original ~= nil
            destroyVisuals()
            if original then
                for property, value in pairs(original) do
                    if not (fogEnabled and (property == "FogStart" or property == "FogEnd" or property == "FogColor")) then
                        pcall(function() Lighting[property] = value end)
                    end
                end
                original = nil
            end
            for object, parent in pairs(skyObjects) do
                pcall(function() if object and object.Parent == nil then object.Parent = parent end end)
            end
            for object, values in pairs(atmosObjects) do
                pcall(function()
                    if object then
                        for key, value in pairs(values) do object[key] = value end
                    end
                end)
            end
            for object, value in pairs(cloudObjects) do
                pcall(function() if object then object.Enabled = value end end)
            end
            for object, value in pairs(postObjects) do
                pcall(function() if object then object.Enabled = value end end)
            end
            table.clear(skyObjects)
            table.clear(atmosObjects)
            table.clear(cloudObjects)
            table.clear(postObjects)
            weatherOverlay(false)
            if Theme.RestoreSkyDomes then pcall(Theme.RestoreSkyDomes) end
            if wasActive and not Unloaded then
                task.defer(function()
                    if S.enabled or Unloaded then return end
                    if WeatherState and WeatherState.enabled and WeatherState.apply then pcall(WeatherState.apply) end
                    if fogEnabled and type(applyFog) == "function" then pcall(applyFog) end
                end)
            end
        end

        local function muteChild(object)
            if not S.enabled or not S.active then return end
            if object:IsA("Sky") and object ~= ownSky then
                if skyObjects[object] == nil then skyObjects[object] = object.Parent or Lighting end
                pcall(function() object.Parent = nil end)
            elseif object:IsA("Atmosphere") and not isOwnOrOptInAtmos(object) and not fogEnabled then
                if atmosObjects[object] == nil then
                    atmosObjects[object] = {
                        Density = object.Density, Haze = object.Haze, Glare = object.Glare,
                        Color = object.Color, Decay = object.Decay, Offset = object.Offset,
                    }
                end
                pcall(function() object.Density = 0; object.Haze = 0; object.Glare = 0 end)
            elseif not isOwnOrOptInPost(object)
                and (object:IsA("BloomEffect") or object:IsA("ColorCorrectionEffect") or object:IsA("SunRaysEffect")) then
                if postObjects[object] == nil then postObjects[object] = object.Enabled end
                pcall(function() object.Enabled = false end)
            end
        end

        local function protect()
            if not S.enabled or not S.active then return end
            for _, object in ipairs(Lighting:GetChildren()) do
                muteChild(object)
            end
            local terrain = workspace:FindFirstChildOfClass("Terrain")
            if terrain then
                for _, object in ipairs(terrain:GetChildren()) do
                    if object:IsA("Clouds") then
                        if cloudObjects[object] == nil then cloudObjects[object] = object.Enabled end
                        pcall(function() object.Enabled = false end)
                    end
                end
            end
            if Theme.HideSkyDomes then pcall(Theme.HideSkyDomes) end
            weatherOverlay(true)
            if fogEnabled and not fogAtStart and fogBackup and original then
                fogBackup.FogStart = original.FogStart
                fogBackup.FogEnd = original.FogEnd
                fogBackup.FogColor = original.FogColor
            end
        end

        local function applyLighting()
            if not S.active then return end
            local p, c = profiles[S.preset], settings[S.preset]
            local lightScale = c.light / 100
            local mood01 = c.mood / 100

            -- Balanced world lighting: keep atmospheric tone without crushing shadows to black.
            Lighting.Brightness = math.clamp(p.brightness * lightScale, 0.55, 1.75)
            Lighting.ExposureCompensation = math.clamp(p.exposure + 0.24 + (c.light - 95) / 220, -0.22, 0.25)
            Lighting.ClockTime = S.preset == "Cloud Haven" and (14.8 + mood01 * 1.6) or p.clock
            local ambLift = math.clamp(1.25 + (lightScale - 0.95) * 0.55, 0.85, 1.75)
            local baseAmb = p.ambient:Lerp(Color3.fromRGB(74, 72, 92), 0.35)
            local baseOut = p.outdoor:Lerp(Color3.fromRGB(98, 96, 118), 0.38)
            Lighting.Ambient = Color3.new(
                math.clamp(baseAmb.R * ambLift, 0.20, 0.62),
                math.clamp(baseAmb.G * ambLift, 0.20, 0.62),
                math.clamp(baseAmb.B * ambLift, 0.24, 0.66)
            )
            Lighting.OutdoorAmbient = Color3.new(
                math.clamp(baseOut.R * ambLift, 0.26, 0.72),
                math.clamp(baseOut.G * ambLift, 0.26, 0.72),
                math.clamp(baseOut.B * ambLift, 0.30, 0.76)
            )
            Lighting.ColorShift_Top = Color3.new(0, 0, 0)
            Lighting.ColorShift_Bottom = Color3.new(0, 0, 0)
            Lighting.EnvironmentDiffuseScale = math.clamp(0.72 + (lightScale - 0.95) * 0.35, 0.55, 0.95)
            Lighting.EnvironmentSpecularScale = math.clamp(0.55 + (lightScale - 0.95) * 0.25, 0.40, 0.80)
            Lighting.ShadowSoftness = 0.82
            if not fogEnabled then
                Lighting.FogStart = 9000
                Lighting.FogEnd = 100000
                Lighting.FogColor = p.tint
            end

            if grade then
                grade.Brightness = 0
                if S.preset == "Violet Slipstream" then
                    grade.Contrast = 0.012 + mood01 * 0.040
                    grade.Saturation = 0.015 + mood01 * 0.03
                    grade.TintColor = Color3.new(1, 1, 1):Lerp(p.tint, 0.045 + mood01 * 0.035)
                elseif S.preset == "Prism Carnival" then
                    grade.Contrast = 0.018
                    grade.Saturation = -0.01 + mood01 * 0.075
                    grade.TintColor = Color3.new(1, 1, 1):Lerp(p.tint, 0.03 + mood01 * 0.05)
                elseif S.preset == "Liquid Nebula" then
                    grade.Contrast = 0.020
                    grade.Saturation = 0.02
                    grade.TintColor = Color3.new(1, 1, 1):Lerp(p.tint, 0.045 + mood01 * 0.04)
                elseif S.preset == "Starlace Veil" then
                    grade.Contrast = 0.015 + mood01 * 0.035
                    grade.Saturation = 0.01
                    grade.TintColor = Color3.new(1, 1, 1):Lerp(p.tint, 0.04 + mood01 * 0.045)
                elseif S.preset == "Astral Lagoon" then
                    grade.Contrast = 0.018
                    grade.Saturation = 0.015 + mood01 * 0.035
                    grade.TintColor = Color3.new(1, 1, 1):Lerp(p.tint, 0.035 + mood01 * 0.055)
                elseif S.preset == "Emerald Aurora" then
                    grade.Contrast = 0.016
                    grade.Saturation = 0.02 + mood01 * 0.04
                    grade.TintColor = Color3.new(1, 1, 1):Lerp(p.tint, 0.040 + mood01 * 0.045)
                elseif S.preset == "Rose Mirage" then
                    grade.Contrast = 0.016
                    grade.Saturation = 0.015 + mood01 * 0.040
                    grade.TintColor = Color3.new(1, 1, 1):Lerp(p.tint, 0.040 + mood01 * 0.050)
                elseif S.preset == "Crimson Eclipse" then
                    grade.Contrast = 0.020 + mood01 * 0.025
                    grade.Saturation = 0.015 + mood01 * 0.035
                    grade.TintColor = Color3.new(1, 1, 1):Lerp(p.tint, 0.040 + mood01 * 0.045)
                elseif S.preset == "Solar Reverie" then
                    grade.Contrast = 0.015
                    grade.Saturation = 0.015 + mood01 * 0.040
                    grade.TintColor = Color3.new(1, 1, 1):Lerp(p.tint, 0.038 + mood01 * 0.050)
                else -- Cloud Haven
                    grade.Brightness = 0
                    grade.Contrast = 0.015
                    grade.Saturation = 0.01
                    grade.TintColor = Color3.new(1, 1, 1):Lerp(Color3.fromRGB(255, 236, 214), mood01 * 0.075)
                end
            end

            if atmos then
                atmos.Parent = if fogEnabled then nil else Lighting
                atmos.Color = p.tint
                atmos.Decay = p.ambient
                atmos.Glare = 0
                atmos.Offset = 0
                if S.preset == "Liquid Nebula" then
                    atmos.Density = 0.065 + mood01 * 0.105
                    atmos.Haze = 0.18 + mood01 * 0.50
                elseif S.preset == "Violet Slipstream" or S.preset == "Starlace Veil" then
                    atmos.Density = 0.055 + mood01 * 0.075
                    atmos.Haze = p.haze
                elseif S.preset == "Astral Lagoon" then
                    atmos.Density = 0.075 + mood01 * 0.065
                    atmos.Haze = 0.18 + mood01 * 0.42
                elseif S.preset == "Emerald Aurora" then
                    atmos.Density = 0.060 + mood01 * 0.075
                    atmos.Haze = 0.18 + mood01 * 0.36
                elseif S.preset == "Rose Mirage" then
                    atmos.Density = 0.068 + mood01 * 0.065
                    atmos.Haze = 0.18 + mood01 * 0.38
                elseif S.preset == "Crimson Eclipse" then
                    atmos.Density = 0.062 + mood01 * 0.070
                    atmos.Haze = 0.18 + mood01 * 0.36
                elseif S.preset == "Solar Reverie" then
                    atmos.Density = 0.060 + mood01 * 0.065
                    atmos.Haze = 0.16 + mood01 * 0.36
                else
                    atmos.Density = p.density
                    atmos.Haze = p.haze
                end
            end

            if emitter then
                local perfScale = Theme.ExtremePerformance and 0.6 or 1
                local rate = p.rate * (c.detail / 60) * perfScale
                emitter.Enabled = c.effects and c.detail > 0
                emitter.Rate = (c.effects and c.detail > 0) and rate or 0
                local sp = p.pSpeed * (0.45 + c.motion / 90)
                emitter.Speed = NumberRange.new(sp * 0.45, sp)
                if S.preset == "Starlace Veil" then
                    emitter.Acceleration = Vector3.new(0, 0.04 + c.motion / 240, 0)
                elseif S.preset == "Cloud Haven" then
                    emitter.Acceleration = Vector3.new(0.08 + c.motion / 180, 0.01, 0.03)
                end
            end

            local activeLimit = math.floor(#motes * (c.detail / 100) + 0.5)
            if Theme.ExtremePerformance then activeLimit = math.min(activeLimit, 10) end
            for i, entry in ipairs(motes) do
                local show = c.effects and i <= activeLimit
                entry.part.Transparency = show and entry.opacity or 1
                if entry.cross then entry.cross.Transparency = show and entry.opacity or 1 end
            end
        end

        local function decode(source, ticket)
            local cleaned = string.gsub(source, "%s", "")
            local nativeDecoder
            pcall(function()
                if crypt and crypt.base64 and type(crypt.base64.decode) == "function" then
                    nativeDecoder = crypt.base64.decode
                elseif syn and syn.crypt and syn.crypt.base64 and type(syn.crypt.base64.decode) == "function" then
                    nativeDecoder = syn.crypt.base64.decode
                elseif base64 and type(base64.decode) == "function" then
                    nativeDecoder = base64.decode
                end
            end)
            if nativeDecoder then
                local ok, bytes = pcall(nativeDecoder, cleaned)
                if ok and type(bytes) == "string" and #bytes > 8 then return bytes end
            end
            local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
            local lookup = {}
            for i = 1, #alphabet do lookup[string.byte(alphabet, i)] = i - 1 end
            local out = {}
            for i = 1, #cleaned, 4 do
                if i % 16384 == 1 then
                    if not valid(ticket) then return nil end
                    task.wait()
                end
                local a, b, c, d = string.byte(cleaned, i, i + 3)
                local x = (lookup[a] or 0) * 262144 + (lookup[b] or 0) * 4096 + (lookup[c] or 0) * 64 + (lookup[d] or 0)
                out[#out + 1] = string.char(math.floor(x / 65536) % 256)
                if c ~= 61 then out[#out + 1] = string.char(math.floor(x / 256) % 256) end
                if d ~= 61 then out[#out + 1] = string.char(x % 256) end
            end
            return table.concat(out)
        end

        local function loadFaces(name, ticket)
            if cache[name] then return cache[name] end
            local loader = getcustomasset or getsynasset
            if type(writefile) ~= "function" or type(loader) ~= "function" then
                error("Executor lacks writefile + getcustomasset/getsynasset; original sky preserved.")
            end
            local slug = string.gsub(name, " ", "_")
            local faces = {}
            for _, prop in ipairs(faceProps) do
                if not valid(ticket) then return nil end
                local path = "FaceLessSkyArt_v91hd_" .. slug .. "_" .. prop .. ".jpg"
                local exists = false
                if type(isfile) == "function" then pcall(function() exists = isfile(path) end) end
                if not exists then
                    local bytes = decode(ART[name][prop], ticket)
                    if not bytes then return nil end
                    if string.sub(bytes, 1, 2) ~= "\255\216" then
                        error("Sky JPEG decode verification failed for " .. prop)
                    end
                    writefile(path, bytes)
                end
                local url = loader(path)
                if type(url) ~= "string" or url == "" then
                    error("Local sky texture registration failed for " .. prop)
                end
                faces[prop] = url
            end
            if not valid(ticket) then return nil end
            local provider = game:GetService("ContentProvider")
            local urls = {}
            for _, prop in ipairs(faceProps) do urls[#urls + 1] = faces[prop] end
            local failed = false
            provider:PreloadAsync(urls, function(_, status)
                if status ~= Enum.AssetFetchStatus.Success then failed = true end
            end)
            if failed then error("Sky texture preload failed") end
            if not valid(ticket) then return nil end
            cache[name] = faces
            return faces
        end

        local function makeMotePart(partClass, name, size, color, opacity, parent)
            local part = Instance.new(partClass)
            part.Name = name
            part.Size = size
            part.Anchored = true
            part.CanCollide = false
            part.CanTouch = false
            part.CanQuery = false
            part.CastShadow = false
            part.Material = Enum.Material.Neon
            part.Color = color
            part.Transparency = opacity
            part.Parent = parent
            return part
        end

        local function build(faces)
            destroyVisuals()
            if not original then
                original = {}
                fogAtStart = fogEnabled == true
                for _, property in ipairs(lightProperties) do
                    pcall(function() original[property] = Lighting[property] end)
                end
                if fogEnabled and fogBackup then
                    original.FogStart = fogBackup.FogStart
                    original.FogEnd = fogBackup.FogEnd
                    original.FogColor = fogBackup.FogColor
                    fogAtStart = false
                end
            end

            local nextSky = Instance.new("Sky")
            nextSky.Name = "FaceLessSkyAtelier"
            nextSky.CelestialBodiesShown = false
            nextSky.StarCount = 0
            pcall(function()
                nextSky.SunAngularSize = 0
                nextSky.MoonAngularSize = 0
                nextSky.SkyboxOrientation = Vector3.new(0, S.angle, 0)
            end)
            for _, prop in ipairs(faceProps) do
                nextSky[prop] = faces[prop]
            end
            ownSky = nextSky
            nextSky.Parent = Lighting

            fxFolder = Instance.new("Folder")
            fxFolder.Name = "FaceLessSkyAtelier"
            fxFolder.Parent = workspace

            grade = Instance.new("ColorCorrectionEffect")
            grade.Name = "AtelierSkyGrade"
            grade.Parent = Lighting

            atmos = Instance.new("Atmosphere")
            atmos.Name = "AtelierSkyAtmosphere"

            local p = profiles[S.preset]
            -- v9.1: world particles / motes removed on request (sky only).

            S.active = true
            protect()
            applyLighting()
            if fogEnabled and type(applyFog) == "function" then
                pcall(applyFog)
            end
        end

        local function apply()
            revision = revision + 1
            local ticket = revision
            if not S.enabled or Unloaded then
                restore()
                return
            end
            if Theme.ConfigRegistry.applying then return end
            local selected = S.preset
            task.spawn(function()
                local ok, result = pcall(loadFaces, selected, ticket)
                if not valid(ticket) then return end
                if not ok or not result then
                    warn("[Sky Atelier] " .. tostring(result or "texture load cancelled"))
                    S.enabled = false
                    revision = revision + 1
                    restore()
                    changing = true
                    if toggles[selected] then toggles[selected].Set(false) end
                    changing = false
                    return
                end
                local installed, err = pcall(build, result)
                if not installed then
                    warn("[Sky Atelier] " .. tostring(err))
                    S.enabled = false
                    revision = revision + 1
                    restore()
                    changing = true
                    if toggles[selected] then toggles[selected].Set(false) end
                    changing = false
                end
            end)
        end

        local function activate(name, value)
            if changing then return end
            if value then
                changing = true
                for key, toggle in pairs(toggles) do
                    if key ~= name and toggle.Get() then toggle.Set(false) end
                end
                changing = false
                S.preset = name
                S.enabled = true
                S.angle = 0
                if not Theme.ConfigRegistry.applying then apply() end
            elseif S.preset == name then
                S.enabled = false
                apply()
            end
        end

        local sec = createSection(worldTab.Right, "Sky Atelier")
        for _, name in ipairs(names) do
            local key = name
            local p = profiles[key]
            toggles[key] = sec:AddToggle(key, false, function(value)
                activate(key, value)
            end, function(api)
                local c = settings[key]
                local refs = {}
                popupControls[key] = refs
                local function slider(label, low, high, field, step)
                    refs[field] = api:AddSlider(label, low, high, c[field], function(value)
                        c[field] = value
                        if S.preset == key and S.active and not Theme.ConfigRegistry.applying then
                            applyLighting()
                        end
                    end, step or 1)
                end
                slider("World light (%)", 60, 120, "light", 1)
                slider(p.moodLabel, 0, 100, "mood", 1)
                slider("Sky rotation (deg/s)", 0, 3, "rotate", 0.05)
            end)
        end

        local function update(dt)
            if not S.enabled or not S.active or Unloaded then return end
            local c = settings[S.preset]
            local stepDt = math.min(dt, 0.1)
            if c.rotate > 0 then
                S.angle = (S.angle + stepDt * c.rotate) % 360
                if ownSky and ownSky.Parent == Lighting then
                    pcall(function() ownSky.SkyboxOrientation = Vector3.new(0, S.angle, 0) end)
                end
            end

            if not emitterPart and #motes == 0 then return end
            local camera = workspace.CurrentCamera
            local camPos = camera and camera.CFrame.Position or Vector3.new()
            local char = LocalPlayer.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            local origin = root and root.Position or camPos
            if emitterPart then
                emitterPart.CFrame = CFrame.new(origin + Vector3.new(0, 5, 0))
            end

            local t = os.clock()
            local speed = 0.25 + c.motion / 45
            local activeLimit = math.floor(#motes * (c.detail / 100) + 0.5)
            if Theme.ExtremePerformance then activeLimit = math.min(activeLimit, 10) end

            for i, entry in ipairs(motes) do
                local visible = c.effects and i <= activeLimit
                if not visible then
                    entry.part.Transparency = 1
                    if entry.cross then entry.cross.Transparency = 1 end
                else
                    local kind = entry.kind
                    if kind == "streaks" then
                        local travel = ((t * (5.5 + c.motion * 0.16) + entry.phase * 7) % entry.span) - entry.span * 0.5
                        local side = math.cos(entry.phase) * entry.radius
                        local pos = origin + Vector3.new(side, 3.5 + entry.height, travel)
                        entry.part.Transparency = entry.opacity
                        entry.part.CFrame = CFrame.new(pos)
                    elseif kind == "shards" then
                        local a = entry.phase + t * (0.14 + c.motion / 260)
                        local pos = origin + Vector3.new(
                            math.cos(a) * entry.radius,
                            entry.height + math.sin(t * 0.7 + i) * 0.55,
                            math.sin(a) * entry.radius
                        )
                        entry.part.Transparency = entry.opacity
                        entry.part.CFrame = CFrame.new(pos) * CFrame.Angles(t * 0.35 * speed, i, t * 0.5 * speed)
                    elseif kind == "currents" then
                        local a = entry.phase + t * (0.12 + c.motion / 300)
                        local nextA = a + 0.18
                        local p0 = origin + Vector3.new(
                            math.cos(a) * entry.radius,
                            entry.height + math.sin(a * 2 + i) * 0.9,
                            math.sin(a) * entry.radius
                        )
                        local p1 = origin + Vector3.new(
                            math.cos(nextA) * entry.radius,
                            entry.height + math.sin(nextA * 2 + i) * 0.9,
                            math.sin(nextA) * entry.radius
                        )
                        entry.part.Transparency = entry.opacity
                        entry.part.CFrame = CFrame.lookAt(p0, p1)
                    elseif kind == "starlace" then
                        local lift = ((t * (0.35 + c.motion / 110) + entry.phase) % 7.5)
                        local a = entry.phase + math.sin(t * 0.3 + i) * 0.25
                        local pos = origin + Vector3.new(
                            math.cos(a) * entry.radius,
                            1.2 + lift,
                            math.sin(a) * entry.radius
                        )
                        local twinkle = math.clamp(entry.opacity + math.sin(t * 2.4 + entry.phase * 3) * 0.22, 0.16, 0.88)
                        local cf = CFrame.new(pos) * CFrame.Angles(0, t * 0.25, math.rad(45))
                        entry.part.Transparency = twinkle
                        entry.part.CFrame = cf
                        if entry.cross then
                            entry.cross.Transparency = twinkle
                            entry.cross.CFrame = cf
                        end
                    elseif kind == "lagoon" then
                        local a = entry.phase + t * (0.16 + c.motion / 240)
                        local tilt = CFrame.Angles(math.rad(22), 0, math.rad(-16))
                        local localPos = Vector3.new(math.cos(a) * entry.radius, entry.height, math.sin(a) * entry.radius)
                        local tangent = Vector3.new(-math.sin(a), 0, math.cos(a))
                        local worldPos = origin + Vector3.new(0, 4.2, 0) + tilt:VectorToWorldSpace(localPos)
                        local worldDir = tilt:VectorToWorldSpace(tangent)
                        entry.part.Transparency = entry.opacity
                        entry.part.CFrame = CFrame.lookAt(worldPos, worldPos + worldDir)
                    else -- breeze
                        local drift = ((t * (1.8 + c.motion * 0.055) + entry.phase * 6) % entry.span) - entry.span * 0.5
                        local zOff = math.sin(entry.phase) * entry.radius
                        local pos = origin + Vector3.new(drift, entry.height + math.sin(t * 0.6 + i) * 0.35, zOff)
                        entry.part.Transparency = entry.opacity
                        entry.part.CFrame = CFrame.lookAt(pos, pos + Vector3.new(1, 0, 0.12))
                    end
                end
            end
        end

        local legacy = {
            Space = names[1], ["Crimson Sky"] = names[1],
            ["Golden Dawn"] = names[2],
            Nebula = names[3], Vaporwave = names[3],
            ["Starry Night"] = names[4], Twilight = names[4],
            Aurora = names[5], ["Pink Dawn"] = names[5],
            Paradise = names[6], Heavens = names[6], ["Azure Day"] = names[6],
        }

        local function syncPopupControls(key)
            local c = settings[key]
            local p = profiles[key]
            local scope = "Settings/" .. key
            local reg = Theme.ConfigRegistry
            if reg and reg.ApplyLabel then
                reg:ApplyLabel("World light (%)", c.light, scope)
                reg:ApplyLabel(p.moodLabel, c.mood, scope)
                reg:ApplyLabel("Sky rotation (deg/s)", c.rotate, scope)
            end
        end

        Theme.CustomSkyBoxState = {
            IsEnabled = function() return S.enabled end,
            GetOriginalFog = function()
                if original then
                    return original.FogStart, original.FogEnd, original.FogColor
                end
                return nil, nil, nil
            end,
            RefreshBackdrop = function()
                if S.active then
                    protect()
                    applyLighting()
                end
            end,
            FinalizeConfig = apply,
            Cleanup = function()
                S.enabled = false
                revision = revision + 1
                restore()
            end,
            Export = function()
                local copy = {}
                for name, c in pairs(settings) do
                    copy[name] = {}
                    for k, v in pairs(c) do copy[name][k] = v end
                end
                return {version = 8, enabled = S.enabled, preset = S.preset, settings = copy}
            end,
            Import = function(data)
                if type(data) ~= "table" then return end
                local name = profiles[data.preset] and data.preset or legacy[data.preset] or names[1]
                if type(data.settings) == "table" then
                    for key, c in pairs(settings) do
                        local incoming = data.settings[key]
                        if type(incoming) == "table" then
                            local ranges = {
                                light = {60, 120}, mood = {0, 100}, rotate = {0, 3},
                                detail = {0, 100}, motion = {0, 100},
                            }
                            for field, range in pairs(ranges) do
                                local num = tonumber(incoming[field])
                                if num == nil and field == "mood" then num = tonumber(incoming.sky) end
                                if num ~= nil then
                                    c[field] = math.clamp(num, range[1], range[2])
                                end
                            end
                            c.effects = false
                            syncPopupControls(key)
                        end
                    end
                end
                changing = true
                for key, toggle in pairs(toggles) do
                    toggle.Set(data.enabled == true and key == name)
                end
                changing = false
                S.enabled = data.enabled == true
                S.preset = name
                if not Theme.ConfigRegistry.applying then apply() end
            end,
        }

        track(Lighting.ChildAdded:Connect(function(child)
            if not Unloaded and S.enabled and S.active then
                task.defer(function()
                    if not Unloaded and S.enabled and S.active and child and child.Parent == Lighting then
                        muteChild(child)
                    end
                end)
            end
        end))
        local initTerrain = workspace:FindFirstChildOfClass("Terrain")
        if initTerrain then
            track(initTerrain.ChildAdded:Connect(function(child)
                if not Unloaded and S.enabled and S.active and child:IsA("Clouds") then
                    if cloudObjects[child] == nil then cloudObjects[child] = child.Enabled end
                    pcall(function() child.Enabled = false end)
                end
            end))
        end

        local binding = "FaceLessSkyAtelier_v8"
        RunService:UnbindFromRenderStep(binding)
        RunService:BindToRenderStep(binding, Enum.RenderPriority.Camera.Value + 5, update)

        local elapsed = 0
        track(RunService.Heartbeat:Connect(function(dt)
            if Unloaded or not S.enabled or not S.active then return end
            elapsed = elapsed + dt
            if elapsed < 1 then return end
            elapsed = 0
            -- Lighting is applied on activation and slider changes.
            if not ownSky or ownSky.Parent ~= Lighting or not fxFolder or not fxFolder.Parent then
                local recovered = false
                if ownSky and fxFolder then
                    recovered = pcall(function()
                        if ownSky.Parent ~= Lighting then ownSky.Parent = Lighting end
                        if fxFolder.Parent ~= workspace then fxFolder.Parent = workspace end
                    end)
                end
                if not recovered or not ownSky or ownSky.Parent ~= Lighting or not fxFolder or not fxFolder.Parent then
                    apply()
                end
            end
        end))

        registerCleanup(function()
            S.enabled = false
            revision = revision + 1
            RunService:UnbindFromRenderStep(binding)
            restore()
        end)
    end

    local ok, err = pcall(initSkyAtelier)
    if not ok then warn("[Sky Atelier] initialization: " .. tostring(err)) end
end

-- GAROU RECOLOR RED
do
    local secGaro = createSection(rightVis, "Garou Recolor RED")
    -- всё состояние в одной таблице, чтобы не занимать локальные переменные верхнего уровня
    local st = {
        on = false,
        h = 0, s = 1, v = 1,              -- выбранный цвет (HSV)
        ch = 0.95, cs = 1, cv = 1,        -- запомненный "свой" цвет
        I = 1,                            -- интенсивность 0..1
        acc = 0, tintAcc = 0, queued = false,
        picker = nil, dd = nil,
        char = nil, thrown = nil,
    }
    local originals = setmetatable({}, {__mode = "k"})
    local tracked = setmetatable({}, {__mode = "k"})
    local hooks = {}

    local COLOR_OPTIONS = {
        {name = "Red",    color = Color3.fromRGB(255, 0, 0)},
        {name = "Purple", color = Color3.fromRGB(150, 30, 255)},
        {name = "Black",     color = Color3.fromRGB(12, 12, 12)},
        {name = "Custom",  color = Color3.fromRGB(225, 225, 225)},
    }

    -- чем выше интенсивность, тем шире диапазон "синих" оттенков и тем больше объектов красится
    local function isBlue(c)
        local h, s, v = c:ToHSV()
        local I = st.I
        local lo = 0.5 - 0.08 * I
        local hi = 0.7 + 0.07 * I
        local minS = 0.35 - 0.27 * I
        local minV = 0.25 - 0.15 * I
        return s > minS and v > minV and h > lo and h < hi
    end

    -- интенсивность: минимум = блеклый (низкая насыщенность и яркость),
    -- максимум = максимально насыщенный и яркий выбранный цвет
    local function tint(c)
        local _, _, v = c:ToHSV()
        local I = st.I
        local satF = 0.15 + 0.85 * I
        v = v ^ (1 - 0.6 * I)
        return Color3.fromHSV(st.h, math.clamp(st.s * satF, 0, 1), math.clamp(v * st.v, 0, 1))
    end

    local function seqHasBlue(seq)
        for _, k in ipairs(seq.Keypoints) do
            if isBlue(k.Value) then return true end
        end
        return false
    end

    local function tintSeq(seq)
        local kps = {}
        for _, k in ipairs(seq.Keypoints) do
            local c = k.Value
            if isBlue(c) then c = tint(c) end
            kps[#kps + 1] = ColorSequenceKeypoint.new(k.Time, c)
        end
        return ColorSequence.new(kps)
    end

    local function propsFor(obj)
        if obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam") then return {"Color"}, true end
        if obj:IsA("BasePart") or obj:IsA("Light") or obj:IsA("Smoke") then return {"Color"}, false end
        if obj:IsA("Fire") then return {"Color", "SecondaryColor"}, false end
        if obj:IsA("Sparkles") then return {"SparkleColor"}, false end
        if obj:IsA("Highlight") then return {"FillColor", "OutlineColor"}, false end
        if obj:IsA("Decal") then return {"Color3"}, false end
        return nil, false
    end

    local function apply(obj)
        local store = originals[obj]
        if not store then return end
        if not obj.Parent then tracked[obj] = nil; return end
        for prop, orig in pairs(store) do
            local new
            if typeof(orig) == "ColorSequence" then new = tintSeq(orig) else new = tint(orig) end
            pcall(function() obj[prop] = new end)
        end
    end

    local function process(obj)
        if not st.on then return end
        -- Atelier owns its palette; world-VFX recoloring must not override theme/custom sync.
        local ancestor = obj
        while ancestor and ancestor ~= workspace do
            if string.sub(ancestor.Name, 1, 14) == "CosmicAtelier_" then return end
            ancestor = ancestor.Parent
        end
        pcall(function()
            local props, isSeq = propsFor(obj)
            if not props then return end
            for _, prop in ipairs(props) do
                local store = originals[obj]
                if not (store and store[prop] ~= nil) then
                    local cur = obj[prop]
                    local blue
                    if isSeq then blue = seqHasBlue(cur) else blue = isBlue(cur) end
                    if blue then
                        if not store then store = {}; originals[obj] = store end
                        store[prop] = cur
                        tracked[obj] = true
                    end
                end
            end
            apply(obj)
        end)
    end

    local function restore()
        for obj, props in pairs(originals) do
            if obj and obj.Parent then
                for prop, val in pairs(props) do pcall(function() obj[prop] = val end) end
            end
            originals[obj] = nil
        end
        for o in pairs(tracked) do tracked[o] = nil end
    end

    local function unhook()
        for _, c in ipairs(hooks) do pcall(function() c:Disconnect() end) end
        hooks = {}
        st.char, st.thrown = nil, nil
    end
    registerCleanup(function() st.on = false; unhook(); restore() end)

    local function hookContainer(container)
        for _, d in ipairs(container:GetDescendants()) do process(d) end
        hooks[#hooks + 1] = container.DescendantAdded:Connect(function(d) task.defer(process, d) end)
    end

    local function hookAll()
        unhook()
        local char = LocalPlayer and LocalPlayer.Character
        if char then hookContainer(char); st.char = char end
        local thrown = workspace:FindFirstChild("Thrown")
        if thrown then hookContainer(thrown); st.thrown = thrown end
    end

    -- при смене интенсивности пересканируем эффекты (диапазон "синего" меняется)
    local function queueRescan()
        if st.queued or not st.on then return end
        st.queued = true
        task.delay(0.3, function()
            st.queued = false
            if st.on and not Unloaded then hookAll() end
        end)
    end

    -- ПКМ по переключателю открывает окно: палитра (квадрат + полоса оттенка) и интенсивность
    secGaro:AddToggle("Garou recolor RED", false, function(state)
        st.on = state
        if state then hookAll() else unhook(); restore() end
    end, function(api)
        st.picker = api:AddColorPicker(st.h, st.s, st.v, function(h, s, v)
            st.h, st.s, st.v = h, s, v
            st.ch, st.cs, st.cv = h, s, v
            if st.dd then st.dd.Set(4, true) end
        end)
        api:AddSlider("Intensity (0 = faded, 100 = vivid)", 0, 100, math.floor(st.I * 100 + 0.5), function(val)
            st.I = val / 100
            queueRescan()
        end)
    end)

    -- быстрые пресеты
    st.dd = secGaro:AddDropdown("Color", COLOR_OPTIONS, 1, function(name, color, idx)
        if idx == 4 then
            st.h, st.s, st.v = st.ch, st.cs, st.cv
        else
            st.h, st.s, st.v = color:ToHSV()
        end
        if st.picker and st.picker.Alive() then st.picker.Set(st.h, st.s, st.v) end
    end)

    track(RunService.Heartbeat:Connect(function(dt)
        if Unloaded then
            if st.on then st.on = false; unhook(); restore() end
            return
        end
        if not st.on then return end
        st.acc = st.acc + dt
        if st.acc >= 0.5 then
            st.acc = 0
            local char = LocalPlayer and LocalPlayer.Character
            local thrown = workspace:FindFirstChild("Thrown")
            if char ~= st.char or thrown ~= st.thrown then hookAll() end
        end
        st.tintAcc = st.tintAcc + dt
        if st.tintAcc >= 0.45 then
            st.tintAcc = 0
            for obj in pairs(tracked) do apply(obj) end
        end
    end))
end

-- COSMIC ATELIER / shared, texture-free visual renderer.
-- No BloomEffect, global lighting edits, external textures or camera-facing artwork.
do
    local FX = {groups = {}, clock = 0, alive = true, nebulaUpdate = nil}
    Theme.PremiumFX = FX
    local TAU = math.pi * 2
    local WHITE = Color3.new(1, 1, 1)
    function FX.color(settings)
        local c = settings.custom and settings.color or Theme.BloodRed
        if typeof(c) ~= "Color3" then c = Color3.fromRGB(160, 110, 255) end
        if settings.saturation then
            local h, s, v = c:ToHSV()
            c = Color3.fromHSV(h, math.min(1, s * 1.18 + 0.06), math.min(1, v * 1.12))
        end
        return c
    end
    function FX.new(name, settings)
        local folder = Instance.new("Folder")
        folder.Name = "CosmicAtelier_" .. name
        folder.Parent = workspace
        local anchor = Instance.new("Part")
        anchor.Name = "Origin"
        anchor.Size = Vector3.new(0.05, 0.05, 0.05)
        anchor.Anchored = true
        anchor.Transparency = 1
        anchor.CanCollide, anchor.CanTouch, anchor.CanQuery = false, false, false
        anchor.CastShadow = false
        anchor.Parent = folder
        local group = {folder = folder, anchor = anchor, paths = {}, settings = settings,
            opacity = 1, scale = 1, time = 0, dead = false}
        FX.groups[group] = true
        return group
    end
    function FX.destroy(group)
        if not group or group.dead then return end
        group.dead = true
        for _, attachment in ipairs(group.ownedAttachments or {}) do attachment:Destroy() end
        FX.groups[group] = nil
        group.folder:Destroy()
        table.clear(group.paths)
    end
    -- Layered ribbons: wide low-opacity fringe, narrow bloom, crisp hairline.
    -- Normal depth testing is preserved; no AlwaysOnTop/through-wall rendering.
    function FX.path(group, count, closed, width, calculate, opacity, gradient)
        local path = {nodes = {}, layers = {}, calc = calculate, closed = closed,
            opacity = opacity or 1, gradient = gradient or 0}
        for i = 1, count do
            local a = Instance.new("Attachment")
            a.Name = "CurveNode"
            a.Parent = group.anchor
            path.nodes[i] = a
        end
        for layer = 1, 3 do
            local beams = {}
            path.layers[layer] = beams
            for i = 1, closed and count or count - 1 do
                local b = Instance.new("Beam")
                b.Name = layer == 3 and "Hairline" or "SoftFringe"
                b.Attachment0 = path.nodes[i]
                b.Attachment1 = path.nodes[i % count + 1]
                b.FaceCamera = true
                b.Width0 = width * ({5.2, 2.6, 1})[layer]
                b.Width1 = b.Width0
                b.Segments = 1
                b.LightInfluence = 0
                b.LightEmission = 1
                b.Transparency = NumberSequence.new(1)
                b.Enabled = false
                b.Parent = group.folder
                beams[i] = b
            end
        end
        group.paths[#group.paths + 1] = path
        return path
    end
    function FX.ring(group, radius, y, tilt, speed, width, opacity, phase, span)
        local count = Theme.ExtremePerformance and 64 or 96
        local extent = span or TAU
        if extent < TAU then count = math.max(12, math.ceil(count * extent / TAU)) end
        local rotation = CFrame.Angles(tilt or 0, 0, 0)
        return FX.path(group, count, extent == TAU, width, function(t, u)
            local a = u * extent + t * (speed or 0) + (phase or 0)
            return rotation:VectorToWorldSpace(Vector3.new(math.cos(a) * radius, y, math.sin(a) * radius))
        end, opacity, 0.24)
    end
    function FX.line(group, a, b, width, opacity)
        return FX.path(group, 2, false, width, function(_, u) return a:Lerp(b, u) end, opacity)
    end
    function FX.ground(root, char, distance)
        local p = RaycastParams.new()
        p.FilterType = Enum.RaycastFilterType.Exclude
        local exclude = {char}
        for g in pairs(FX.groups) do exclude[#exclude + 1] = g.folder end
        p.FilterDescendantsInstances = exclude
        p.IgnoreWater = true
        local hit = workspace:Raycast(root.Position, Vector3.new(0, -(distance or 12), 0), p)
        if not hit then return nil end
        local up = hit.Normal
        local tangent = Vector3.new(1, 0, 0) - up * up.X
        if tangent.Magnitude < 0.05 then tangent = Vector3.new(0, 0, 1):Cross(up) end
        tangent = tangent.Unit
        return CFrame.fromMatrix(hit.Position + up * 0.045, tangent, up, tangent:Cross(up))
    end
    function FX.style(group)
        local color = FX.color(group.settings)
        local glow = group.settings.glow ~= false
        local opacity = math.clamp(group.opacity, 0, 1)
        -- Recolor only when necessary; animation does not allocate ColorSequences.
        if group.lastColor ~= color or group.lastCinematic ~= group.settings.cinematic then
            group.lastCinematic = group.settings.cinematic
            group.lastColor = color
            for _, path in ipairs(group.paths) do
                for layer, beams in ipairs(path.layers) do
                    for i, b in ipairs(beams) do
                        local u = (i - 1) / math.max(1, #beams - 1)
                        local mix = path.gradient * (0.5 + 0.5 * math.sin(u * TAU))
                        local base = (group.settings.cinematic and path.palette) or color
                        local c = base:Lerp(WHITE, mix + (layer == 3 and 0.10 or 0))
                        b.Color = ColorSequence.new(c)
                    end
                end
            end
        end
        -- Quantized opacity avoids allocating thousands of sequences every frame.
        local step = math.floor(opacity * 90 + 0.5)
        if step ~= group.lastOpacity or glow ~= group.lastGlow then
            group.lastOpacity, group.lastGlow = step, glow
            local alpha = step / 90
            for _, path in ipairs(group.paths) do
                for layer, beams in ipairs(path.layers) do
                    local enabled = (layer == 3 or glow) and alpha > 0.001
                    local strength = ({0.055, 0.13, 0.92})[layer] * alpha * path.opacity
                    local transparency = NumberSequence.new(1 - math.clamp(strength, 0, 1))
                    for _, b in ipairs(beams) do
                        b.Enabled = enabled
                        b.Transparency = transparency
                    end
                end
            end
        end
    end
    local renderKey = "Atelier_WingsTrails_v7"
    RunService:UnbindFromRenderStep(renderKey)
    RunService:BindToRenderStep(renderKey, Enum.RenderPriority.Character.Value + 1, function(dt)
        if Unloaded or not FX.alive then return end
        FX.clock = FX.clock + math.min(dt, 0.1)
        for group in pairs(FX.groups) do
            if not group.dead and (not group.folder.Parent or not group.anchor.Parent) then FX.destroy(group) end
            if not group.dead then
                group.time = group.time + math.min(dt, 0.1)
                if group.update then group.update(group, dt) end
                if not group.dead then
                    local t, scale = group.time * (group.settings.speed or 1), group.scale
                    for _, path in ipairs(group.paths) do
                        local n = #path.nodes
                        local divisor = path.closed and n or math.max(1, n - 1)
                        for i, node in ipairs(path.nodes) do
                            node.Position = path.calc(t, (i - 1) / divisor) * scale
                        end
                    end
                    FX.style(group)
                    if FX.nebulaUpdate then FX.nebulaUpdate(group) end

                end
            end
        end
    end)
    registerCleanup(function()
        FX.alive = false
        RunService:UnbindFromRenderStep(renderKey)
        local pending = {}
        for group in pairs(FX.groups) do pending[#pending + 1] = group end
        for _, group in ipairs(pending) do FX.destroy(group) end
    end)
    -- Registry-backed choices keep mode buttons in sync with saved configs.
    function FX.choice(section, scope, label, choices, get, set)
        local key = scope .. "::" .. label .. "::1"
        local button
        local function choose(value)
            for _, name in ipairs(choices) do
                if name == value then
                    set(value)
                    if button then button.Text = "Mode: " .. get() end
                    Theme.ConfigRegistry:Store(key, get())
                    return
                end
            end
        end
        button = section:AddButton("Mode: " .. get(), function()
            local index = table.find(choices, get()) or 0
            choose(choices[index % #choices + 1])
        end)
        Theme.ConfigRegistry:Register(key, label, "choice", get, choose, scope, 1)
        button.Text = "Mode: " .. get()
        return button
    end
    function FX.controls(api, settings)
        local h, s, v = settings.color:ToHSV()
        -- A picker changes the stored custom color; theme sync is explicit and default ON.
        api:AddColorPicker(h, s, v, function(nh, ns, nv)
            settings.color = Color3.fromHSV(nh, ns, nv)
        end)
        api:AddToggle("Theme sync", not settings.custom, function(value) settings.custom = not value end)
        api:AddToggle("Cinematic palette", settings.cinematic == true, function(value) settings.cinematic = value end)
        api:AddToggle("Glow", settings.glow ~= false, function(value) settings.glow = value end)
        api:AddToggle("Saturation", settings.saturation == true, function(value) settings.saturation = value end)
    end
end

-- NEBULA v3 / procedural energy surfaces and bounded particle fields.
do
    local FX = Theme.PremiumFX
    FX.cinematic = {Color3.fromRGB(92, 238, 240), Color3.fromRGB(168, 108, 244),
        Color3.fromRGB(213, 255, 249), Color3.fromRGB(119, 236, 178)}
    function FX.ribbon(g, count, width, calc, alpha, palette)
        local p = FX.path(g, count, false, width, calc, alpha, 0.3)
        p.palette = palette
        for layer, beams in ipairs(p.layers) do
            for i, beam in ipairs(beams) do
                local u0, u1 = (i - 1) / #beams, i / #beams
                local function profile(u) return math.max(0.018, math.sin(math.pi * u) ^ 0.7) end
                local multiplier = ({2.7, 1.5, 1})[layer]
                beam.Width0 = width * multiplier * profile(u0)
                beam.Width1 = width * multiplier * profile(u1)
            end
        end
        return p
    end
    function FX.fog(g, calc, rate, size, stars, palette, falling)
        local a = Instance.new("Attachment")
        a.Name = stars and "StarSource" or "NebulaSource"
        a.Parent = g.anchor
        local e = Instance.new("ParticleEmitter")
        e.Name = stars and "CosmicStars" or "CosmicMist"
        e.Texture = stars and "rbxasset://textures/particles/sparkles_main.dds" or "rbxasset://textures/particles/smoke_main.dds"
        e.Rate = rate * (Theme.ExtremePerformance and 0.6 or 1)
        e.Lifetime = NumberRange.new(stars and 1.1 or 1.6, stars and 2.2 or 3.0)
        e.Speed = NumberRange.new(0.05, stars and 0.3 or 0.13)
        e.SpreadAngle = Vector2.new(180, 180)
        e.Acceleration = Vector3.new(0, falling and -0.65 or 0.06, 0)
        e.Drag = 0.6
        e.LightEmission, e.LightInfluence = 1, 0
        e.Rotation = NumberRange.new(0, 360)
        e.RotSpeed = NumberRange.new(-15, 15)
        e.Size = NumberSequence.new({NumberSequenceKeypoint.new(0, size * 0.22),
            NumberSequenceKeypoint.new(0.3, size), NumberSequenceKeypoint.new(1, 0)})
        e.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 1),
            NumberSequenceKeypoint.new(0.18, stars and 0.2 or 0.94),
            NumberSequenceKeypoint.new(0.7, stars and 0.6 or 0.97), NumberSequenceKeypoint.new(1, 1)})
        e.Enabled = false
        e.LockedToPart = true
        e.Parent = a
        g.nebulaEmitters = g.nebulaEmitters or {}
        table.insert(g.nebulaEmitters, {a = a, e = e, calc = calc, palette = palette})
    end
    function FX.sphere(g, name, size, color, transparency)
        local p = Instance.new("Part")
        p.Name, p.Size = name, Vector3.new(1, 1, 1)
        p.Anchored = true
        p.CanCollide, p.CanTouch, p.CanQuery, p.CastShadow = false, false, false, false
        p.Color, p.Transparency = color, transparency
        p.Material = Enum.Material.SmoothPlastic
        local m = Instance.new("SpecialMesh")
        m.MeshType, m.Scale = Enum.MeshType.Sphere, size
        m.Parent = p
        p.Parent = g.folder
        return p
    end
    function FX.localLight(g, position, brightness, range, palette)
        local a = Instance.new("Attachment")
        a.Position = position * g.scale
        a.Parent = g.anchor
        local light = Instance.new("PointLight")
        light.Brightness, light.Range, light.Shadows = 0, range, false
        light.Parent = a
        g.nebulaLights = g.nebulaLights or {}
        table.insert(g.nebulaLights, {light = light, a = a, position = position, brightness = brightness, palette = palette})
    end
    function FX.nebulaUpdate(g)
        local color = FX.color(g.settings)
        for _, item in ipairs(g.nebulaLights or {}) do
            item.a.Position = item.position * g.scale
            item.light.Color = (g.settings.cinematic and item.palette) or color
            item.light.Brightness = g.settings.glow ~= false and item.brightness * g.opacity * (0.94 + 0.06 * math.sin(g.time * 1.2)) or 0
        end
        for _, item in ipairs(g.nebulaEmitters or {}) do
            item.a.Position = item.calc(g.time * (g.settings.speed or 1)) * g.scale
            item.e.Enabled = g.opacity > 0.18
            local c = g.settings.cinematic and item.palette or color
            if item.lastColor ~= c then
                item.e.Color = ColorSequence.new(c:Lerp(Color3.new(1, 1, 1), 0.32), c)
                item.lastColor = c
            end
        end
    end
end

-- v6 / sculpted blades. Flat metal faces, luminous inlays and bounded soft halos.
do
    local FX=Theme.PremiumFX
    local WHITE=Color3.new(1,1,1)
    local rainbow={Color3.fromRGB(255,100,209),Color3.fromRGB(183,96,255),Color3.fromRGB(109,158,255),
        Color3.fromRGB(94,241,241),Color3.fromRGB(119,255,153),Color3.fromRGB(236,255,102)}
    local metal={Color3.fromRGB(31,39,91),Color3.fromRGB(96,45,165),Color3.fromRGB(44,210,222)}
    local function frame(p,direction)
        local up=direction.Unit
        local back=Vector3.new(0,0,1)
        if math.abs(up.Z)>0.98 then back=Vector3.new(1,0,0) end
        local right=up:Cross(back).Unit
        return CFrame.fromMatrix(p,right,up,right:Cross(up).Unit)
    end
    local function part(g,kind,size,calc,color,alpha,emissive,themeMix)
        local p=Instance.new(kind)
        p.Name=emissive and "LuminousInlay" or "ForgedFacet"
        p.Size=size*g.scale
        p.Anchored=true;p.CanCollide=false;p.CanTouch=false;p.CanQuery=false;p.CastShadow=false
        p.Material=emissive and Enum.Material.Neon or Enum.Material.Metal
        p.Reflectance=emissive and 0 or 0.27
        p.Transparency=1;p.Parent=g.folder
        g.referenceParts=g.referenceParts or {}
        table.insert(g.referenceParts,{part=p,calc=calc,color=color,alpha=alpha,emissive=emissive,mix=themeMix or 0})
    end
    -- Upper and lower four-sided pyramids meet at a broad ridge to form a pointed blade.
    local function blade(g,start,tip,width,depth,color,alpha,emissive,motion)
        local vector=tip-start
        local length=vector.Magnitude
        local center=start:Lerp(tip,0.48)
        local base=frame(center,vector)
        for half=0,1 do
            for side=0,3 do
                local h,s=half,side
                local transform=CFrame.Angles(0,s*math.pi/2,h*math.pi)
                local size=(s%2==0) and Vector3.new(width/2,length/2,depth/2) or Vector3.new(depth/2,length/2,width/2)
                part(g,"CornerWedgePart",size,function(t)
                    local breath=motion and math.sin(t*0.7+motion)*0.035 or 0
                    return CFrame.new(0,breath,0)*base*transform*CFrame.new((s%2==0 and width or depth)/4,length/4,(s%2==0 and depth or width)/4)
                end,color,alpha,emissive,side%2==0 and 0.10 or 0)
            end
        end
    end
    local function glowCurve(g,a,b,width,color,opacity)
        g.referenceGlows=g.referenceGlows or {}
        local aa=Instance.new("Attachment");aa.Parent=g.anchor
        local bb=Instance.new("Attachment");bb.Parent=g.anchor
        local beam=Instance.new("Beam")
        beam.Name="BladeSoftRadiance"
        beam.Attachment0,beam.Attachment1=aa,bb
        beam.FaceCamera=true;beam.Segments=32
        beam.Width0=width*g.scale;beam.Width1=0.01*g.scale
        beam.LightEmission=1;beam.LightInfluence=0
        beam.Texture="rbxasset://textures/particles/smoke_main.dds"
        beam.TextureMode=Enum.TextureMode.Stretch
        beam.Enabled=false;beam.Parent=g.folder
        table.insert(g.referenceGlows,{a=aa,b=bb,beam=beam,start=a,tip=b,color=color,alpha=opacity})
    end
    function FX.wings(g)
        g.isReferenceWings=true
        g.bladePivots={}
        local aqua=Color3.fromRGB(106,209,229)
        local violet=Color3.fromRGB(174,112,224)
        local pearl=Color3.fromRGB(230,216,252)
        -- Each row specifies tip, widest cross section and root height.
        local fan={{4.25,4.30,0.58,0.25},{4.85,2.62,0.68,0.14},
            {5.12,0.43,0.34,0.02},{4.07,-0.28,0.26,-0.10},{3.12,-2.34,0.94,-0.22}}
        for _,side in ipairs({-1,1}) do
            for i,row in ipairs(fan) do
                local root=Vector3.new(side*0.49,row[4],0.12)
                local tip=Vector3.new(side*row[1],row[2],0.24+i*0.065)
                local ray=tip-root
                local across=Vector3.new(-side*ray.Y,side*ray.X,0).Unit*row[3]
                local pivot={root=root,side=side,index=i,transform=CFrame.identity}
                table.insert(g.bladePivots,pivot)
                local ridge=root:Lerp(tip,0.61)
                local upper,lower=ridge+across,ridge-across*0.63
                local joint=root:Lerp(tip,0.28)
                local function face(a,b,c,color,alpha,lit,mix)
                    Theme.WingsState.facet(a,b,c,0.032,function(cf,size)
                        part(g,"WedgePart",size,function() return pivot.transform * cf end,color,alpha,lit,mix)
                    end)
                end
                local collarA,collarB=joint+across*0.32,joint-across*0.21
                face(root,collarA,collarB,aqua,0.96,true,0.25)
                face(collarA,upper,joint,aqua:Lerp(violet,0.48),0.92,false,0.30)
                face(collarB,joint,lower,aqua:Lerp(violet,0.60),0.94,false,0.38)
                face(joint,upper,tip,violet,0.90,false,0.12)
                face(joint,tip,lower,violet:Lerp(pearl,0.40),0.91,false,0.40)
                local lift=Vector3.new(0,0,0.05)
                face(joint+lift,upper+lift,upper:Lerp(ridge,0.075)+lift,pearl,0.92,true,0.72)
                face(upper+lift,tip+lift,upper:Lerp(ridge,0.075)+lift,pearl,0.92,true,0.72)
            end
        end
    end
    local oldUpdate=FX.nebulaUpdate
    function FX.nebulaUpdate(g)
        oldUpdate(g)
        local base=FX.color(g.settings)
        local reference=g.settings.referenceColors~=false
        local strength=g.isReferenceWings and (g.settings.wingBrightness or 1) or 1
        if g.bladePivots then
            local wings=Theme.WingsState
            local phase=g.time*wings.speed*1.38
            local amplitude=math.rad(wings.flap)
            for _,pivot in ipairs(g.bladePivots) do
                local rank=(pivot.index-1)/4
                local opening=math.sin(phase-rank*0.85)
                local fan=amplitude*(0.65-rank*1.12)*opening
                local sweep=-math.rad(wings.spread)*0.42+amplitude*0.24*math.cos(phase-rank*0.85)
                pivot.transform=CFrame.new(pivot.root)*CFrame.Angles(0,pivot.side*sweep,pivot.side*fan)*CFrame.new(-pivot.root)
            end
        end
        local pulse=g.isReferenceWings and 1 or (0.97+0.03*math.sin(g.time*1.2))
        for _,item in ipairs(g.referenceParts or {}) do
            local cf=item.calc(g.time)
            item.part.CFrame=g.anchor.CFrame*CFrame.new(cf.Position*g.scale)*cf.Rotation
            local c=reference and item.color or base:Lerp(WHITE,item.mix)
            item.part.Color=c
            local transparency=1-math.clamp(item.alpha*g.opacity*pulse*(item.emissive and strength or 1),0,1)
            if item.lastTransparency~=transparency then item.part.Transparency=transparency;item.lastTransparency=transparency end
        end
        for _,item in ipairs(g.referenceGlows or {}) do
            local a,b=item.start*g.scale,item.tip*g.scale
            local d=b-a
            -- The curve is a continuous surface, not per-segment geometry.
            local function tangentFrame(p,v)
                local right=v.Unit;local up=Vector3.new(0,1,0)
                if math.abs(right.Y)>0.98 then up=Vector3.new(0,0,1)end
                local back=right:Cross(up).Unit
                return CFrame.fromMatrix(p,right,back:Cross(right).Unit,back)
            end
            item.a.CFrame=tangentFrame(a,d)
            item.b.CFrame=tangentFrame(b,d)
            item.beam.CurveSize0=d.Magnitude/3;item.beam.CurveSize1=d.Magnitude/3
            local c=reference and item.color or base
            if item.lastColor~=c then item.beam.Color=ColorSequence.new(c:Lerp(WHITE,0.25),c);item.lastColor=c end
            item.beam.Enabled=g.settings.glow~=false and g.opacity>0.01
            local step=math.floor(g.opacity*30)
            if item.step~=step then
                item.beam.Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,1),NumberSequenceKeypoint.new(0.28,1-item.alpha*step/30),NumberSequenceKeypoint.new(1,1)})
                item.step=step
            end
        end
        -- Particle and local-light palettes obey the same reference/theme switch as the geometry.
        if g.isReferenceWings then
            for _,item in ipairs(g.nebulaEmitters or {}) do
                local c=reference and item.palette or base
                if item.referenceColor~=c or item.referenceTheme~=base then item.e.Color=ColorSequence.new(c:Lerp(WHITE,0.25),c);item.referenceColor=c;item.referenceTheme=base end
            end
            for _,item in ipairs(g.nebulaLights or {}) do item.light.Color=reference and item.palette or base end
        end
    end
end

-- Prism is a Wings style, not a separate feature/module.
do
    local FX=Theme.PremiumFX
    Theme.PrismWings={}
    function Theme.PrismWings.Build(W,torso)
        local settings={referenceColors=W.prismReference,custom=not W.prismTheme,color=W.color,
            glow=W.glow,wingBrightness=W.prismBrightness,saturation=false}
        local g=FX.new("PrismWings",settings)
        W.prismGroup=g;W.folder=g.folder;W.boundCharacter=LocalPlayer.Character;W.boundTorso=torso
        g.scale=W.size;g.opacity=0
        FX.wings(g)
        g.anchor.CFrame=torso.CFrame*CFrame.new(W.prismX,0.65*W.size+W.prismY,0.8*W.size+W.prismZ)
        g.update=function(current)
            local char=LocalPlayer.Character
            if Unloaded or not W.on or W.style~=3 or not torso.Parent or char~=W.boundCharacter then
                FX.destroy(current);return
            end
            settings.referenceColors=W.prismReference;settings.custom=not W.prismTheme
            settings.color=W.color;settings.glow=W.glow;settings.wingBrightness=W.prismBrightness
            current.anchor.CFrame=torso.CFrame*CFrame.new(W.prismX,0.65*W.size+W.prismY,0.8*W.size+W.prismZ)
            current.opacity=math.min(1,current.time/0.25)*(1-W.trans)
        end
    end
end

-- JUMP CIRCLES / fixed world-space impressions, never attached to a moving foot.
do
    local FX = Theme.PremiumFX
    local section = createSection(rightVis, "Jump Circles")
    local state = {enabled = false, mode = "Clean Circle", radius = 2.6, lifetime = 1.1,
        settings = {color = Color3.fromRGB(170, 125, 255), custom = false,
            glow = true, saturation = false, speed = 1}, active = {}, last = -10}
    Theme.JumpCircles = state
    local TAU = math.pi * 2
    local function clear()
        for _, group in ipairs(state.active) do FX.destroy(group) end
        table.clear(state.active)
    end
    local function spawn(char, root)
        if not state.enabled or Unloaded or os.clock() - state.last < 0.16 then return end
        local ground = FX.ground(root, char, 9)
        if not ground then return end
        state.last = os.clock()
        for i = #state.active, 1, -1 do
            if state.active[i].dead then table.remove(state.active, i) end
        end
        -- Hard cap prevents unlimited instances during rapid/infinite jumps.
        local budget = Theme.ExtremePerformance and 3 or 5
        while #state.active >= budget do FX.destroy(table.remove(state.active, 1)) end
        local mode, radius, lifetime = state.mode, state.radius, state.lifetime
        local g = FX.new("Jump_" .. mode, state.settings)
        state.active[#state.active + 1] = g
        g.anchor.CFrame = ground
        FX.ring(g, 1, 0, 0, 0, 0.022, 1)
        if mode == "Pentagram Circle" then
            -- Exact regular pentagram: vertices on the same circumcircle, step = 2.
            local points = {}
            for i = 0, 4 do
                local a = -math.pi / 2 + i * TAU / 5
                points[i + 1] = Vector3.new(math.cos(a), 0, math.sin(a)) * 0.90
            end
            for i = 0, 4 do FX.line(g, points[i + 1], points[(i + 2) % 5 + 1], 0.018, 0.86) end
        elseif mode == "Orbital" then
            FX.ring(g, 0.85, 0.65, 1.18, 0.32, 0.018, 0.9)
            FX.ring(g, 1.06, 0.45, -0.86, -0.25, 0.016, 0.7)
            FX.ring(g, 0.92, 0.6, 0.6, 0.19, 0.015, 0.55)
        elseif mode == "Triple Halo" then
            FX.ring(g, 0.76, 0.008, 0, -0.2, 0.018, 0.7)
            FX.ring(g, 1.19, 0.012, 0, 0.2, 0.016, 0.55)
            for i = 0, 3 do
                local phase = i * TAU / 4
                FX.fog(g, function(t) local a = phase + t * 0.5; return Vector3.new(math.cos(a), 0.02, math.sin(a)) end,
                    3, 0.055, true, FX.cinematic[i + 1])
            end
        elseif mode == "Eclipse Bloom" then
            for i = 0, 3 do
                local phase = i * TAU / 4
                FX.ribbon(g, 24, 0.085, function(t, u)
                    local a = phase + u * math.pi * 0.42 + t * 0.14
                    local r = 0.67 + 0.26 * math.sin(u * math.pi)
                    return Vector3.new(math.cos(a) * r, 0.012, math.sin(a) * r)
                end, 0.45, FX.cinematic[i + 1])
            end
        elseif mode == "Stellar Tide" then
            FX.ring(g, 0.62, 0.01, 0, 0, 0.025, 0.5)
            FX.ring(g, 0.82, 0.02, 0, 0, 0.018, 0.75)
            for i = 0, 3 do
                local phase = i * TAU / 4
                FX.fog(g, function(t) local a = phase - t * 0.3; return Vector3.new(math.cos(a) * 0.9, 0.04, math.sin(a) * 0.9) end,
                    2, 0.4, false, FX.cinematic[i + 1])
            end
        elseif mode == "Advanced" then
            -- Astral Dial: counter-rotating crescents, fine inner ring and diamond satellites.
            FX.ring(g, 0.83, 0.002, 0, 0, 0.012, 0.45)
            for i = 0, 2 do
                FX.ring(g, 1.13, 0.004, 0, 0.32, 0.024, 0.85, i * TAU / 3, TAU * 0.20)
                FX.ring(g, 0.72, 0.006, 0, -0.45, 0.018, 0.65, i * TAU / 3, TAU * 0.14)
            end
            for i = 0, 7 do
                local phase = i * TAU / 8
                FX.path(g, 4, true, 0.019, function(t, u)
                    local angle = phase + t * 0.18
                    local a = u * TAU
                    local r = 1.015 + math.cos(a) * 0.022
                    local theta = angle + math.sin(a) * 0.016
                    return Vector3.new(math.cos(theta) * r, 0.006, math.sin(theta) * r)
                end, i % 2 == 0 and 0.8 or 0.4, 0.35)
            end
        end
        g.scale, g.opacity = radius * 0.24, 0
        g.update = function(group)
            local u = group.time / lifetime
            if u >= 1 or not state.enabled then FX.destroy(group); return end
            local ease = 1 - (1 - u) ^ 3
            group.scale = radius * (0.24 + 0.76 * ease)
            -- Fast silk-like reveal, held midlife, then smooth disappearance.
            local reveal = math.clamp(u / 0.09, 0, 1)
            local fade = math.clamp((1 - u) / 0.52, 0, 1)
            group.opacity = reveal * fade * fade * (3 - 2 * fade)
        end
    end
    section:AddToggle("Enable Jump Circles", false, function(value)
        state.enabled = value
        if not value then clear() end
    end, function(api)
        FX.controls(api, state.settings)
        api:AddSlider("Radius", 10, 50, state.radius * 10, function(value) state.radius = value / 10 end)
        api:AddSlider("Lifetime (ms)", 400, 2200, state.lifetime * 1000, function(value) state.lifetime = value / 1000 end)
    end)
    FX.choice(section, "FaceLess/Visuals/Jump Circles", "Jump Circle Mode",
        {"Clean Circle", "Pentagram Circle", "Orbital", "Triple Halo", "Eclipse Bloom", "Stellar Tide", "Advanced"}, function() return state.mode end,
        function(value) state.mode = value end)
    local stateConnection, childConnection, boundHumanoid
    local function unbind()
        if childConnection then childConnection:Disconnect(); childConnection = nil end
        if stateConnection then stateConnection:Disconnect(); stateConnection = nil end
        boundHumanoid = nil
        clear()
    end
    local function bind(char)
        unbind()
        local function attach(hum)
            if Unloaded or LocalPlayer.Character ~= char or not hum:IsA("Humanoid") or hum == boundHumanoid then return end
            if stateConnection then stateConnection:Disconnect() end
            boundHumanoid = hum
            stateConnection = hum.StateChanged:Connect(function(_, nextState)
                if nextState == Enum.HumanoidStateType.Jumping and LocalPlayer.Character == char then
                    local root = char:FindFirstChild("HumanoidRootPart")
                    if root then spawn(char, root) end
                end
            end)
        end
        childConnection = char.ChildAdded:Connect(attach)
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then attach(hum) end
    end
    track(LocalPlayer.CharacterAdded:Connect(bind))
    track(LocalPlayer.CharacterRemoving:Connect(unbind))
    if LocalPlayer.Character then bind(LocalPlayer.Character) end
    registerCleanup(unbind)
end

do
    local bodyConnection, pending
    local function restoreBody(char)
        if Unloaded or LocalPlayer.Character ~= char then return end
        if korbloxEnabled then pcall(applyKorblox) end
        if headlessEnabled then pcall(applyHeadless) end
        if customHatEnabled and char:FindFirstChild("Head") and not hatFolder then pcall(updateHat) end
        local wings = Theme.WingsState
        if wings and wings.on and wings.RepairIfNeeded then pcall(wings.RepairIfNeeded, char) end
    end
    local function schedule(char)
        if pending == char then return end
        pending = char
        task.defer(function()
            if pending ~= char then return end
            pending = nil
            restoreBody(char)
        end)
    end
    local function unbind()
        pending = nil
        if bodyConnection then bodyConnection:Disconnect(); bodyConnection = nil end
    end
    local function bind(char)
        unbind()
        bodyConnection = char.DescendantAdded:Connect(function(part)
            if (part.Parent == char and (part.Name == "Head" or part.Name == "Right Leg"
                or part.Name == "RightUpperLeg" or part.Name == "Torso" or part.Name == "UpperTorso"))
                or (part:IsA("Decal") and part.Parent == char:FindFirstChild("Head")) then
                schedule(char)
            end
        end)
        schedule(char)
    end
    track(LocalPlayer.CharacterAdded:Connect(bind))
    track(LocalPlayer.CharacterRemoving:Connect(unbind))
    track(LocalPlayer.CharacterAppearanceLoaded:Connect(schedule))
    if LocalPlayer.Character then bind(LocalPlayer.Character) end
    registerCleanup(unbind)
end

if LocalPlayer then
    -- Tear down the old character-owned head accessory as soon as it is removed.
    track(LocalPlayer.CharacterRemoving:Connect(function(char)
        if hatBuilders.HeadRigPrefixes[hatMode] and hatFolder and hatFolder.Parent == char then clearHat() end
    end))
end

-- Low-frequency cosmetic integrity watchdog catches same-character ragdolls/hits too.
-- Rebuild a head accessory when a joint, group pivot, geometry or the head changes.
do
    local cosmeticRepairAccumulator = 0
    local function hatRigNeedsRepair(char)
        if not customHatEnabled or hatMode == "Wings" then return false end
        local prefix = hatBuilders.HeadRigPrefixes[hatMode]
        local anchor = char and getHatAnchor(char)
        if not anchor then
            -- Clean a previous head rig even if rendering is paused; then wait.
            return prefix ~= nil and hatFolder ~= nil
        end
        if prefix then
            local hum = char:FindFirstChildOfClass("Humanoid")
            if not anchor:IsA("BasePart") or (hum and hum.Health <= 0) then return hatFolder ~= nil end
        end
        local expectedParent = prefix and char or workspace
        if not hatFolder or hatFolder.Parent ~= expectedParent or #hatParts == 0 then return true end
        for _, entry in ipairs(hatParts) do
            if not entry.part or not entry.part.Parent then return true end
        end
        if prefix then
            local root = hatPhysicsRoot
            if not hatStaticWelded or not root or root.Parent ~= hatFolder or root.Anchored or root.CanCollide
                or not root.Massless or hatBoundAnchor ~= anchor then return true end
            if not hatBuilders.BoundHeadSize or (anchor.Size - hatBuilders.BoundHeadSize).Magnitude > 0.05 then return true end
            local mount = root:FindFirstChild(prefix .. "Mount")
            if not mount or not mount:IsA("Motor6D") or not mount.Enabled or mount.Part0 ~= anchor or mount.Part1 ~= root then return true end
            if hatMode == "Halo" then
                if #hatGroups ~= 2 then return true end
                for i, group in ipairs(hatGroups) do
                    local pivot, motor = group.haloPivot, group.haloMotor
                    if not pivot or pivot.Parent ~= hatFolder or pivot.Anchored or pivot.CanCollide or not pivot.Massless
                        or not motor or motor.Parent ~= pivot or motor.Name ~= "HaloOrbitMotor_" .. i
                        or not motor:IsA("Motor6D") or not motor.Enabled or motor.Part0 ~= root or motor.Part1 ~= pivot then return true end
                end
            end
            for _, entry in ipairs(hatParts) do
                local part = entry.part
                local partRoot = hatMode == "Halo" and entry.group.haloPivot or root
                local weld = part and part:FindFirstChild(prefix .. "Weld")
                if not part or part.Parent ~= hatFolder or part.Anchored or part.CanCollide or not part.Massless
                    or not weld or not weld:IsA("Weld") or not weld.Enabled
                    or weld.Part0 ~= partRoot or weld.Part1 ~= part then
                    return true
                end
                if not partRoot then return true end
            end
        end
        return false
    end
    track(RunService.Heartbeat:Connect(function(dt)
        if Unloaded then return end
        cosmeticRepairAccumulator = cosmeticRepairAccumulator + dt
        if cosmeticRepairAccumulator < 0.34 then return end
        cosmeticRepairAccumulator = 0
        local char = LocalPlayer and LocalPlayer.Character
        if not char or not char.Parent then return end
        if customHatEnabled and hatRigNeedsRepair(char) then pcall(updateHat) end
        local wingState = Theme and Theme.WingsState
        if wingState and wingState.on and wingState.RepairIfNeeded then pcall(wingState.RepairIfNeeded, char) end
    end))
end

-- TRAILS / native Roblox motion history. Sources follow the rig; history remains in world space.
do
    local FX=Theme.PremiumFX
    local section=createSection(visualTab.Right,"Trails")
    local state={enabled=false,mode="Soft Lines",lifetime=0.42,width=1,
        settings={custom=false,color=Color3.fromRGB(145,195,255),glow=true,saturation=false,cinematic=false}}
    local group
    local modes={"Soft Lines","Comet Silk","Firefly Drift","Pulse Wake"}
    local function clear()
        FX.destroy(group);group=nil
    end
    local function apply()
        clear()
        if not state.enabled or Unloaded then return end
        local char=LocalPlayer.Character
        local root=char and char:FindFirstChild("HumanoidRootPart")
        if not root then return end
        local g=FX.new("Trails_"..state.mode,state.settings)
        group=g;g.nativeTrails={};g.ownedAttachments={}
        local function source(position)
            local a=Instance.new("Attachment")
            a.Name="CosmicAtelier_TrailSource"
            a.Position=position;a.Parent=root
            table.insert(g.ownedAttachments,a)
            return a
        end
        local function ribbon(x,y,width,phase,halo)
            local a=source(Vector3.new(x,y-width/2,0.65))
            local b=source(Vector3.new(x,y+width/2,0.65))
            local trail=Instance.new("Trail")
            trail.Name=halo and "SoftTrailHalo" or "PremiumMotionRibbon"
            trail.Attachment0,trail.Attachment1=a,b
            trail.FaceCamera=true
            trail.Lifetime=state.lifetime
            trail.MinLength=0.025
            trail.MaxLength=22
            trail.LightEmission=1;trail.LightInfluence=0
            trail.WidthScale=NumberSequence.new({NumberSequenceKeypoint.new(0,0.8),NumberSequenceKeypoint.new(0.15,1),NumberSequenceKeypoint.new(0.7,0.25),NumberSequenceKeypoint.new(1,0)})
            trail.Enabled=false;trail.Parent=g.folder
            table.insert(g.nativeTrails,{trail=trail,phase=phase,a=a,b=b,x=x,y=y,width=width,halo=halo})
        end
        local function layered(x,y,width,phase)
            ribbon(x,y,width,phase,false)
            ribbon(x,y,width*3.2,phase,true)
        end
        if state.mode=="Soft Lines" then
            layered(-0.58,-0.25,0.055,1);layered(0.58,-0.25,0.055,2)
        elseif state.mode=="Comet Silk" then
            layered(0,-0.35,0.28,1)
            layered(-0.52,-0.4,0.04,2);layered(0.52,-0.4,0.04,3)
        elseif state.mode=="Pulse Wake" then
            layered(-0.44,-0.35,0.11,1);layered(0.44,-0.35,0.11,2)
        end
        for _,side in ipairs({-1,1}) do
            local x=side*0.48
            local dust=state.mode=="Firefly Drift"
            local pulse=state.mode=="Pulse Wake"
            FX.fog(g,function(t)return Vector3.new(x,-0.3,0.75)end,pulse and 0 or (dust and 10 or 1.8),
                dust and 0.095 or 0.045,true,FX.cinematic[side==1 and 1 or 2])
            local item=g.nebulaEmitters[#g.nebulaEmitters]
            item.e.LockedToPart=false
            item.e.Speed=NumberRange.new(dust and 0.16 or 0.04,dust and 0.5 or 0.18)
            item.e.Lifetime=NumberRange.new(dust and 0.65 or 0.3,dust and 1.1 or 0.65)
            item.burst=pulse
            if dust or state.mode=="Comet Silk" then
                FX.fog(g,function(t)return Vector3.new(x,-0.4,0.85)end,dust and 2.2 or 1.4,0.45,false,FX.cinematic[side==1 and 1 or 2])
                local fog=g.nebulaEmitters[#g.nebulaEmitters]
                fog.e.LockedToPart=false;fog.e.Lifetime=NumberRange.new(0.35,0.75)
            end
        end
        local traveled=0
        local previousPosition=root.Position
        local lastLifetime, lastWidth
        local lastColor,lastPalette,lastGlow
        g.anchor.CFrame=root.CFrame
        g.opacity=0
        g.update=function(current,dt)
            if Unloaded or not state.enabled or not root.Parent or LocalPlayer.Character~=char then FX.destroy(current);return end
            current.anchor.CFrame=root.CFrame
            local distance=(root.Position-previousPosition).Magnitude
            local moving=distance/math.max(dt,0.001)>0.65
            -- Never leave long lines across teleports.
            if distance>12 then
                moving=false
                for _,item in ipairs(current.nativeTrails) do item.trail:Clear() end
                for _,item in ipairs(current.nebulaEmitters or {}) do item.e:Clear() end
            end
            if moving and distance<12 then
                traveled=traveled+distance
                if traveled>=0.65 then
                    traveled=traveled%0.65
                    for _,item in ipairs(current.nebulaEmitters or {})do if item.burst then item.e:Emit(3) end end
                end
            end
            previousPosition=root.Position
            current.opacity=moving and 1 or 0
            local c=FX.color(state.settings)
            local recolor=c~=lastColor or lastPalette~=state.settings.cinematic
            local restyle=lastGlow~=state.settings.glow
            for _,item in ipairs(current.nativeTrails) do
                item.trail.Enabled=moving and (not item.halo or state.settings.glow~=false)
                if lastLifetime ~= state.lifetime then item.trail.Lifetime = state.lifetime end
                if lastWidth ~= state.width then
                    item.a.Position=Vector3.new(item.x,item.y-item.width*state.width/2,0.65)
                    item.b.Position=Vector3.new(item.x,item.y+item.width*state.width/2,0.65)
                end
                if recolor then
                    local base=state.settings.cinematic and FX.cinematic[item.phase] or c
                    item.trail.Color = ColorSequence.new({
                        ColorSequenceKeypoint.new(0, base:Lerp(Color3.new(1,1,1), 0.45)),
                        ColorSequenceKeypoint.new(0.38, base),
                        ColorSequenceKeypoint.new(1, base:Lerp(Color3.fromRGB(98,77,150), 0.32)),
                    })
                end
                if restyle then
                    local a=item.halo and 0.9 or (state.settings.glow~=false and 0.12 or 0.38)
                    item.trail.Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,a),NumberSequenceKeypoint.new(0.55,a + (1-a)*0.45),NumberSequenceKeypoint.new(1,1)})
                end
            end
            lastLifetime, lastWidth = state.lifetime, state.width
            lastColor,lastPalette,lastGlow=c,state.settings.cinematic,state.settings.glow
        end
    end
    section:AddToggle("Enable Trails",false,function(value)
        state.enabled=value
        if not Theme.ConfigRegistry.applying then apply() end
    end,function(api)
        FX.controls(api,state.settings)
        api:AddSlider("Trail lifetime (ms)",150,1200,420,function(value)state.lifetime=value/1000 end)
        api:AddSlider("Trail width (%)",50,200,100,function(value)state.width=value/100 end)
    end)
    FX.choice(section,"FaceLess/Visuals/Trails","Trail Mode",modes,function()return state.mode end,function(value)
        state.mode=value
        if state.enabled and not Theme.ConfigRegistry.applying then apply() end
    end)
    track(LocalPlayer.CharacterRemoving:Connect(clear))
    local elapsed=0
    track(RunService.Heartbeat:Connect(function(dt)
        elapsed=elapsed+dt
        if elapsed<0.5 then return end
        elapsed=0
        if Unloaded then clear();return end
        if state.enabled and (not group or group.dead) then apply() end
    end))
    Theme.Trails={Apply=apply,Clear=clear}
    registerCleanup(clear)
end

-- 6. FFLAGS
local secFFlags = createSection(fflagsTab.Left, "TSB Visual Cleanup")
secFFlags:AddButton("Stable FPS cap (144)", function()
    -- Avoid an extreme cap that can keep the client CPU/GPU unnecessarily busy.
    pcall(function() if setfpscap then setfpscap(144) end end)
end)
local cleanupOptions = {particles=true, trees=false, mountains=false, destruction=true, grass=false, trash=false, ashes=true}
local cleanupOriginals = {}
local setCleanupObject
local applyTSBCleanup
local restoreTSBCleanup
do
    local function isTreeSegmentName(s)
        local noStreet = string.gsub(s, "street", " ")
        return string.find(noStreet, "tree", 1, true) ~= nil
            or string.find(s, "foliage", 1, true) ~= nil
            or string.find(s, "leaves", 1, true) ~= nil
            or string.find(s, "leaf", 1, true) ~= nil
            or string.find(s, "canopy", 1, true) ~= nil
            or string.find(s, "branch", 1, true) ~= nil
            or string.find(s, "trunk", 1, true) ~= nil
            or string.find(s, "stump", 1, true) ~= nil
            or string.find(s, "bark", 1, true) ~= nil
    end
    local function isTreeModelNode(model, charRoots, cache)
        local cached = cache[model]
        if cached ~= nil then return cached end
        if not model:IsA("Model") or model == workspace or model.Parent == workspace or charRoots[model] then
            cache[model] = false
            return false
        end
        local mn = string.lower(model.Name)
        if isTreeSegmentName(mn) then
            cache[model] = true
            return true
        end
        if string.find(mn, "map", 1, true) or string.find(mn, "building", 1, true)
            or string.find(mn, "chunk", 1, true) or string.find(mn, "street", 1, true)
            or string.find(mn, "destruction", 1, true) or string.find(mn, "debris", 1, true)
            or model:FindFirstChildOfClass("Humanoid") then
            cache[model] = false
            return false
        end
        local children = model:GetChildren()
        if #children == 0 or #children > 25 then
            cache[model] = false
            return false
        end
        local hasTreeChild = false
        for _, ch in ipairs(children) do
            if ch:IsA("Folder") then
                cache[model] = false
                return false
            end
            local cn = string.lower(ch.Name)
            if string.find(cn, "foliage", 1, true) or string.find(cn, "leaves", 1, true)
                or string.find(cn, "canopy", 1, true) or string.find(cn, "trunk", 1, true)
                or string.find(cn, "stump", 1, true) then
                hasTreeChild = true
            end
        end
        cache[model] = hasTreeChild
        return hasTreeChild
    end
    local function cleanupMatchPath(obj, n, isTree, isParticle, key)
        if key == "particles" then
            -- Preserve Atelier particle and ribbon effects during environment cleanup.
            if string.find(n, "cosmicatelier_", 1, true) then return false end
            return isParticle
        end
        if key == "ashes" then return isParticle and (string.find(n, "ash", 1, true) ~= nil or string.find(n, "dust", 1, true) ~= nil) end
        if key == "trees" then return isTree end
        if key == "mountains" then return string.find(n, "mountain", 1, true) ~= nil or string.find(n, "rock", 1, true) ~= nil or string.find(n, "boulder", 1, true) ~= nil end
        if key == "destruction" then
            if not isParticle and isTree then
                local isDynamicDebris = string.find(n, "thrown", 1, true) ~= nil
                    or string.find(n, "vfx", 1, true) ~= nil
                    or string.find(n, "effect", 1, true) ~= nil
                if not isDynamicDebris then return false end
            end
            return string.find(n, "destruction", 1, true) ~= nil
                or string.find(n, "destroy", 1, true) ~= nil
                or string.find(n, "rubble", 1, true) ~= nil
                or string.find(n, "debris", 1, true) ~= nil
        end
        if key == "grass" then return string.find(n, "grass", 1, true) ~= nil end
        if key == "trash" then
            return string.find(n, "trash", 1, true) ~= nil
                or string.find(n, "garbage", 1, true) ~= nil
                or string.find(n, "dumpster", 1, true) ~= nil
                or string.find(n, "bin", 1, true) ~= nil
        end
        return false
    end
    local function buildCleanupMeta(obj, protectedRoots, charRoots, treeModelCache)
        if ScreenGui and obj:IsDescendantOf(ScreenGui) then
            return nil, false, false, true, false
        end
        local names = {}
        local cur = obj
        local depth = 0
        local inChar = false
        local inTreeModel = false
        while cur and cur ~= workspace and cur ~= game and depth < 24 do
            if protectedRoots[cur] then
                return nil, false, false, true, false
            end
            if charRoots[cur] then inChar = true end
            if not inTreeModel and cur ~= obj and cur:IsA("Model") and isTreeModelNode(cur, charRoots, treeModelCache) then
                inTreeModel = true
            end
            names[#names + 1] = string.lower(cur.Name)
            cur = cur.Parent
            depth = depth + 1
        end
        local n = table.concat(names, " ")
        local isTree = inTreeModel or isTreeSegmentName(n)
        local isParticle = obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam")
        return n, isTree, isParticle, false, inChar
    end
    setCleanupObject = function(obj, enabled)
        if not obj then return end
        if enabled then
            if not obj.Parent then return end
            if not cleanupOriginals[obj] then
                local snap = {}
                if obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam") then snap.Enabled = obj.Enabled
                elseif obj:IsA("BasePart") then
                    snap.LocalTransparencyModifier = obj.LocalTransparencyModifier
                    snap.CastShadow = obj.CastShadow
                elseif obj:IsA("Decal") or obj:IsA("Texture") then snap.Transparency = obj.Transparency
                else return end
                cleanupOriginals[obj] = snap
            end
            pcall(function()
                if obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam") then obj.Enabled = false
                elseif obj:IsA("BasePart") then
                    obj.LocalTransparencyModifier = 1
                    obj.CastShadow = false
                elseif obj:IsA("Decal") or obj:IsA("Texture") then obj.Transparency = 1 end
            end)
        else
            local snap = cleanupOriginals[obj]
            if snap then
                pcall(function()
                    if snap.Enabled ~= nil then obj.Enabled = snap.Enabled end
                    if snap.LocalTransparencyModifier ~= nil then obj.LocalTransparencyModifier = snap.LocalTransparencyModifier end
                    if snap.CastShadow ~= nil then obj.CastShadow = snap.CastShadow end
                    if snap.Transparency ~= nil then obj.Transparency = snap.Transparency end
                end)
                cleanupOriginals[obj] = nil
            end
        end
    end
    applyTSBCleanup = function()
        if Theme.ConfigRegistry and Theme.ConfigRegistry.applying then
            Theme.ConfigRegistry.cleanupPending = true
            return
        end
        pcall(function()
            local protectedRoots = {}
            for _, name in ipairs({"SatanicWeather", "FaceLessSkyAtelier", "SatanicCinematicFX", "SatanicSandevistanFX", "CustomHatEffect", "CustomWingsEffect"}) do
                local node = workspace:FindFirstChild(name)
                if node then protectedRoots[node] = true end
            end
            local charRoots = {}
            for _, player in ipairs(Players:GetPlayers()) do
                if player.Character then charRoots[player.Character] = true end
            end
            local treeModelCache = {}

            for _, obj in ipairs(workspace:GetDescendants()) do
                local isPart = obj:IsA("BasePart")
                local isFx = obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam")
                local isDecal = obj:IsA("Decal") or obj:IsA("Texture")
                if isPart or isFx or isDecal then
                    local n, isTree, isParticle, protected, inChar = buildCleanupMeta(obj, protectedRoots, charRoots, treeModelCache)
                    if not protected and n then
                        local selected = false
                        if not (isPart and inChar) then
                            for key, enabled in pairs(cleanupOptions) do
                                if enabled and cleanupMatchPath(obj, n, isTree, isParticle, key) then selected = true; break end
                            end
                        end
                        if selected then
                            setCleanupObject(obj, true)
                        elseif isPart and not inChar and not cleanupOptions.trees and isTree and obj.LocalTransparencyModifier >= 0.99 then
                            pcall(function() obj.LocalTransparencyModifier = 0 end)
                        end
                    end
                end
            end
            local tracked = {}
            for obj in pairs(cleanupOriginals) do tracked[#tracked + 1] = obj end
            for _, obj in ipairs(tracked) do
                local selected = false
                if obj and obj.Parent and obj:IsDescendantOf(workspace) then
                    local n, isTree, isParticle, protected, inChar = buildCleanupMeta(obj, protectedRoots, charRoots, treeModelCache)
                    if not protected and n and not (obj:IsA("BasePart") and inChar) then
                        for key, enabled in pairs(cleanupOptions) do
                            if enabled and cleanupMatchPath(obj, n, isTree, isParticle, key) then selected = true; break end
                        end
                    end
                end
                if not selected then setCleanupObject(obj, false) end
            end
        end)
    end
    restoreTSBCleanup = function()
        local tracked = {}
        for obj in pairs(cleanupOriginals) do tracked[#tracked + 1] = obj end
        for _, obj in ipairs(tracked) do setCleanupObject(obj, false) end
        pcall(function()
            local protectedRoots = {}
            for _, name in ipairs({"SatanicWeather", "FaceLessSkyAtelier", "SatanicCinematicFX", "SatanicSandevistanFX", "CustomHatEffect", "CustomWingsEffect"}) do
                local node = workspace:FindFirstChild(name)
                if node then protectedRoots[node] = true end
            end
            local charRoots = {}
            for _, player in ipairs(Players:GetPlayers()) do
                if player.Character then charRoots[player.Character] = true end
            end
            local treeModelCache = {}
            for _, obj in ipairs(workspace:GetDescendants()) do
                if obj:IsA("BasePart") and obj.LocalTransparencyModifier >= 0.99 then
                    local n, isTree, isParticle, protected, inChar = buildCleanupMeta(obj, protectedRoots, charRoots, treeModelCache)
                    if not protected and not inChar and n and (
                        isTree
                        or cleanupMatchPath(obj, n, isTree, isParticle, "mountains")
                        or cleanupMatchPath(obj, n, isTree, isParticle, "destruction")
                        or cleanupMatchPath(obj, n, isTree, isParticle, "grass")
                        or cleanupMatchPath(obj, n, isTree, isParticle, "trash")
                    ) then
                        pcall(function() obj.LocalTransparencyModifier = 0 end)
                    end
                end
            end
        end)
    end
end
Theme.ConfigRegistry.FlushCleanup = applyTSBCleanup

-- EXTREME PERFORMANCE PROFILE: lower custom geometry/update cost without removing the UI or config system.
do
    local secPerformance = createSection(fflagsTab.Right, "Extreme Performance")
    secPerformance:AddToggle("Extreme Performance Mode", true, function(enabled)
        Theme.ExtremePerformance = enabled == true
        -- Rebuild only effects which are currently enabled. These changes are one-shot;
        -- inactive effects do not start background work.
        if Theme.WingsState and Theme.WingsState.FinalizeConfig then pcall(Theme.WingsState.FinalizeConfig) end
        if customHatEnabled then pcall(updateHat) end
            if Theme.Trails and Theme.Trails.Apply then pcall(Theme.Trails.Apply) end
        if WeatherState and WeatherState.enabled and WeatherState.apply then pcall(WeatherState.apply) end
    end)
    secPerformance:AddButton("Apply maximum local cleanup", function()
        cleanupOptions.particles = true
        cleanupOptions.destruction = true
        cleanupOptions.ashes = true
        applyTSBCleanup()
    end)
    secPerformance:AddButton("Restore cleaned environment", function()
        restoreTSBCleanup()
    end)
end
secFFlags:AddButton("Apply selected changes", applyTSBCleanup, function(api)
    api:AddToggle("Reduce particles", cleanupOptions.particles, function(v) cleanupOptions.particles=v; applyTSBCleanup() end)
    api:AddToggle("Trees + foliage", cleanupOptions.trees, function(v) cleanupOptions.trees=v; applyTSBCleanup() end)
    api:AddToggle("Mountains / rocks", cleanupOptions.mountains, function(v) cleanupOptions.mountains=v; applyTSBCleanup() end)
    api:AddToggle("Destruction visuals", cleanupOptions.destruction, function(v) cleanupOptions.destruction=v; applyTSBCleanup() end)
    api:AddToggle("Grass", cleanupOptions.grass, function(v) cleanupOptions.grass=v; applyTSBCleanup() end)
    api:AddToggle("Trash / bins", cleanupOptions.trash, function(v) cleanupOptions.trash=v; applyTSBCleanup() end)
    api:AddToggle("Ash / dust particles", cleanupOptions.ashes, function(v) cleanupOptions.ashes=v; applyTSBCleanup() end)
    api:AddButton("Restore environment", restoreTSBCleanup)
end)


-- POTATO GRAPHICS v2: картофельная графика как в рабочем SatanicHub —
-- чистка сцены напрямую (FFlag'ы в рантайме не цепляются): SmoothPlastic
-- на все части, без отражений и декалей, плюс тени/вода/качество в пол.
-- Всё обратимо тумблером и не трогает меню и наши эффекты.
do
    local PotatoFF = {applied = false, savedObjs = {}, savedEnv = {}}
    local PROTECTED = {"SatanicWeather", "WorldWeatherGeometry", "FaceLessSkyAtelier",
        "SatanicCinematicFX", "SatanicSandevistanFX", "CustomHatEffect", "CustomWingsEffect"}
    local function isProtected(obj)
        local character = LocalPlayer.Character
        if character and obj:IsDescendantOf(character) then return true end
        if ScreenGui and obj:IsDescendantOf(ScreenGui) then return true end
        for _, name in ipairs(PROTECTED) do
            local node = workspace:FindFirstChild(name)
            if node and obj:IsDescendantOf(node) then return true end
        end
        return false
    end
    function PotatoFF.apply()
        if PotatoFF.applied then return end
        PotatoFF.applied = true
        pcall(function()
            for _, obj in ipairs(workspace:GetDescendants()) do
                if not isProtected(obj) then
                    if obj:IsA("BasePart") then
                        if not PotatoFF.savedObjs[obj] then
                            PotatoFF.savedObjs[obj] = {Material = obj.Material, Reflectance = obj.Reflectance}
                        end
                        pcall(function()
                            obj.Material = Enum.Material.SmoothPlastic
                            obj.Reflectance = 0
                        end)
                    elseif obj:IsA("Decal") or obj:IsA("Texture") then
                        if not PotatoFF.savedObjs[obj] then
                            PotatoFF.savedObjs[obj] = {Transparency = obj.Transparency}
                        end
                        pcall(function() obj.Transparency = 1 end)
                    end
                end
            end
        end)
        pcall(function()
            local L = game:GetService("Lighting")
            if PotatoFF.savedEnv.GlobalShadows == nil then
                PotatoFF.savedEnv.GlobalShadows = L.GlobalShadows
                PotatoFF.savedEnv.EnvironmentDiffuseScale = L.EnvironmentDiffuseScale
                PotatoFF.savedEnv.EnvironmentSpecularScale = L.EnvironmentSpecularScale
            end
            L.GlobalShadows = false
            L.EnvironmentDiffuseScale = 0
            L.EnvironmentSpecularScale = 0
        end)
        pcall(function()
            local T = workspace.Terrain
            if PotatoFF.savedEnv.WaterWaveSize == nil then
                PotatoFF.savedEnv.WaterWaveSize = T.WaterWaveSize
                PotatoFF.savedEnv.WaterWaveSpeed = T.WaterWaveSpeed
                PotatoFF.savedEnv.WaterReflectance = T.WaterReflectance
            end
            T.WaterWaveSize = 0
            T.WaterWaveSpeed = 0
            T.WaterReflectance = 0
        end)
        pcall(function()
            local gs = UserSettings().GameSettings
            if PotatoFF.savedEnv.SavedQualityLevel == nil then
                PotatoFF.savedEnv.SavedQualityLevel = gs.SavedQualityLevel
            end
            gs.SavedQualityLevel = Enum.SavedQualitySetting.QualityLevel1
        end)
    end
    function PotatoFF.restore()
        if not PotatoFF.applied then return end
        PotatoFF.applied = false
        for obj, snap in pairs(PotatoFF.savedObjs) do
            pcall(function()
                if snap.Material ~= nil then obj.Material = snap.Material end
                if snap.Reflectance ~= nil then obj.Reflectance = snap.Reflectance end
                if snap.Transparency ~= nil then obj.Transparency = snap.Transparency end
            end)
        end
        PotatoFF.savedObjs = {}
        pcall(function()
            local L = game:GetService("Lighting")
            if PotatoFF.savedEnv.GlobalShadows ~= nil then L.GlobalShadows = PotatoFF.savedEnv.GlobalShadows end
            if PotatoFF.savedEnv.EnvironmentDiffuseScale ~= nil then L.EnvironmentDiffuseScale = PotatoFF.savedEnv.EnvironmentDiffuseScale end
            if PotatoFF.savedEnv.EnvironmentSpecularScale ~= nil then L.EnvironmentSpecularScale = PotatoFF.savedEnv.EnvironmentSpecularScale end
        end)
        pcall(function()
            local T = workspace.Terrain
            if PotatoFF.savedEnv.WaterWaveSize ~= nil then T.WaterWaveSize = PotatoFF.savedEnv.WaterWaveSize end
            if PotatoFF.savedEnv.WaterWaveSpeed ~= nil then T.WaterWaveSpeed = PotatoFF.savedEnv.WaterWaveSpeed end
            if PotatoFF.savedEnv.WaterReflectance ~= nil then T.WaterReflectance = PotatoFF.savedEnv.WaterReflectance end
        end)
        pcall(function()
            if PotatoFF.savedEnv.SavedQualityLevel ~= nil then
                UserSettings().GameSettings.SavedQualityLevel = PotatoFF.savedEnv.SavedQualityLevel
            end
        end)
        PotatoFF.savedEnv = {}
    end
    local secPotato = createSection(fflagsTab.Right, "Potato Graphics · картошка")
    secPotato:AddToggle("КАРТОШКА: графика в пол (макс FPS)", false, function(enabled)
        if enabled then PotatoFF.apply() else PotatoFF.restore() end
    end)
    secPotato:AddButton("Снять FPS-кап (турбина)", function()
        pcall(function() if setfpscap then setfpscap(999) end end)
    end)
    registerCleanup(PotatoFF.restore)
end


-- ===================== CONFIG CLOUD =====================
-- Облако конфигов: загрузка на файлохостинг + код FLCFG1 для пересылки.
-- Ссылку или код отправляешь другу — он жмёт «☁ ИЗ ОБЛАКА» и вставляет.
-- Список загруженных ссылок хранится локально: SatanicUI/cloud_index.json.
ConfigCloud = {index = {}, busy = false}
do
    local HttpService = game:GetService("HttpService")
    local INDEX_PATH = "SatanicUI/cloud_index.json"
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local encMap, decMap = {}, {}
    for i = 1, 64 do
        local ch = string.sub(alphabet, i, i)
        encMap[i - 1] = ch
        decMap[ch] = i - 1
    end

    local function b64encode(data)
        local out, n, len, i = {}, 0, #data, 1
        while i <= len do
            local a = string.byte(data, i)
            local b = string.byte(data, i + 1)
            local c = string.byte(data, i + 2)
            out[n + 1] = encMap[math.floor(a / 4)]
            out[n + 2] = encMap[(a % 4) * 16 + (b and math.floor(b / 16) or 0)]
            if b then
                out[n + 3] = encMap[(b % 16) * 4 + (c and math.floor(c / 64) or 0)]
                out[n + 4] = c and encMap[c % 64] or "="
            else
                out[n + 3] = "="
                out[n + 4] = "="
            end
            n = n + 4
            i = i + 3
        end
        return table.concat(out)
    end

    local function b64decode(s)
        s = string.gsub(string.gsub(string.gsub(s, "%s", ""), "-", "+"), "_", "/")
        local out, n, buf, bits = {}, 0, 0, 0
        for i = 1, #s do
            local v = decMap[string.sub(s, i, i)]
            if v then
                buf = buf * 64 + v
                bits = bits + 6
                if bits >= 8 then
                    bits = bits - 8
                    local byte = math.floor(buf / (2 ^ bits))
                    buf = buf % (2 ^ bits)
                    n = n + 1
                    out[n] = string.char(byte)
                end
            end
        end
        return table.concat(out)
    end

    local function httpReq(opts)
        local req = request or http_request or (syn and syn.request) or (fluxus and fluxus.request) or httpRequest
        if not req then return nil, "нет HTTP API (request/http_request)" end
        local ok, res = pcall(req, opts)
        if not ok then return nil, tostring(res) end
        if type(res) ~= "table" then return nil, "пустой ответ" end
        return res
    end

    local function httpGet(url)
        local res, err = httpReq({Url = url, Method = "GET"})
        if res and type(res.Body) == "string" and res.Body ~= "" then return res.Body end
        local ok2, body = pcall(function() return game:HttpGet(url) end)
        if ok2 and type(body) == "string" and body ~= "" then return body end
        return nil, err
    end

    local function multipartBody(fields)
        local boundary = "FaceLessCfg" .. tostring(math.random(10000000, 99999999))
        local parts = {}
        for _, f in ipairs(fields) do
            parts[#parts + 1] = "--" .. boundary .. "\r\n"
            if f.filename then
                parts[#parts + 1] = 'Content-Disposition: form-data; name="' .. f.name .. '"; filename="' .. f.filename .. '"\r\n'
                parts[#parts + 1] = "Content-Type: " .. (f.ctype or "application/octet-stream") .. "\r\n\r\n"
            else
                parts[#parts + 1] = 'Content-Disposition: form-data; name="' .. f.name .. '"\r\n\r\n'
            end
            parts[#parts + 1] = f.value
            parts[#parts + 1] = "\r\n"
        end
        parts[#parts + 1] = "--" .. boundary .. "--\r\n"
        return table.concat(parts), boundary
    end

    function ConfigCloud.EncodeShare(jsonStr)
        return "FLCFG1." .. b64encode(jsonStr)
    end

    function ConfigCloud.DecodeShare(code)
        local compact = string.gsub(code, "%s+", "")
        local payload = string.match(compact, "^FLCFG1%.(.+)$") or compact
        local ok, raw = pcall(b64decode, payload)
        if ok and type(raw) == "string" and string.sub(raw, 1, 1) == "{" then return raw end
        return nil
    end

    function ConfigCloud.Copy(text)
        if setclipboard then return pcall(setclipboard, text) end
        if toclipboard then return pcall(toclipboard, text) end
        return false
    end

    function ConfigCloud.LoadIndex()
        ConfigCloud.index = {}
        pcall(function()
            if isfile and isfile(INDEX_PATH) then
                local data = HttpService:JSONDecode(readfile(INDEX_PATH))
                if type(data) == "table" then ConfigCloud.index = data end
            end
        end)
    end

    function ConfigCloud.SaveIndex()
        pcall(function()
            if not isfolder("SatanicUI") then makefolder("SatanicUI") end
            writefile(INDEX_PATH, HttpService:JSONEncode(ConfigCloud.index))
        end)
    end

    function ConfigCloud.Upload(name, jsonStr, onDone)
        task.spawn(function()
            local fname = (string.gsub(name, "[^%w_%-]", "_")) .. ".json"
            local hosts = {
                { url = "https://catbox.moe/user/api.php", mode = "text", fields = {
                    {name = "reqtype", value = "fileupload"},
                    {name = "fileToUpload", filename = fname, ctype = "application/json", value = jsonStr},
                }},
                { url = "https://0x0.st", mode = "text", fields = {
                    {name = "file", filename = fname, ctype = "application/json", value = jsonStr},
                }},
                { url = "https://litterbox.catbox.moe/resources/internals/api.php", mode = "text", fields = {
                    {name = "reqtype", value = "fileupload"},
                    {name = "time", value = "72h"},
                    {name = "fileToUpload", filename = fname, ctype = "application/json", value = jsonStr},
                }},
                { url = "https://tmpfiles.org/api/v1/upload", mode = "json", fields = {
                    {name = "file", filename = fname, ctype = "application/json", value = jsonStr},
                }},
            }
            local lastErr = "?"
            for _, host in ipairs(hosts) do
                local body, boundary = multipartBody(host.fields)
                local res = httpReq({
                    Url = host.url,
                    Method = "POST",
                    Body = body,
                    Headers = {
                        ["Content-Type"] = "multipart/form-data; boundary=" .. boundary,
                        ["User-Agent"] = "FaceLess-Config/1.0 (Roblox)",
                    },
                })
                if res and type(res.Body) == "string" and type(res.StatusCode) == "number"
                    and res.StatusCode >= 200 and res.StatusCode < 300 then
                    local url
                    if host.mode == "json" then
                        local okj, parsed = pcall(function() return HttpService:JSONDecode(res.Body) end)
                        if okj and type(parsed) == "table" and type(parsed.data) == "table" and parsed.data.url then
                            url = string.gsub(parsed.data.url, "tmpfiles.org/", "tmpfiles.org/dl/", 1)
                        end
                    else
                        url = string.match(res.Body, "(https?://%S+)")
                    end
                    if url and #url > 12 then
                        table.insert(ConfigCloud.index, 1, {name = name, url = url, at = os.time()})
                        while #ConfigCloud.index > 30 do table.remove(ConfigCloud.index) end
                        ConfigCloud.SaveIndex()
                        onDone(url, nil)
                        return
                    end
                    lastErr = "хост ответил без ссылки"
                else
                    lastErr = (res and ("HTTP " .. tostring(res.StatusCode))) or lastErr
                end
            end
            onDone(nil, lastErr)
        end)
    end

    function ConfigCloud.Fetch(urlOrCode, onDone)
        task.spawn(function()
            local s = string.gsub(urlOrCode or "", "^%s*(.-)%s*$", "%1")
            if s == "" then onDone(nil, "пустая строка"); return end
            local jsonStr, err
            if string.find(s, "^https?://") then
                local url = s
                if string.find(url, "tmpfiles.org/", 1, true) and not string.find(url, "tmpfiles.org/dl/", 1, true) then
                    url = string.gsub(url, "tmpfiles.org/", "tmpfiles.org/dl/", 1)
                end
                jsonStr = httpGet(url)
                if not jsonStr then err = "не удалось скачать ссылку" end
            else
                jsonStr = ConfigCloud.DecodeShare(s)
                if not jsonStr then err = "код FLCFG1 повреждён" end
            end
            if not jsonStr then onDone(nil, err); return end
            local ok, data = pcall(function() return HttpService:JSONDecode(jsonStr) end)
            if not ok or type(data) ~= "table" then
                onDone(nil, "файл не похож на конфиг")
                return
            end
            onDone(data, nil)
        end)
    end

    ConfigCloud.LoadIndex()
end

-- ===================== CONFIGS =====================
-- Конфиги — страница "Configs" внутри главного меню (категория MISC), отдельной панели больше нет.
-- Окно настроек (ПКМ) раскладывается по свободному месту слева/справа от меню (layoutSidePanels ниже).
-- Весь модуль живёт внутри функции, чтобы не занимать локальные регистры главного чанка.
ConfigUI = {selected = "Default", flashToken = 0, cloudView = false}

-- Раскладка окна настроек: справа от меню, если там есть место, иначе слева; если обе стороны тесны,
-- окно прижимается к краю экрана.
function layoutSidePanels()
    if not Main or not Main.Visible then return end
    local win = activeSettingsWindow
    local order = {}
    if win and win.Parent then order[#order + 1] = win end
    if #order == 0 then return end

    local cam = workspace.CurrentCamera
    local vp = cam and cam.ViewportSize or Vector2.new(1920, 1080)
    -- начало координат ScreenGui на экране (учитывает верхнюю панель Roblox, если она есть)
    local ox, oy = 0, 0
    local probe = ConfigUI.probe
    if probe and probe.Parent then ox, oy = probe.AbsolutePosition.X, probe.AbsolutePosition.Y end
    local bw, bh = vp.X - ox, vp.Y - oy
    local mx, my = Main.AbsolutePosition.X - ox, Main.AbsolutePosition.Y - oy
    local mw, mh = Main.AbsoluteSize.X, Main.AbsoluteSize.Y
    local GAP, EDGE = 12, 6
    local M = GAP - 0.5
    local placed = {{mx, my, mw, mh}}   -- [1] = само меню, дальше уже расставленные панели

    local function hit(x, y, w, h, from)
        for i = from, #placed do
            local r = placed[i]
            if x < r[1] + r[3] + M and x + w + M > r[1] and y < r[2] + r[4] + M and y + h + M > r[2] then
                return true
            end
        end
        return false
    end
    local function inside(x, y, w, h)
        return x >= EDGE and y >= EDGE and x + w <= bw - EDGE and y + h <= bh - EDGE
    end

    for _, p in ipairs(order) do
        local baseW = p:GetAttribute("BaseWidth") or p.Size.X.Offset
        local minW = p:GetAttribute("MinWidth") or baseW      -- панель конфигов умеет сужаться на маленьких экранах
        local h = p.Size.Y.Offset
        local y0 = math.clamp(my, EDGE, math.max(EDGE, bh - h - EDGE))

        local function search(w)
            local rightX, leftX = mx + mw + GAP, mx - GAP - w
            local cands = {{rightX, y0}, {leftX, y0}}
            for i = 2, #placed do
                local r = placed[i]
                cands[#cands + 1] = {r[1] + r[3] + GAP, y0}   -- правее соседней панели
                cands[#cands + 1] = {r[1] - GAP - w, y0}      -- левее соседней панели
            end
            for i = 2, #placed do
                local r = placed[i]
                cands[#cands + 1] = {r[1], r[2] + r[4] + GAP} -- под соседней панелью
                cands[#cands + 1] = {r[1], r[2] - GAP - h}    -- над соседней панелью
            end
            for _, c in ipairs(cands) do
                if inside(c[1], c[2], w, h) and not hit(c[1], c[2], w, h, 1) then return c[1], c[2] end
            end
            return nil
        end

        local w = baseW
        local px, py = search(w)
        if not px and minW < baseW then
            local free = math.max(mx - GAP - EDGE, bw - (mx + mw + GAP) - EDGE)
            w = math.clamp(math.floor(free), minW, baseW)
            px, py = search(w)
        end
        if not px then
            -- на экране совсем тесно: прижимаем к краю (меню может быть слегка перекрыто, но панели друг друга - нет)
            local maxX = math.max(EDGE, bw - w - EDGE)
            local fb = {{math.clamp(mx + mw + GAP, EDGE, maxX), y0}, {math.clamp(mx - GAP - w, EDGE, maxX), y0}}
            px, py = fb[1][1], fb[1][2]
            for _, c in ipairs(fb) do
                if not hit(c[1], c[2], w, h, 2) then px, py = c[1], c[2]; break end
            end
        end
        if p.Size.X.Offset ~= w then p.Size = UDim2.new(0, w, 0, h) end
        p.Position = UDim2.new(0, math.floor(px + 0.5), 0, math.floor(py + 0.5))
        placed[#placed + 1] = {px, py, w, h}
    end
end

do
    local function initConfigs()
        local K = ConfigUI
        local HttpService = game:GetService("HttpService")
        local CONFIG_DIR = "SatanicUI"
        local RED = Color3.fromRGB(255, 110, 110)
        local DEL = Color3.fromRGB(105, 35, 45)
        local PALETTE = {
            Color3.fromRGB(255, 35, 118), Color3.fromRGB(255, 35, 90),
            Color3.fromRGB(37, 255, 204), Color3.fromRGB(0, 240, 166),
            Color3.fromRGB(130, 66, 255), Color3.fromRGB(77, 170, 255),
        }
        local PW, PH = 592, 403
        local ROW_H = 54

        local function cfgPath(name)
            return CONFIG_DIR .. "/" .. string.gsub(name, "[^%w_%-]", "_") .. ".json"
        end

        -- Keep the compact legacy fields for older configs, plus a complete registry snapshot.
        local function snapshot()
            local wingState = Theme.WingsState
            local skyboxSnapshot = Theme.CustomSkyBoxState and Theme.CustomSkyBoxState.Export and Theme.CustomSkyBoxState.Export() or nil
            return {
                version = 5,
                controls = Theme.ConfigRegistry:Capture(),
                theme = Theme.Runtime and Theme.Runtime.GetName and Theme.Runtime.GetName() or "Halloween",
                watermark={x=wmBaseX,y=wmBaseY,fps=wmShowFPS,ping=wmShowPing,clock=wmShowClock,signal=wmShowSignal,
                    bg={wmBackgroundColor.R,wmBackgroundColor.G,wmBackgroundColor.B},
                    outline={wmOutlineColor.R,wmOutlineColor.G,wmOutlineColor.B},outlineTransparency=wmOutlineTransparency,outlineThickness=wmOutlineThickness},
                fog={enabled=fogEnabled,distance=currentFogDensity,strength=currentFogStrength,color={rFog,gFog,bFog}},
                weather={enabled=WeatherState.enabled,mode=WeatherState.mode},
                skybox=skyboxSnapshot,
                featureState={
                    skybox=skyboxSnapshot,
                    chamsMode=chamsMode, chamsColor={chamsColor.R,chamsColor.G,chamsColor.B},
                    chamsIntensity=chamsIntensity, chamsFillTrans=chamsFillTrans, chamsOutlineTrans=chamsOutlineTrans,
                    customHatEnabled=customHatEnabled,
                    hatMode=hatMode, hatSizeX=hatSizeX, hatSizeY=hatSizeY, hatSizeZ=hatSizeZ,
                    hatHornYOffset=hatBuilders.HornYOffset, hatHatYOffset=hatBuilders.HatYOffset,
                    hatHaloYOffset=hatBuilders.HaloYOffset, hatHaloSpin=hatBuilders.HaloSpin,
                    hatColor={hatR,hatG,hatB}, hatGlow=hatGlow,
                    wings=wingState and {
                        enabled=wingState.on, style=wingState.style, size=wingState.size, profiles=wingState.ExportProfiles(),
                        prismReference=wingState.prismReference,prismTheme=wingState.prismTheme,prismBrightness=wingState.prismBrightness,
                        prismX=wingState.prismX,prismY=wingState.prismY,prismZ=wingState.prismZ,
                        speed=wingState.speed, flap=wingState.flap, spread=wingState.spread,
                        transparency=wingState.trans, glow=wingState.glow,
                        color={wingState.color.R * 255, wingState.color.G * 255, wingState.color.B * 255},
                    } or nil,
                    weatherIntensity=WeatherState.weatherIntensity, weatherWindScale=WeatherState.weatherWindScale,
                    weatherLightningFrequency=WeatherState.weatherLightningFrequency, weatherLightningBrightness=WeatherState.weatherLightningBrightness,
                    weatherAudioEnabled=WeatherState.weatherAudioEnabled, weatherAudioVolume=WeatherState.weatherAudioVolume,
                    arrowsEnabled=arrowsEnabled, arrowRadius=arrowRadius, arrowTransparency=arrowTransparency, arrowGlow=arrowGlow,
                    arrowColor={arrowColor.R,arrowColor.G,arrowColor.B},
                    korbloxEnabled=korbloxEnabled, headlessEnabled=headlessEnabled,
                },
                cleanup=cleanupOptions
            }
        end
        local function applyCfg(c)
            if type(c) ~= "table" then return end
            local registry = Theme.ConfigRegistry
            registry.applying = true
            local appliedControlCount = 0
            local hasSerializedControls = false
            if type(c.controls) == "table" then
                for key in pairs(c.controls) do
                    if key ~= "__pendingLabels" and key ~= "__controlList" then
                        hasSerializedControls = true
                        break
                    end
                end
                if not hasSerializedControls and type(c.controls.__controlList) == "table" then
                    hasSerializedControls = #c.controls.__controlList > 0
                end
            end
            local function applyLegacyControl(label, value, scope, occurrence)
                -- If the modern controls section has this exact control, let the generic
                -- pass apply it once. Otherwise update a live control or queue the legacy value.
                if registry:HasControlValue(c.controls, label, scope, occurrence) then return true end
                return registry:ApplyLabel(label, value, scope, occurrence)
            end
            local ok, err = pcall(function()
                -- Restore button-selected modes and control values that used to be lost because
                -- those modes are not ordinary toggle/slider widgets.
                local f = c.featureState
                if type(f) == "table" then
                    if f.chamsMode == "Fill" or f.chamsMode == "Outline" then chamsMode = f.chamsMode end
                    if type(f.chamsColor) == "table" then chamsColor = Color3.new(tonumber(f.chamsColor[1]) or 1, tonumber(f.chamsColor[2]) or 0.2, tonumber(f.chamsColor[3]) or 0.2) end
                    do
                        local value = tonumber(f.chamsIntensity)
                        if value then chamsIntensity = math.clamp(f.chamsIntensity, 0, 1) end
                    end
                    do
                        local value = tonumber(f.chamsFillTrans)
                        if value then chamsFillTrans = math.clamp(f.chamsFillTrans, 0, 1) end
                    end
                    do
                        local value = tonumber(f.chamsOutlineTrans)
                        if value then chamsOutlineTrans = math.clamp(f.chamsOutlineTrans, 0, 1) end
                    end
                    if type(f.hatMode) == "string" then
                        for i, mode in ipairs(modesList) do if mode == f.hatMode then hatMode = mode; modeIndex = i; break end end
                    end
                    do
                        local value = tonumber(f.hatSizeX)
                        if value then hatSizeX = math.clamp(f.hatSizeX, 1, 10) end
                    end
                    do
                        local value = tonumber(f.hatSizeY)
                        if value then hatSizeY = math.clamp(f.hatSizeY, 1, 10) end
                    end
                    do
                        local value = tonumber(f.hatSizeZ)
                        if value then hatSizeZ = math.clamp(f.hatSizeZ, 1, 10) end
                    end
                    do
                        local value = tonumber(f.hatHornYOffset)
                        if value then hatBuilders.HornYOffset = math.clamp(value, -0.5, 2.0) end
                    end
                    do
                        local value = tonumber(f.hatHatYOffset)
                        if value then hatBuilders.HatYOffset = math.clamp(value, -0.5, 2.0) end
                    end
                    do
                        local value = tonumber(f.hatHaloYOffset)
                        if value then hatBuilders.HaloYOffset = math.clamp(value, -0.5, 2.0) end
                    end
                    do
                        local value = tonumber(f.hatHaloSpin)
                        if value then hatBuilders.HaloSpin = math.clamp(value, 0, 2) end
                    end
                    if type(f.hatColor) == "table" then hatR = math.clamp(tonumber(f.hatColor[1]) or hatR,0,255); hatG = math.clamp(tonumber(f.hatColor[2]) or hatG,0,255); hatB = math.clamp(tonumber(f.hatColor[3]) or hatB,0,255) end
                    if type(f.hatGlow) == "boolean" then hatGlow = f.hatGlow end
                    if type(f.customHatEnabled) == "boolean" then customHatEnabled = f.customHatEnabled end
                    if type(f.wings) == "table" and Theme.WingsState and Theme.WingsState.LoadConfigValues then
                        Theme.WingsState.LoadConfigValues(f.wings)
                    end
                    do
                        local value = tonumber(f.weatherIntensity)
                        if value then WeatherState.weatherIntensity = math.clamp(value,0.5,2) end
                    end
                    do
                        local value = tonumber(f.weatherWindScale)
                        if value then WeatherState.weatherWindScale = math.clamp(value,0.25,2) end
                    end
                    do
                        local value = tonumber(f.weatherLightningFrequency)
                        if value then WeatherState.weatherLightningFrequency = math.clamp(value,0.5,2) end
                    end
                    do
                        local value = tonumber(f.weatherLightningBrightness)
                        if value then WeatherState.weatherLightningBrightness = math.clamp(value,2,10) end
                    end
                    if type(f.weatherAudioEnabled) == "boolean" then WeatherState.weatherAudioEnabled = f.weatherAudioEnabled end
                    do
                        local value = tonumber(f.weatherAudioVolume)
                        if value then WeatherState.weatherAudioVolume = math.clamp(value,0,1) end
                    end
                    if tonumber(f.weatherIntensity) then applyLegacyControl("Effect density", WeatherState.weatherIntensity, "Settings/Enable Weather") end
                    if tonumber(f.weatherWindScale) then applyLegacyControl("Wind strength", WeatherState.weatherWindScale, "Settings/Enable Weather") end
                    if tonumber(f.weatherLightningFrequency) then applyLegacyControl("Lightning frequency", WeatherState.weatherLightningFrequency, "Settings/Enable Weather") end
                    if tonumber(f.weatherLightningBrightness) then applyLegacyControl("Lightning brightness", WeatherState.weatherLightningBrightness, "Settings/Enable Weather") end
                    if type(f.weatherAudioEnabled) == "boolean" then applyLegacyControl("Weather sound", WeatherState.weatherAudioEnabled, "Settings/Enable Weather") end
                    if tonumber(f.weatherAudioVolume) then applyLegacyControl("Weather volume", WeatherState.weatherAudioVolume, "Settings/Enable Weather") end
                    if type(f.arrowsEnabled) == "boolean" then arrowsEnabled = f.arrowsEnabled end
                    do
                        local value = tonumber(f.arrowRadius)
                        if value then arrowRadius = math.clamp(f.arrowRadius,50,300) end
                    end
                    do
                        local value = tonumber(f.arrowTransparency)
                        if value then arrowTransparency = math.clamp(f.arrowTransparency,0.1,1) end
                    end
                    if type(f.arrowGlow) == "boolean" then arrowGlow = f.arrowGlow end
                    if type(f.arrowColor) == "table" then arrowColor = Color3.new(tonumber(f.arrowColor[1]) or 1, tonumber(f.arrowColor[2]) or 0.3, tonumber(f.arrowColor[3]) or 0.3) end
                    if type(f.korbloxEnabled) == "boolean" then korbloxEnabled = f.korbloxEnabled end
                    if type(f.headlessEnabled) == "boolean" then headlessEnabled = f.headlessEnabled end
                end
                -- Theme is applied first so the remaining controls render with its colors.
                if type(c.theme) == "string" and Theme.Runtime and Theme.Runtime.Apply then
                    pcall(Theme.Runtime.Apply, LegacyNames[c.theme] or c.theme)
                end
                if c.watermark then
                    local w=c.watermark
                    wmBaseX=w.x or wmBaseX; wmBaseY=w.y or wmBaseY
                    wmShowFPS=w.fps ~= false; wmShowPing=w.ping ~= false; wmShowClock=w.clock ~= false; wmShowSignal=w.signal ~= false
                    if w.bg then wmBackgroundColor=Color3.new(w.bg[1],w.bg[2],w.bg[3]) end
                    if w.outline then wmOutlineColor=Color3.new(w.outline[1],w.outline[2],w.outline[3]) end
                    wmOutlineTransparency=w.outlineTransparency ~= nil and w.outlineTransparency or wmOutlineTransparency
                    wmOutlineThickness=w.outlineThickness ~= nil and w.outlineThickness or wmOutlineThickness
                    Watermark.Position=UDim2.new(0,wmBaseX,0,wmBaseY); wmRefresh()
                    applyLegacyControl("Show FPS", wmShowFPS, "Settings/Watermark")
                    applyLegacyControl("Show Ping", wmShowPing, "Settings/Watermark")
                    applyLegacyControl("Show Clock", wmShowClock, "Settings/Watermark")
                    applyLegacyControl("Show Signal Icon", wmShowSignal, "Settings/Watermark")
                    local bh, bs, bv = wmBackgroundColor:ToHSV()
                    local oh, osat, ov = wmOutlineColor:ToHSV()
                    applyLegacyControl("Color Picker", {bh, bs, bv}, "Settings/Watermark", 1)
                    applyLegacyControl("Color Picker", {oh, osat, ov}, "Settings/Watermark", 2)
                    applyLegacyControl("Outline Thickness", wmOutlineThickness, "Settings/Watermark")
                    applyLegacyControl("Outline Transparency", math.floor(wmOutlineTransparency * 100 + 0.5), "Settings/Watermark")
                end
                if c.fog then
                    fogEnabled=c.fog.enabled == true
                    currentFogDensity=tonumber(c.fog.distance) or currentFogDensity
                    currentFogStrength=tonumber(c.fog.strength) or currentFogStrength
                    if c.fog.color then
                        rFog = tonumber(c.fog.color[1]) or rFog
                        gFog = tonumber(c.fog.color[2]) or gFog
                        bFog = tonumber(c.fog.color[3]) or bFog
                    end
                    local fogToggleHandled = applyLegacyControl("Enable Minecraft Fog", fogEnabled, "Visuals/Right/Minecraft Fog")
                    applyLegacyControl("Fog Distance", currentFogDensity, "Settings/Enable Minecraft Fog")
                    applyLegacyControl("Fog Density", math.floor(currentFogStrength * 100 + 0.5), "Settings/Enable Minecraft Fog")
                    local fh, fs, fv = Color3.fromRGB(rFog,gFog,bFog):ToHSV()
                    applyLegacyControl("Color Picker", {fh, fs, fv}, "Settings/Enable Minecraft Fog")
                    if not fogToggleHandled then
                        if fogEnabled then applyFog() elseif fogBackup then restoreFog() end
                    end
                end
                if c.weather then
                    WeatherState.enabled=c.weather.enabled == true
                    for i,m in ipairs(WeatherState.modes) do if m==(LegacyNames[c.weather.mode] or c.weather.mode) then WeatherState.index=i; WeatherState.mode=m end end
                    if WeatherState.button then WeatherState.button.Text="Weather: "..WeatherState.mode end
                    local weatherToggleHandled = applyLegacyControl("Enable Weather", WeatherState.enabled, "Visuals/Left/Weather")
                    if not weatherToggleHandled then WeatherState.apply() end
                end
                if c.cleanup then
                    for k in pairs(cleanupOptions) do if c.cleanup[k] ~= nil then cleanupOptions[k]=c.cleanup[k] end end
                    applyLegacyControl("Reduce particles", cleanupOptions.particles, "Settings/Apply selected changes")
                    applyLegacyControl("Trees + foliage", cleanupOptions.trees, "Settings/Apply selected changes")
                    applyLegacyControl("Mountains / rocks", cleanupOptions.mountains, "Settings/Apply selected changes")
                    applyLegacyControl("Destruction visuals", cleanupOptions.destruction, "Settings/Apply selected changes")
                    applyLegacyControl("Grass", cleanupOptions.grass, "Settings/Apply selected changes")
                    applyLegacyControl("Trash / bins", cleanupOptions.trash, "Settings/Apply selected changes")
                    applyLegacyControl("Ash / dust particles", cleanupOptions.ashes, "Settings/Apply selected changes")
                    applyTSBCleanup()
                end
            end)
            if not ok then warn("[Satanic Config] legacy apply warning: " .. tostring(err)) end
            if type(c.controls) == "table" then
                local controlsOk, countOrErr = pcall(function() return registry:Apply(c.controls) end)
                if controlsOk then
                    appliedControlCount = tonumber(countOrErr) or 0
                else
                    warn("[Satanic Config] controls apply failed: " .. tostring(countOrErr))
                end
            end

            -- The explicit feature block is authoritative for accessory sizes/colors. Restore it
            -- after generic controls so stale values from an older temporary settings window
            -- cannot override China hat or wing parameters. ApplyLabel also queues values for
            -- settings windows that have not been opened yet.
            local featureData = type(c.featureState) == "table" and c.featureState or nil
            if featureData then
                if type(featureData.hatMode) == "string" then
                    for i, mode in ipairs(modesList) do
                        if mode == featureData.hatMode then hatMode = mode; modeIndex = i; break end
                    end
                end
                do
                    local value = tonumber(featureData.hatSizeX)
                    if value then hatSizeX = math.clamp(value, 1, 10) end
                end
                do
                    local value = tonumber(featureData.hatSizeY)
                    if value then hatSizeY = math.clamp(value, 1, 10) end
                end
                do
                    local value = tonumber(featureData.hatSizeZ)
                    if value then hatSizeZ = math.clamp(value, 1, 10) end
                end
                do
                    local value = tonumber(featureData.hatHornYOffset)
                    if value then hatBuilders.HornYOffset = math.clamp(value, -0.5, 2.0) end
                end
                do
                    local value = tonumber(featureData.hatHatYOffset)
                    if value then hatBuilders.HatYOffset = math.clamp(value, -0.5, 2.0) end
                end
                do
                    local value = tonumber(featureData.hatHaloYOffset)
                    if value then hatBuilders.HaloYOffset = math.clamp(value, -0.5, 2.0) end
                end
                do
                    local value = tonumber(featureData.hatHaloSpin)
                    if value then hatBuilders.HaloSpin = math.clamp(value, 0, 2) end
                end
                if type(featureData.hatColor) == "table" then
                    hatR = math.clamp(tonumber(featureData.hatColor[1]) or hatR, 0, 255)
                    hatG = math.clamp(tonumber(featureData.hatColor[2]) or hatG, 0, 255)
                    hatB = math.clamp(tonumber(featureData.hatColor[3]) or hatB, 0, 255)
                end
                if type(featureData.hatGlow) == "boolean" then hatGlow = featureData.hatGlow end
                if type(featureData.customHatEnabled) == "boolean" then customHatEnabled = featureData.customHatEnabled end
                registry:ApplyLabel("Enable Hat / Effect", customHatEnabled, "Visuals/Left/Custom Hats & Effects")

                local hatHue, hatSat, hatVal = Color3.fromRGB(hatR, hatG, hatB):ToHSV()
                for _, scope in ipairs({"Settings/Mode: China hat", "Settings/Enable Hat / Effect"}) do
                    registry:ApplyLabel("Size X (width)", hatSizeX, scope)
                    registry:ApplyLabel("Size Y (height)", hatSizeY, scope)
                    registry:ApplyLabel("Size Z (depth)", hatSizeZ, scope)
                    registry:ApplyLabel("Horn Height Offset", hatBuilders.HornYOffset, scope)
                    registry:ApplyLabel("Hat Height Offset", hatBuilders.HatYOffset, scope)
                    registry:ApplyLabel("Halo Height Offset", hatBuilders.HaloYOffset, scope)
                    registry:ApplyLabel("Halo Spin Speed", hatBuilders.HaloSpin, scope)
                    registry:ApplyLabel("Color Picker", {hatHue, hatSat, hatVal}, scope, 1)
                    registry:ApplyLabel("Glow (neon + bloom)", hatGlow, scope)
                end

                if type(featureData.wings) == "table" and Theme.WingsState and Theme.WingsState.LoadConfigValues then
                    Theme.WingsState.LoadConfigValues(featureData.wings)
                end
            end

            local skyboxData = type(c.skybox) == "table" and c.skybox or (featureData and featureData.skybox)
            if type(skyboxData) == "table" and Theme.CustomSkyBoxState and Theme.CustomSkyBoxState.Import then
                pcall(Theme.CustomSkyBoxState.Import, skyboxData)
            end

            local wingState = Theme.WingsState
            if wingState then
                local wingColor = wingState.color
                local wh, ws, wv = wingColor:ToHSV()
                registry:ApplyLabel("Size", wingState.size, "Settings/Enable Wings")
                registry:ApplyLabel("Flap speed", wingState.speed, "Settings/Enable Wings")
                registry:ApplyLabel("Flap amplitude (°)", wingState.flap, "Settings/Enable Wings")
                registry:ApplyLabel("Spread back (°)", wingState.spread, "Settings/Enable Wings")
                registry:ApplyLabel("Transparency", wingState.trans, "Settings/Enable Wings")
                registry:ApplyLabel("Color Picker", {wh, ws, wv}, "Settings/Enable Wings", 1)
                registry:ApplyLabel("Glow (neon)", wingState.glow, "Settings/Enable Wings")
                if wingState.SyncConfigControls then pcall(wingState.SyncConfigControls) end
            end
            registry.applying = false
            if chamsModeBtn then chamsModeBtn.Text = "Mode: " .. chamsMode end
            if hatModeBtn then hatModeBtn.Text = "Mode: " .. hatMode end
            if Theme.Trails and Theme.Trails.Apply then pcall(Theme.Trails.Apply) end
            if customHatEnabled then pcall(updateHat) else pcall(clearHat) end
            if Theme.WingsState and Theme.WingsState.FinalizeConfig then
                pcall(Theme.WingsState.FinalizeConfig)
            end
            if WeatherState.enabled then pcall(WeatherState.apply) end
            if fogEnabled then pcall(applyFog) elseif fogBackup then pcall(restoreFog) end
            if Theme.CustomSkyBoxState and Theme.CustomSkyBoxState.FinalizeConfig then
                pcall(Theme.CustomSkyBoxState.FinalizeConfig)
            end
            pcall(applyKorblox)
            pcall(applyHeadless)
            if registry.cleanupPending then
                registry.cleanupPending = false
                task.defer(applyTSBCleanup)
            end
            return appliedControlCount, hasSerializedControls
        end

        local function tween(obj, t, props)
            TweenService:Create(obj, TweenInfo.new(t, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), props):Play()
        end

        -- нижняя строка панели: подсказка под курсором / результат действия / выбранный конфиг
        local function renderStatus()
            local s = K.status
            if not s then return end
            if K.flash then
                s.Text = K.flash; s.TextColor3 = K.flashColor or Theme.BloodGlow
            elseif K.hint then
                s.Text = K.hint; s.TextColor3 = Theme.TextDark
            else
                s.Text = "Selected: " .. K.selected; s.TextColor3 = Theme.TextDark
            end
        end
        K.setHint = function(t) K.hint = t; renderStatus() end
        local function flash(text, color)
            K.flashToken = K.flashToken + 1
            local my = K.flashToken
            K.flash = text; K.flashColor = color
            renderStatus()
            task.delay(2.6, function()
                if K.flashToken == my then K.flash = nil; renderStatus() end
            end)
        end

        local function mkButton(parent, text, w, h, callback, base, hintText, textSize, zi)
            local normal = base or Theme.Element
            local over = base and base:Lerp(Color3.new(1, 1, 1), 0.2) or Theme.ElementHover
            local b = Instance.new("TextButton")
            b.Size = UDim2.new(0, w, 0, h)
            b.BackgroundColor3 = normal
            b.BorderSizePixel = 0
            b.AutoButtonColor = false
            b.Text = text
            b.Font = Enum.Font.GothamBold
            b.TextSize = textSize or 14
            b.TextColor3 = Theme.Text
            b.ZIndex = zi or 201
            b.Parent = parent
            Instance.new("UICorner", b).CornerRadius = UDim.new(0, 8)
            local st = Instance.new("UIStroke", b)
            st.Color = Theme.Stroke; st.Thickness = 1
            b.MouseEnter:Connect(function()
                tween(b, 0.12, {BackgroundColor3 = over})
                if hintText then K.setHint(hintText) end
            end)
            b.MouseLeave:Connect(function()
                tween(b, 0.12, {BackgroundColor3 = normal})
                if hintText then K.setHint(nil) end
            end)
            b.MouseButton1Click:Connect(function() if callback then callback(b) end end)
            return b
        end

        local function readConfig(name)
            local ok, data = pcall(function() return HttpService:JSONDecode(readfile(cfgPath(name))) end)
            if ok and type(data) == "table" then return data end
            return nil
        end
        local function listNames()
            local names = {}
            if isfolder and listfiles then
                pcall(function()
                    if not isfolder(CONFIG_DIR) then makefolder(CONFIG_DIR) end
                    for _, file in ipairs(listfiles(CONFIG_DIR)) do
                        local normalized = string.gsub(file, "\\", "/")
                        local name = string.match(normalized, "([^/]+)%.json$")
                        if name then table.insert(names, name) end
                    end
                end)
            end
            table.sort(names)
            return names
        end
        -- вторая строка карточки: что включено внутри конфига
        local function summarize(data)
            if not data then return "Unreadable file" end
            local parts = {}
            if data.fog and data.fog.enabled then parts[#parts + 1] = "Fog" end
            if data.weather and data.weather.enabled then parts[#parts + 1] = tostring(data.weather.mode or "Weather") end
            if type(data.cleanup) == "table" then
                local n = 0
                for _, v in pairs(data.cleanup) do if v == true then n = n + 1 end end
                if n > 0 then parts[#parts + 1] = "Cleanup " .. n end
            end
            if #parts == 0 then return "Watermark and base settings" end
            return table.concat(parts, "  •  ")
        end

