        -- ---------- действия ----------
        local refresh

        local function loadConfig(name)
            K.selected = name
            local data = readConfig(name)
            if not data then
                flash("Could not read «" .. name .. "»", RED)
                refresh()
                return
            end
            local appliedCount, hasControlData = applyCfg(data)
            -- Older configs stored a single custom accent but did not store a theme.
            -- Modern configs must keep the selected theme coherent across all windows.
            if data.theme == nil and type(data.__color) == "table" then
                local ok, c = pcall(Color3.new, tonumber(data.__color[1]) or 1, tonumber(data.__color[2]) or 0.55, tonumber(data.__color[3]) or 0)
                if ok and c then
                    Theme.BloodRed = c
                    mainStroke.Color = c
            borderGlow.Color = c
                end
            end
            if not hasControlData then
                flash("Loaded: " .. name .. " — old format, feature states were not saved. Set up your features and re-save the config.", Color3.fromRGB(255, 175, 90))
            elseif appliedCount <= 0 then
                flash("Config read, but no controls matched; see console", RED)
                warn("[Satanic Config] No controls applied. Saved schema/version may not match this script.")
            else
                flash("Loaded: " .. name .. " · values: " .. tostring(appliedCount))
            end
            refresh()
        end

        local function saveCurrent(name, color)
            local existed = false
            pcall(function() existed = isfile(cfgPath(name)) end)
            local ok, saveErr = pcall(function()
                if not isfolder(CONFIG_DIR) then makefolder(CONFIG_DIR) end
                local data = snapshot()
                data.__color = {color.R, color.G, color.B}
                local encoded = HttpService:JSONEncode(data)
                writefile(cfgPath(name), encoded)
            end)
            K.selected = name
            if ok then
                flash((existed and "Updated: " or "Saved: ") .. name)
            else
                warn("[Satanic Config] save failed: " .. tostring(saveErr))
                flash("Config save error — see console", RED)
            end
            refresh()
        end

        local function exportSelected()
            local data = readConfig(K.selected)
            if not data then data = snapshot() end
            data.__color = data.__color or {Theme.BloodRed.R, Theme.BloodRed.G, Theme.BloodRed.B}
            local payload = HttpService:JSONEncode(data)
            local copied = false
            if setclipboard then copied = pcall(setclipboard, payload)
            elseif toclipboard then copied = pcall(toclipboard, payload) end
            if copied then
                flash("Copied to clipboard: " .. K.selected)
            else
                warn("[Satanic UI] Clipboard API unavailable; config JSON: " .. payload)
                flash("Clipboard unavailable, JSON printed to console", RED)
            end
        end

