        local function cloudUpload()
            if ConfigCloud.busy then flash("Облако уже занято запросом", RED); return end
            local data = readConfig(K.selected) or snapshot()
            data.__color = data.__color or {Theme.BloodRed.R, Theme.BloodRed.G, Theme.BloodRed.B}
            local okj, jsonStr = pcall(function() return HttpService:JSONEncode(data) end)
            if not okj then flash("Не удалось собрать конфиг", RED); return end
            local name = K.selected or "Config"
            ConfigCloud.busy = true
            flash("Загружаю «" .. name .. "» в облако...")
            ConfigCloud.Upload(name, jsonStr, function(url, err)
                ConfigCloud.busy = false
                if url then
                    flash("☁ " .. name .. " загружен в облако")
                    showCloudResult(name, url, ConfigCloud.EncodeShare(jsonStr))
                    if refresh then refresh() end
                else
                    warn("[FaceLess] cloud upload: " .. tostring(err))
                    flash("Облако недоступно: " .. tostring(err), RED)
                end
            end)
        end

        local function cloudImport()
            showInputDialog("Импорт конфига", "Вставь код FLCFG1 от друга или ссылку", "", function(raw)
                if ConfigCloud.busy then flash("Облако уже занято запросом", RED); return end
                ConfigCloud.busy = true
                flash("Скачиваю конфиг...")
                ConfigCloud.Fetch(raw, function(data, err)
                    ConfigCloud.busy = false
                    if data then
                        local appliedCount = applyCfg(data)
                        flash("Загружено из облака · значений: " .. tostring(appliedCount or 0))
                        pcall(function() FLLog.info("cloud", "конфиг применён из облака") end)
                        if refresh then refresh() end
                    else
                        warn("[FaceLess] cloud fetch: " .. tostring(err))
                        flash("Не получилось: " .. tostring(err), RED)
                    end
                end)
            end)
        end

        local function cloudShareCode()
            local data = readConfig(K.selected) or snapshot()
            data.__color = data.__color or {Theme.BloodRed.R, Theme.BloodRed.G, Theme.BloodRed.B}
            local okj, jsonStr = pcall(function() return HttpService:JSONEncode(data) end)
            if not okj then flash("Не удалось собрать конфиг", RED); return end
            local code = ConfigCloud.EncodeShare(jsonStr)
            if ConfigCloud.Copy(code) then
                flash("Код FLCFG1 скопирован (" .. tostring(math.floor(#code / 1024)) .. " КБ) — отправь другу")
            else
                showInputDialog("Код конфига", "Выдели код и скопируй его для друга", code, function() end)
            end
        end

