            nameLbl.Position = UDim2.new(0, 24, 0, 8); nameLbl.Size = UDim2.new(1, -160, 0, 18)
            nameLbl.BackgroundTransparency = 1; nameLbl.Text = "☁ " .. tostring(entry.name); nameLbl.Font = Enum.Font.GothamBold
            nameLbl.TextSize = 13; nameLbl.TextColor3 = Theme.Text; nameLbl.TextXAlignment = Enum.TextXAlignment.Left
            nameLbl.TextTruncate = Enum.TextTruncate.AtEnd; nameLbl.ZIndex = 204
            local subLbl = Instance.new("TextLabel", row)
