            subLbl.BackgroundTransparency = 1; subLbl.Text = tostring(entry.url); subLbl.Font = Enum.Font.GothamMedium
            subLbl.TextSize = 10; subLbl.TextColor3 = Theme.TextDark; subLbl.TextXAlignment = Enum.TextXAlignment.Left
            subLbl.TextTruncate = Enum.TextTruncate.AtEnd; subLbl.ZIndex = 204
            local loadBtn = mkButton(row, "LOAD", 44, 28, function()
                if ConfigCloud.busy then flash("Облако уже занято запросом", RED); return end
                ConfigCloud.busy = true
                flash("Скачиваю «" .. tostring(entry.name) .. "»...")
                ConfigCloud.Fetch(entry.url, function(data, err)
                    ConfigCloud.busy = false
                    if data then
                        local appliedCount = applyCfg(data)
                        flash("Загружено из облака · значений: " .. tostring(appliedCount or 0))
                        if refresh then refresh() end
                    else
                        flash("Не получилось: " .. tostring(err), RED)
                    end
                end)
            end, Theme.BloodDark, "Скачать и применить этот облачный конфиг", 12, 205)
            loadBtn.Position = UDim2.new(1, -128, 0.5, -14)
            local copyBtn = mkButton(row, "COPY", 44, 28, function()
                if ConfigCloud.Copy(entry.url) then flash("Ссылка скопирована") else flash("Буфер обмена недоступен", RED) end
            end, nil, "Скопировать ссылку для друга", 12, 205)
            copyBtn.Position = UDim2.new(1, -78, 0.5, -14)
            local armed = false
            local delBtn
            delBtn = mkButton(row, "×", 28, 28, function()
                if not armed then
                    armed = true
                    delBtn.Text = "?"
                    tween(delBtn, 0.12, {BackgroundColor3 = Color3.fromRGB(200, 45, 60)})
                    flash("Нажми ещё раз, чтобы убрать из списка", RED)
                    task.delay(2.2, function()
                        if delBtn and delBtn.Parent then
                            armed = false
                            delBtn.Text = "×"
                            tween(delBtn, 0.12, {BackgroundColor3 = DEL})
                        end
                    end)
                    return
                end
                for i, e in ipairs(ConfigCloud.index) do
                    if e == entry then table.remove(ConfigCloud.index, i); break end
