            t2.TextWrapped = true; t2.TextYAlignment = Enum.TextYAlignment.Top; t2.ZIndex = 203
        end

        local function buildRow(list, name, order)
            local data = readConfig(name)
            local selected = (name == K.selected)
            local col = Theme.BloodRed
            if data and type(data.__color) == "table" then
                local ok, c = pcall(Color3.new, tonumber(data.__color[1]) or 1, tonumber(data.__color[2]) or 0.55, tonumber(data.__color[3]) or 0)
                if ok and c then col = c end
            end

            local row = Instance.new("Frame")
            row.Name = "Cfg_" .. name
            row.LayoutOrder = order
            row.Size = UDim2.new(1, -6, 0, ROW_H)
            row.BackgroundColor3 = selected and Theme.Element or Theme.Section
            row.BorderSizePixel = 0
            row.ZIndex = 202
            row.Parent = list
            Instance.new("UICorner", row).CornerRadius = UDim.new(0, 9)
            local rst = Instance.new("UIStroke", row)
            rst.Color = selected and Theme.BloodRed or Theme.Stroke
            rst.Thickness = 1
            rst.Transparency = selected and 0.05 or 0.35

            local bar = Instance.new("Frame", row)
            bar.Position = UDim2.new(0, 9, 0, 10); bar.Size = UDim2.new(0, 4, 1, -20)
            bar.BackgroundColor3 = col; bar.BorderSizePixel = 0; bar.ZIndex = 204
            Instance.new("UICorner", bar).CornerRadius = UDim.new(1, 0)

            -- вся левая часть карточки - кнопка выбора
            local hitBtn = Instance.new("TextButton", row)
            hitBtn.Size = UDim2.new(1, -136, 1, 0); hitBtn.BackgroundTransparency = 1
            hitBtn.Text = ""; hitBtn.AutoButtonColor = false; hitBtn.ZIndex = 203
            local nameLbl = Instance.new("TextLabel", row)
            nameLbl.Position = UDim2.new(0, 24, 0, 8); nameLbl.Size = UDim2.new(1, -160, 0, 18)
            nameLbl.BackgroundTransparency = 1; nameLbl.Text = name; nameLbl.Font = Enum.Font.GothamBold
            nameLbl.TextSize = 13; nameLbl.TextColor3 = Theme.Text; nameLbl.TextXAlignment = Enum.TextXAlignment.Left
            nameLbl.TextTruncate = Enum.TextTruncate.AtEnd; nameLbl.ZIndex = 204
            local subLbl = Instance.new("TextLabel", row)
            subLbl.Position = UDim2.new(0, 24, 0, 28); subLbl.Size = UDim2.new(1, -160, 0, 16)
            subLbl.BackgroundTransparency = 1; subLbl.Text = summarize(data); subLbl.Font = Enum.Font.GothamMedium
            subLbl.TextSize = 10; subLbl.TextColor3 = selected and Theme.BloodGlow or Theme.TextDark
            subLbl.TextXAlignment = Enum.TextXAlignment.Left; subLbl.TextTruncate = Enum.TextTruncate.AtEnd; subLbl.ZIndex = 204

            hitBtn.MouseEnter:Connect(function()
                if name ~= K.selected then tween(row, 0.12, {BackgroundColor3 = Theme.ElementHover}) end
            end)
            hitBtn.MouseLeave:Connect(function()
                if name ~= K.selected then tween(row, 0.12, {BackgroundColor3 = Theme.Section}) end
            end)
            hitBtn.MouseButton1Click:Connect(function()
                K.selected = name
                refresh()
                renderStatus()
            end)

            local loadBtn = mkButton(row, "LOAD", 44, 28, function() loadConfig(name) end, Theme.BloodDark, "Загрузить этот конфиг", 14, 205)
            loadBtn.Position = UDim2.new(1, -128, 0.5, -14)
            local renBtn = mkButton(row, "EDIT", 44, 28, function()
                showDialog("Rename config", "Допустимы a-z, цифры, _ и -", name, function(newName)
                    if newName == name then return end
                    local taken = false
                    pcall(function() taken = isfile(cfgPath(newName)) end)
                    if taken then flash("Name «" .. newName .. "» is already taken", RED); return end
                    local ok = pcall(function()
                        local raw = readfile(cfgPath(name))
                        writefile(cfgPath(newName), raw)
                        if isfile(cfgPath(name)) then delfile(cfgPath(name)) end
                    end)
                    if ok then
                        if K.selected == name then K.selected = newName end
                        flash("Renamed: " .. newName)
                    else
                        flash("Rename failed", RED)
                    end
                    refresh()
                end, false)
            end, nil, "Переименовать", 13, 205)
            renBtn.Position = UDim2.new(1, -78, 0.5, -14)

            -- удаление с подтверждением: первый клик "заряжает" кнопку, второй удаляет
            local armed = false
            local delBtn
            delBtn = mkButton(row, "×", 28, 28, function()
                if not armed then
                    armed = true
                    delBtn.Text = "?"
                    tween(delBtn, 0.12, {BackgroundColor3 = Color3.fromRGB(200, 45, 60)})
                    flash("Click again to delete «" .. name .. "»", RED)
                    task.delay(2.2, function()
                        if delBtn and delBtn.Parent then
                            armed = false
                            delBtn.Text = "×"
                            tween(delBtn, 0.12, {BackgroundColor3 = DEL})
                        end
                    end)
                    return
                end
                pcall(function() if isfile(cfgPath(name)) then delfile(cfgPath(name)) end end)
                if K.selected == name then K.selected = "Default" end
                flash("Deleted: " .. name)
                refresh()
            end, DEL, "Удалить (нажми дважды)", 15, 205)
            delBtn.Position = UDim2.new(1, -36, 0.5, -14)
        end

        refresh = function()
            local list = K.list
            if not list then return end
            for _, child in ipairs(list:GetChildren()) do
                if not child:IsA("UIListLayout") and not child:IsA("UIPadding") then child:Destroy() end
            end
            if K.cloudView then
                local entries = ConfigCloud.index
                if #entries == 0 then
                    buildEmpty(list)
                    list.CanvasSize = UDim2.new(0, 0, 0, 180)
                else
                    for i, entry in ipairs(entries) do buildCloudRow(list, entry, i) end
                    list.CanvasSize = UDim2.new(0, 0, 0, #entries * (ROW_H + 6) + 8)
                end
                if K.count then K.count.Text = "☁ " .. #entries end
            else
                local names = listNames()
                if #names == 0 then
                    buildEmpty(list)
                    list.CanvasSize = UDim2.new(0, 0, 0, 180)
                else
                    for i, name in ipairs(names) do buildRow(list, name, i) end
                    list.CanvasSize = UDim2.new(0, 0, 0, #names * (ROW_H + 6) + 8)
                end
                if K.count then K.count.Text = "Total: " .. #names end
            end
            renderStatus()
            if Theme.Runtime and Theme.Runtime.Rebuild then
                task.defer(function()
                    if Theme.Runtime and Theme.Runtime.Rebuild then pcall(Theme.Runtime.Rebuild) end
                end)
            end
        end
        K.refresh = refresh

        -- ---------- сама панель ----------
        local function build()
            if K.panel then K.panel:Destroy() end
            -- Страница внутри главного меню (MISC → Configs); колонки секций ей не нужны.
            if not K.page then
                -- CONFIGS — самостоятельная категория нижней навигации.
                if not Nav.categories["CONFIGS"] then
                    createCategoryHeader("CONFIGS")
                    Nav.titles.CONFIGS = "CONFIGS"
                    Nav.subtitles.CONFIGS = "Профили настроек"
                end
                Nav.currentCategory = "CONFIGS"
                K.page = createTab("Configs", "", "Configs")
                local leftCol, rightCol = K.page:FindFirstChild("Left"), K.page:FindFirstChild("Right")
                if leftCol then leftCol:Destroy() end
                if rightCol then rightCol:Destroy() end
                -- без колонок прокручивать нечего: убираем полосу прокрутки справа
                K.page.CanvasSize = UDim2.new(0, 0, 0, 0)
                K.page.ScrollBarThickness = 0
                K.page.ScrollingEnabled = false
            end
            local panel = Instance.new("Frame")
