            status.BackgroundTransparency = 1; status.Font = Enum.Font.GothamMedium; status.TextSize = 11
            status.TextColor3 = Theme.TextDark; status.TextXAlignment = Enum.TextXAlignment.Left
            status.TextTruncate = Enum.TextTruncate.AtEnd; status.ZIndex = 201
            K.status = status
            local count = Instance.new("TextLabel", panel)
            count.Position = UDim2.new(1, -96, 1, -34); count.Size = UDim2.new(0, 82, 0, 26)
            count.BackgroundTransparency = 1; count.Font = Enum.Font.GothamBold; count.TextSize = 11
            count.TextColor3 = Theme.BloodRed; count.TextXAlignment = Enum.TextXAlignment.Right; count.ZIndex = 201
            K.count = count

            refresh()
        end

        -- невидимая точка отсчёта: по ней узнаём, где на экране начинается система координат ScreenGui
        local probe = Instance.new("Frame")
        probe.Name = "LayoutProbe"; probe.Size = UDim2.new(0, 0, 0, 0); probe.Position = UDim2.new(0, 0, 0, 0)
        probe.BackgroundTransparency = 1; probe.BorderSizePixel = 0; probe.Parent = ScreenGui
        K.probe = probe

        build()

        -- перераскладка при любом изменении меню / экрана
        track(Main:GetPropertyChangedSignal("AbsolutePosition"):Connect(layoutSidePanels))
        track(Main:GetPropertyChangedSignal("AbsoluteSize"):Connect(layoutSidePanels))
        if Camera then track(Camera:GetPropertyChangedSignal("ViewportSize"):Connect(layoutSidePanels)) end
    end

    local initResult = {pcall(initConfigs)}
    if not initResult[1] then
        warn("[Satanic UI] configs panel error: " .. tostring(initResult[2]))
    end
end

do -- EXTERNAL SCRIPTS: keep this page separate from built-in movement features
    local secScriptsList = createSection(scriptTab.Left, "External Scripts & Hubs")
    secScriptsList:AddButton("Load Revenant Script", function()
        pcall(function()
            loadstring(game:HttpGet("https://raw.githubusercontent.com/skiderman/revenant/main/loader.lua"))()
        end)
    end)
    secScriptsList:AddButton("Load Click TP", function()
        pcall(function()
            loadstring(game:HttpGet("https://cdn.wearedevs.net/scripts/Click%20Teleport.txt"))()
        end)
    end)
end

-- Shared: aimbot reads lagged CF when backtrack visualizer is active.
Theme.GetBacktrackRootCF = function(_player)
    return nil
end

do -- MOVEMENT: Legit / Rage air control and backtrack visuals
  -- Isolated in its own function to avoid exhausting main-chunk local registers (limit 200).
  local function initAirMovementAndBacktrack()
    local airSection = createSection(movementTab.Left, "Air Movement")
    -- Backtrack — «легитный» визуал, поэтому карточка переехала из Rage в Legit.
    -- Скоуп конфига сохранён прежним, чтобы старые сохранения продолжали работать.
    local historySection = createSection(legitTab.Right, "Backtrack Visualizer", "Aimbot/Left/Backtrack Visualizer")

    local movementMode = "Legit"
    local airStrafeEnabled = false
    local airStrafeSpeed = 28
    local backtrackEnabled = false
    local backtrackTimeMs = 250
    local rewindOffsetMs = 150
    local sampleInterval = 0.075
    local historyByPlayer = {}
    local ghostByPlayer = {}
    local historyAccumulator = 0

    local function applyMovementMode(mode)
        movementMode = mode
        if mode == "Rage" then
            sampleInterval = 0.025
        else
            sampleInterval = 0.075
        end
    end

    airSection:AddDropdown("Movement Style", {
        {name = "Legit", color = Color3.fromRGB(50, 220, 255)},
        {name = "Rage", color = Color3.fromRGB(255, 45, 65)},
    }, 1, function(name)
        applyMovementMode(name)
    end)

    airSection:AddToggle("Air Strafe", false, function(state)
        airStrafeEnabled = state
    end)
    airSection:AddSlider("Air Strafe Speed", 10, 100, airStrafeSpeed, function(value)
        airStrafeSpeed = value
    end, 1)

    -- Lightweight character-model backtrack (clone once, CF-only updates, throttled).
    local backtrackRootByPlayer = {}
    local MAX_TRACKED = 8 -- nearest players only
    local ghostUpdateAcc = 0
    local GHOST_UPDATE_HZ = 20 -- visual refresh rate
    local MAX_HISTORY = 24

    Theme.GetBacktrackRootCF = function(player)
        if not backtrackEnabled then return nil end
        return backtrackRootByPlayer[player]
    end

    local function stripGhostScripts(model)
        local removeList = {}
        for _, d in ipairs(model:GetDescendants()) do
            if d:IsA("Script") or d:IsA("LocalScript") or d:IsA("ModuleScript")
                or d:IsA("BillboardGui") or d:IsA("SurfaceGui") or d:IsA("ProximityPrompt")
                or d:IsA("ForceField") or d:IsA("ParticleEmitter") or d:IsA("Trail")
                or d:IsA("Fire") or d:IsA("Smoke") or d:IsA("Sparkles")
                or d:IsA("PointLight") or d:IsA("SpotLight") or d:IsA("SurfaceLight")
                or d:IsA("Sound") or d:IsA("WeldConstraint") or d:IsA("Motor6D")
                or d:IsA("Beam") or d:IsA("Highlight") then
                removeList[#removeList + 1] = d
            end
        end
        for _, d in ipairs(removeList) do
            pcall(function() d:Destroy() end)
        end
        local hum = model:FindFirstChildOfClass("Humanoid")
        if hum then
            hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
            hum.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
            hum.PlatformStand = true
            hum.AutoRotate = false
            pcall(function()
                hum.MaxHealth = 1e9
                hum.Health = 1e9
            end)
        end
        -- Keep only body parts + simple accessory handles; drop heavy MeshParts beyond limit.
        local meshCount = 0
        for _, d in ipairs(model:GetDescendants()) do
            if d:IsA("BasePart") then
                d.Anchored = true
                d.CanCollide = false
                d.Massless = true
                d.CastShadow = false
                d.CanQuery = true
                d.CanTouch = false
                if d:IsA("MeshPart") then
                    meshCount = meshCount + 1
                    if meshCount > 20 then
                        d.Transparency = 1
                        d.CanQuery = false
                    end
                end
            end
        end
    end

    local function applyTintOnce(model, color, transparency)
        for _, d in ipairs(model:GetDescendants()) do
            if d:IsA("BasePart") then
                if d.Name == "HumanoidRootPart" then
                    d.Transparency = 1
                    d.CanQuery = true
                    d.CanCollide = false
                elseif d.Transparency < 1 then
                    d.Color = color
                    d.Material = Enum.Material.ForceField
                    d.Transparency = transparency
                    d.Reflectance = 0
                end
            elseif d:IsA("Decal") or d:IsA("Texture") then
                d.Transparency = math.max(d.Transparency, transparency)
            end
        end
    end

    local function removeGhost(player)
        local ghost = ghostByPlayer[player]
        if ghost then
            pcall(function()
                if ghost.model then ghost.model:Destroy() end
            end)
            ghostByPlayer[player] = nil
        end
        backtrackRootByPlayer[player] = nil
    end

    local function clearHistory()
        for player in pairs(ghostByPlayer) do removeGhost(player) end
        table.clear(historyByPlayer)
        table.clear(backtrackRootByPlayer)
    end

    local function getGhost(player)
        local ghost = ghostByPlayer[player]
        if ghost and ghost.model and ghost.model.Parent then
            return ghost
        end
        removeGhost(player)
        local character = player.Character
        if not character then return nil end
        local ok, clone = pcall(function()
            character.Archivable = true
            local c = character:Clone()
            character.Archivable = false
            return c
        end)
        if not ok or not clone then
            pcall(function() if character then character.Archivable = false end end)
            return nil
        end
        stripGhostScripts(clone)
        clone.Name = "SatanicBacktrackModel_" .. tostring(player.UserId)
        clone.Parent = workspace
        local partMap = {}
        for _, d in ipairs(clone:GetDescendants()) do
            if d:IsA("BasePart") then
                partMap[d.Name] = d
            end
        end
        local tint = movementMode == "Rage" and Color3.fromRGB(255, 40, 70) or Color3.fromRGB(75, 220, 255)
        local transparency = movementMode == "Rage" and 0.3 or 0.5
        applyTintOnce(clone, tint, transparency)
        ghost = {model = clone, parts = partMap, mode = movementMode}
        ghostByPlayer[player] = ghost
        return ghost
    end

    local function applySnapshotToGhost(ghost, snapshot)
        if not ghost or not ghost.model then return end
        local map = ghost.parts
        for i = 1, #snapshot.parts do
            local saved = snapshot.parts[i]
            local part = map[saved.name]
            if part and part.Parent then
                part.CFrame = saved.cf
            end
        end
        if snapshot.cf then
            local root = map.HumanoidRootPart or ghost.model:FindFirstChild("HumanoidRootPart")
            if root then
                root.CFrame = snapshot.cf
            end
        end
    end

    local function nearestPlayers(limit)
        local myRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        local list = {}
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer then
                local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
                local hum = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
                if root and hum and hum.Health > 0 then
                    local dist = myRoot and (root.Position - myRoot.Position).Magnitude or 0
                    list[#list + 1] = {player = player, dist = dist, root = root, hum = hum}
                end
            end
        end
        table.sort(list, function(a, b) return a.dist < b.dist end)
        local out = {}
        for i = 1, math.min(limit, #list) do
            out[i] = list[i]
        end
        return out
    end

    local function updateBacktrack(dt)
        if not backtrackEnabled or Unloaded then
            if next(ghostByPlayer) then
                for player in pairs(ghostByPlayer) do removeGhost(player) end
            end
            return
        end

        -- Sample history less often (always >= 0.08s even in Rage).
        local interval = math.max(sampleInterval, 0.08)
        historyAccumulator = historyAccumulator + dt
        if historyAccumulator >= interval then
            historyAccumulator = historyAccumulator % interval
            local now = os.clock()
            local tracked = nearestPlayers(MAX_TRACKED)
            local trackedSet = {}
            for i = 1, #tracked do
                local entry = tracked[i]
                local player = entry.player
                trackedSet[player] = true
                local history = historyByPlayer[player]
                if not history then
                    history = {}
                    historyByPlayer[player] = history
                end
                -- Only core body parts — skip accessories for history (big lag saver).
                local snapshot = {time = now, cf = entry.root.CFrame, parts = {}}
                local char = player.Character
                local names = {
                    "Head", "Torso", "UpperTorso", "LowerTorso",
                    "Left Arm", "Right Arm", "Left Leg", "Right Leg",
                    "LeftUpperArm", "LeftLowerArm", "LeftHand",
                    "RightUpperArm", "RightLowerArm", "RightHand",
                    "LeftUpperLeg", "LeftLowerLeg", "LeftFoot",
                    "RightUpperLeg", "RightLowerLeg", "RightFoot",
                    "HumanoidRootPart",
                }
                for n = 1, #names do
                    local bodyPart = char:FindFirstChild(names[n])
                    if bodyPart and bodyPart:IsA("BasePart") then
                        snapshot.parts[#snapshot.parts + 1] = {
                            name = bodyPart.Name,
                            cf = bodyPart.CFrame,
                        }
                    end
                end
                history[#history + 1] = snapshot
                while #history > MAX_HISTORY do
                    table.remove(history, 1)
                end
                local cutoff = now - (backtrackTimeMs / 1000)
                while history[1] and history[1].time < cutoff do
                    table.remove(history, 1)
                end
            end
            -- Drop data for players no longer tracked.
            for player in pairs(historyByPlayer) do
                if not trackedSet[player] then
                    historyByPlayer[player] = nil
                    removeGhost(player)
                end
            end
        end

        -- Visual CF updates at capped Hz (not every Heartbeat).
        ghostUpdateAcc = ghostUpdateAcc + dt
        if ghostUpdateAcc < (1 / GHOST_UPDATE_HZ) then
            return
        end
        ghostUpdateAcc = 0

        local targetAge = math.clamp(rewindOffsetMs, 0, backtrackTimeMs) / 1000
        local targetTime = os.clock() - targetAge
        for player, history in pairs(historyByPlayer) do
            local selected = nil
            for i = #history, 1, -1 do
                if history[i].time <= targetTime then
                    selected = history[i]
                    break
                end
            end
            if selected and player.Parent == Players and player.Character then
                local ghost = getGhost(player)
                if ghost then
                    if ghost.mode ~= movementMode then
                        ghost.mode = movementMode
                        local tint = movementMode == "Rage" and Color3.fromRGB(255, 40, 70) or Color3.fromRGB(75, 220, 255)
                        applyTintOnce(ghost.model, tint, movementMode == "Rage" and 0.3 or 0.5)
                    end
                    applySnapshotToGhost(ghost, selected)
                    backtrackRootByPlayer[player] = selected.cf
                end
            else
                removeGhost(player)
            end
        end
    end

    historySection:AddToggle("Backtrack Visualizer", false, function(state)
        backtrackEnabled = state
        if not state then clearHistory() end
    end)
    historySection:AddSlider("Backtrack Time (ms)", 50, 1000, backtrackTimeMs, function(value)
        backtrackTimeMs = value
        rewindOffsetMs = math.min(rewindOffsetMs, backtrackTimeMs)
    end, 10)
    historySection:AddSlider("Position Rewind (ms)", 0, 1000, rewindOffsetMs, function(value)
        rewindOffsetMs = math.min(value, backtrackTimeMs)
    end, 10)

    track(RunService.Heartbeat:Connect(function(dt)
        if Unloaded or not airStrafeEnabled then return end
        local character = LocalPlayer.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if not humanoid or not root or humanoid.Health <= 0 then return end
        if humanoid.FloorMaterial ~= Enum.Material.Air then return end

        local moveDirection = humanoid.MoveDirection
        if moveDirection.Magnitude < 0.05 then return end

        local currentVelocity = root.AssemblyLinearVelocity
        local horizontalVelocity = Vector3.new(currentVelocity.X, 0, currentVelocity.Z)
        local effectiveSpeed = movementMode == "Rage" and math.min(airStrafeSpeed * 2.8, 120) or airStrafeSpeed
        local desiredVelocity = moveDirection.Unit * effectiveSpeed
        local blend
        if movementMode == "Rage" then
            -- Aggressive, immediate air steering with a much higher velocity cap.
            blend = 1
        else
            -- Subtle correction that stays close to ordinary air movement.
            blend = math.clamp(dt * 2.2, 0, 0.16)
        end
        local adjustedVelocity = horizontalVelocity:Lerp(desiredVelocity, blend)
        root.AssemblyLinearVelocity = Vector3.new(adjustedVelocity.X, currentVelocity.Y, adjustedVelocity.Z)
    end))

    track(RunService.Heartbeat:Connect(updateBacktrack))
    track(Players.PlayerRemoving:Connect(function(player)
        historyByPlayer[player] = nil
        removeGhost(player)
    end))
    registerCleanup(clearHistory)
  end -- initAirMovementAndBacktrack
  initAirMovementAndBacktrack()
end


-- 5B. CINEMATIC VISUAL OVERHAUL: local-only character and world effects
-- Isolated in its own function to avoid exhausting main-chunk local registers.
-- All generated geometry is non-collidable and is removed on toggle-off / unload.
do
  local function initCinematicFx()
    local worldFxSection = createSection(worldTab.Left, "Reality / Atmosphere FX")
    local worldGridSection = createSection(worldTab.Right, "Digital World FX")

    local fxMode = "Legit"
    local fxColor = Color3.fromRGB(255, 35, 65)
    local fxAccent = Color3.fromRGB(40, 220, 255)
    local enabled = {
        atmosphere = false, grid = false,
    }
    local fxFolder = Instance.new("Folder")
    fxFolder.Name = "SatanicCinematicFX"
    fxFolder.Parent = workspace
    local gridParts = {}
    local atmosphereObjects = {}
    local function makeFxPart(name, size, material, color, transparency, shape)
        local part = Instance.new("Part")
        part.Name = name
        part.Size = size
        part.Anchored = true
        part.CanCollide = false
        part.CanTouch = false
        part.CanQuery = false
        part.CastShadow = false
        part.Massless = true
        part.TopSurface = Enum.SurfaceType.Smooth
        part.BottomSurface = Enum.SurfaceType.Smooth
        part.Material = material or Enum.Material.Neon
        part.Color = color or fxColor
        part.Transparency = transparency or 0
        if part.Material == Enum.Material.Metal or part.Material == Enum.Material.DiamondPlate then
            part.Reflectance = 0.12
        end
        if shape then part.Shape = shape end
        part.Parent = fxFolder
        return part
    end

    local function clearParts(list)
        for i, entry in pairs(list) do
            if typeof(entry) == "Instance" then
                pcall(function() entry:Destroy() end)
            elseif type(entry) == "table" then
                if typeof(entry.part) == "Instance" then
                    pcall(function() entry.part:Destroy() end)
                else
                    for _, value in pairs(entry) do
                        if typeof(value) == "Instance" and value:IsA("BasePart") then
                            pcall(function() value:Destroy() end)
                        end
                    end
                end
            end
            list[i] = nil
        end
    end

    local function setAtmosphere(state)
        for _, obj in ipairs(atmosphereObjects) do pcall(function() obj:Destroy() end) end
        table.clear(atmosphereObjects)
        if not state then return end
        local cc = Instance.new("ColorCorrectionEffect")
        cc.Name = "SatanicCinematicColor"
        cc.TintColor = fxMode == "Rage" and Color3.fromRGB(255, 190, 205) or Color3.fromRGB(205, 225, 255)
        cc.Contrast = fxMode == "Rage" and 0.24 or 0.1
        cc.Saturation = fxMode == "Rage" and 0.12 or -0.04
        cc.Brightness = fxMode == "Rage" and -0.025 or 0.015
        cc.Parent = Lighting
        atmosphereObjects[#atmosphereObjects + 1] = cc
        local bloom = Instance.new("BloomEffect")
        bloom.Name = "SatanicCinematicBloom"
        bloom.Intensity = fxMode == "Rage" and 1.25 or 0.45
        bloom.Size = fxMode == "Rage" and 42 or 24
        bloom.Threshold = 1.1
        bloom.Parent = Lighting
        atmosphereObjects[#atmosphereObjects + 1] = bloom
        local atm = Instance.new("Atmosphere")
        atm.Name = "SatanicCinematicAtmosphere"
        atm.Density = fxMode == "Rage" and 0.28 or 0.16
        atm.Haze = fxMode == "Rage" and 1.8 or 0.8
        atm.Glare = fxMode == "Rage" and 0.25 or 0.08
        atm.Color = fxMode == "Rage" and Color3.fromRGB(170, 85, 105) or Color3.fromRGB(145, 180, 205)
        atm.Decay = Color3.fromRGB(55, 35, 65)
        atm.Parent = Lighting
        atmosphereObjects[#atmosphereObjects + 1] = atm
    end

    local function buildGrid()
        clearParts(gridParts)
        if not enabled.grid then return end
        local extent = fxMode == "Rage" and 34 or 22
        local step = fxMode == "Rage" and 4 or 5.5
        for offset = -extent, extent, step do
            local a = makeFxPart("DigitalGridLine", Vector3.new(0.035, 0.035, extent * 2), Enum.Material.Neon, fxAccent, 0.68)
            local b = makeFxPart("DigitalGridLine", Vector3.new(extent * 2, 0.035, 0.035), Enum.Material.Neon, fxColor, 0.68)
            gridParts[#gridParts + 1] = {part = a, offset = offset, axis = 1}
            gridParts[#gridParts + 1] = {part = b, offset = offset, axis = 2}
        end
    end

    worldFxSection:AddToggle("Cinematic Atmosphere", false, function(v) enabled.atmosphere = v; setAtmosphere(v) end)
    worldGridSection:AddToggle("Digital Ground Grid", false, function(v) enabled.grid = v; buildGrid() end)

    track(RunService.RenderStepped:Connect(function(dt)
        -- Раньше цикл каждый кадр искал Humanoid/Root и читал CFrame даже когда
        -- все эффекты выключены. Теперь — мгновенный выход.
        if Unloaded or not enabled.grid then return end
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        local humanoid = char and char:FindFirstChildOfClass("Humanoid")
        if not root or not humanoid then return end

        if enabled.grid then
            local ground = root.Position - Vector3.new(0, math.max(2.8, humanoid.HipHeight + 2.2), 0)
            for _, entry in ipairs(gridParts) do
                if entry.part and entry.part.Parent then
                    if entry.axis == 1 then
                        entry.part.CFrame = CFrame.new(ground + Vector3.new(entry.offset, 0, 0))
                    else
                        entry.part.CFrame = CFrame.new(ground + Vector3.new(0, 0, entry.offset))
                    end
                end
            end
        end

    end))

    registerCleanup(function()
        clearParts(gridParts)
        for _, obj in ipairs(atmosphereObjects) do pcall(function() obj:Destroy() end) end
        if fxFolder and fxFolder.Parent then fxFolder:Destroy() end
    end)
  end
  initCinematicFx()
end


-- 5C. SANDEVISTAN / MILITECH APOGEE
-- VISUALS > SANDEVISTAN. V toggles Overdrive; the bind can be changed in the row.
-- All cyberware, echoes and grading are LOCAL visual effects; the game clock is not changed.
-- Movement Assist is ON by default but changes movement ONLY during active Overdrive. Server rules may override it.
-- R6 and R15 are supported; the torso, lower torso and head each carry their own articulated rig root.
do
    local function initSandevistan()
        local tab = Theme.SandevistanTab
        if not tab then return end

        local cfg = {
            showImplant = true,
            autoDash = false,
            speedAssist = true,
            rainbowTrail = true,
            hud = true,
            grade = true,
            sound = true,
            runSpeed = 36,
            dashPush = 25,
            fovKick = 6,
            -- Extra local-back clearance keeps the mechanical armor outside
            -- clothing instead of leaving only the brighter LEDs visible.
            implantDepth = 0.10,
            autoFitClothing = true,
            preset = "David / Emerald",
            accent = Color3.fromRGB(76, 255, 176),
            custom = Color3.fromRGB(76, 255, 176),
        }
        local state = {
            manual = false, active = false, blend = 0, fins = 0,
            clock = 0, echoClock = 0, hudClock = 0, watchdog = 0,
            autoUntil = 0, serial = 0,
            lastSpeed = 0, lastDashAt = -math.huge, dashKeyUntil = 0,
            dashUntil = 0, dashTarget = 0, dashDirection = nil, dashMovers = {},
            walkLease = nil, velocityLease = nil,
            fitRevision = 0,
            rig = nil, ghosts = {}, camera = nil, cameraDelta = 0, cameraWritten = nil,
        }
        local modeSwitch, paletteDropdown
        local echoPalette = {
            Color3.fromRGB(255, 65, 140), Color3.fromRGB(189, 80, 255),
            Color3.fromRGB(92, 120, 255), Color3.fromRGB(64, 216, 255),
            Color3.fromRGB(67, 255, 220), Color3.fromRGB(138, 255, 126),
            Color3.fromRGB(255, 205, 67),
        }
        local palettes = {
            {name = "David / Emerald", color = Color3.fromRGB(76, 255, 176)},
            {name = "Arasaka / Red", color = Color3.fromRGB(255, 55, 78)},
            {name = "Chrome / Ice", color = Color3.fromRGB(95, 220, 255)},
            {name = "Night City / Gold", color = Color3.fromRGB(255, 203, 67)},
            {name = "Blackwall / Violet", color = Color3.fromRGB(190, 75, 255)},
            {name = "Custom", color = Color3.fromRGB(245, 245, 245)},
        }

        -- Only remove stale objects owned by this feature, never another Lighting effect.
        for _, name in ipairs({"SatanicSandevistanColor", "SatanicSandevistanBloom"}) do
            local old = Lighting:FindFirstChild(name)
            if old then old:Destroy() end
        end
        local oldFx = workspace:FindFirstChild("SatanicSandevistanFX")
        if oldFx then oldFx:Destroy() end
        local uiParent = getParent()
        local oldHud = uiParent:FindFirstChild("SatanicSandevistanHUD")
        if oldHud then oldHud:Destroy() end
        local oldSounds = SoundService:FindFirstChild("SatanicSandevistanSounds")
        if oldSounds then oldSounds:Destroy() end

        local fxFolder = Instance.new("Folder")
        fxFolder.Name = "SatanicSandevistanFX"
        fxFolder.Parent = workspace
        local sounds = Instance.new("Folder")
        sounds.Name = "SatanicSandevistanSounds"
        sounds.Parent = SoundService

        -- Separate post effects; no existing Lighting properties are changed.
        local grade = Instance.new("ColorCorrectionEffect")
        grade.Name = "SatanicSandevistanColor"
        grade.Enabled = false
        grade.Parent = Lighting
        local bloom = Instance.new("BloomEffect")
        bloom.Name = "SatanicSandevistanBloom"
        bloom.Enabled = false
        bloom.Size = 32
        bloom.Threshold = 1.15
        bloom.Parent = Lighting

        -- Entirely procedural HUD and vignette; no external fonts or image assets.
        local hudGui = Instance.new("ScreenGui")
        hudGui.Name = "SatanicSandevistanHUD"
        hudGui.ResetOnSpawn = false
        hudGui.IgnoreGuiInset = true
        hudGui.DisplayOrder = 80
        hudGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        hudGui.Parent = uiParent
        local edges = {}
        local function makeEdge(name, position, size, rotation, reverse)
            local edge = Instance.new("Frame")
            edge.Name = name
            edge.Position = position
            edge.Size = size
            edge.BorderSizePixel = 0
            edge.BackgroundColor3 = Color3.fromRGB(2, 30, 25)
            edge.BackgroundTransparency = 1
            edge.ZIndex = 1
            edge.Parent = hudGui
            local gradient = Instance.new("UIGradient")
            gradient.Rotation = rotation
            gradient.Transparency = reverse and NumberSequence.new(1, 0) or NumberSequence.new(0, 1)
            gradient.Parent = edge
            edges[#edges + 1] = edge
        end
        makeEdge("VignetteLeft", UDim2.fromScale(0, 0), UDim2.fromScale(0.22, 1), 0, false)
        makeEdge("VignetteRight", UDim2.fromScale(0.78, 0), UDim2.fromScale(0.22, 1), 0, true)
        makeEdge("VignetteTop", UDim2.fromScale(0, 0), UDim2.fromScale(1, 0.18), 90, false)
        makeEdge("VignetteBottom", UDim2.fromScale(0, 0.82), UDim2.fromScale(1, 0.18), 90, true)

        local panel = Instance.new("Frame")
        panel.Name = "NeuralLink"
        panel.AnchorPoint = Vector2.new(0.5, 0)
        panel.Position = UDim2.new(0.5, 0, 0, 32)
        panel.Size = UDim2.fromOffset(284, 64)
        panel.BackgroundColor3 = Color3.fromRGB(5, 19, 20)
        panel.BackgroundTransparency = 1
        panel.BorderSizePixel = 0
        panel.Visible = false
        panel.ZIndex = 4
        panel.Parent = hudGui
        local panelStroke = Instance.new("UIStroke")
        panelStroke.Color = cfg.accent
        panelStroke.Thickness = 1
        panelStroke.Transparency = 1
        panelStroke.Parent = panel
        local panelGradient = Instance.new("UIGradient")
        panelGradient.Color = ColorSequence.new(Color3.fromRGB(16, 45, 38), Color3.fromRGB(5, 13, 19))
        panelGradient.Rotation = 20
        panelGradient.Parent = panel
        local accentLine = Instance.new("Frame")
        accentLine.Name = "SignalStripe"
        accentLine.Position = UDim2.fromOffset(0, 0)
        accentLine.Size = UDim2.new(1, 0, 0, 2)
        accentLine.BackgroundColor3 = cfg.accent
        accentLine.BackgroundTransparency = 1
        accentLine.BorderSizePixel = 0
        accentLine.ZIndex = 5
        accentLine.Parent = panel
        local function hudLabel(name, text, x, y, w, h, size, color, font)
            local label = Instance.new("TextLabel")
            label.Name = name
            label.Position = UDim2.fromOffset(x, y)
            label.Size = UDim2.fromOffset(w, h)
            label.BackgroundTransparency = 1
            label.Text = text
            label.Font = font or Enum.Font.Code
            label.TextSize = size
            label.TextColor3 = color
            label.TextTransparency = 1
            label.TextXAlignment = Enum.TextXAlignment.Left
            label.ZIndex = 6
            label.Parent = panel
            return label
        end
        local brand = hudLabel("Manufacturer", "M I L I T E C H  //  A P O G E E", 12, 6, 210, 12, 10, cfg.accent)
        local title = hudLabel("Title", "SANDEVISTAN", 12, 18, 180, 21, 17, Color3.fromRGB(236, 255, 246), Enum.Font.GothamBold)
        local detail = hudLabel("Status", "NEURAL LINK //  ACTIVE", 12, 40, 185, 12, 10, Color3.fromRGB(152, 215, 193))
        local speedText = hudLabel("Telemetry", "00  SPS", 210, 21, 64, 17, 12, Color3.fromRGB(255, 214, 93), Enum.Font.Code)
        speedText.TextXAlignment = Enum.TextXAlignment.Right
        local meterBars = {}
        for i = 1, 12 do
            local bar = Instance.new("Frame")
            bar.Name = "Sync" .. i
            bar.Position = UDim2.fromOffset(12 + (i - 1) * 21, 58)
            bar.Size = UDim2.fromOffset(16, 2)
            bar.BackgroundColor3 = cfg.accent
            bar.BackgroundTransparency = 1
            bar.BorderSizePixel = 0
            bar.ZIndex = 6
            bar.Parent = panel
            meterBars[#meterBars + 1] = bar
        end

        local function signalSound(on)
            if not cfg.sound or not sounds.Parent then return end
            -- Shipped Roblox client sounds: small synth ping + low electronic transient.
            for index = 1, 2 do
                local s = Instance.new("Sound")
                s.Name = on and "SandyEngage" or "SandyRelease"
                s.SoundId = index == 1 and "rbxasset://sounds/electronicpingshort.wav" or "rbxasset://sounds/bass.wav"
                s.Volume = index == 1 and 0.20 or 0.11
                s.PlaybackSpeed = index == 1 and (on and 1.28 or 0.72) or (on and 0.72 or 0.55)
                s.Parent = sounds
                pcall(function() s:Play() end)
                Debris:AddItem(s, 2)
            end
        end

        local function destroyRig()
            local rig = state.rig
            state.rig = nil
            if not rig then return end
            if rig.model then pcall(function() rig.model:Destroy() end) end
            -- A game/ragdoll script may have moved one of our parts or joints
            -- outside the rig; those must not remain loose on the ground.
            for _, entry in ipairs(rig.welds or {}) do
                pcall(function() if entry.joint and entry.joint.Parent then entry.joint:Destroy() end end)
            end
            for _, entry in ipairs(rig.motors or {}) do
                pcall(function() if entry.motor and entry.motor.Parent then entry.motor:Destroy() end end)
            end
            for _, entry in ipairs(rig.roots or {}) do
                pcall(function() if entry.joint and entry.joint.Parent then entry.joint:Destroy() end end)
                pcall(function() if entry.part and entry.part.Parent then entry.part:Destroy() end end)
            end
            for _, part in ipairs(rig.parts or {}) do
                pcall(function() if part and part.Parent then part:Destroy() end end)
            end
        end

        local function clearGhosts()
            for _, echo in ipairs(state.ghosts) do
                if echo.model then pcall(function() echo.model:Destroy() end) end
            end
            table.clear(state.ghosts)
        end
        local function restoreCamera()
            local camera = state.camera
            if camera and state.cameraDelta ~= 0 then
                pcall(function()
                    local current = camera.FieldOfView
                    -- If a camera controller already replaced our value, don't subtract it twice.
                    if state.cameraWritten and math.abs(current - state.cameraWritten) < 0.001 then
                        camera.FieldOfView = math.clamp(current - state.cameraDelta, 1, 120)
                    end
                end)
            end
            state.camera = nil
            state.cameraDelta = 0
            state.cameraWritten = nil
        end
        local function applyCamera(offset)
            local camera = workspace.CurrentCamera
            if camera ~= state.camera then
                restoreCamera()
                state.camera = camera
            end
            if not camera then return end
            -- Add only our delta, so camera scripts can continue to alter their own FOV.
            local ok, current = pcall(function() return camera.FieldOfView end)
            if not ok then return end
            local base
            if state.cameraWritten and math.abs(current - state.cameraWritten) > 0.001 then
                base = current -- another camera controller supplied a new FOV
            else
                base = current - state.cameraDelta
            end
            local desired = math.clamp(base + offset, 1, 120)
            local writeOK = pcall(function() camera.FieldOfView = desired end)
            if writeOK then
                state.cameraDelta = desired - base
                state.cameraWritten = desired
            end
        end

        -- Estimate the rear extent of layered clothing in each torso's local
        -- frame. This is a conservative bounding-box fit, not an exact skinned
        -- surface; the manual depth control remains available for unusual avatars.
        local function implantBodyDepth(character, body)
            local depth = math.clamp(cfg.implantDepth, 0, 1.5)
            if not cfg.autoFitClothing or not character or not body then return depth end
            local back = body.Size.Z * 0.5
            for _, accessory in ipairs(character:GetChildren()) do
                if accessory:IsA("Accessory") then
                    local handle = accessory:FindFirstChild("Handle")
                    if handle and handle:IsA("BasePart") and handle.Transparency < 0.99
                        and handle:FindFirstChildWhichIsA("WrapLayer", true) then
                        local ok, needed = pcall(function()
                            local relative = body.CFrame:ToObjectSpace(handle.CFrame)
                            local p, half = relative.Position, handle.Size * 0.5
                            local r, u, l = relative.RightVector, relative.UpVector, relative.LookVector
                            local ex = math.abs(r.X)*half.X + math.abs(u.X)*half.Y + math.abs(l.X)*half.Z
                            local ey = math.abs(r.Y)*half.X + math.abs(u.Y)*half.Y + math.abs(l.Y)*half.Z
                            local ez = math.abs(r.Z)*half.X + math.abs(u.Z)*half.Y + math.abs(l.Z)*half.Z
                            -- Exclude hair, unrelated side accessories, and items
                            -- that do not intersect this torso and the center spine.
                            if math.abs(p.X) <= ex + 0.30 and math.abs(p.Y) <= ey + body.Size.Y*0.5 then
                                return math.max(0, p.Z + ez - back + 0.025)
                            end
                            return 0
                        end)
                        -- Wrapped bounding boxes can be much thicker than the actual
                        -- fabric. Keep automatic correction close to the back; for
                        -- bulky clothes the user can still adjust up to 1.5 studs.
                        if ok and needed then depth = math.max(depth, math.clamp(needed, 0, 0.20)) end
                    end
                end
            end
            return math.clamp(depth, 0, 1.5)
        end

        -- Faceted Edgerunners-inspired spinal assembly. All visible hardware is
        -- angular: no spheres, circular bolts, cylinders or round particle sprites.
        -- Sub-0.05-stud seams use SpecialMesh scaling over a safe-sized Part.
        local function buildRig(character, upper, lower, head)
            local rig = {model = Instance.new("Model"), upper = upper, lower = lower, head = head,
                fitRevision = state.fitRevision, roots = {}, parts = {}, welds = {}, motors = {},
                leds = {}, accentParts = {}, lights = {}, arcs = {}}
            rig.model.Name = "SatanicSandevistanRig"
            rig.model.Parent = character
            state.rig = rig

            local void = Color3.fromRGB(18, 23, 30)
            local carbon = Color3.fromRGB(39, 48, 58)
            local gunmetal = Color3.fromRGB(79, 91, 102)
            local steel = Color3.fromRGB(155, 170, 178)
            local chrome = Color3.fromRGB(214, 224, 225)
            local copper = Color3.fromRGB(192, 111, 66)
            local caution = Color3.fromRGB(224, 170, 70)

            local function rootFor(body, name, depth)
                if not body then return nil end
                local offset = CFrame.new(0, 0, depth)
                local root = Instance.new("Part")
                root.Name = name
                root.Size = Vector3.new(0.06, 0.06, 0.06)
                root.Transparency = 1
                root.CFrame = body.CFrame * offset
                root.Anchored = false
                root.CanCollide = false; root.CanTouch = false; root.CanQuery = false
                root.CastShadow = false; root.Massless = true
                root.Parent = rig.model
                local joint = Instance.new("Motor6D")
                joint.Name = "SandyBodyAnchor"; joint.Enabled = true
                joint.Part0 = body; joint.Part1 = root
                joint.C0 = offset; joint.C1 = CFrame.new()
                joint.Parent = root
                rig.roots[#rig.roots + 1] = {part = root, body = body, joint = joint, offset = offset, bodySize = body.Size}
                return root
            end
            local upperRoot = rootFor(upper, "SandyUpperRoot", implantBodyDepth(character, upper))
            local lowerRoot = lower and lower ~= upper and rootFor(lower, "SandyLowerRoot", implantBodyDepth(character, lower)) or upperRoot
            local headDepth = math.clamp(cfg.implantDepth * 0.80, 0.04, 1.0)
            local headRoot = head and rootFor(head, "SandyHeadRoot", headDepth) or nil

            local function piece(name, anchor, wanted, offset, material, color, transparency, meshType, noWeld)
                local sx = math.max(0.06, wanted.X)
                local sy = math.max(0.06, wanted.Y)
                local sz = math.max(0.06, wanted.Z)
                local part = Instance.new("Part")
                part.Name = name
                part.Size = Vector3.new(sx, sy, sz)
                part.CFrame = anchor.CFrame * offset
                part.Anchored = false
                part.CanCollide = false; part.CanTouch = false; part.CanQuery = false
                part.Massless = true; part.CastShadow = false
                part.TopSurface = Enum.SurfaceType.Smooth; part.BottomSurface = Enum.SurfaceType.Smooth
                part.Material = material or Enum.Material.Metal
                part.Color = color or gunmetal
                part.Transparency = transparency or 0
                part.Parent = rig.model
                rig.parts[#rig.parts + 1] = part
                if meshType or wanted.X < 0.06 or wanted.Y < 0.06 or wanted.Z < 0.06 then
                    local mesh = Instance.new("SpecialMesh")
                    mesh.Name = "SandyDetailMesh"
                    mesh.MeshType = meshType or Enum.MeshType.Brick
                    mesh.Scale = Vector3.new(wanted.X / sx, wanted.Y / sy, wanted.Z / sz)
                    mesh.Parent = part
                end
                if not noWeld then
                    local weld = Instance.new("Weld")
                    weld.Name = "SandyWeld"; weld.Enabled = true
                    weld.Part0 = anchor; weld.Part1 = part
                    weld.C0 = offset; weld.C1 = CFrame.new()
                    weld.Parent = part
                    rig.welds[#rig.welds + 1] = {part = part, joint = weld, anchor = anchor, offset = offset}
                end
                return part
            end
            local function glow(name, anchor, wanted, offset, transparency)
                local part = piece(name, anchor, wanted, offset, Enum.Material.Neon, cfg.accent, transparency)
                rig.accentParts[#rig.accentParts + 1] = part
                return part
            end
            -- Wedge's local Y/Z triangle becomes a visible triangular XY face.
            local function facet(name, anchor, width, height, depth, offset, side, color)
                return piece(name, anchor, Vector3.new(depth, height, width),
                    offset * CFrame.Angles(0, side * math.rad(90), 0),
                    Enum.Material.Metal, color, 0, Enum.MeshType.Wedge)
            end
            local function light(part, brightness, range)
                local point = Instance.new("PointLight")
                point.Name = "SandyCoreLight"
                point.Color = cfg.accent; point.Brightness = brightness; point.Range = range
                point.Shadows = false; point.Parent = part
                rig.lights[#rig.lights + 1] = {light = point, base = brightness}
            end
            -- Flat segmented cable, rather than a cylinder or a string of balls.
            local function segment(name, anchor, a, b, width, material, color)
                local delta = b - a
                if delta.Magnitude < 0.001 then return nil end
                local middle = (a + b) * 0.5
                local cf = CFrame.lookAt(middle, b) * CFrame.Angles(0, math.rad(90), 0)
                local p = piece(name, anchor, Vector3.new(delta.Magnitude, width, width * 0.65),
                    cf, material, color, 0, Enum.MeshType.Brick)
                if material == Enum.Material.Neon then rig.accentParts[#rig.accentParts + 1] = p end
                return p
            end
            local function bezier(a, b, c, d, t)
                local u = 1 - t
                return a * (u*u*u) + b * (3*u*u*t) + c * (3*u*t*t) + d * (t*t*t)
            end
            local function cable(name, anchor, a, b, c, d, width, material, color, steps)
                local last = a
                for j = 1, steps do
                    local p = bezier(a, b, c, d, j / steps)
                    segment(name .. j, anchor, last, p, width, material, color)
                    last = p
                end
            end
            local function attachment(part, name)
                local a = Instance.new("Attachment")
                a.Name = name; a.Parent = part
                return a
            end
            local function beamBetween(a, b, name, color, width, always)
                local beam = Instance.new("Beam")
                beam.Name = name
                beam.Attachment0 = a; beam.Attachment1 = b
                beam.Width0 = width; beam.Width1 = width * 0.65
                beam.Color = ColorSequence.new(color, color:Lerp(Color3.new(1, 1, 1), 0.45))
                beam.Transparency = NumberSequence.new(0.10, 0.45)
                beam.LightEmission = always and 0.1 or 1
                beam.FaceCamera = true; beam.Segments = 5
                beam.CurveSize0 = 0.14; beam.CurveSize1 = -0.12
                beam.Enabled = always == true
                beam.Parent = rig.model
                if not always then rig.arcs[#rig.arcs + 1] = beam end
                return beam
            end
            local function etch(part, text)
                local surface = Instance.new("SurfaceGui")
                surface.Name = "LaserEtching"
                surface.Face = Enum.NormalId.Back
                surface.CanvasSize = Vector2.new(420, 100)
                surface.LightInfluence = 0.3
                surface.Parent = part
                local label = Instance.new("TextLabel")
                label.Name = "MicroSerial"
                label.Size = UDim2.fromScale(1, 1)
                label.BackgroundTransparency = 1
                label.Text = text
                label.TextScaled = true
                label.TextColor3 = Color3.fromRGB(31, 42, 43)
                label.Font = Enum.Font.Code
                label.Parent = surface
            end

            local back = upper.Size.Z * 0.5
            local top = upper.Size.Y * 0.41
            local widthScale = math.clamp(upper.Size.X / 2, 0.7, 1.3)

            -- Layered trapezoid collar: recessed chassis, angular cheek armor,
            -- warning stripes, tiny engraved model plate, and rectangular core.
            piece("NapeUnderframe", upperRoot, Vector3.new(0.53*widthScale, 0.25, 0.13),
                CFrame.new(0, top, back + 0.08), Enum.Material.Metal, void)
            piece("NapeInnerHousing", upperRoot, Vector3.new(0.32*widthScale, 0.22, 0.075),
                CFrame.new(0, top + 0.005, back + 0.17), Enum.Material.Metal, carbon)
            local nameplate = piece("NapeNameplate", upperRoot, Vector3.new(0.25*widthScale, 0.043, 0.018),
                CFrame.new(0, top + 0.075, back + 0.220), Enum.Material.Metal, chrome)
            etch(nameplate, "MILITECH // APG-07")
            local napeCore = glow("NapeReactorSlit", upperRoot, Vector3.new(0.09, 0.11, 0.026),
                CFrame.new(0, top - 0.025, back + 0.218), 0.03)
            light(napeCore, 0.9, 5)
            for side = -1, 1, 2 do
                facet("NapeOuterFacet", upperRoot, 0.18*widthScale, 0.21, 0.055,
                    CFrame.new(side*0.19*widthScale, top, back + 0.175), side, steel)
                piece("NapeEdge", upperRoot, Vector3.new(0.17*widthScale, 0.025, 0.025),
                    CFrame.new(side*0.19*widthScale, top - 0.065, back + 0.211)
                        * CFrame.Angles(0, 0, side*math.rad(20)), Enum.Material.Metal, chrome)
                piece("NapeWarning", upperRoot, Vector3.new(0.045, 0.019, 0.014),
                    CFrame.new(side*0.14*widthScale, top + 0.055, back + 0.219)
                        * CFrame.Angles(0, 0, side*math.rad(28)), Enum.Material.Metal, caution)

                -- Flat shoulder housings and two layered flex-circuits, not beads.
                local podX = side * math.clamp(upper.Size.X * 0.30, 0.46, 0.80)
                local podY = top - 0.045
                piece("ClavicleChassis", upperRoot, Vector3.new(0.29*widthScale, 0.16, 0.10),
                    CFrame.new(podX, podY, back + 0.065) * CFrame.Angles(0, 0, -side*math.rad(10)),
                    Enum.Material.Metal, carbon)
                facet("ClavicleFacet", upperRoot, 0.22*widthScale, 0.14, 0.045,
                    CFrame.new(podX, podY + 0.01, back + 0.145), side, steel)
                piece("ClavicleEdge", upperRoot, Vector3.new(0.20*widthScale, 0.022, 0.016),
                    CFrame.new(podX, podY - 0.04, back + 0.174) * CFrame.Angles(0, 0, -side*math.rad(10)),
                    Enum.Material.Metal, chrome)
                glow("ClavicleSignal", upperRoot, Vector3.new(0.13*widthScale, 0.014, 0.014),
                    CFrame.new(podX, podY - 0.065, back + 0.178), 0.06)
                local a = Vector3.new(side*0.20, top + 0.015, back + 0.105)
                local b = Vector3.new(side*0.29, top + 0.13, back + 0.12)
                local c = Vector3.new(podX - side*0.10, podY + 0.10, back + 0.12)
                local d = Vector3.new(podX, podY + 0.035, back + 0.105)
                cable("ShoulderFlexCircuit", upperRoot, a, b, c, d, 0.048, Enum.Material.Metal, void, 5)
                local lift = Vector3.new(0, 0, 0.025)
                cable("ShoulderFiber", upperRoot, a + lift, b + lift, c + lift, d + lift,
                    0.013, Enum.Material.Neon, cfg.accent, 5)
            end

            -- Eleven linked, individually layered vertebrae, spanning both R15
            -- torso sections. Their depth follows a gentle anatomical S-curve.
            local mounts = {}
            for i = 1, 11 do
                local t = (i - 1) / 10
                local body, root, localT, count
                if lower and lower ~= upper then
                    if i <= 6 then body, root, localT, count = upper, upperRoot, (i - 1) / 5, 6
                    else body, root, localT, count = lower, lowerRoot, (i - 7) / 4, 5 end
                else
                    body, root, localT, count = upper, upperRoot, t, 11
                end
                local y
                if lower and lower ~= upper then
                    -- Reach closer to both sides of the R15 waist instead of leaving a visible gap.
                    y = body.Size.Y * ((i <= 6 and 0.34 or 0.41) - localT * 0.75)
                else
                    y = body.Size.Y * (0.34 - localT * 0.68)
                end
                local z = body.Size.Z * 0.5 + 0.105 + 0.033 * math.sin(t * math.pi * 2 - 0.35)
                local h = math.clamp(body.Size.Y * 0.80 / count, 0.105, 0.24)
                local w = (0.78 - t * 0.18) * widthScale
                mounts[i] = {root = root, body = body, y = y, z = z, w = w, h = h}

                -- Dark inset, silver triangular cheeks, beveled V-ridges and
                -- rectangular recessed fasteners create the mechanical silhouette.
                piece("VertebraHousing_" .. i, root, Vector3.new(w*0.83, h*0.94, 0.14),
                    CFrame.new(0, y, z), Enum.Material.Metal, i%2 == 0 and gunmetal or carbon)
                piece("VertebraRecess_" .. i, root, Vector3.new(w*0.35, h*0.84, 0.055),
                    CFrame.new(0, y, z + 0.095), Enum.Material.Metal, carbon)
                piece("CoreBezel_" .. i, root, Vector3.new(0.12, h*0.74, 0.025),
                    CFrame.new(0, y, z + 0.135), Enum.Material.Metal, gunmetal)
                for side = -1, 1, 2 do
                    facet("VertebraFacet_" .. i .. "_" .. side, root, w*0.40, h*0.94, 0.055,
                        CFrame.new(side*w*0.275, y, z + 0.105), side, i%2==0 and steel or chrome)
                    piece("ChevronRidge_" .. i .. "_" .. side, root, Vector3.new(w*0.45, math.max(0.027,h*0.19), 0.023),
                        CFrame.new(side*w*0.24, y + h*0.12, z + 0.142)
                            * CFrame.Angles(0, 0, side*math.rad(20)), Enum.Material.Metal, chrome)
                    piece("AngularHingeBlock_" .. i .. "_" .. side, root, Vector3.new(w*0.14, h*0.59, 0.068),
                        CFrame.new(side*w*0.49, y - h*0.06, z + 0.020), Enum.Material.Metal, gunmetal)
                    -- Raised contrasting frame makes the metal silhouette readable
                    -- on a black shirt as well as under dim lighting.
                    piece("RaisedCheekEdge_" .. i .. "_" .. side, root, Vector3.new(0.040, h*0.78, 0.026),
                        CFrame.new(side*w*0.47, y, z + 0.18), Enum.Material.Metal, steel)
                    piece("RectFastener_" .. i .. "_" .. side, root, Vector3.new(0.052, 0.028, 0.018),
                        CFrame.new(side*w*0.46, y - h*0.04, z + 0.066), Enum.Material.Metal, chrome)
                    piece("CopperBus_" .. i .. "_" .. side, root, Vector3.new(0.022, h*0.60, 0.016),
                        CFrame.new(side*w*0.165, y - h*0.02, z + 0.156), Enum.Material.Metal, copper)
                    if i % 2 == 1 then
                        piece("ArmorEngraving_" .. i .. "_" .. side, root, Vector3.new(w*0.17, 0.012, 0.012),
                            CFrame.new(side*w*0.33, y - h*0.23, z + 0.143)
                                * CFrame.Angles(0, 0, side*math.rad(20)), Enum.Material.Metal, void)
                    end
                end
                local led = glow("NeuralLED_" .. i, root, Vector3.new(0.060, math.max(0.048,h*0.56), 0.022),
                    CFrame.new(0, y - h*0.04, z + 0.155), 0.12)
                rig.leds[#rig.leds + 1] = led
                if i == 6 or i == 11 then light(led, 0.55, 4) end

                -- Five pairs of multi-layer heat sinks. Each opens around a
                -- Motor6D pivot during Overdrive; the trim follows the blade.
                if i == 2 or i == 4 or i == 6 or i == 8 or i == 10 then
                    for side = -1, 1, 2 do
                        local bladeWidth = 0.20 * widthScale
                        local hinge = CFrame.new(side*w*0.50, y, z + 0.018)
                            * CFrame.Angles(0, 0, side*math.rad(14))
                        local c1 = CFrame.new(-side*bladeWidth*0.5, 0, 0)
                        local blade = piece("CoolingVent_" .. i .. "_" .. side, root,
                            Vector3.new(bladeWidth, math.max(0.075,h*0.70), 0.055), hinge*c1:Inverse(),
                            Enum.Material.Metal, carbon, 0, nil, true)
                        local motor = Instance.new("Motor6D")
                        motor.Name = "SandyVentMotor"; motor.Enabled = true
                        motor.Part0 = root; motor.Part1 = blade
                        motor.C0 = hinge; motor.C1 = c1
                        motor.Parent = blade
                        rig.motors[#rig.motors + 1] = {motor = motor, side = side, hinge = hinge, root = root, part = blade}
                        facet("VentArmorFacet", blade, bladeWidth*0.73, math.max(0.065,h*0.64), 0.022,
                            CFrame.new(side*bladeWidth*0.10, 0, 0.038), side, steel)
                        piece("VentEdge", blade, Vector3.new(bladeWidth*0.75, 0.015, 0.012),
                            CFrame.new(0, -h*0.18, 0.052) * CFrame.Angles(0, 0, side*math.rad(9)),
                            Enum.Material.Metal, chrome)
                        glow("VentLightSlit", blade, Vector3.new(bladeWidth*0.57, 0.012, 0.012),
                            CFrame.new(0, h*0.09, 0.052), 0.08)
                    end
                end
            end

            -- A flexible, flat bridge follows the two independent R15 torso
            -- roots while the waist bends; it is not a rigid cross-body weld.
            if lower and lower ~= upper then
                local a = attachment(rig.leds[6], "WaistUpper")
                local b = attachment(rig.leds[7], "WaistLower")
                a.Position = Vector3.new(0, -mounts[6].h*0.26, -0.02)
                b.Position = Vector3.new(0, mounts[7].h*0.26, -0.02)
                local waist = beamBetween(a, b, "FlexibleWaistBridge", carbon, 0.105, true)
                waist.LightEmission = 0
                waist.Color = ColorSequence.new(carbon, gunmetal)
                waist.CurveSize0 = 0.035; waist.CurveSize1 = -0.035
            end

            -- Two squared coolant channels with thinner luminous nerve traces.
            -- R15 rails are split at the waist so UpperTorso/LowerTorso articulate.
            for i = 2, #mounts do
                local a, b = mounts[i-1], mounts[i]
                if a.root == b.root then
                    for side = -1, 1, 2 do
                        local p0 = Vector3.new(side*a.w*0.53, a.y, a.z + 0.037)
                        local p1 = Vector3.new(side*b.w*0.53, b.y, b.z + 0.037)
                        segment("CoolantChannel", a.root, p0, p1, 0.046, Enum.Material.Metal, void)
                        local lift = Vector3.new(0, 0, 0.022)
                        segment("NeuralTrace", a.root, p0 + lift, p1 + lift, 0.012, Enum.Material.Neon, cfg.accent)
                    end
                end
            end

            -- Forked sacral terminal, with angular claws and exposed contacts.
            local bottom = mounts[#mounts]
            local tailY = bottom.y - bottom.h*0.92
            piece("SacralChassis", bottom.root, Vector3.new(0.27*widthScale, 0.16, 0.11),
                CFrame.new(0, tailY, bottom.z), Enum.Material.Metal, carbon)
            piece("SacralCap", bottom.root, Vector3.new(0.17*widthScale, 0.07, 0.025),
                CFrame.new(0, tailY, bottom.z + 0.069), Enum.Material.Metal, steel)
            glow("SacralSignal", bottom.root, Vector3.new(0.105, 0.018, 0.015),
                CFrame.new(0, tailY - 0.014, bottom.z + 0.087), 0.05)
            for side = -1, 1, 2 do
                piece("SacralFork_" .. side, bottom.root, Vector3.new(0.23*widthScale, 0.045, 0.045),
                    CFrame.new(side*0.13*widthScale, tailY - 0.11, bottom.z + 0.025)
                        * CFrame.Angles(0, 0, side*math.rad(-35)), Enum.Material.Metal, steel)
                piece("SacralTrace_" .. side, bottom.root, Vector3.new(0.12*widthScale, 0.013, 0.013),
                    CFrame.new(side*0.10*widthScale, tailY - 0.085, bottom.z + 0.052)
                        * CFrame.Angles(0, 0, side*math.rad(-35)), Enum.Material.Metal, copper)
            end

            -- Occipital socket is a faceted rectangular stack, not a round plug.
            if headRoot and head then
                local hz = head.Size.Z*0.5
                local hy = -head.Size.Y*0.28
                local socket = piece("OccipitalSocket", headRoot, Vector3.new(0.32, 0.22, 0.10),
                    CFrame.new(0, hy, hz + 0.07), Enum.Material.Metal, void)
                piece("OccipitalPlate", headRoot, Vector3.new(0.18, 0.16, 0.035),
                    CFrame.new(0, hy, hz + 0.135), Enum.Material.Metal, gunmetal)
                for side = -1, 1, 2 do
                    facet("OccipitalFacet", headRoot, 0.12, 0.18, 0.035,
                        CFrame.new(side*0.12, hy, hz + 0.135), side, steel)
                    piece("OccipitalEdge", headRoot, Vector3.new(0.08, 0.016, 0.014),
                        CFrame.new(side*0.10, hy - 0.045, hz + 0.16)
                            * CFrame.Angles(0, 0, side*math.rad(18)), Enum.Material.Metal, chrome)
                end
                local plugCore = glow("BrainstemCoreSlit", headRoot, Vector3.new(0.045, 0.11, 0.015),
                    CFrame.new(0, hy, hz + 0.164), 0.04)
                beamBetween(attachment(socket, "HeadLink"), attachment(napeCore, "NapeLink"),
                    "FlexibleNeckCoupler", void, 0.045, true)
                light(plugCore, 0.6, 3.5)
            end
            -- Thin angular electrical links: no particle sprites / floating dots.
            for _, pair in ipairs({{1,3}, {4,6}, {6,8}, {9,11}}) do
                beamBetween(attachment(rig.leds[pair[1]], "ArcStart"), attachment(rig.leds[pair[2]], "ArcEnd"),
                    "NeuralArc", cfg.accent, 0.018, false)
            end
            return rig
        end

        local function recolorRig()
            local rig = state.rig
            if rig and rig.model and rig.model.Parent then
                for _, part in ipairs(rig.accentParts) do if part.Parent then part.Color = cfg.accent end end
                for _, entry in ipairs(rig.lights) do if entry.light.Parent then entry.light.Color = cfg.accent end end
                for _, beam in ipairs(rig.arcs) do
                    if beam.Parent then beam.Color = ColorSequence.new(cfg.accent, cfg.accent:Lerp(Color3.new(1, 1, 1), 0.45)) end
                end
            end
            panelStroke.Color = cfg.accent
            accentLine.BackgroundColor3 = cfg.accent
            brand.TextColor3 = cfg.accent
            for _, bar in ipairs(meterBars) do bar.BackgroundColor3 = cfg.accent end
        end

        local function syncRig(force)
            if Unloaded then return end
            local want = cfg.showImplant or state.active or state.blend > 0.02
            local character = LocalPlayer.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            if not want or not character or not humanoid or humanoid.Health <= 0 then
                destroyRig()
                return
            end
            local upper = character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso")
            local lower = character:FindFirstChild("LowerTorso")
            local head = character:FindFirstChild("Head")
            if not upper or not upper:IsA("BasePart") then destroyRig(); return end
            if lower and not lower:IsA("BasePart") then lower = nil end
            if head and not head:IsA("BasePart") then head = nil end
            local rig = state.rig
            local valid = rig and rig.model and rig.model.Parent == character and rig.upper == upper
                and rig.lower == lower and rig.head == head and rig.fitRevision == state.fitRevision
            if valid then
                for _, entry in ipairs(rig.roots) do
                    local part, joint, body = entry.part, entry.joint, entry.body
                    if (body.Size - entry.bodySize).Magnitude > 0.05 then valid = false; break end
                    if not part or part.Parent ~= rig.model or part.Anchored or part.CanCollide or not part.Massless
                        or not joint or joint.Parent ~= part or not joint.Enabled
                        or joint.Part0 ~= body or joint.Part1 ~= part then
                        valid = false; break
                    end

                end
            end
            if valid then
                for _, entry in ipairs(rig.welds) do
                    local part, joint, anchor = entry.part, entry.joint, entry.anchor
                    if not part or part.Parent ~= rig.model or part.Anchored or part.CanCollide or not part.Massless
                        or not anchor or not anchor.Parent or not joint or joint.Parent ~= part or not joint.Enabled
                        or joint.Part0 ~= anchor or joint.Part1 ~= part then
                        valid = false; break
                    end
                end
            end
            if valid then
                for _, entry in ipairs(rig.motors) do
                    local motor, part = entry.motor, entry.part
                    if not motor or not part or motor.Parent ~= part or part.Parent ~= rig.model
                        or part.Anchored or part.CanCollide or not part.Massless or not motor.Enabled
                        or motor.Part0 ~= entry.root or motor.Part1 ~= part then
                        valid = false; break
                    end
                end
            end
            if valid and not force then return end
            destroyRig()
            local stale = character:FindFirstChild("SatanicSandevistanRig")
            if stale then stale:Destroy() end
            local ok, err = pcall(buildRig, character, upper, lower, head)
            if not ok then
                destroyRig()
                warn("[Sandevistan] Could not attach implant: " .. tostring(err))
            else
                recolorRig()
            end
        end

        -- All movement edits are leased only while Overdrive is active. When the
        -- game or another script changes a value, its newer value wins on release.
        local function restoreWalkSpeed()
            local lease = state.walkLease
            if lease and lease.humanoid and lease.applied ~= nil then
                pcall(function()
                    local current = lease.humanoid.WalkSpeed
                    if math.abs(current - lease.applied) < 0.05 then
                        lease.humanoid.WalkSpeed = lease.base
                    end
                end)
            end
            state.walkLease = nil
        end
        local function boostWalkSpeed(humanoid)
            local lease = state.walkLease
            if not lease or lease.humanoid ~= humanoid then
                restoreWalkSpeed()
                lease = {humanoid = humanoid, base = humanoid.WalkSpeed, applied = nil}
                state.walkLease = lease
            end
            local current = humanoid.WalkSpeed
            -- The game can set its own slow/zero speed for attacks or stuns.
            -- Do not overwrite that lock; use it as the new baseline instead.
            if lease.applied == nil or math.abs(current - lease.applied) >= 0.05 then
                lease.base = current
                lease.applied = nil
            end
            if current <= 8 then return nil end
            local base = lease.base
            local target = math.max(cfg.runSpeed, base * 1.35)
            target = math.max(base, math.min(target, 80))
            if math.abs(current - target) >= 0.05 then humanoid.WalkSpeed = target end
            lease.applied = target
            return target
        end
        local function restoreDashMovers()
            for mover, lease in pairs(state.dashMovers) do
                pcall(function()
                    if not mover.Parent then return end
                    local current = mover[lease.property]
                    if (current - lease.applied).Magnitude < 0.1 then
                        mover[lease.property] = lease.base
                    end
                end)
            end
            table.clear(state.dashMovers)
        end
        local function setAssistedVelocity(root, before, after)
            local lease = state.velocityLease
            local beforeFlat = Vector3.new(before.X, 0, before.Z)
            local base = beforeFlat
            if lease and lease.root == root then
                local lastFlat = Vector3.new(lease.applied.X, 0, lease.applied.Z)
                if (beforeFlat - lastFlat).Magnitude < 0.1 then base = lease.base end
            end
            root.AssemblyLinearVelocity = after
            state.velocityLease = {root = root, base = base, applied = after}
        end
        local function restoreAssistedVelocity()
            local lease = state.velocityLease
            state.velocityLease = nil
            if not lease or not lease.root then return end
            pcall(function()
                if not lease.root.Parent then return end
                local current = lease.root.AssemblyLinearVelocity
                local nowFlat = Vector3.new(current.X, 0, current.Z)
                local lastFlat = Vector3.new(lease.applied.X, 0, lease.applied.Z)
                -- Restore only our own last write, never a newer knockback/dash.
                if (nowFlat - lastFlat).Magnitude < 0.1 then
                    lease.root.AssemblyLinearVelocity = Vector3.new(lease.base.X, current.Y, lease.base.Z)
                end
            end)
        end
        local function stopDashAssist()
            restoreDashMovers()
            state.dashUntil = 0
            state.dashTarget = 0
            state.dashDirection = nil
        end
        local function releaseKinetics()
            restoreWalkSpeed()
            stopDashAssist()
            restoreAssistedVelocity()
        end

        local function setActive(value, silent)
            value = value == true
            if state.active == value then return end
            state.active = value
            if not value then releaseKinetics() end
            if not silent then signalSound(value) end
            syncRig()
        end

        local bodyNames = {
            Head = true, Torso = true, ["Left Arm"] = true, ["Right Arm"] = true,
            ["Left Leg"] = true, ["Right Leg"] = true, UpperTorso = true, LowerTorso = true,
            LeftUpperArm = true, LeftLowerArm = true, LeftHand = true,
            RightUpperArm = true, RightLowerArm = true, RightHand = true,
            LeftUpperLeg = true, LeftLowerLeg = true, LeftFoot = true,
            RightUpperLeg = true, RightLowerLeg = true, RightFoot = true,
        }
        local function cloneEchoPart(source, model, color)
            if not source:IsA("BasePart") or source.Transparency >= 0.99 then return nil end
            local ok, ghost = pcall(function() return source:Clone() end)
            if not ok or not ghost or not ghost:IsA("BasePart") then
                ghost = Instance.new("Part")
                ghost.Size = source.Size
                local mesh = source:FindFirstChildOfClass("SpecialMesh")
                if mesh then pcall(function() mesh:Clone().Parent = ghost end) end
            else
                -- Preserve the actual Head mesh and MeshPart geometry, but never copy
                -- scripts, joints, sounds, textures, emitters or character accessories.
                for _, child in ipairs(ghost:GetChildren()) do
                    if not child:IsA("DataModelMesh") then child:Destroy()
                    else pcall(function() child.TextureId = "" end) end
                end
                if ghost:IsA("MeshPart") then pcall(function() ghost.TextureID = "" end) end
            end
            ghost.Name = "Echo_" .. source.Name
            ghost.Anchored = true
            ghost.CanCollide = false; ghost.CanTouch = false; ghost.CanQuery = false
            ghost.CastShadow = false; ghost.Massless = true
            ghost.CFrame = source.CFrame
            ghost.Material = Enum.Material.ForceField
            ghost.Color = color
            ghost.Transparency = 0.44
            pcall(function() ghost.LocalTransparencyModifier = 0 end)
            ghost.Parent = model
            return ghost
        end
        local function spawnEcho(character)
            if not character or not character.Parent or not fxFolder.Parent then return end
            -- Ten echoes = at most ten Highlights, leaving room for player ESP/chams.
            while #state.ghosts >= 10 do
                local oldest = table.remove(state.ghosts, 1)
                if oldest.model then oldest.model:Destroy() end
            end
            state.serial = state.serial + 1
            local color = echoPalette[(state.serial - 1) % #echoPalette + 1]
            local model = Instance.new("Model")
            model.Name = "SandyChromaticEcho"
            model.Parent = fxFolder
            local parts, copied, accessoryCount = {}, 0, 0
            for _, child in ipairs(character:GetChildren()) do
                if child:IsA("BasePart") and bodyNames[child.Name] then
                    local ghost = cloneEchoPart(child, model, color)
                    if ghost then
                        parts[#parts + 1] = {part = ghost, base = 0.44}
                        copied = copied + 1
                        if child.Name == "Torso" or child.Name == "UpperTorso" or child.Name == "LowerTorso" then
                            local strip = Instance.new("Part")
                            strip.Name = "EchoSpine"
                            strip.Size = Vector3.new(0.075, math.max(0.1, child.Size.Y * 0.72), 0.06)
                            strip.CFrame = child.CFrame * CFrame.new(0, 0, child.Size.Z * 0.5 + 0.04)
                            strip.Anchored = true
                            strip.CanCollide = false; strip.CanTouch = false; strip.CanQuery = false
                            strip.CastShadow = false; strip.Material = Enum.Material.Neon
                            strip.Color = color:Lerp(Color3.new(1, 1, 1), 0.35)
                            strip.Transparency = 0.2
                            strip.Parent = model
                            parts[#parts + 1] = {part = strip, base = 0.2}
                        end
                    end
                elseif child:IsA("Tool") then
                    local toolCount = 0
                    for _, item in ipairs(child:GetDescendants()) do
                        if item:IsA("BasePart") and toolCount < 6 then
                            local ghost = cloneEchoPart(item, model, color)
                            if ghost then parts[#parts + 1] = {part = ghost, base = 0.44}; toolCount = toolCount + 1 end
                        end
                    end
                elseif child:IsA("Accessory") then
                    -- Keep up to four visible hair/hat handles without copying scripts.
                    local handle = child:FindFirstChild("Handle")
                    if handle and handle:IsA("BasePart") and accessoryCount < 4 then
                        local ghost = cloneEchoPart(handle, model, color)
                        if ghost then
                            parts[#parts + 1] = {part = ghost, base = 0.50}
                            copied = copied + 1; accessoryCount = accessoryCount + 1
                        end
                    end
                end
            end
            if copied == 0 then model:Destroy(); return end
            local highlight = Instance.new("Highlight")
            highlight.Name = "ChromaticOutline"
            highlight.Adornee = model
            highlight.FillColor = color
            highlight.OutlineColor = color:Lerp(Color3.new(1, 1, 1), 0.40)
            highlight.FillTransparency = 0.82
            highlight.OutlineTransparency = 0.15
            highlight.DepthMode = Enum.HighlightDepthMode.Occluded
            highlight.Parent = model
            state.ghosts[#state.ghosts + 1] = {model = model, parts = parts, highlight = highlight, age = 0, life = 0.62}
        end
        local function updateEchoes(dt)
            for i = #state.ghosts, 1, -1 do
                local echo = state.ghosts[i]
                echo.age = echo.age + dt
                local alpha = math.clamp(echo.age / echo.life, 0, 1)
                if alpha >= 1 or not echo.model.Parent then
                    if echo.model then echo.model:Destroy() end
                    table.remove(state.ghosts, i)
                else
                    local fade = alpha * alpha
                    for _, item in ipairs(echo.parts) do
                        if item.part.Parent then item.part.Transparency = item.base + (1 - item.base) * fade end
                    end
                    if echo.highlight and echo.highlight.Parent then
                        echo.highlight.FillTransparency = 0.82 + 0.18 * fade
                        echo.highlight.OutlineTransparency = 0.15 + 0.85 * fade
                    end
                end
            end
        end

        local function marked(value)
            if type(value) == "boolean" then return value end
            if type(value) == "number" then return value > 0 end
            if type(value) == "string" then
                local text = string.lower(value)
                return text ~= "" and text ~= "false" and text ~= "0"
            end
            return value ~= nil
        end
        local blockedNames = {"Ragdoll", "Ragdolled", "IsRagdoll", "Stun", "Stunned", "IsStunned", "Knocked", "KnockedOut"}
        local function markerIsOn(instance)
            if not instance then return false end
            if instance:IsA("BoolValue") or instance:IsA("NumberValue") or instance:IsA("IntValue") or instance:IsA("StringValue") then
                return marked(instance.Value)
            end
            return true -- marker folders/objects mean the state is present
        end
        local function motionBlocked(character, humanoid, root)
            if not humanoid or humanoid.Health <= 0 or humanoid.Sit or humanoid.PlatformStand or root.Anchored then return true end
            local humanoidState = humanoid:GetState()
            if humanoidState == Enum.HumanoidStateType.Dead or humanoidState == Enum.HumanoidStateType.Ragdoll
                or humanoidState == Enum.HumanoidStateType.FallingDown or humanoidState == Enum.HumanoidStateType.Physics
                or humanoidState == Enum.HumanoidStateType.GettingUp or humanoidState == Enum.HumanoidStateType.Climbing
                or humanoidState == Enum.HumanoidStateType.Swimming or humanoidState == Enum.HumanoidStateType.Seated then return true end
            local statuses = character:FindFirstChild("Status") or character:FindFirstChild("States")
            for _, name in ipairs(blockedNames) do
                if marked(character:GetAttribute(name)) or marked(humanoid:GetAttribute(name))
                    or markerIsOn(character:FindFirstChild(name)) or markerIsOn(humanoid:FindFirstChild(name))
                    or (statuses and markerIsOn(statuses:FindFirstChild(name))) then return true end
            end
            return false
        end
        local function actionRestricted(character, humanoid)
            local statuses = character:FindFirstChild("Status") or character:FindFirstChild("States")
            for _, name in ipairs({"Attacking", "Blocking"}) do
                if marked(character:GetAttribute(name)) or marked(humanoid:GetAttribute(name))
                    or markerIsOn(character:FindFirstChild(name)) or markerIsOn(humanoid:FindFirstChild(name))
                    or (statuses and markerIsOn(statuses:FindFirstChild(name))) then return true end
            end
            return false
        end

        -- These controls are intentionally compact: the page scrolls horizontally.
        local spineSection = createSection(tab.Left, "Militech / Apogee")
        local spineCard = tab.Left:FindFirstChild("Militech / Apogee")
        local overdriveSection = createSection(tab.Right, "Sandevistan Overdrive")
        local customSection = createSection(tab.Left, "Custom Core Color")
        local tuningSection = createSection(tab.Right, "Optics & Kinetics")
        local fitRefreshTicket = 0
        local function scheduleRigFit()
            fitRefreshTicket = fitRefreshTicket + 1
            local ticket = fitRefreshTicket
            task.delay(0.12, function()
                if not Unloaded and ticket == fitRefreshTicket and not Theme.ConfigRegistry.applying then syncRig(true) end
            end)
        end

        spineSection:AddToggle("Show Implant", true, function(v)
            cfg.showImplant = v
            syncRig()
        end)
        spineSection:AddToggle("Auto Fit Clothing", true, function(v)
            if cfg.autoFitClothing ~= v then
                cfg.autoFitClothing = v
                state.fitRevision = state.fitRevision + 1
                if not Theme.ConfigRegistry.applying then scheduleRigFit() end
            end
        end)
        -- The main UI uses integer sliders: 10 means 0.10 studs.
        spineSection:AddSlider("Implant Depth (x0.01)", 0, 150, 10, function(v)
            local depth = math.clamp(v, 0, 150) / 100
            if math.abs(cfg.implantDepth - depth) > 0.0001 then
                cfg.implantDepth = depth
                state.fitRevision = state.fitRevision + 1
                if not Theme.ConfigRegistry.applying then scheduleRigFit() end
            end
        end)
        paletteDropdown = spineSection:AddDropdown("Core Palette", palettes, 1, function(name, color)
            cfg.preset = name
            cfg.accent = name == "Custom" and cfg.custom or color
            recolorRig()
        end)
        local customH, customS, customV = cfg.custom:ToHSV()
        customSection:AddColorPicker(customH, customS, customV, function(h, s, v)
            cfg.custom = Color3.fromHSV(h, s, v)
            -- Config restore must not overwrite a separately saved preset.
            if not Theme.ConfigRegistry.applying then
                cfg.preset = "Custom"
                if paletteDropdown then paletteDropdown.Set("Custom", true) end
            end
            if cfg.preset == "Custom" then cfg.accent = cfg.custom; recolorRig() end
        end)
        modeSwitch = overdriveSection:AddToggle("Overdrive", false, function(v)
            state.manual = v
            -- A deliberate V-off stops acceleration immediately, even mid-dash.
            if not v then state.autoUntil = 0; state.dashKeyUntil = 0 end
            local char = LocalPlayer.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            setActive((v or (cfg.autoDash and os.clock() < state.autoUntil)) and hum ~= nil and hum.Health > 0)
        end, nil, Enum.KeyCode.V)
        overdriveSection:AddToggle("Auto Dash", false, function(v)
            cfg.autoDash = v
            if not v then state.autoUntil = 0; setActive(state.manual) end
        end)
        overdriveSection:AddToggle("Speed Assist", true, function(v)
            cfg.speedAssist = v
            if not v then releaseKinetics() end
        end)
        overdriveSection:AddToggle("Rainbow Trail", true, function(v) cfg.rainbowTrail = v end)
        overdriveSection:AddToggle("Cyber HUD", true, function(v) cfg.hud = v end)
        tuningSection:AddToggle("Time-Dilation Grade", true, function(v) cfg.grade = v end)
        tuningSection:AddToggle("Synth SFX", true, function(v) cfg.sound = v end)
        tuningSection:AddSlider("Run Speed", 18, 70, 36, function(v) cfg.runSpeed = v end)
        tuningSection:AddSlider("Dash Push", 0, 50, 25, function(v) cfg.dashPush = v end)
        tuningSection:AddSlider("FOV Kick", 0, 14, 6, function(v) cfg.fovKick = v end)

        -- The host UI's horizontal card grid normally fixes heights after first layout.
        -- Resize this one compact card while its preset dropdown is opening/closing.
        if spineCard then
            local container = spineCard:FindFirstChild("Container")
            local layout = container and container:FindFirstChildOfClass("UIListLayout")
            if layout then
                track(layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
                    if spineCard.Parent and spineCard:GetAttribute("SatanicGridManaged") == true then
                        local height = math.max(56, math.ceil(layout.AbsoluteContentSize.Y + 49))
                        if spineCard.Size.Y.Offset ~= height then
                            spineCard.Size = UDim2.fromOffset(spineCard.Size.X.Offset, height)
                        end
                    end
                end))
            end
        end

        local function resetForCharacter()
            state.autoUntil = 0; state.echoClock = 0; state.dashKeyUntil = 0
            state.lastSpeed = 0; state.lastDashAt = -math.huge
            releaseKinetics()
            if modeSwitch and modeSwitch.Get() then
                modeSwitch.Set(false)
            else
                state.manual = false
                setActive(false, true)
            end
            state.active = false
            state.blend = 0; state.fins = 0
            grade.Enabled = false; bloom.Enabled = false
            panel.Visible = false
            for _, edge in ipairs(edges) do edge.BackgroundTransparency = 1 end
            restoreCamera()
            clearGhosts()
            destroyRig()
        end
        local function waitForCharacter(character)
            task.spawn(function()
                local humanoid = character:FindFirstChildOfClass("Humanoid") or character:WaitForChild("Humanoid", 10)
                if not humanoid or Unloaded or LocalPlayer.Character ~= character then return end
                local torsoName = humanoid.RigType == Enum.HumanoidRigType.R15 and "UpperTorso" or "Torso"
                character:WaitForChild(torsoName, 10)
                if humanoid.RigType == Enum.HumanoidRigType.R15 then character:WaitForChild("LowerTorso", 5) end
                character:WaitForChild("Head", 5)
                if not Unloaded and LocalPlayer.Character == character then syncRig() end
            end)
        end
        track(LocalPlayer.CharacterRemoving:Connect(function() resetForCharacter() end))
        -- Layered clothes may finish loading after the torso; refit once the
        -- avatar appearance arrives, without deleting or modifying clothing.
        track(LocalPlayer.CharacterAppearanceLoaded:Connect(function(character)
            if Unloaded or LocalPlayer.Character ~= character then return end
            task.delay(0.25, function()
                if not Unloaded and LocalPlayer.Character == character then
                    state.fitRevision = state.fitRevision + 1
                    syncRig(true)
                end
            end)
        end))
        track(LocalPlayer.CharacterAdded:Connect(function(character)
            resetForCharacter()
            waitForCharacter(character)
        end))
        if LocalPlayer.Character then waitForCharacter(LocalPlayer.Character) end

        -- Record the actual dash key, but never synthesize a keypress or create a
        -- dash when it is on cooldown. Gamepad/mobile still use the speed-spike fallback.
        track(UserInputService.InputBegan:Connect(function(input)
            if Unloaded or Theme.CapturingKey or input.UserInputType ~= Enum.UserInputType.Keyboard or input.KeyCode ~= Enum.KeyCode.Q then return end
            local ok, focused = pcall(function() return UserInputService:GetFocusedTextBox() end)
            if ok and focused then return end
            if state.active or state.manual or cfg.autoDash then
                state.dashKeyUntil = os.clock() + 0.38
            end
        end))

        -- A game dash may be driven by LinearVelocity or BodyVelocity rather
        -- than raw AssemblyLinearVelocity. Temporarily raise its target only
        -- during a detected dash; never compound the bonus on our own writes.
        local function boostDashMovers(character, root)
            local seen = {}
            local function consider(mover)
                if seen[mover] then return end
                seen[mover] = true
                local property
                if mover:IsA("BodyVelocity") then
                    property = "Velocity"
                elseif mover:IsA("LinearVelocity") and mover.VelocityConstraintMode == Enum.VelocityConstraintMode.Vector then
                    property = "VectorVelocity"
                else
                    return
                end
                local ok, current = pcall(function() return mover[property] end)
                if not ok or typeof(current) ~= "Vector3" then return end
                local old = state.dashMovers[mover]
                local base = current
                if old and old.property == property and (current - old.applied).Magnitude < 0.1 then
                    base = old.base
                end
                local flat = Vector3.new(base.X, 0, base.Z)
                local magnitude = flat.Magnitude
                if magnitude < 12 then
                    state.dashMovers[mover] = nil
                    return
                end
                -- World-relative forces must actually point in the dash direction.
                -- Local-relative LinearVelocity retains its own local direction.
                if state.dashDirection and (mover:IsA("BodyVelocity") or mover.RelativeTo == Enum.ActuatorRelativeTo.World)
                    and flat.Unit:Dot(state.dashDirection) < 0.35 then return end
                local target = math.max(magnitude, math.min(180, magnitude + cfg.dashPush))
                if target <= magnitude + 0.01 then return end
                local boosted = flat.Unit * target
                local nextValue = Vector3.new(boosted.X, base.Y, boosted.Z)
                local wrote = pcall(function() mover[property] = nextValue end)
                if wrote then state.dashMovers[mover] = {property = property, base = base, applied = nextValue} end
            end
            for _, name in ipairs({"HumanoidRootPart", "UpperTorso", "Torso"}) do
                local body = name == "HumanoidRootPart" and root or character:FindFirstChild(name)
                if body and body:IsA("BasePart") then
                    for _, descendant in ipairs(body:GetDescendants()) do consider(descendant) end
                end
            end
            -- If a dash driver disappeared or was reparented, stop managing it.
            for mover, lease in pairs(state.dashMovers) do
                if not seen[mover] then
                    pcall(function()
                        if mover.Parent then
                            local current = mover[lease.property]
                            if (current - lease.applied).Magnitude < 0.1 then mover[lease.property] = lease.base end
                        end
                    end)
                    state.dashMovers[mover] = nil
                end
            end
        end

        track(RunService.Heartbeat:Connect(function(dt)
            if Unloaded then return end
            -- Холостой ход: когда кибер-режимы полностью выключены, не тратим кадр
            -- на поиски частей персонажа, motionBlocked и releaseKinetics.
            if not cfg.autoDash and not cfg.speedAssist and not state.manual and not state.active then
                if state.lastSpeed ~= 1e9 then state.lastSpeed = 1e9 end
                return
            end
            local character = LocalPlayer.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            local root = character and character:FindFirstChild("HumanoidRootPart")
            if not character or not humanoid or not root or not root:IsA("BasePart") or humanoid.Health <= 0 then
                state.autoUntil = 0
                setActive(false, true)
                releaseKinetics()
                state.lastSpeed = 0
                return
            end
            local now = os.clock()
            local velocity = root.AssemblyLinearVelocity
            local horizontal = Vector3.new(velocity.X, 0, velocity.Z)
            local speed = horizontal.Magnitude
            local moving = humanoid.MoveDirection
            local direction = Vector3.new(moving.X, 0, moving.Z)
            local movingEnough = direction.Magnitude > 0.05
            if movingEnough then direction = direction.Unit end
            local blocked = (cfg.autoDash or cfg.speedAssist) and motionBlocked(character, humanoid, root) or false
            local aligned = movingEnough and speed > 0.1 and horizontal.Unit:Dot(direction) > 0.5
            local currentWalk = math.max(0, humanoid.WalkSpeed)
            local gate = math.max(35, currentWalk * 1.20)
            local keyGate = math.max(27, currentWalk * 1.08)
            local recentlyPressed = now < state.dashKeyUntil
            local crossing = state.lastSpeed < gate + 8 and speed >= gate + 8
            local interested = state.active or state.manual or cfg.autoDash
            local keyDash = recentlyPressed and speed >= keyGate and (aligned or not movingEnough)
            local spikeDash = crossing and aligned
            local detected = interested and not blocked and now - state.lastDashAt >= 0.45
                and (keyDash or spikeDash)
            if detected then
                state.lastDashAt = now
                state.dashKeyUntil = 0
                if cfg.autoDash then state.autoUntil = now + 0.48 end
            end
            setActive(state.manual or (cfg.autoDash and now < state.autoUntil))
            if detected and cfg.speedAssist and state.active and cfg.dashPush > 0 then
                state.dashUntil = now + 0.32
                state.dashTarget = math.max(speed, math.min(180, speed + cfg.dashPush))
                state.dashDirection = horizontal.Unit
            end

            if not cfg.speedAssist or not state.active or blocked then
                releaseKinetics()
            else
                -- WalkSpeed drives the actual Humanoid controller, while the
                -- conservative velocity blend helps games that rewrite it locally.
                local target
                if actionRestricted(character, humanoid) then
                    restoreWalkSpeed()
                else
                    target = boostWalkSpeed(humanoid)
                end
                velocity = root.AssemblyLinearVelocity
                horizontal = Vector3.new(velocity.X, 0, velocity.Z)
                speed = horizontal.Magnitude
                local dashing = now < state.dashUntil and state.dashDirection ~= nil
                if dashing then
                    if speed < gate * 0.45 or (speed > 0.1 and horizontal.Unit:Dot(state.dashDirection) < -0.15) then
                        stopDashAssist()
                        dashing = false
                    elseif speed < state.dashTarget then
                        local boosted = horizontal.Unit * state.dashTarget
                        local nextVelocity = Vector3.new(boosted.X, velocity.Y, boosted.Z)
                        setAssistedVelocity(root, velocity, nextVelocity)
                        speed = state.dashTarget
                    end
                elseif state.dashUntil ~= 0 then
                    stopDashAssist()
                end
                if not dashing and target and movingEnough and speed < target and horizontal:Dot(direction) > -4 then
                    local alpha = 1 - math.exp(-math.clamp(dt, 0, 0.1) * 7)
                    local nextHorizontal = horizontal:Lerp(direction * target, alpha)
                    setAssistedVelocity(root, velocity, Vector3.new(nextHorizontal.X, velocity.Y, nextHorizontal.Z))
                    speed = nextHorizontal.Magnitude
                end
            end
            state.lastSpeed = speed
        end))

        -- PreSimulation is the last script step before physics and therefore
        -- works with dashes whose own controller rewrites its velocity each frame.
        track(RunService.PreSimulation:Connect(function()
            if Unloaded then return end
            if not state.active or not cfg.speedAssist or os.clock() >= state.dashUntil then
                restoreDashMovers()
                return
            end
            local character = LocalPlayer.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            local root = character and character:FindFirstChild("HumanoidRootPart")
            if not character or not humanoid or not root or not root:IsA("BasePart")
                or motionBlocked(character, humanoid, root) then
                stopDashAssist()
                restoreAssistedVelocity()
                return
            end
            boostDashMovers(character, root)
        end))

        local visualsSettled = false
        track(RunService.RenderStepped:Connect(function(dt)
            if Unloaded then return end
            dt = math.clamp(dt, 0, 0.1)
            state.clock = state.clock + dt
            state.blend = state.blend + ((state.active and 1 or 0) - state.blend) * (1 - math.exp(-dt * 9))
            state.fins = state.fins + ((state.active and 1 or 0) - state.fins) * (1 - math.exp(-dt * (state.active and 18 or 8)))
            local blend = state.blend
            local rig = state.rig
            -- Угасание завершено и рига нет: применяем финальное состояние один раз
            -- и не трогаем grade/bloom/панель/камеру каждый кадр зря.
            if not state.active and blend <= 0.001 and state.fins <= 0.001 and not (rig and rig.model and rig.model.Parent) then
                if not visualsSettled then
                    visualsSettled = true
                    grade.Enabled = false
                    bloom.Enabled = false
                    panel.Visible = false
                    for _, edge in ipairs(edges) do edge.BackgroundTransparency = 1 end
                    restoreCamera()
                end
                return
            end
            visualsSettled = false
            if rig and rig.model and rig.model.Parent then
                for _, entry in ipairs(rig.motors) do
                    if entry.motor.Parent then
                        -- C0 is not overwritten by the character Animator like Transform can be.
                        entry.motor.C0 = entry.hinge * CFrame.Angles(0, entry.side * state.fins * math.rad(62), entry.side * state.fins * math.rad(7))
                    end
                end
                for i, beam in ipairs(rig.arcs) do
                    if beam.Parent then
                        if beam.Enabled ~= state.active then beam.Enabled = state.active end
                        beam.CurveSize0 = 0.11
                    end
                end
            end

            local visualBlend = cfg.grade and blend or 0
            grade.Enabled = visualBlend > 0.005
            bloom.Enabled = visualBlend > 0.005
            if visualBlend > 0.005 then
                grade.TintColor = Color3.new(1, 1, 1):Lerp(Color3.fromRGB(166, 255, 218), visualBlend)
                grade.Contrast = 0.19 * visualBlend
                grade.Saturation = -0.16 * visualBlend
                grade.Brightness = 0.015 * visualBlend
                bloom.Intensity = 0.7 * visualBlend
            end
            for _, edge in ipairs(edges) do edge.BackgroundTransparency = 1 - 0.62 * visualBlend end
            if blend > 0.001 and cfg.fovKick > 0 then
                applyCamera(cfg.fovKick * blend)
            else
                restoreCamera()
            end
            panel.Visible = cfg.hud and blend > 0.01
            if panel.Visible then
                panel.BackgroundTransparency = 1 - blend * 0.90
                panelStroke.Transparency = 1 - blend * 0.72
                accentLine.BackgroundTransparency = 1 - blend
                brand.TextTransparency = 1 - blend
                title.TextTransparency = 1 - blend
                detail.TextTransparency = 1 - blend
                speedText.TextTransparency = 1 - blend
                state.hudClock = state.hudClock + dt
                if state.hudClock >= 0.10 then
                    state.hudClock = 0
                    local character = LocalPlayer.Character
                    local root = character and character:FindFirstChild("HumanoidRootPart")
                    local v = root and root.AssemblyLinearVelocity or Vector3.new()
                    local speed = math.floor(Vector3.new(v.X, 0, v.Z).Magnitude + 0.5)
                    speedText.Text = string.format("%02d SPS", math.min(999, speed))
                    detail.Text = state.manual and "NEURAL LINK  //  OVERDRIVE" or "NEURAL LINK  //  AUTO DASH"
                    local lit = math.clamp(5 + math.floor(speed / 8), 5, 12)
                    for i, bar in ipairs(meterBars) do
                        bar.BackgroundTransparency = i <= lit and (1 - blend * 0.94) or (1 - blend * 0.20)
                    end
                end
            end
            updateEchoes(dt)
            local character = LocalPlayer.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            state.echoClock = state.echoClock + dt
            if state.active and cfg.rainbowTrail and root and root.AssemblyLinearVelocity.Magnitude > 5 and state.echoClock >= 0.065 then
                state.echoClock = 0
                spawnEcho(character)
            end
            state.watchdog = state.watchdog + dt
            if state.watchdog >= 1 then
                state.watchdog = 0
                syncRig()
            end
        end))

        registerCleanup(function()
            state.manual = false; state.active = false; state.blend = 0
            releaseKinetics()
            restoreCamera()
            clearGhosts()
            destroyRig()
            pcall(function() grade:Destroy() end)
            pcall(function() bloom:Destroy() end)
            pcall(function() hudGui:Destroy() end)
            pcall(function() sounds:Destroy() end)
            pcall(function() fxFolder:Destroy() end)
        end)
    end
    initSandevistan()
end


-- Общий строгий стиль: только прямые углы. Шрифты не трогаем.
do
    for _, obj in ipairs(ScreenGui:GetDescendants()) do
        if obj:IsA("Frame") or obj:IsA("TextButton") or obj:IsA("TextBox") then
            if not obj:FindFirstChildOfClass("UICorner") then
                local corner = Instance.new("UICorner")
                corner.CornerRadius = UDim.new(0, 0)
                corner.Parent = obj
            end
        end
    end
end

