    Palette["FaceLess"] = {
        Background=Color3.fromRGB(15,17,27), Sidebar=Color3.fromRGB(20,23,36), Section=Color3.fromRGB(29,32,48),
        Element=Color3.fromRGB(36,40,59), ElementHover=Color3.fromRGB(51,52,77), Stroke=Color3.fromRGB(78,79,105),
        StrokeActive=Color3.fromRGB(235,109,111), Text=Color3.fromRGB(239,230,228), TextDark=Color3.fromRGB(159,135,132),
