        Watermark=Color3.fromRGB(22,17,17), GradientA=Color3.fromRGB(250,150,153), GradientB=Color3.fromRGB(172,155,235), Icon=""
    }
    local themeKeys = {"Background","Sidebar","Section","Element","ElementHover","Stroke","StrokeActive","Text","TextDark","BloodRed","BloodDark","BloodGlow"}
    local ThemeNames = {"FaceLess", "Capri", "Blood", "Halloween", "Astolfo", "Sky", "Ocean", "Emerald", "Cyberpunk", "Midnight"}
    local themeListeners = {}
    local activeName = "FaceLess"
    local activePalette = Palette[activeName]
    local gradientEnabled = false
    local gradientSpeed = 45
    local gradientTween = nil
    local pulseValue = Instance.new("Color3Value")
    pulseValue.Value = activePalette.GradientA
    local accentTargets = {}
    local themeGradients = {}
    local watermarkGradient, mainAccentLine, mainAccentGradient, configAccentLine, configAccentGradient

    local function setPaletteValues(p)
        for _, key in ipairs(themeKeys) do Theme[key] = p[key] end
    end

    local function mappedColor(color, oldPalette, newPalette, roles)
        for _, role in ipairs(roles) do
            if color == oldPalette[role] then return newPalette[role], role end
        end
        return nil, nil
    end

    local function addAccentTarget(obj, property, role)
        local props = accentTargets[obj]
        if not props then props = {}; accentTargets[obj] = props end
        props[property] = role
    end

    local function rebuildAccentTargets()
        accentTargets = {}
        if not ScreenGui or not ScreenGui.Parent then return end
        local primaryColors = {activePalette.BloodRed, activePalette.StrokeActive, Theme.BloodRed, Theme.StrokeActive}
        local glowColors = {activePalette.BloodGlow, Theme.BloodGlow}
        local function matchRole(c)
            for _, v in ipairs(primaryColors) do if c == v then return "primary" end end
            for _, v in ipairs(glowColors) do if c == v then return "glow" end end
            return nil
        end
        for _, obj in ipairs(ScreenGui:GetDescendants()) do
            if obj:IsA("GuiObject") then
                local r = matchRole(obj.BackgroundColor3)
                if r then addAccentTarget(obj, "BackgroundColor3", r) end
            end
            if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
                local r = matchRole(obj.TextColor3)
                if r then addAccentTarget(obj, "TextColor3", r) end
            end
            if obj:IsA("UIStroke") then
                local r = matchRole(obj.Color)
                if r then addAccentTarget(obj, "Color", r) end
            end
            if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
                local r = matchRole(obj.ImageColor3)
                if r then addAccentTarget(obj, "ImageColor3", r) end
            end
        end
    end

    local function applyAccentColors(color, glow)
        if not activePalette then return end
        Theme.BloodRed = color
        Theme.StrokeActive = color
        Theme.BloodGlow = glow
        wmOutlineColor = color -- wmRefresh() uses this value, so its one-second refresh won't break the gradient
        for obj, props in pairs(accentTargets) do
            if obj and obj.Parent then
                for prop, role in pairs(props) do
                    pcall(function() obj[prop] = (role == "glow") and glow or color end)
                end
            end
        end
        local gradientStart = gradientEnabled and color or activePalette.GradientA
        local sequence = ColorSequence.new(gradientStart, activePalette.GradientB)
        for grad in pairs(themeGradients) do
            if grad and grad.Parent then
                grad.Color = sequence
            else
                themeGradients[grad] = nil
            end
        end
    end

    local function setAccentPulse(color)
        applyAccentColors(color, color:Lerp(Color3.new(1, 1, 1), 0.18))
    end

    local function stopGradientTween()
        if gradientTween then pcall(function() gradientTween:Cancel() end); gradientTween = nil end
    end

    local function startGradient()
        stopGradientTween()
        if not gradientEnabled or not activePalette then return end
        pulseValue.Value = activePalette.GradientA
        setAccentPulse(pulseValue.Value)
        local duration = math.clamp(6 - (gradientSpeed / 100) * 5, 1, 6)
        gradientTween = TweenService:Create(pulseValue, TweenInfo.new(duration, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), {Value = activePalette.GradientB})
        gradientTween:Play()
    end

    local lastPulseUpdate = 0
    track(pulseValue.Changed:Connect(function(value)
        if not gradientEnabled or typeof(value) ~= "Color3" then return end
        -- Не обновляем сотни GUI-цветов каждый кадр: 20 Гц визуально плавно и дешевле.
        local now = os.clock()
        local pulseInterval = Theme.ExtremePerformance and 0.08 or 0.05
        if now - lastPulseUpdate < pulseInterval then return end
        lastPulseUpdate = now
        setAccentPulse(value)
    end))

    local function decoratePanel(panel, which)
        if not panel or not panel.Parent then return end
        if which == "main" then return end -- у главного окна своя линия под шапкой
        local line = panel:FindFirstChild("ThemeAccentLine")
        if not line then
            line = Instance.new("Frame")
            line.Name = "ThemeAccentLine"
            line.Position = UDim2.new(0, 8, 0, 1)
            line.Size = UDim2.new(1, -16, 0, 2)
            line.BorderSizePixel = 0
            line.ZIndex = math.max(panel.ZIndex + 2, 10)
            line.Parent = panel
            Instance.new("UICorner", line).CornerRadius = UDim.new(1, 0)
        end
        line.BackgroundColor3 = activePalette.BloodRed
        local grad = line:FindFirstChildOfClass("UIGradient")
        if not grad then grad = Instance.new("UIGradient", line) end
        grad.Color = ColorSequence.new(activePalette.GradientA, activePalette.GradientB)
        themeGradients[grad] = true
        if which == "main" then mainAccentLine, mainAccentGradient = line, grad end
        if which == "config" then configAccentLine, configAccentGradient = line, grad end
        if which == "settings" then line.ZIndex = 104; line.Position=UDim2.new(0,20,0,65); line.Size=UDim2.new(0,28,0,2); line.BackgroundTransparency=.25 end
    end

    local function updateSpecialUI(p)
        wmBackgroundColor = p.Watermark or p.Background
        wmOutlineColor = p.StrokeActive
        Watermark.BackgroundColor3 = wmBackgroundColor
        wmStroke.Color = p.StrokeActive
        wmIconBox.BackgroundColor3 = p.Element
        wmIconStroke.Color = p.BloodRed
        wmTitle.TextColor3 = p.Text
        wmInfo.TextColor3 = p.TextDark
        for _, child in ipairs(wmSignal:GetChildren()) do
            if child:IsA("Frame") then child.BackgroundColor3 = p.BloodRed end
        end
        if mainStroke then mainStroke.Color = p.BloodRed end
        if ConfigUI and ConfigUI.panel then ConfigUI.panel.BackgroundColor3 = p.Background end
        if activeSettingsWindow and activeSettingsWindow.Parent then
            activeSettingsWindow.BackgroundColor3 = p.Background
            local s = activeSettingsWindow:FindFirstChildOfClass("UIStroke")
            if s then s.Color = p.BloodRed end
        end
        if not watermarkGradient then
            watermarkGradient = Instance.new("UIGradient")
            watermarkGradient.Name = "ThemeGradient"
            watermarkGradient.Rotation = 12
            watermarkGradient.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 0.18)})
            watermarkGradient.Parent = Watermark
        end
        watermarkGradient.Color = ColorSequence.new(Color3.fromRGB(255, 255, 255), Color3.fromRGB(215, 210, 210))
        decoratePanel(Main, "main")
        if activeSettingsWindow then decoratePanel(activeSettingsWindow, "settings") end
        wmRefresh()
    end

    local function recolorDescendants(oldPalette, newPalette)
        local bgRoles = {"Background","Sidebar","Section","Element","ElementHover","BloodDark","BloodRed","BloodGlow","StrokeActive"}
        local textRoles = {"Text","TextDark","BloodRed","BloodGlow","BloodDark","StrokeActive"}
        local strokeRoles = {"Stroke","BloodRed","StrokeActive","BloodGlow","BloodDark"}
        for _, obj in ipairs(ScreenGui:GetDescendants()) do
            if obj:IsA("GuiObject") then
                local c = mappedColor(obj.BackgroundColor3, oldPalette, newPalette, bgRoles)
                if c then obj.BackgroundColor3 = c end
            end
            if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
                local c = mappedColor(obj.TextColor3, oldPalette, newPalette, textRoles)
                if c then obj.TextColor3 = c end
                if obj:IsA("TextBox") then
                    local pc = mappedColor(obj.PlaceholderColor3, oldPalette, newPalette, textRoles)
                    if pc then obj.PlaceholderColor3 = pc end
                end
            end
            if obj:IsA("UIStroke") then
                local c = mappedColor(obj.Color, oldPalette, newPalette, strokeRoles)
                if c then obj.Color = c end
            end
            if obj:IsA("ScrollingFrame") then
                local c = mappedColor(obj.ScrollBarImageColor3, oldPalette, newPalette, strokeRoles)
                if c then obj.ScrollBarImageColor3 = c end
            end
            if obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
                local c = mappedColor(obj.ImageColor3, oldPalette, newPalette, strokeRoles)
                if c then obj.ImageColor3 = c end
            end
            if obj:IsA("UIGradient") and obj.Parent then
                -- Recolor generic accents while leaving each theme-card preview's own swatches intact.
                local inThemeGrid = false
                local anc = obj.Parent
                while anc and anc ~= ScreenGui do
                    if anc.Name == "ThemeCardGrid" then inThemeGrid = true; break end
                    anc = anc.Parent
                end
                if not inThemeGrid then
                    local parent = obj.Parent
                    local accentParent = parent and parent:IsA("GuiObject") and
                        (parent.Name == "HeaderLine" or parent.Name == "FooterLine" or parent.Name == "ThemeAccentLine" or parent.Name == "AccentBar" or parent.Name == "Indicator" or parent.Name == "CompanionStage" or parent.Name == "CompanionDock" or (parent.Parent and parent.Parent.Name == "PageHeader"))
                    if accentParent then
                        obj.Color = ColorSequence.new(newPalette.GradientA, newPalette.GradientB)
                    end
                end
            end
        end
    end

    -- Explicit semantic pass: palette application must reach the whole UI, not only controls
    -- whose old RGB happened to exactly match a palette entry.
    local function applyWholeMenuPalette(p)
        if not ScreenGui or not ScreenGui.Parent then return end
        local mainFrame = ScreenGui:FindFirstChild("Main")
        if mainFrame then
            mainFrame.BackgroundColor3 = p.Background
            local sidePanel = mainFrame:FindFirstChild("SidePanel")
            if sidePanel and sidePanel:IsA("GuiObject") then
                sidePanel.BackgroundColor3 = p.Sidebar
            end
            for _, lineName in ipairs({"HeaderLine", "FooterLine"}) do
                local line = mainFrame:FindFirstChild(lineName)
                if line and line:IsA("GuiObject") then line.BackgroundColor3 = p.BloodRed end
            end
            local border = mainFrame:FindFirstChildOfClass("UIStroke")
            if border then border.Color = p.BloodRed end
        end

        local function inThemeCardGrid(obj)
            local anc = obj
            while anc and anc ~= ScreenGui do
                if anc.Name == "ThemeCardGrid" then return true end
                anc = anc.Parent
            end
            return false
        end
        local function insideSectionContainer(obj)
            local anc = obj.Parent
            while anc and anc ~= ScreenGui do
                if anc.Name == "Container" then
                    local section = anc.Parent
                    if section and section:IsA("Frame") and section:FindFirstChildOfClass("UIStroke") then return true end
                end
                anc = anc.Parent
            end
            return false
        end
        local function inThemedControlRegion(obj)
            if insideSectionContainer(obj) then return true end
            if activeSettingsWindow and obj:IsDescendantOf(activeSettingsWindow) then return true end
            if ConfigUI and ConfigUI.panel and obj:IsDescendantOf(ConfigUI.panel) then return true end
            if Nav and Nav.topBar and obj:IsDescendantOf(Nav.topBar) then return true end
            if Nav and Nav.subList and obj:IsDescendantOf(Nav.subList) then return true end
            return false
        end

        for _, obj in ipairs(ScreenGui:GetDescendants()) do
            if obj:IsA("Frame") and obj.Parent and (obj.Parent.Name == "Left" or obj.Parent.Name == "Right") and obj:FindFirstChild("Container") then
                -- Section card surface and header.
                obj.BackgroundColor3 = p.Section
                obj.BackgroundTransparency = 1
                local stroke = obj:FindFirstChildOfClass("UIStroke")
                if stroke then stroke.Color = p.Stroke end
                for _, child in ipairs(obj:GetChildren()) do
                    if child:IsA("TextLabel") then
                        child.TextColor3 = (child.Name == "SectionSubtitle") and p.TextDark or p.Text
                    elseif child.Name == "AccentBar" then
                        child.BackgroundColor3 = p.BloodRed
                    end
                end
            elseif obj:GetAttribute("SatanicControlRow") == true and obj:IsA("GuiObject") then
                obj.BackgroundColor3 = p.Element
                local rowStroke = obj:FindFirstChildOfClass("UIStroke")
                if rowStroke then rowStroke.Color = p.Stroke end
            elseif obj.Name == "CompanionDock" and obj:IsA("Frame") then
                obj.BackgroundColor3 = p.Section
                local dockStroke = obj:FindFirstChildOfClass("UIStroke")
                if dockStroke then dockStroke.Color = p.Stroke end
            elseif (obj.Name == "CompanionDockTitle" or obj.Name == "CompanionDockSubtitle") and obj:IsA("TextLabel") then
                obj.TextColor3 = (obj.Name == "CompanionDockTitle") and p.Text or p.TextDark
            elseif obj.Name == "CompanionStage" and obj:IsA("Frame") then
                obj.BackgroundColor3 = p.Background
                local stageStroke = obj:FindFirstChildOfClass("UIStroke")
                if stageStroke then stageStroke.Color = p.Stroke end
            elseif (obj.Name == "HaloRing1" or obj.Name == "HaloRing2" or obj.Name == "HaloRing3") and obj:IsA("Frame") then
                local ringStroke = obj:FindFirstChildOfClass("UIStroke")
                if ringStroke then ringStroke.Color = (obj.Name == "HaloRing1") and p.BloodGlow or p.Stroke end
            elseif obj.Name == "CompanionTitle" and obj:IsA("TextLabel") then
                obj.TextColor3 = p.Text
            elseif obj.Name == "IdleBadge" and obj:IsA("TextLabel") then
                obj.BackgroundColor3 = p.Element
                obj.TextColor3 = p.BloodGlow
            elseif obj.Name == "AccentBar" or obj.Name == "ThemeAccentLine" or obj.Name == "HeaderLine" or obj.Name == "FooterLine" then
                if obj:IsA("GuiObject") then obj.BackgroundColor3 = p.BloodRed end
            elseif obj.Name == "Indicator" and obj:IsA("GuiObject") then
                obj.BackgroundColor3 = p.BloodRed
            end

            if not inThemeCardGrid(obj) then
                if obj:IsA("TextBox") and obj.BackgroundTransparency < 0.99 then
                    obj.BackgroundColor3 = p.Element
                    for _, child in ipairs(obj:GetChildren()) do
                        if child:IsA("UIStroke") then child.Color = p.Stroke end
                    end
                elseif obj:IsA("TextButton") and obj.BackgroundTransparency < 0.99 then
                    -- Controls and buttons adopt the selected surface. Color chips and palette cards are excluded above.
                    if obj.Text == "✓" then
                        obj.BackgroundColor3 = p.BloodRed
                    elseif obj.Name == "Indicator" then
                        obj.BackgroundColor3 = p.BloodRed
                    elseif inThemedControlRegion(obj) then
                        obj.BackgroundColor3 = p.Element
                    end
                    for _, child in ipairs(obj:GetChildren()) do
                        if child:IsA("UIStroke") then
                            child.Color = (obj.Text == "✓") and p.BloodGlow or p.Stroke
                        end
                    end
                end
            end
        end

        -- Re-apply special component surfaces explicitly so the active theme reaches adjacent panels.
        if activeSettingsWindow and activeSettingsWindow.Parent then
            activeSettingsWindow.BackgroundColor3 = p.Background
            local st = activeSettingsWindow:FindFirstChildOfClass("UIStroke")
            if st then st.Color = p.BloodRed end
        end
        if ConfigUI and ConfigUI.panel then
            ConfigUI.panel.BackgroundColor3 = p.Background
        end
        if Nav and Nav.categories then
            local activeCategory = ActiveTab and Nav.tabCategory[ActiveTab]
            for categoryName, category in pairs(Nav.categories) do
                category.btn.BackgroundColor3 = p.ElementHover
                category.btn.TextColor3 = (categoryName == activeCategory) and p.Text or p.TextDark
                local catLabel = category.btn:FindFirstChild("CatLabel")
                if catLabel then catLabel.TextColor3 = (categoryName == activeCategory) and p.Text or p.TextDark end
                local indicator = category.btn:FindFirstChild("Indicator")
                if indicator then indicator.BackgroundColor3 = p.BloodRed end
            end
            for tabName, button in pairs(TabButtons) do
                button.BackgroundColor3 = p.Sidebar
                button.TextColor3 = (tabName == ActiveTab) and p.Text or p.TextDark
                local tabLabel = button:FindFirstChild("TabLabel")
                if tabLabel then tabLabel.TextColor3 = (tabName == ActiveTab) and p.Text or p.TextDark end
                local indicator = button:FindFirstChild("Indicator")
                if indicator then indicator.BackgroundColor3 = p.BloodRed end
            end
        end
    end

