    local function addThemeGrid(column, sectionName, names)
        local container = getSectionContainer(column, sectionName)
        if not container then return end
        local gridHolder = Instance.new("Frame")
        gridHolder.Name = "ThemeCardGrid"
        local columns = 3
        local rows = math.max(1, math.ceil(#names / columns))
        gridHolder.Size = UDim2.new(1, 0, 0, rows * 67 + (rows - 1) * 8)
        gridHolder.BackgroundTransparency = 1
        gridHolder.LayoutOrder = 2
        gridHolder.Parent = container

        local grid = Instance.new("UIGridLayout", gridHolder)
        grid.Name = "ThemeGridLayout"
        grid.CellSize = UDim2.new(1 / columns, -6, 0, 67)
        grid.CellPadding = UDim2.new(0, 8, 0, 8)
        grid.FillDirection = Enum.FillDirection.Horizontal
        grid.FillDirectionMaxCells = columns
        grid.SortOrder = Enum.SortOrder.LayoutOrder

        for i, name in ipairs(names) do
            local p = Palette[name]
            local btn = Instance.new("TextButton")
            btn.Name = "ThemeCard_" .. name
            btn.Size = UDim2.new(1 / columns, -6, 0, 67)
            btn.BackgroundColor3 = p.Element
            btn.BorderSizePixel = 0
            btn.Text = ""
            btn.AutoButtonColor = false
            btn.ClipsDescendants = true
            btn.LayoutOrder = i
            btn.ZIndex = 2
            btn.Parent = gridHolder
            Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 8)

            local stroke = Instance.new("UIStroke", btn)
            stroke.Name = "ThemeCardStroke"
            stroke.Color = p.Stroke
            stroke.Thickness = 1
            stroke.Transparency = 0.18

            local wash = Instance.new("Frame")
            wash.Name = "ThemeColorWash"
            wash.Size = UDim2.new(1, 0, 1, 0)
            wash.BackgroundColor3 = p.GradientA
            wash.BackgroundTransparency = 0.82
            wash.BorderSizePixel = 0
            wash.ZIndex = 2
            wash.Parent = btn
            Instance.new("UICorner", wash).CornerRadius = UDim.new(0, 8)
            local washGradient = Instance.new("UIGradient", wash)
            washGradient.Color = ColorSequence.new(p.GradientA, p.GradientB)
            washGradient.Rotation = 24
            washGradient.Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 0.36),
                NumberSequenceKeypoint.new(1, 0.86),
            })

            local accent = Instance.new("Frame")
