            accent.BackgroundColor3 = p.BloodRed
            accent.BorderSizePixel = 0
            accent.ZIndex = 4
            accent.Parent = btn
            Instance.new("UICorner", accent).CornerRadius = UDim.new(1, 0)

            local iconTile = Instance.new("Frame")
