            iconTile.Size = UDim2.new(0, 29, 0, 29)
            iconTile.BackgroundColor3 = p.Background
            iconTile.BorderSizePixel = 0
            iconTile.ZIndex = 4
            iconTile.Parent = btn
            Instance.new("UICorner", iconTile).CornerRadius = UDim.new(0, 7)
            local iconStroke = Instance.new("UIStroke", iconTile)
            iconStroke.Color = p.BloodRed
            iconStroke.Transparency = 0.30
            iconStroke.Thickness = 1
            local iconFill = Instance.new("UIGradient", iconTile)
            iconFill.Color = ColorSequence.new(p.GradientA, p.GradientB)
            iconFill.Rotation = 35
            iconFill.Transparency = NumberSequence.new(0.35)

