                accent = accent, iconTile = iconTile, iconStroke = iconStroke, iconFill = iconFill,
                iconText = iconText, title = title, subtitle = subtitle, activeDot = activeDot,
                miniBar = miniBar, miniGradient = miniGradient, miniSwatches = miniSwatches,
            }

            track(btn.MouseEnter:Connect(function()
                local card = themeButtons[name]
                if not card then return end
                TweenService:Create(btn, TweenInfo.new(0.12), {BackgroundColor3 = p.ElementHover}):Play()
                TweenService:Create(card.stroke, TweenInfo.new(0.12), {Transparency = 0, Color = p.BloodRed}):Play()
            end))
            track(btn.MouseLeave:Connect(function()
                if name == activeName then return end
                local card = themeButtons[name]
                if not card then return end
                TweenService:Create(btn, TweenInfo.new(0.12), {BackgroundColor3 = p.Element}):Play()
                TweenService:Create(card.stroke, TweenInfo.new(0.12), {Transparency = 0.18, Color = p.Stroke}):Play()
            end))
            track(btn.MouseButton1Click:Connect(function()
                -- Theme changes remain centralized so watermark, settings and configs stay synchronized.
                if applyTheme then applyTheme(name) end
            end))
        end
    end

    addThemeGrid(themeTab.Left, "Theme Library", {"Capri", "Blood", "Halloween", "Astolfo", "Sky", "Ocean", "Emerald", "Cyberpunk", "Midnight"})

    local function updateThemeButtons()
        for name, card in pairs(themeButtons) do
            local p = Palette[name]
            local active = (name == activeName)
            card.button.BackgroundColor3 = active and p.ElementHover or p.Element
            card.stroke.Color = active and p.BloodRed or p.Stroke
            card.stroke.Thickness = active and 1.5 or 1
            card.stroke.Transparency = active and 0 or 0.18
            card.wash.BackgroundColor3 = p.GradientA
            card.washGradient.Color = ColorSequence.new(p.GradientA, p.GradientB)
            card.accent.BackgroundColor3 = p.BloodRed
            card.iconTile.BackgroundColor3 = p.Background
            card.iconStroke.Color = p.BloodRed
            card.iconFill.Color = ColorSequence.new(p.GradientA, p.GradientB)
            card.iconText.TextColor3 = p.Text
            card.title.TextColor3 = p.Text
            card.subtitle.TextColor3 = p.TextDark
            card.activeDot.Visible = active
            card.activeDot.BackgroundColor3 = p.BloodGlow
            card.miniBar.BackgroundColor3 = p.GradientA
            card.miniGradient.Color = ColorSequence.new(p.GradientA, p.GradientB)
            local colors = {p.BloodRed, p.BloodGlow, p.GradientB}
            for i, chip in ipairs(card.miniSwatches) do chip.BackgroundColor3 = colors[i] end
        end
    end

    applyTheme = function(name)
        if name == "Traceless" then name = "FaceLess" end
        local selected = Palette[name]
        if not selected then return end
        stopGradientTween()
        if activePalette then
            applyAccentColors(activePalette.BloodRed, activePalette.BloodGlow)
        end
        local previous = activePalette or Palette["Halloween"]
        recolorDescendants(previous, selected)
        activeName = name
        activePalette = selected
        setPaletteValues(selected)
        updateSpecialUI(selected)
        for grad in pairs(themeGradients) do
            if grad and grad.Parent then grad.Color = ColorSequence.new(selected.GradientA, selected.GradientB)
            else themeGradients[grad] = nil end
        end
        if ActiveTab then selectTab(ActiveTab) end
        updateThemeButtons()
        applyWholeMenuPalette(selected)
        updateThemeButtons()
        rebuildAccentTargets()
        if gradientEnabled then startGradient() else applyAccentColors(selected.BloodRed, selected.BloodGlow) end
        -- Одна рассылка после всех внутренних перекрасок: TAB, ватермарка,
        -- настройки, конфиги и главное меню получают идентичную палитру.
        for _, listener in ipairs(themeListeners) do
            pcall(listener, selected, activeName)
        end
    end

    -- A small animated color rail previews the currently selected gradient without adding a new update loop.
    local animationSection = createSection(themeTab.Left, "Gradient Animation")
    local animationContainer = getSectionContainer(themeTab.Left, "Gradient Animation")
    local flowPreview = Instance.new("Frame")
    flowPreview.Name = "GradientLivePreview"
    flowPreview.Size = UDim2.new(1, 0, 0, 24)
    flowPreview.BackgroundColor3 = activePalette.GradientA
    flowPreview.BorderSizePixel = 0
    flowPreview.LayoutOrder = -1
    flowPreview.Parent = animationContainer
    Instance.new("UICorner", flowPreview).CornerRadius = UDim.new(0, 6)
    local flowGradient = Instance.new("UIGradient", flowPreview)
    flowGradient.Color = ColorSequence.new(activePalette.GradientA, activePalette.GradientB)
    flowGradient.Rotation = 0
    themeGradients[flowGradient] = true
    local flowLabel = Instance.new("TextLabel", flowPreview)
    flowLabel.Size = UDim2.new(1, -16, 1, 0)
    flowLabel.Position = UDim2.new(0, 8, 0, 0)
    flowLabel.BackgroundTransparency = 1
    flowLabel.Text = "LIVE COLOR FLOW   /   ACCENT PREVIEW"
    flowLabel.Font = Enum.Font.GothamBold
    flowLabel.TextSize = 8
    flowLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
    flowLabel.TextXAlignment = Enum.TextXAlignment.Left
    flowLabel.ZIndex = 3

    animationSection:AddToggle("Color cycling", false, function(enabled)
        gradientEnabled = enabled
        if enabled then
            rebuildAccentTargets()
            startGradient()
        else
            stopGradientTween()
            applyAccentColors(activePalette.BloodRed, activePalette.BloodGlow)
            for grad in pairs(themeGradients) do
                if grad and grad.Parent then grad.Color = ColorSequence.new(activePalette.GradientA, activePalette.GradientB)
                else themeGradients[grad] = nil end
            end
        end
    end)
    animationSection:AddSlider("Gradient speed", 10, 100, gradientSpeed, function(v)
        gradientSpeed = v
        if gradientEnabled then startGradient() end
    end)
    animationSection:AddButton("Reset to Capri theme", function() applyTheme("Capri") end)
    Theme.Runtime = {
        Rebuild = function()
            rebuildAccentTargets()
            applyWholeMenuPalette(activePalette)
            for _, listener in ipairs(themeListeners) do pcall(listener, activePalette, activeName) end
        end,
        Decorate = function(panel) decoratePanel(panel, "settings") end,
        Apply = applyTheme,
        GetName = function() return activeName end,
        GetPalette = function() return activePalette, activeName end,
        Names = ThemeNames,
        Subscribe = function(fn)
            if type(fn) ~= "function" then return end
            table.insert(themeListeners, fn)
            pcall(fn, activePalette, activeName)
        end,
        Next = function()
            local current = table.find(ThemeNames, activeName) or 1
            local nextName = ThemeNames[current % #ThemeNames + 1]
            applyTheme(nextName)
            return nextName
        end,
        SetCustomAccent = function(color)
            if typeof(color) ~= "Color3" then return end
            local custom = {}
            for k, v in pairs(activePalette) do custom[k] = v end
            custom.BloodRed = color
            custom.StrokeActive = color
            custom.BloodGlow = color:Lerp(Color3.new(1, 1, 1), 0.18)
            custom.GradientA = color
            custom.GradientB = color:Lerp(activePalette.Background, 0.65)
            setPaletteValues(custom)
            applyAccentColors(color, custom.BloodGlow)
            updateSpecialUI(custom)
            applyWholeMenuPalette(custom)
            rebuildAccentTargets()
            for _, listener in ipairs(themeListeners) do pcall(listener, custom, activeName .. " / CUSTOM") end
        end,
        AfterSettingsBuild = function()
            -- Refresh only effects whose settings are rebuilt dynamically.
            if customHatEnabled then pcall(updateHat) end
            if WeatherState.enabled then pcall(WeatherState.apply) end
            if fogEnabled then pcall(applyFog) end
            if chamsEnabled then
                for _, player in ipairs(Players:GetPlayers()) do
                    if player ~= LocalPlayer then pcall(applyChamsTo, player) end
                end
            end
        end,
        Cleanup = function()
            gradientEnabled = false
            stopGradientTween()
        end,
    }

    setPaletteValues(activePalette)
    updateSpecialUI(activePalette)
    applyWholeMenuPalette(activePalette)
    updateThemeButtons()
    rebuildAccentTargets()
end

local themeInitOk, themeInitErr = pcall(installThemeSystem)
if not themeInitOk then
    warn("[FaceLess UI] Theme initialization failed; continuing with the base menu: " .. tostring(themeInitErr))
end
if themeInitOk and Theme.Runtime and Theme.Runtime.Subscribe then
    Theme.Runtime.Subscribe(function(palette)
        for _, page in pairs(Tabs) do
            for _, child in ipairs(page:GetChildren()) do
                if child:IsA("Frame") and string.sub(child.Name, 1, 15) == "TracelessColumn" then
                    local wash = child:FindFirstChildOfClass("UIGradient")
                    if wash then wash.Color = ColorSequence.new(palette.Section, palette.ElementHover) end
                end
            end
        end
        local badge = Main:FindFirstChild("TitleBadge")
        local mark = badge and badge:FindFirstChild("PentagramLogo")
        if mark then
            local markEdge = mark:FindFirstChildOfClass("UIStroke")
            if markEdge then markEdge.Color = palette.BloodRed end
            mark.BackgroundColor3 = palette.Element
            for _, part in ipairs(mark:GetChildren()) do
                if part:IsA("Frame") then
                    if part.BackgroundTransparency < 1 then part.BackgroundColor3 = palette.BloodRed end
                    local edge = part:FindFirstChildOfClass("UIStroke")
                    if edge then edge.Color = palette.BloodRed end
                end
            end
        end
    end)
end
end


pcall(selectTab, "Menu")

-- ОТКРЫТИЕ И ПЕРЕТАСКИВАНИЕ ГЛАВНОГО МЕНЮ (В ОТДЕЛЬНОЙ ФУНКЦИИ, ЧТОБЫ НЕ БЫЛО OUT OF LOCAL REGISTERS)
do
    local function initMainMenuDrag()
        local isOpen = false
        local dragging = false
        local dragStart, startPos
        local restPos = Main.Position
        local hasOpenedOnce = false
        local animToken = 0
        local currentTween
        local animating = false
        local SLIDE = 130

        local function setOpen(open, initial)
            animToken = animToken + 1
            local myToken = animToken
            if currentTween then pcall(function() currentTween:Cancel() end); currentTween = nil end
            isOpen = open
            local badge = Main:FindFirstChild("TitleBadge")
            local bottom = Nav and Nav.bottomCats
            if open then
                Main.Visible = true
                syncMainBorder()
                if badge then badge.BackgroundTransparency = 1 end
                if bottom then bottom.BackgroundTransparency = 1 end
                TweenService:Create(blur, TweenInfo.new(0.3), { Size = Theme.MenuBlur.enabled and Theme.MenuBlur.amount or 0 }):Play()
                -- Появление: меню собирается из частиц-плиток как пазл
                -- (модуль PuzzleIntro в конце файла) + мягкое проявление стекла.
                Main.Size = UDim2.new(0, 1050, 0, 690)
                Main.Position = restPos
                Main.BackgroundTransparency = 1
                animating = true
                if Theme.PuzzleIntro then Theme.PuzzleIntro() end
                local introTween = UITween(Main, {BackgroundTransparency = 0.32}, 0.75, Enum.EasingStyle.Quint)
                currentTween = introTween
                task.spawn(function()
                    introTween.Completed:Wait()
                    if myToken ~= animToken then return end
                    currentTween = nil
                    animating = false
                    task.defer(layoutSidePanels)
                end)
                if badge then UITween(badge, {BackgroundTransparency = 0.66}, 0.6, Enum.EasingStyle.Quint) end
                if bottom then UITween(bottom, {BackgroundTransparency = 0.65}, 0.6, Enum.EasingStyle.Quint) end
                hasOpenedOnce = true
                task.defer(layoutSidePanels)
            else
                -- Выключение: слайд вправо, затем скрываем и возвращаем позицию.
                if Theme.CancelBindCapture then Theme.CancelBindCapture() end
                if activeSettingsWindow then activeSettingsWindow:Destroy(); activeSettingsWindow = nil end
                if ConfigUI.closeDialog then ConfigUI.closeDialog() end
                if badge then UITween(badge, {BackgroundTransparency = 1}, 0.18) end
                if bottom then UITween(bottom, {BackgroundTransparency = 1}, 0.18) end
                TweenService:Create(blur, TweenInfo.new(0.28), { Size = 0 }):Play()
                if not animating then restPos = Main.Position end
                animating = true
                local target = UDim2.new(restPos.X.Scale, restPos.X.Offset + SLIDE, restPos.Y.Scale, restPos.Y.Offset)
                local tw = TweenService:Create(Main, TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.In), {
                    Position = target,
                    BackgroundTransparency = 0.3,
                })
                currentTween = tw
                tw:Play()
                task.spawn(function()
                    while myToken == animToken and tw.PlaybackState ~= Enum.PlaybackState.Completed do task.wait(0.03) end
                    if myToken ~= animToken then return end
                    Main.Visible = false
                    Main.Position = restPos
                    Main.BackgroundTransparency = 0
                    currentTween = nil
                    animating = false
                end)
            end
        end

        -- Кнопка закрытия главного окна мышью.
        local closeMainBtn = Instance.new("TextButton")
        closeMainBtn.Name = "CloseMainMenu"
        closeMainBtn.Size = UDim2.new(0, 26, 0, 26)
        closeMainBtn.Position = UDim2.new(1, -45, 0, 43)
        closeMainBtn.BackgroundColor3 = Theme.Element; closeMainBtn.BackgroundTransparency = 0.65
        closeMainBtn.BorderSizePixel = 0
        closeMainBtn.Text = "×"
        closeMainBtn.Font = Enum.Font.GothamBold
        closeMainBtn.TextSize = 20
        closeMainBtn.TextColor3 = Theme.Text
        closeMainBtn.ZIndex = 500
        closeMainBtn.Parent = Main
        Instance.new("UICorner", closeMainBtn).CornerRadius = UDim.new(0, 8)
        local closeMainStroke = Instance.new("UIStroke", closeMainBtn)
        closeMainStroke.Color = Theme.StrokeActive
        closeMainStroke.Thickness = 1
        track(closeMainBtn.MouseButton1Click:Connect(function() setOpen(false) end))
        if UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
            local mobile = Instance.new("TextButton", ScreenGui)
            mobile.Name = "FaceLessMobileMenu"
            mobile.AnchorPoint = Vector2.new(0, 0.5)
            mobile.Position = UDim2.new(0, 12, 0.5, 0)
            mobile.Size = UDim2.fromOffset(44, 44)
            mobile.BackgroundColor3 = Theme.Background
            mobile.BackgroundTransparency = 0.25
            mobile.Text = "FL"
            mobile.Font = Enum.Font.GothamBold
            mobile.TextSize = 14
            mobile.TextColor3 = Theme.Text
            mobile.BorderSizePixel = 0
            mobile.ZIndex = 400
            Instance.new("UICorner", mobile).CornerRadius = UDim.new(0, 12)
            local edge = Instance.new("UIStroke", mobile)
            edge.Color = Theme.BloodRed
            edge.Transparency = 0.5
            track(mobile.MouseButton1Click:Connect(function() if MenuIntroReady then setOpen(not isOpen) end end))
        end

        task.spawn(function()
            while not MenuIntroReady and not Unloaded and ScreenGui.Parent do task.wait(0.05) end
            if not Unloaded and ScreenGui.Parent then
                setOpen(true, true)
                selectTab("Menu")
                layoutSidePanels()
            end
        end)

        track(UserInputService.InputBegan:Connect(function(input)
            if Unloaded then return end
            if input.KeyCode == TOGGLE_KEY and not Theme.CapturingKey and not UserInputService:GetFocusedTextBox() and MenuIntroReady then
                setOpen(not isOpen)
            end
        end))

        track(Main.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                if input.Position.Y - Main.AbsolutePosition.Y <= 40 * uiScale.Scale then 
                    dragging = true
                    dragStart = input.Position
                    startPos = Main.Position
                end
            end
        end))
        
        track(UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = false
            end
        end))
        
        track(UserInputService.InputChanged:Connect(function(input)
            if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) and Main then
                local delta = input.Position - dragStart
                Main.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
                restPos = Main.Position
                layoutSidePanels()
            end
        end))
    end
    
    local dragInitOk, dragInitErr = pcall(initMainMenuDrag)
    if dragInitOk then
        startupInitializationComplete = true
    else
        warn("[Satanic UI] Main menu input initialization failed: " .. tostring(dragInitErr))
    end
end


-- ===================== [PATCH] ДРУЖБА ТОЛЬКО ЧЕРЕЗ TAB =====================
-- Нативное окно Roblox (Add Friend / View / Wave) гасится на уровне клиента:
-- единственный способ добавить в друзья — кнопка «+» в списке People (Tab).
do
    local sg = game:GetService("StarterGui")
    pcall(function() sg:SetCore("AvatarContextMenuEnabled", false) end)
    local hooked = false
    pcall(function()
        if type(hookfunction) ~= "function" then return end
        local original
        original = hookfunction(sg.SetCore, function(self, key, ...)
            if key == "AvatarContextMenuTarget" or key == "AvatarContextMenuEnabled" then
                return false
            end
            return original(self, key, ...)
        end)
        hooked = type(original) == "function"
    end)
    if not hooked and FLLog and FLLog.push then
        FLLog.push("info", "friends", "соцменю выключено через SetCore", "жёсткий хук недоступен в этом исполнителе")
    end
end

-- The standard CoreGui player list has no supported palette API, so use a
-- compact themed roster and open Roblox's own context/inspect UI on click.
do
local rollbackRoster
local function initThemedRoster()
    local StarterGui = game:GetService("StarterGui")
    local ContextActionService = game:GetService("ContextActionService")
    local GuiService = game:GetService("GuiService")
    local SocialService = game:GetService("SocialService")
    local oldEnabled = true
    local oldContext = false
    pcall(function() oldEnabled = StarterGui:GetCoreGuiEnabled(Enum.CoreGuiType.PlayerList) end)
    local contextKnown = pcall(function() oldContext = StarterGui:GetCore("AvatarContextMenuEnabled") end)

    local gui = Instance.new("ScreenGui")
    gui.Name = "SatanicThemedPlayers"
    gui.ResetOnSpawn = false
    gui.IgnoreGuiInset = true
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    gui.DisplayOrder = 997
    local okParent = pcall(function() gui.Parent = getParent() end)
    if not okParent or not gui.Parent then
        gui:Destroy()
        error("не удалось открыть контейнер интерфейса")
    end
    -- Register cleanup before any later API or rendering operation can fail.
    local cleaned = false
    rollbackRoster = function()
        if cleaned then return end
        cleaned = true
        pcall(function() ContextActionService:UnbindAction("SatanicThemedPlayerList") end)
        pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, oldEnabled) end)
        if contextKnown then pcall(function() StarterGui:SetCore("AvatarContextMenuEnabled", oldContext) end) end
        pcall(function() gui:Destroy() end)
    end
    registerCleanup(rollbackRoster)

    local W, HEADER, ROW, MAX_ROWS = 335, 43, 36, 8
    local panel = Instance.new("Frame", gui)
    panel.Name = "Players"
    panel.AnchorPoint = Vector2.new(1, 0)
    panel.Position = UDim2.new(1, -16, 0, 45)
    panel.Size = UDim2.fromOffset(W, HEADER)
    panel.BorderSizePixel = 0
    panel.BackgroundTransparency = 0.3
    panel.ClipsDescendants = true
    Instance.new("UICorner", panel).CornerRadius = UDim.new(0, 12)
    local border = Instance.new("UIStroke", panel)
    border.Thickness = 1
    border.Transparency = 0.7
    local topAccent = Instance.new("Frame", panel)
    topAccent.Name = "Accent"
    topAccent.Position = UDim2.new(0, 12, 0, 0)
    topAccent.Size = UDim2.new(1, -24, 0, 2)
    topAccent.BorderSizePixel = 0
    topAccent.BackgroundTransparency = 0.22
    local accentGradient = Instance.new("UIGradient", topAccent)
    accentGradient.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0,1), NumberSequenceKeypoint.new(0.5,0), NumberSequenceKeypoint.new(1,1)})
    local close = Instance.new("TextButton", panel)
    close.Size = UDim2.fromOffset(27, 25)
    close.Position = UDim2.fromOffset(7, 5)
    close.BackgroundTransparency = 1
    close.Font = Enum.Font.GothamMedium
    close.TextSize = 19
    close.Text = "×"
    close.AutoButtonColor = false
    local title = Instance.new("TextLabel", panel)
    title.Position = UDim2.fromOffset(39, 6)
    title.Size = UDim2.fromOffset(100, 24)
    title.BackgroundTransparency = 1
    title.Font = Enum.Font.GothamBold
    title.TextSize = 11
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.Text = "People"
    local statHeaders = {}
    for i = 1, 2 do
        local label = Instance.new("TextLabel", panel)
        label.Position = UDim2.new(1, -169 + (i-1)*71, 0, 7)
        label.Size = UDim2.fromOffset(67, 22)
        label.BackgroundTransparency = 1
        label.Font = Enum.Font.GothamMedium
        label.TextSize = 10
        label.TextTruncate = Enum.TextTruncate.AtEnd
        label.Text = ""
        statHeaders[i] = label
    end
    local rule = Instance.new("Frame", panel)
    rule.Position = UDim2.fromOffset(12, HEADER-2)
    rule.Size = UDim2.new(1, -24, 0, 1)
    rule.BorderSizePixel = 0
    rule.BackgroundTransparency = 0.85
    local scroll = Instance.new("ScrollingFrame", panel)
    scroll.Name = "Rows"
    scroll.Position = UDim2.fromOffset(6, HEADER)
    scroll.Size = UDim2.new(1, -12, 1, -HEADER - 6)
    scroll.BackgroundTransparency = 1
    scroll.BorderSizePixel = 0
    scroll.ScrollBarThickness = 2
    scroll.ScrollingDirection = Enum.ScrollingDirection.Y
    scroll.CanvasSize = UDim2.fromOffset(0, 0)
    local layout = Instance.new("UIListLayout", scroll)
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, 1)
    local items = {}
    local palette = nil
    local function paint(p)
        if not p or not panel.Parent then return end
        palette = p
        panel.BackgroundColor3 = p.Background
        border.Color = p.Stroke
        title.TextColor3 = p.Text
        close.TextColor3 = p.TextDark
        rule.BackgroundColor3 = p.Stroke
        scroll.ScrollBarImageColor3 = p.BloodRed
        topAccent.BackgroundColor3 = p.BloodRed
        for _, label in ipairs(statHeaders) do label.TextColor3 = p.TextDark end
        for _, row in pairs(items) do
            row.button.BackgroundColor3 = p.ElementHover
            row.avatar.BackgroundColor3 = p.Element
            row.name.TextColor3 = p.Text
            for _, stat in ipairs(row.stats) do stat.TextColor3 = p.Text end
            if row.friend and row.friend.Parent then
                row.friend.BackgroundColor3 = p.Element
                if not row.isFriend then row.friend.TextColor3 = p.Text end
            end
        end
    end
    if Theme.Runtime and Theme.Runtime.Subscribe then Theme.Runtime.Subscribe(paint) end
    if not palette then paint(Theme) end

    local function openPlayer(player)
        -- [PATCH] Соцменю Roblox (Add Friend / View / Wave) отключено.
        -- Клик по строке в списке People больше не открывает нативное окно игрока.
        if not player or not player.Parent then return end
        if player == LocalPlayer then
            local ok, err = pcall(function() GuiService:InspectPlayerFromUserId(player.UserId) end)
            if not ok then warn("[Satanic] Не удалось открыть профиль: " .. tostring(err)) end
        end
    end

    -- [PATCH] Дружба из списка People (Tab): кнопка «+» у ника шлёт запрос в друзья.
    local function setFriendBadge(row, isFriend)
        if not row or not row.friend or not row.friend.Parent then return end
        row.isFriend = isFriend == true
        row.checkedAt = os.clock()
        row.friend.Text = row.isFriend and "✓" or "+"
        row.friend.TextSize = row.isFriend and 13 or 14
        row.friend.TextColor3 = row.isFriend and Color3.fromRGB(120, 220, 150) or Color3.fromRGB(235, 235, 240)
    end
    local function isFriendOf(player)
        if not player or player == LocalPlayer then return false end
        local ok, res = pcall(function() return LocalPlayer:IsFriendsWith(player.UserId) end)
        return ok and res == true
    end
    local function requestFriend(player, row)
        if not player or not player.Parent or player == LocalPlayer then return end
        if isFriendOf(player) then
            setFriendBadge(row, true)
            if FLLog and FLLog.info then FLLog.info("friends", "уже в друзьях: " .. player.DisplayName) end
            return
        end
        local ok, err = pcall(function() SocialService:PromptSendFriendRequest(player) end)
        if ok then
            if FLLog and FLLog.info then FLLog.info("friends", "запрос в друзья: " .. player.DisplayName) end
            return
        end
        -- Фолбэка на нативное окно больше нет: дружба только через Tab.
        if FLLog and FLLog.push then
            FLLog.push("warn", "friends", "запрос не отправлен: " .. tostring(err), "SocialService:PromptSendFriendRequest недоступен")
        end
    end
    local function makeRow(player)
        local button = Instance.new("TextButton", scroll)
        button.Name = "Player_" .. tostring(player.UserId)
        button.Size = UDim2.new(1, -2, 0, ROW - 1)
        button.BackgroundTransparency = 1
        button.BorderSizePixel = 0
        button.AutoButtonColor = false
        button.Text = ""
        Instance.new("UICorner", button).CornerRadius = UDim.new(0, 7)
        local avatar = Instance.new("ImageLabel", button)
        avatar.AnchorPoint = Vector2.new(0, 0.5)
        avatar.Position = UDim2.new(0, 6, 0.5, 0)
        avatar.Size = UDim2.fromOffset(26, 26)
        avatar.BackgroundTransparency = 0.25
        avatar.Image = "rbxthumb://type=AvatarHeadShot&id=" .. player.UserId .. "&w=150&h=150"
        Instance.new("UICorner", avatar).CornerRadius = UDim.new(1, 0)
        local name = Instance.new("TextLabel", button)
        name.Position = UDim2.fromOffset(38, 0)
        name.Size = UDim2.new(1, -214, 1, 0)
        name.BackgroundTransparency = 1
        name.Font = Enum.Font.GothamMedium
        name.TextSize = 11
        name.TextXAlignment = Enum.TextXAlignment.Left
        name.TextTruncate = Enum.TextTruncate.AtEnd
        local values = {}
        for i = 1, 2 do
            local value = Instance.new("TextLabel", button)
            value.Position = UDim2.new(1, -163 + (i-1)*71, 0, 0)
            value.Size = UDim2.fromOffset(67, ROW-1)
            value.BackgroundTransparency = 1
            value.Font = Enum.Font.GothamMedium
            value.TextSize = 11
            value.TextTruncate = Enum.TextTruncate.AtEnd
            values[i] = value
        end
        local friend = Instance.new("TextButton", button)
        friend.Name = "FriendAction"
        friend.AnchorPoint = Vector2.new(1, 0.5)
        friend.Position = UDim2.new(1, -3, 0.5, 0)
        friend.Size = UDim2.fromOffset(21, 21)
        friend.BackgroundTransparency = 0.45
        friend.BorderSizePixel = 0
        friend.AutoButtonColor = false
        friend.Font = Enum.Font.GothamBold
        friend.TextSize = 14
        friend.Text = "+"
        friend.TextColor3 = Color3.fromRGB(235, 235, 240)
        Instance.new("UICorner", friend).CornerRadius = UDim.new(0, 6)
        local row = {button=button, avatar=avatar, name=name, stats=values, friend=friend, isFriend=false, checkedAt=0}
        items[player] = row
        button.MouseButton1Click:Connect(function() openPlayer(player) end)
        friend.MouseEnter:Connect(function() if friend.Parent then friend.BackgroundTransparency = 0.15 end end)
        friend.MouseLeave:Connect(function() if friend.Parent then friend.BackgroundTransparency = 0.45 end end)
        friend.MouseButton1Click:Connect(function() requestFriend(player, row) end)
        button.MouseEnter:Connect(function() button.BackgroundTransparency = 0.6 end)
        button.MouseLeave:Connect(function() button.BackgroundTransparency = 1 end)
        task.spawn(function()
            local ok, image = pcall(function()
                return Players:GetUserThumbnailAsync(player.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size150x150)
            end)
            if ok and avatar.Parent and type(image) == "string" and image ~= "" then avatar.Image = image end
        end)
        if palette then
            button.BackgroundColor3 = palette.ElementHover
            avatar.BackgroundColor3 = palette.Element
            name.TextColor3 = palette.Text
            for _, value in ipairs(values) do value.TextColor3 = palette.Text end
        end
        return row
    end
    local function isStat(x)
        return x:IsA("IntValue") or x:IsA("NumberValue") or x:IsA("StringValue") or x:IsA("BoolValue")
    end
    local function refresh()
        if not gui.Parent then return end
        local players = Players:GetPlayers()
        table.sort(players, function(a,b)
            if a == b then return false end
            if a == LocalPlayer then return true end
            if b == LocalPlayer then return false end
            local an, bn = string.lower(a.DisplayName), string.lower(b.DisplayName)
            if an == bn then return a.UserId < b.UserId end
            return an < bn
        end)
        local statNames, seen = {}, {}
        for _, player in ipairs(players) do
            local stats = player:FindFirstChild("leaderstats")
            if stats then
                for _, stat in ipairs(stats:GetChildren()) do
                    if #statNames < 2 and isStat(stat) and not seen[stat.Name] then
                        seen[stat.Name] = true
                        table.insert(statNames, stat.Name)
                    end
                end
            end
        end
        for i = 1, 2 do statHeaders[i].Text = statNames[i] or "" end
        local alive = {}
        for i, player in ipairs(players) do
            alive[player] = true
            local row = items[player] or makeRow(player)
            row.button.LayoutOrder = i
            row.name.Text = player.DisplayName
            if row.friend and (os.clock() - (row.checkedAt or 0)) > 5 then setFriendBadge(row, isFriendOf(player)) end
            local stats = player:FindFirstChild("leaderstats")
            for j = 1, 2 do
                local obj = stats and statNames[j] and stats:FindFirstChild(statNames[j])
                row.stats[j].Text = obj and isStat(obj) and tostring(obj.Value) or (statNames[j] and "—" or "")
            end
        end
        for player, row in pairs(items) do
            if not alive[player] then row.button:Destroy(); items[player] = nil end
        end
        local height = math.min(#players, MAX_ROWS) * ROW
        panel.Size = UDim2.fromOffset(W, HEADER + height + 7)
        scroll.CanvasSize = UDim2.fromOffset(0, #players * ROW)
    end
    refresh()
    local elapsed = 0
    track(RunService.Heartbeat:Connect(function(dt)
        elapsed = elapsed + dt
        if elapsed >= 0.5 then
            elapsed = 0
            local ok, err = pcall(refresh)
            if not ok then warn("[Satanic] Player list: " .. tostring(err)) end
        end
        -- Gradient animation updates this shared accent continuously.
        if panel.Visible and topAccent.Parent then topAccent.BackgroundColor3 = Theme.BloodRed end
    end))
    track(close.MouseButton1Click:Connect(function() panel.Visible = false end))
    local function onTab(_, state)
        if Theme.CapturingKey or UserInputService:GetFocusedTextBox() then return Enum.ContextActionResult.Pass end
        if state == Enum.UserInputState.Begin then panel.Visible = not panel.Visible end
        return Enum.ContextActionResult.Sink
    end
    local okBind = pcall(function()
        ContextActionService:BindActionAtPriority("SatanicThemedPlayerList", onTab, false, 10000, Enum.KeyCode.Tab)
    end)
    if not okBind then error("Cannot bind Tab") end
    local okCore = pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, false) end)
    if not okCore then error("не удалось скрыть стандартный список игроков") end
end
local ok, err = pcall(initThemedRoster)
if not ok then
    if rollbackRoster then pcall(rollbackRoster) end
    warn("[Satanic] Не удалось создать список игроков: " .. tostring(err))
end
end

-- ===================== PVP v2 — полностью переписанный боевой модуль =====================
-- Всё считается на клиенте: аим/инфо видны только вам, атаки/блок идут через
-- инструменты персонажа и разрешённые клиенту действия (Tool:Activate / VirtualUser).
-- Rage / Legit / FOV / highlight / hitboxes only; Combat page and its workers removed.
do
local function initPvP()
    local SECS = Theme.Sections or {}
    local secAim, secTarget, secHitbox = SECS.pvpAim, SECS.pvpTarget, SECS.pvpHitbox
    local secLegit = SECS.pvpLegit
    if not secAim then return end

    -- ------------------------------------------------------------------ состояние
    local State = {
        aim = {
            enabled = false, mode = 1, activation = 1, priority = 1, part = 1,
            fov = 120, smooth = 55, predict = 8, maxDist = 500,
            wallCheck = true, teamCheck = true, sticky = true, stickyTime = 0.65,
            humanize = false, jitter = 25, autoFire = false, fireRate = 0.12,
            mouseSens = 1.0,
        },
        fov = { draw = true, filled = false, thickness = 1, opacity = 55, sides = 64,
                color = Color3.fromRGB(255, 55, 140) },
        highlight = { enabled = false, fill = Color3.fromRGB(255, 40, 130), outline = Color3.fromRGB(43, 224, 255),
                      transparency = 0.55, info = true, infoColor = Color3.fromRGB(255, 255, 255) },
        hitbox = { enabled = false, size = 9, range = 40, ghost = true, targetOnly = false },
        legit = { enabled = false, fov = 42, smooth = 30, curve = 1, jitter = 12,
                  maxDist = 220, wallCheck = true,
                  trigger = false, triggerRange = 6, triggerDelay = 0.06, triggerVisible = true },
        target = nil, targetPart = nil, legitTarget = nil, targetSince = 0,
    }
    Theme.PvP = State

    local hasDrawing = false
    pcall(function() hasDrawing = Drawing ~= nil and Drawing.new ~= nil end)
    local mouseAim = false
    pcall(function() mouseAim = type(mousemoverel) == "function" end)
    local VU = nil
    pcall(function() VU = game:GetService("VirtualUser") end)

    local function now() return os.clock() end

    local aimHeld, lmbHeld = false, false
    local aimKeyDown = false
    local lastAimShot, triggerAt = 0, 0

    ------------------------------------------------------------------ помощники
    local function myCharacter()
        local char = LocalPlayer and LocalPlayer.Character
        if not char then return nil end
        local hum = char:FindFirstChildOfClass("Humanoid")
        local root = char:FindFirstChild("HumanoidRootPart")
        if not hum or not root or hum.Health <= 0 then return nil end
        return char, hum, root
    end

    local function aliveChar(player)
        if not player or player == LocalPlayer then return nil end
        local char = player.Character
        if not char then return nil end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum and hum.Health > 0 then return char, hum end
        return nil
    end

    local function sameTeam(player)
        local myTeam = LocalPlayer and LocalPlayer.Team
        if not myTeam then return false end
        return player.Team == myTeam
    end

    local function rayParams(extra)
        local params = RaycastParams.new()
        local ok = pcall(function() params.FilterType = Enum.RaycastFilterType.Exclude end)
        if not ok then pcall(function() params.FilterType = Enum.RaycastFilterType.Blacklist end) end
        local ignore = {}
        local myChar = LocalPlayer and LocalPlayer.Character
        if myChar then ignore[#ignore + 1] = myChar end
        if extra then ignore[#ignore + 1] = extra end
        pcall(function() params.FilterDescendantsInstances = ignore end)
        pcall(function() params.IgnoreWater = true end)
        return params
    end

    local function partVisible(part)
        if not part or not Camera then return false end
        local ok, result = pcall(function()
            local origin = Camera.CFrame.Position
            return workspace:Raycast(origin, part.Position - origin, rayParams(part.Parent))
        end)
        if not ok then return true end
        return result == nil
    end

    local function partOf(char, mode)
        if not char then return nil end
        if mode == 2 then
            return char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") or char:FindFirstChild("HumanoidRootPart")
        elseif mode == 3 then
            local best, bestDist
            local mouse = UserInputService:GetMouseLocation()
            for _, name in ipairs({"Head", "UpperTorso", "Torso", "HumanoidRootPart", "LeftUpperArm", "RightUpperArm"}) do
                local p = char:FindFirstChild(name)
                if p then
                    local ok, sp, onScreen = pcall(function() return Camera:WorldToViewportPoint(p.Position) end)
                    if ok and onScreen then
                        local d = (Vector2.new(sp.X, sp.Y) - mouse).Magnitude
                        if not bestDist or d < bestDist then best, bestDist = p, d end
                    end
                end
            end
            return best or char:FindFirstChild("Head")
        elseif mode == 4 then
            local list = {}
            for _, name in ipairs({"Head", "UpperTorso", "Torso", "HumanoidRootPart"}) do
                local p = char:FindFirstChild(name)
                if p then list[#list + 1] = p end
            end
            if #list == 0 then return nil end
            return list[math.random(1, #list)]
        end
        return char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
    end

    local function screenPoint(part)
        if not part then return nil end
        local ok, sp, onScreen = pcall(function() return Camera:WorldToViewportPoint(part.Position) end)
        if not ok or not onScreen then return nil end
        return Vector2.new(sp.X, sp.Y), (Camera.CFrame.Position - part.Position).Magnitude
    end

    local function validTarget(player, teamCheck, checkWall)
        local char = aliveChar(player)
        if not char then return nil end
        if teamCheck and sameTeam(player) then return nil end
        local targetPart = partOf(char, State.aim.part)
        if not targetPart then return nil end
        if checkWall and not partVisible(targetPart) then return nil end
        return char, targetPart
    end

    local function pickAimTarget()
        local aim = State.aim
        local center = Camera.ViewportSize / 2
        local mouse = UserInputService:GetMouseLocation()
        local origin = center
        if aim.priority == 1 then origin = mouse end
        local best, bestScore, bestPart
        for _, player in ipairs(Players:GetPlayers()) do
            local char, targetPart = validTarget(player, aim.teamCheck, aim.wallCheck)
            if char and targetPart then
                local point, dist = screenPoint(targetPart)
                if dist and dist <= aim.maxDist then
                    local score
                    if aim.priority == 3 then
                        score = dist
                    elseif point then
                        score = (point - origin).Magnitude
                        if score > aim.fov then score = nil end
                    end
                    if score and (not bestScore or score < bestScore) then
                        best, bestScore, bestPart = player, score, targetPart
                    end
                end
            end
        end
        return best, bestPart
    end

    local function fireAttack()
        local char = LocalPlayer and LocalPlayer.Character
        if not char then return end
        local tool = char:FindFirstChildOfClass("Tool")
        if tool then pcall(function() tool:Activate() end) end
        if type(mouse1click) == "function" then
            pcall(mouse1click)
        elseif type(mouse1press) == "function" and type(mouse1release) == "function" then
            pcall(mouse1press); pcall(mouse1release)
        elseif VU then
            pcall(function() VU:ClickButton1(Vector2.new(0, 0)) end)
        end
    end

    ------------------------------------------------------------------ 1. AIM ASSIST (Rage)
    secAim:AddToggle("Aim Assist", false, function(state)
        State.aim.enabled = state
        if not state then State.target = nil; State.targetPart = nil end
    end, function(api)
        local modeBtn
        modeBtn = api:AddButton("Способ: камера", function()
            State.aim.mode = (State.aim.mode % 2) + 1
            modeBtn.Text = State.aim.mode == 1 and "Способ: камера" or "Способ: мышь"
        end)
        local actBtn
        actBtn = api:AddButton("Активация: всегда", function()
            State.aim.activation = (State.aim.activation % 3) + 1
            local names = {"Активация: всегда", "Активация: ПКМ", "Активация: ЛКМ"}
            actBtn.Text = names[State.aim.activation]
        end)
        local prioBtn
        prioBtn = api:AddButton("Приоритет: курсор", function()
            State.aim.priority = (State.aim.priority % 3) + 1
            local names = {"Приоритет: курсор", "Приоритет: центр", "Приоритет: дистанция"}
            prioBtn.Text = names[State.aim.priority]
        end)
        local partBtn
        partBtn = api:AddButton("Часть: голова", function()
            State.aim.part = (State.aim.part % 4) + 1
            local names = {"Часть: голова", "Часть: торс", "Часть: ближе к курсору", "Часть: случайная"}
            partBtn.Text = names[State.aim.part]
        end)
        api:AddSlider("FOV радиус", 20, 500, State.aim.fov, function(v) State.aim.fov = v end)
        api:AddSlider("Плавность (%)", 1, 100, State.aim.smooth, function(v) State.aim.smooth = v end)
        api:AddSlider("Предсказание (x100)", 0, 40, State.aim.predict, function(v) State.aim.predict = v end)
        api:AddSlider("Макс. дистанция", 20, 1000, State.aim.maxDist, function(v) State.aim.maxDist = v end)
        api:AddSlider("Чувствительность мыши", 10, 300, math.floor(State.aim.mouseSens * 100), function(v)
            State.aim.mouseSens = v / 100
        end)
        api:AddToggle("Проверка стен", true, function(v) State.aim.wallCheck = v end)
        api:AddToggle("Игнорировать своих", true, function(v) State.aim.teamCheck = v end)
        api:AddToggle("Держать цель", true, function(v) State.aim.sticky = v end)
        api:AddSlider("Время удержания (x100)", 10, 200, math.floor(State.aim.stickyTime * 100), function(v)
            State.aim.stickyTime = v / 100
        end)
        api:AddToggle("Гуманизация (дрожь)", false, function(v) State.aim.humanize = v end)
        api:AddSlider("Сила дрожи", 1, 100, State.aim.jitter, function(v) State.aim.jitter = v end)
        api:AddToggle("Авто-выстрел по цели", false, function(v) State.aim.autoFire = v end)
        api:AddSlider("Скорость выстрела (x100 с)", 5, 100, math.floor(State.aim.fireRate * 100), function(v)
            State.aim.fireRate = v / 100
        end)
    end)

    ------------------------------------------------------------------ 2. TARGET & FOV
    if secTarget then
        secTarget:AddToggle("Круг FOV", true, function(v) State.fov.draw = v end, function(api)
            api:AddToggle("Залить круг", false, function(v) State.fov.filled = v end)
            api:AddSlider("Толщина", 1, 6, State.fov.thickness, function(v) State.fov.thickness = v end)
            api:AddSlider("Прозрачность (%)", 5, 100, State.fov.opacity, function(v) State.fov.opacity = v end)
            api:AddSlider("Сегментов", 16, 128, State.fov.sides, function(v) State.fov.sides = v end)
            local h, s, v = State.fov.color:ToHSV()
            api:AddColorPicker(h, s, v, function(nh, ns, nv) State.fov.color = Color3.fromHSV(nh, ns, nv) end)
        end)

        secTarget:AddToggle("Подсветка цели", false, function(v)
            State.highlight.enabled = v
        end, function(api)
            local h1, s1, v1 = State.highlight.fill:ToHSV()
            api:AddColorPicker(h1, s1, v1, function(nh, ns, nv) State.highlight.fill = Color3.fromHSV(nh, ns, nv) end)
            local h2, s2, v2 = State.highlight.outline:ToHSV()
            api:AddColorPicker(h2, s2, v2, function(nh, ns, nv) State.highlight.outline = Color3.fromHSV(nh, ns, nv) end)
            api:AddSlider("Прозрачность (%)", 0, 100, math.floor((1 - State.highlight.transparency) * 100), function(v)
                State.highlight.transparency = 1 - v / 100
            end)
            api:AddToggle("Текст над целью (HP / дистанция)", true, function(v) State.highlight.info = v end)
            local h3, s3, v3 = State.highlight.infoColor:ToHSV()
            api:AddColorPicker(h3, s3, v3, function(nh, ns, nv) State.highlight.infoColor = Color3.fromHSV(nh, ns, nv) end)
        end)

        secTarget:AddButton("Сбросить цель", function()
            State.target = nil
            State.targetPart = nil
            State.targetSince = 0
        end)
    end

    ------------------------------------------------------------------ 3. LEGIT AIM + TRIGGER
    if secLegit then
        secLegit:AddToggle("Legit Aim (на ЛКМ)", false, function(v) State.legit.enabled = v end, function(api)
            api:AddSlider("FOV радиус", 10, 200, State.legit.fov, function(v) State.legit.fov = v end)
            api:AddSlider("Плавность (%)", 1, 100, State.legit.smooth, function(v) State.legit.smooth = v end)
            api:AddSlider("Макс. дистанция", 20, 500, State.legit.maxDist, function(v) State.legit.maxDist = v end)
            local curveBtn
            curveBtn = api:AddButton("Кривая: линейная", function()
                State.legit.curve = (State.legit.curve % 3) + 1
                local names = {"Кривая: линейная", "Кривая: ease-out", "Кривая: человеческая"}
                curveBtn.Text = names[State.legit.curve]
            end)
            api:AddSlider("Дрожь (%)", 0, 100, State.legit.jitter, function(v) State.legit.jitter = v end)
            api:AddToggle("Проверка стен", true, function(v) State.legit.wallCheck = v end)
        end)

        secLegit:AddToggle("Trigger Bot", false, function(v) State.legit.trigger = v end, function(api)
            api:AddSlider("Прицельный радиус (px)", 1, 60, State.legit.triggerRange, function(v) State.legit.triggerRange = v end)
            api:AddSlider("Задержка (x1000 с)", 0, 500, math.floor(State.legit.triggerDelay * 1000), function(v)
                State.legit.triggerDelay = v / 1000
            end)
            api:AddToggle("Только видимых", true, function(v) State.legit.triggerVisible = v end)
        end)
    end

    ------------------------------------------------------------------ Drawing-объекты
    local fovCircle, infoText
    registerCleanup(function()
        pcall(function() if fovCircle then fovCircle:Remove() end end)
        pcall(function() if infoText then infoText:Remove() end end)
    end)

    local function ensureFov()
        if not hasDrawing then return nil end
        if fovCircle then return fovCircle end
        local ok, circle = pcall(function() return Drawing.new("Circle") end)
        if not ok or not circle then return nil end
        fovCircle = circle
        return fovCircle
    end
    local function ensureInfo()
        if not hasDrawing then return nil end
        if infoText then return infoText end
        local ok, text = pcall(function() return Drawing.new("Text") end)
        if not ok or not text then return nil end
        text.Size = 13; text.Center = true; text.Outline = true; text.Font = 2
        infoText = text
        return infoText
    end
    ------------------------------------------------------------------ Ввод
    track(UserInputService.InputBegan:Connect(function(input, processed)
        if Unloaded then return end
        if input.UserInputType == Enum.UserInputType.MouseButton2 then
            aimHeld = true
        elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
            lmbHeld = true
            if State.legit.trigger then triggerAt = now() + State.legit.triggerDelay end
        end
    end))
    track(UserInputService.InputEnded:Connect(function(input)
        if Unloaded then return end
        if input.UserInputType == Enum.UserInputType.MouseButton2 then
            aimHeld = false
        elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
            lmbHeld = false
        end
    end))

    ------------------------------------------------------------------ Рендер-цикл
    local highlightByPlayer = {}
    local function clearHighlights(exceptPlayer)
        for player, hl in pairs(highlightByPlayer) do
            if player ~= exceptPlayer then
                pcall(function() if hl then hl:Destroy() end end)
                highlightByPlayer[player] = nil
            end
        end
    end
    registerCleanup(function() clearHighlights(nil) end)

    local function applyHighlight(player, char)
        clearHighlights(player)
        if not (player and char) then return end
        local hl = highlightByPlayer[player]
        if not hl or not hl.Parent then
            hl = Instance.new("Highlight")
            hl.Name = "SatanicTargetHighlight"
            pcall(function() hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop end)
            pcall(function() hl.Parent = char end)
            highlightByPlayer[player] = hl
        end
        hl.FillColor = State.highlight.fill
        hl.OutlineColor = State.highlight.outline
        hl.FillTransparency = State.highlight.transparency
        hl.OutlineTransparency = 0
    end

    local function updateFovVisual()
        local circle = ensureFov()
        if not circle then return end
        local aim, fov = State.aim, State.fov
        local showAim = aim.enabled and (aim.activation == 1 or aimHeld or (aim.activation == 3 and lmbHeld))
        if not (fov.draw and (showAim or State.legit.enabled)) then
            circle.Visible = false
            return
        end
        circle.Position = Camera.ViewportSize / 2
        circle.Radius = showAim and aim.fov or math.max(State.legit.fov, 12)
        circle.Color = fov.color
        circle.Thickness = fov.thickness
        circle.Filled = fov.filled
        circle.NumSides = fov.sides
        circle.Transparency = fov.opacity / 100
        circle.Visible = true
    end

    local function aimAt(part, dt, smoothPercent, humanize, jitterAmount)
        local camCF = Camera.CFrame
        local goalPos = part.Position
        local aim = State.aim
        if aim.predict > 0 then
            local vel = part.AssemblyLinearVelocity
            if vel then goalPos = goalPos + vel * (aim.predict / 100) end
        end
        if humanize and jitterAmount > 0 then
            local j = (jitterAmount / 100) * 0.55
            goalPos = goalPos + Vector3.new((math.random() - 0.5) * j, (math.random() - 0.5) * j, (math.random() - 0.5) * j)
        end
        local goal = CFrame.lookAt(camCF.Position, goalPos)
        local rate = 3 + (100 - math.clamp(smoothPercent, 1, 100)) * 0.55
        local alpha = math.clamp(1 - math.exp(-rate * dt), 0.02, 1)

        if aim.mode == 2 and mouseAim then
            local ok, sp, onScreen = pcall(function() return Camera:WorldToViewportPoint(goalPos) end)
            if ok and onScreen then
                local center = Camera.ViewportSize / 2
                local dx = (sp.X - center.X) * alpha * aim.mouseSens
                local dy = (sp.Y - center.Y) * alpha * aim.mouseSens
                pcall(mousemoverel, dx, dy)
                return
            end
        end
        Camera.CFrame = camCF:Lerp(goal, alpha)
    end

    local function renderStep(dt)
        if Unloaded or not Camera then return end
        dt = math.clamp(dt or 0.016, 0.001, 0.1)
        local aim = State.aim
        local activeAim = aim.enabled and (aim.activation == 1 or aimHeld or (aim.activation == 3 and lmbHeld))

        if activeAim then
            local target, targetPart = nil, nil
            if aim.sticky and State.target then
                local keepChar = aliveChar(State.target)
                local keepPart = keepChar and partOf(keepChar, aim.part)
                if keepPart and ((not aim.wallCheck) or partVisible(keepPart)) then
                    local _, keepDist = screenPoint(keepPart)
                    if keepDist and keepDist <= aim.maxDist * 1.25 then
                        target, targetPart = State.target, keepPart
                    end
                end
            end
            if not target then
                target, targetPart = pickAimTarget()
                State.targetSince = now()
            end
            if target and targetPart then
                State.target, State.targetPart = target, targetPart
                aimAt(targetPart, dt, aim.smooth, aim.humanize, aim.jitter)
                if aim.autoFire and now() - lastAimShot >= aim.fireRate then
                    lastAimShot = now()
                    fireAttack()
                end
            else
                State.target, State.targetPart = nil, nil
            end
        else
            State.target, State.targetPart = nil, nil
        end
        -- Цель «залипала» после выключения аима и поддерживала блок подсветки/HUD
        -- в работе каждый кадр. Сбрасываем её, пока аим неактивен.
        if not activeAim and (State.target or State.targetPart) then
            State.target, State.targetPart = nil, nil
        end

        -- Legit Aim: только пока зажата ЛКМ и не активен Rage-аим
        if State.legit.enabled and lmbHeld and not activeAim then
            local best, bestDist, bestPart = nil, nil, nil
            local center = Camera.ViewportSize / 2
            for _, player in ipairs(Players:GetPlayers()) do
                local char, p = validTarget(player, State.aim.teamCheck, State.legit.wallCheck)
                if char and p then
                    local point, dist = screenPoint(p)
                    if point and dist <= State.legit.maxDist then
                        local d = (point - center).Magnitude
                        if d <= State.legit.fov and (not bestDist or d < bestDist) then
                            best, bestDist, bestPart = player, d, p
                        end
                    end
                end
            end
            if bestPart then
                local smooth = State.legit.smooth
                if State.legit.curve == 2 then smooth = math.max(1, smooth * 0.6) end
                if State.legit.curve == 3 then smooth = smooth * (0.8 + math.random() * 0.4) end
                aimAt(bestPart, dt, smooth, State.legit.jitter > 0, State.legit.jitter * 0.6)
                State.legitTarget = best
            else
                State.legitTarget = nil
            end
        elseif not State.legit.enabled then
            State.legitTarget = nil
        end

        -- Trigger Bot
        if State.legit.trigger then
            local center = Camera.ViewportSize / 2
            for _, player in ipairs(Players:GetPlayers()) do
                local char, p = validTarget(player, State.aim.teamCheck, State.legit.triggerVisible)
                if char and p then
                    local point = screenPoint(p)
                    if point and (point - center).Magnitude <= State.legit.triggerRange then
                        if now() >= triggerAt then
                            triggerAt = now() + math.max(State.legit.triggerDelay, 0.02)
                            fireAttack()
                        end
                        break
                    end
                end
            end
        end

        -- Подсветка / текст / HUD
        local shown = State.target or State.legitTarget
        if shown then
            local char, hum = aliveChar(shown)
            if char and hum then
                if State.highlight.enabled then
                    applyHighlight(shown, char)
                end
                local part = (State.target == shown and State.targetPart) or partOf(char, State.aim.part)
                if State.highlight.enabled and State.highlight.info and part then
                    local text = ensureInfo()
                    if text then
                        local _, _, root = myCharacter()
                        local rootPart = char:FindFirstChild("HumanoidRootPart")
                        local dist = (root and rootPart) and math.floor((root.Position - rootPart.Position).Magnitude) or 0
                        local ok, sp, onScreen = pcall(function()
                            return Camera:WorldToViewportPoint(part.Position + Vector3.new(0, 1.6, 0))
                        end)
                        if ok and onScreen then
                            text.Text = string.format("%s  %d%%  %dm", shown.Name,
                                math.floor((hum.Health / math.max(hum.MaxHealth, 1)) * 100), dist)
                            text.Position = Vector2.new(sp.X, sp.Y)
                            text.Color = State.highlight.infoColor
                            text.Visible = true
                        else
                            text.Visible = false
                        end
                    end
                elseif infoText then
                    infoText.Visible = false
                end
            else
                clearHighlights(nil)
                if infoText then infoText.Visible = false end
            end
        else
            clearHighlights(nil)
            if infoText then infoText.Visible = false end
        end
        if not State.highlight.enabled and next(highlightByPlayer) then clearHighlights(nil) end

        updateFovVisual()
    end

    RunService:BindToRenderStep("SatanicPvPRender", Enum.RenderPriority.Camera.Value + 1, renderStep)
    registerCleanup(function() pcall(function() RunService:UnbindFromRenderStep("SatanicPvPRender") end) end)

    ------------------------------------------------------------------ Тик-цикл: хитбоксы
    local modifiedHitboxes = {}
    local tickClock = 0

    local function restoreHitboxes()
        for part, old in pairs(modifiedHitboxes) do
            pcall(function()
                if part and part.Parent then
                    part.Size = old.size
                    part.Transparency = old.transparency
                end
            end)
        end
        table.clear(modifiedHitboxes)
    end
    registerCleanup(restoreHitboxes)

    -- Hitbox создаём здесь: восстановление должно быть общим с тик-циклом.
    if secHitbox then
        secHitbox:AddToggle("Hitbox Expander", false, function(state)
            State.hitbox.enabled = state
            if not state then restoreHitboxes() end
        end, function(api)
            api:AddSlider("Размер хитбокса", 2, 30, State.hitbox.size, function(v) State.hitbox.size = v end)
            api:AddSlider("Радиус применения", 5, 200, State.hitbox.range, function(v) State.hitbox.range = v end)
            api:AddToggle("Прозрачный (призрак)", true, function(v) State.hitbox.ghost = v end)
            api:AddToggle("Только по цели аима", false, function(v) State.hitbox.targetOnly = v end)
        end)
        secHitbox:AddButton("Вернуть хитбоксы", function() restoreHitboxes() end)
    end

    local function enemiesInRange(range, needVisible)
        local _, _, myRoot = myCharacter()
        if not myRoot then return {} end
        local list = {}
        for _, player in ipairs(Players:GetPlayers()) do
            local char, hum = aliveChar(player)
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if root then
                local dist = (root.Position - myRoot.Position).Magnitude
                if dist <= range and not (State.aim.teamCheck and sameTeam(player)) then
                    if not needVisible or partVisible(root) then
                        list[#list + 1] = {player = player, char = char, hum = hum, root = root, dist = dist}
                    end
                end
            end
        end
        table.sort(list, function(a, b) return a.dist < b.dist end)
        return list
    end

    local function tickStep()
        if Unloaded then return end
        local _, hum, myRoot = myCharacter()
        if not hum then
            if next(modifiedHitboxes) then restoreHitboxes() end
            return
        end

        local clock = now()
        -- Hitbox Expander
        local hb = State.hitbox
        if hb.enabled then
            local size = Vector3.new(hb.size, hb.size, hb.size)
            local wanted = {}
            if hb.targetOnly then
                local targetChar = State.target and State.target.Character
                local root = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
                if root then wanted[#wanted + 1] = root end
            else
                for _, entry in ipairs(enemiesInRange(hb.range, false)) do
                    wanted[#wanted + 1] = entry.root
                end
            end
            for _, part in ipairs(wanted) do
                if modifiedHitboxes[part] == nil then
                    modifiedHitboxes[part] = {size = part.Size, transparency = part.Transparency}
                end
                pcall(function()
                    part.Size = size
                    if hb.ghost then part.Transparency = 0.55 end
                end)
            end
            for part in pairs(modifiedHitboxes) do
                local stillWanted = false
                for _, p2 in ipairs(wanted) do
                    if p2 == part then stillWanted = true; break end
                end
                if not stillWanted then
                    pcall(function()
                        if part and part.Parent then
                            part.Size = modifiedHitboxes[part].size
                            part.Transparency = modifiedHitboxes[part].transparency
                        end
                    end)
                    modifiedHitboxes[part] = nil
                end
            end
        elseif next(modifiedHitboxes) then
            restoreHitboxes()
        end
    end

    track(RunService.Heartbeat:Connect(function(dt)
        if Unloaded then return end
        tickClock = tickClock + (dt or 0)
        if tickClock < 0.08 then return end
        tickClock = 0
        local ok, err = pcall(tickStep)
        if not ok and not State._warned then
            State._warned = true
            warn("[Satanic PvP] " .. tostring(err))
        end
    end))

    track(Players.PlayerRemoving:Connect(function(player)
        local hl = highlightByPlayer[player]
        if hl then pcall(function() hl:Destroy() end); highlightByPlayer[player] = nil end
    end))
end

local ok, err = pcall(initPvP)
if not ok then warn("[Satanic UI] Rage/Legit: " .. tostring(err)) end
end


-- ===================== MOVEMENT: SPEED / FLY / DASH / PHYSICS =====================
-- Всё клиентское: значения возвращаются назад при выключении тумблера или скрипта.
do
local function initMovement()
    local S = Theme.Sections or {}
    local secSpeed, secFly, secUtil = S.moveSpeed, S.moveFly, S.moveUtility
    local secPhysics = S.movePhysics
    if not (secSpeed and secFly) then return end

    local State = {
        walk = {enabled = false, value = 32, base = nil},
        jump = {enabled = false, value = 62, base = nil, baseUseJumpPower = nil, baseJumpHeight = nil},
        infjump = false,
        bunny = false,
        fastFall = false,
        antiFling = false,
        fly = {enabled = false, speed = 65},
        noclip = false,
        gravity = {enabled = false, value = 196, base = nil},
        antiAfk = false,
        bunnyInterval = 0.08,
        lastJump = 0,
    }
    Theme.Movement = State

    local function humanoid()
        local char = LocalPlayer and LocalPlayer.Character
        if not char then return nil end
        local hum = char:FindFirstChildOfClass("Humanoid")
        local root = char:FindFirstChild("HumanoidRootPart")
        if not hum or not root then return nil end
        return char, hum, root
    end

    -- ---------- SPEED & JUMP ----------
    local function applyWalk()
        local _, hum = humanoid()
        if not hum then return end
        if State.walk.enabled then
            if State.walk.base == nil then State.walk.base = hum.WalkSpeed end
            if math.abs(hum.WalkSpeed - State.walk.value) > 0.01 then hum.WalkSpeed = State.walk.value end
        elseif State.walk.base ~= nil then
            pcall(function() hum.WalkSpeed = State.walk.base end)
            State.walk.base = nil
        end
    end

    local function applyJump()
        local _, hum = humanoid()
        if not hum then return end
        if State.jump.enabled then
            if State.jump.base == nil then
                State.jump.base = hum.JumpPower
                State.jump.baseUseJumpPower = hum.UseJumpPower
                State.jump.baseJumpHeight = hum.JumpHeight
            end
            pcall(function()
                hum.UseJumpPower = true
                if math.abs(hum.JumpPower - State.jump.value) > 0.01 then hum.JumpPower = State.jump.value end
            end)
        elseif State.jump.base ~= nil then
            pcall(function()
                hum.JumpPower = State.jump.base
                hum.JumpHeight = State.jump.baseJumpHeight
                hum.UseJumpPower = State.jump.baseUseJumpPower
            end)
            State.jump.base = nil
        end
    end

    secSpeed:AddToggle("Walk Speed", false, function(state)
        State.walk.enabled = state
        applyWalk()
    end, function(api)
        api:AddSlider("Speed", 8, 250, State.walk.value, function(v)
            State.walk.value = v
            if State.walk.enabled then applyWalk() end
        end)
        api:AddButton("Reset to 16", function()
            State.walk.value = 16
            if State.walk.enabled then local _, hum = humanoid(); if hum then hum.WalkSpeed = 16 end end
        end)
    end)

    secSpeed:AddToggle("Jump Power", false, function(state)
        State.jump.enabled = state
        applyJump()
    end, function(api)
        api:AddSlider("Jump power", 20, 250, State.jump.value, function(v)
            State.jump.value = v
            if State.jump.enabled then applyJump() end
        end)
    end)

    secSpeed:AddToggle("Infinite Jump", false, function(state) State.infjump = state end)
    secSpeed:AddToggle("Bunny Hop (auto jump)", false, function(state) State.bunny = state end, function(api)
        api:AddSlider("Bunny hop interval (ms)", 20, 400, math.floor(State.bunnyInterval * 1000), function(v)
            State.bunnyInterval = v / 1000
        end)
    end)

    track(UserInputService.JumpRequest:Connect(function()
        if Unloaded or not State.infjump then return end
        local _, hum = humanoid()
        if hum and hum:GetState() ~= Enum.HumanoidStateType.Dead then
            pcall(function() hum:ChangeState(Enum.HumanoidStateType.Jumping) end)
        end
    end))

    -- ---------- FLY ----------
    local flyBody

    local function stopFly()
        if flyBody then
            pcall(function() flyBody:Destroy() end)
            flyBody = nil
        end
        local _, _, root = humanoid()
        if root then pcall(function() root.AssemblyLinearVelocity = Vector3.new(0, 0, 0) end) end
    end

    local function startFly()
        local _, _, root = humanoid()
        if not root then return end
        stopFly()
        local bv = Instance.new("BodyVelocity")
        bv.Name = "SatanicFly"
        bv.MaxForce = Vector3.new(100000, 100000, 100000)
        bv.Velocity = Vector3.new(0, 0, 0)
        bv.P = 1250
        bv.Parent = root
        flyBody = bv
    end

    local function flyStep()
        if not State.fly.enabled or not Camera then return end
        local _, _, root = humanoid()
        if not root then
            stopFly()
            return
        end
        if not flyBody or not flyBody.Parent then startFly() end
        if not flyBody then return end
        local cam = Camera.CFrame
        local dir = Vector3.new(0, 0, 0)
        if UserInputService:IsKeyDown(Enum.KeyCode.W) then dir = dir + cam.LookVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.S) then dir = dir - cam.LookVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.D) then dir = dir + cam.RightVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.A) then dir = dir - cam.RightVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.Space) then dir = dir + Vector3.new(0, 1, 0) end
        if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then
            dir = dir - Vector3.new(0, 1, 0)
        end
        if dir.Magnitude > 0.01 then
            dir = dir.Unit * State.fly.speed
        else
            dir = Vector3.new(0, 0, 0)
        end
        pcall(function() flyBody.Velocity = dir end)
    end

    secFly:AddToggle("Fly", false, function(state)
        State.fly.enabled = state
        if state then startFly() else stopFly() end
    end, function(api)
        api:AddSlider("Fly speed", 10, 300, State.fly.speed, function(v) State.fly.speed = v end)
        api:AddButton("Стоп полёт", function() stopFly() end)
    end)
    registerCleanup(stopFly)

    -- ---------- NOCLIP ----------
    local savedCollide = {}
    local function applyNoClip()
        local char = LocalPlayer.Character
        if not char then return end
        if State.noclip then
            for _, part in ipairs(char:GetDescendants()) do
                if part:IsA("BasePart") then
                    if savedCollide[part] == nil then savedCollide[part] = part.CanCollide end
                    part.CanCollide = false
                end
            end
        else
            for part, value in pairs(savedCollide) do
                pcall(function() if part and part.Parent then part.CanCollide = value end end)
            end
            table.clear(savedCollide)
        end
    end
    secFly:AddToggle("No Clip", false, function(state)
        State.noclip = state
        applyNoClip()
    end, function(api)
        api:AddButton("Обновить части персонажа", applyNoClip)
    end)
    registerCleanup(function() State.noclip = false; applyNoClip() end)

    -- ---------- PHYSICS ----------

    secPhysics:AddToggle("Fast Fall", false, function(state) State.fastFall = state end)
    secPhysics:AddToggle("Anti-Fling", false, function(state) State.antiFling = state end)
    secPhysics:AddToggle("Custom Gravity", false, function(state)
        State.gravity.enabled = state
        if state then
            State.gravity.base = workspace.Gravity
            workspace.Gravity = State.gravity.value
        elseif State.gravity.base then
            workspace.Gravity = State.gravity.base
            State.gravity.base = nil
        end
    end, function(api)
        api:AddSlider("Gravity", 0, 400, State.gravity.value, function(v)
            State.gravity.value = v
            if State.gravity.enabled then workspace.Gravity = v end
        end)
    end)
    registerCleanup(function()
        if State.gravity.base then workspace.Gravity = State.gravity.base end
    end)

    -- ---------- UTILITY ----------
    secUtil:AddToggle("Anti-AFK", false, function(state) State.antiAfk = state end, function(api)
        api:AddButton("Проверить сейчас", function()
            local vu = game:GetService("VirtualUser")
            pcall(function() vu:CaptureController() end)
            pcall(function() vu:ClickButton2(Vector2.new()) end)
        end)
    end)
    secUtil:AddButton("Reset character", function()
        local _, hum = humanoid()
        if hum then pcall(function() hum.Health = 0 end) end
    end)
    secUtil:AddButton("Restore movement (все настройки)", function()
        State.walk.enabled = false; State.jump.enabled = false
        State.fly.enabled = false; State.noclip = false
        State.fastFall = false; State.antiFling = false
        State.infjump = false; State.bunny = false
        applyWalk(); applyJump(); stopFly(); applyNoClip()
        if State.gravity.base then workspace.Gravity = State.gravity.base; State.gravity.base = nil end
        State.gravity.enabled = false
    end)

    track(LocalPlayer.Idled:Connect(function()
        if Unloaded or not State.antiAfk then return end
        local vu = game:GetService("VirtualUser")
        pcall(function() vu:CaptureController() end)
        pcall(function() vu:ClickButton2(Vector2.new()) end)
    end))

    -- ---------- цикл ----------
    local speedClock, physicsClock = 0, 0
    track(RunService.Heartbeat:Connect(function(dt)
        if Unloaded then return end
        speedClock = speedClock + dt
        if speedClock >= 0.2 then
            speedClock = 0
            if State.walk.enabled then applyWalk() end
            if State.jump.enabled then applyJump() end
            if State.noclip then applyNoClip() end
            if State.bunny then
                local _, hum = humanoid()
                if hum and hum.FloorMaterial ~= Enum.Material.Air and os.clock() - State.lastJump > State.bunnyInterval then
                    State.lastJump = os.clock()
                    pcall(function() hum.Jump = true end)
                end
            end
        end
        flyStep()
        physicsClock = physicsClock + dt
        if physicsClock >= 0.05 then
            physicsClock = 0
            local _, hum, root = humanoid()
            if root then
                if State.fastFall and hum and hum.FloorMaterial == Enum.Material.Air then
                    local v = root.AssemblyLinearVelocity
                    if v.Y > -70 then
                        pcall(function() root.AssemblyLinearVelocity = Vector3.new(v.X, v.Y - 60, v.Z) end)
                    end
                end
                if State.antiFling then
                    local angular = root.AssemblyAngularVelocity
                    if angular.Magnitude > 25 then pcall(function() root.AssemblyAngularVelocity = Vector3.new(0, 0, 0) end) end
                    local linear = root.AssemblyLinearVelocity
                    if linear.Magnitude > 900 then
                        pcall(function() root.AssemblyLinearVelocity = linear.Unit * 900 end)
                    end
                end
            end
        end
    end))
end

local ok, err = pcall(initMovement)
if not ok then warn("[Satanic UI] Movement модуль: " .. tostring(err)) end
end

-- ===================== TAB → INTERFACE: прозрачность, цвета, эффекты =====================
do
local function initInterfaceSettings()
    local previousCategory = Nav.currentCategory
    Nav.titles.TAB = "TAB"
    Nav.currentCategory = "TAB"
    Nav.subtitles["Interface"] = "Прозрачность, цвета и оформление меню"
    local page = createTab("Interface", "")
    Nav.currentCategory = previousCategory or "TAB"
    if not page then return end

    local secStyle = createSection(page.Left, "Menu Style")
    local secColors = createSection(page.Left, "Interface Colors")
    local secFx = createSection(page.Right, "HUD & Effects")

    -- ---------- прозрачность меню ----------
    local baseTransparency = setmetatable({}, {__mode = "k"})
    local opacityAmount = 0
    local opacityEnabled = false

    local function applyMenuOpacity()
        if not Main then return end
        for _, obj in ipairs(Main:GetDescendants()) do
            if (obj:IsA("Frame") or obj:IsA("TextButton") or obj:IsA("TextBox") or obj:IsA("ScrollingFrame"))
                and obj.Name ~= "DropShadow" and obj.Name ~= "CardShadow" then
                if baseTransparency[obj] == nil then baseTransparency[obj] = obj.BackgroundTransparency end
                local base = baseTransparency[obj]
                if opacityEnabled then
                    obj.BackgroundTransparency = math.clamp(base + (1 - base) * (opacityAmount / 100), 0, 1)
                else
                    obj.BackgroundTransparency = base
                end
            end
        end
    end

    local opacityToggle = secStyle:AddToggle("Menu Transparency", false, function(state)
        opacityEnabled = state
        applyMenuOpacity()
    end, function(api)
        api:AddSlider("Transparency amount (%)", 0, 90, 40, function(v)
            opacityAmount = v
            if opacityEnabled then applyMenuOpacity() end
        end)
    end)

    local scaleControl = secStyle:AddSlider("UI Scale (%)", 70, 130, math.floor((uiScale and uiScale.Scale or 1) * 100 + 0.5), function(v)
        if uiScale then uiScale.Scale = v / 100 end
    end)

    -- ---------- блюр ----------
    local blurSettings = Theme.MenuBlur
    local function applyBlur()
        if not blur or not blur.Parent then return end
        TweenService:Create(blur, TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Size = blurSettings.enabled and Main.Visible and blurSettings.amount or 0,
        }):Play()
    end
    local blurToggle = secStyle:AddToggle("Menu Blur", false, function(state)
        blurSettings.enabled = state
        applyBlur()
    end, function(api)
        api:AddSlider("Blur size", 2, 40, blurSettings.amount, function(v)
            blurSettings.amount = v
            if blurSettings.enabled then applyBlur() end
        end)
    end)
    registerCleanup(function() if blur and blur.Parent then blur.Size = 0 end end)

    -- ---------- цвета ----------
    local function setAccent(color)
        if Theme.Runtime and Theme.Runtime.SetCustomAccent then
            pcall(Theme.Runtime.SetCustomAccent, color)
        else
            Theme.BloodRed = color
        end
    end

    local accentButton
    accentButton = secColors:AddButton("Accent color picker", function()
        local h, s, v = Theme.BloodRed:ToHSV()
        openSettingsWindow("Accent color", function(api)
            api:AddColorPicker(h, s, v, function(nh, ns, nv)
                setAccent(Color3.fromHSV(nh, ns, nv))
            end)
        end)
    end)

    secColors:AddButton("Next theme preset", function()
        if Theme.Runtime and Theme.Runtime.Next then
            local name = Theme.Runtime.Next()
            if accentButton and accentButton.Parent then
                accentButton.Text = "Accent color picker (" .. tostring(name) .. ")"
            end
        end
    end)

    secColors:AddButton("Reset menu appearance", function()
        opacityToggle.Set(false)
        blurToggle.Set(false)
        scaleControl.Set(100)
        Main.BackgroundColor3 = Theme.Background
    end)

    -- ---------- эффекты ----------
    local scanlines = Main and Main:FindFirstChild("SatanicScanlines")
    secFx:AddToggle("Scanline overlay", true, function(state)
        if scanlines then scanlines.Visible = state end
    end)

    local particles
    if Nav.content then particles = Nav.content:FindFirstChild("SatanicMenuParticles") end
    secFx:AddToggle("Menu particles", true, function(state)
        if particles then particles.Visible = state end
    end)

    local ambient
    if Nav.content then ambient = Nav.content:FindFirstChild("Ambient") end
    secFx:AddToggle("Ambient glow", true, function(state)
        if ambient then ambient.Visible = state end
    end)

    local edgeAura = Main and Main:FindFirstChild("PinkAura")
    secFx:AddToggle("Edge glow", true, function(state)
        if edgeAura then edgeAura.Visible = state end
        local shadow = Main and Main:FindFirstChild("DropShadow")
        if shadow then shadow.Visible = state end
    end)

    local badgeGlow = Main and Main:FindFirstChild("TitleBadge") and Main.TitleBadge:FindFirstChild("Glow")
    secFx:AddToggle("Header glow", true, function(state)
        if badgeGlow then badgeGlow.Visible = state end
    end)

    secFx:AddButton("Center menu", function()
        if Main then Main.Position = UDim2.new(0.5, 0, 0.5, 0) end
    end)
end

local ok, err = pcall(initInterfaceSettings)
if not ok then warn("[Satanic UI] Interface модуль: " .. tostring(err)) end
end

-- ===================== MISC → OTHER: меню и сервер =====================
-- Карточка осталась после удаления Death Counter и получила полезные утилиты.
do
local function initOtherTab()
    local S = Theme.Sections or {}
    local secOther = S.miscOther
    if not secOther then return end

    secOther:AddButton("Copy Job ID", function()
        local id = game.JobId
        if type(setclipboard) == "function" then
            pcall(setclipboard, id)
        end
        print("[Satanic] JobId: " .. tostring(id))
    end)

    secOther:AddButton("Copy Place ID", function()
        local id = tostring(game.PlaceId)
        if type(setclipboard) == "function" then pcall(setclipboard, id) end
        print("[Satanic] PlaceId: " .. id)
    end)

    secOther:AddButton("Rejoin server", function()
        local TeleportService = game:GetService("TeleportService")
        pcall(function() TeleportService:Teleport(game.PlaceId, LocalPlayer) end)
    end)

    secOther:AddButton("Keybinds panel (панель клавиш)", function()
        if Theme.KeyPanel and Theme.KeyPanel.toggle then
            Theme.KeyPanel.toggle()
        else
            warn("[Satanic] Панель кейбиндов ещё не готова — открой меню заново.")
        end
    end)

    secOther:AddButton("Unload menu (RightShift заново)", function()
        if Theme.Unload then
            pcall(Theme.Unload)
        else
            warn("[Satanic] Unload недоступен: перезапусти скрипт.")
        end
    end)
end

local ok, err = pcall(initOtherTab)
if not ok then warn("[Satanic UI] Other модуль: " .. tostring(err)) end
end

-- ===================== COMPACT HOTKEYS HUD =====================
-- Uses the original bind registry. Only bound and enabled toggles are displayed.
do
local function initCompactHotkeys()
    if Theme.KeyPanel then return end
    local gui = Instance.new("ScreenGui")
    gui.Name = "SatanicKeyPanel"
    gui.ResetOnSpawn = false
    gui.IgnoreGuiInset = true
    gui.DisplayOrder = 998
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    local ok = pcall(function() gui.Parent = getParent() end)
    if not ok or not gui.Parent then return end
    registerCleanup(function() pcall(function() gui:Destroy() end) end)

    local width, headerHeight, rowHeight, maxRows = 238, 44, 30, 6
    local panel = Instance.new("Frame", gui)
    panel.Name = "Hotkeys"
    panel.Position = UDim2.new(0, 20, 0.42, 0)
    panel.Size = UDim2.fromOffset(width, headerHeight)
    panel.BackgroundColor3 = Color3.fromRGB(13, 11, 18)
    panel.BackgroundTransparency = 0.16
    panel.BorderSizePixel = 0
    panel.ClipsDescendants = true
    Instance.new("UICorner", panel).CornerRadius = UDim.new(0, 13)
    local border = Instance.new("UIStroke", panel)
    border.Color = Theme.BloodRed
    border.Transparency = 0.55
    border.Thickness = 1

    -- шапка: акцентный штрих, иконка-клавиша, заголовок, счётчик, шеврон
    local header = Instance.new("TextButton", panel)
    header.Name = "Header"
    header.Size = UDim2.new(1, 0, 0, headerHeight)
    header.BackgroundTransparency = 1
    header.Text = ""
    header.AutoButtonColor = false
    header.Active = true

    local tick = Instance.new("Frame", header)
    tick.Name = "Tick"
    tick.Position = UDim2.fromOffset(12, 14)
    tick.Size = UDim2.fromOffset(4, 16)
    tick.BackgroundColor3 = Theme.BloodRed
    tick.BorderSizePixel = 0
    tick.ZIndex = 2
    Instance.new("UICorner", tick).CornerRadius = UDim.new(1, 0)

    local icon = Instance.new("Frame", header)
    icon.Name = "HotkeysIcon"
    icon.Position = UDim2.fromOffset(28, 15)
    icon.Size = UDim2.fromOffset(18, 14)
    icon.BackgroundTransparency = 1
    icon.ZIndex = 2
    local keyBorder = Instance.new("UIStroke", icon)
    keyBorder.Thickness = 1.1
    keyBorder.Transparency = 0.15
    Instance.new("UICorner", icon).CornerRadius = UDim.new(0, 3)
    local keyDots = {}
    for i = 1, 4 do
        local dot = Instance.new("Frame", icon)
        dot.BorderSizePixel = 0
        dot.Size = UDim2.fromOffset(2, 2)
        dot.Position = UDim2.fromOffset(3 + ((i - 1) % 2) * 6, 3 + math.floor((i - 1) / 2) * 5)
        dot.BackgroundTransparency = 0.15
        Instance.new("UICorner", dot).CornerRadius = UDim.new(0, 1)
        keyDots[#keyDots + 1] = dot
    end

    local title = Instance.new("TextLabel", header)
    title.Position = UDim2.fromOffset(56, 6)
    title.Size = UDim2.new(1, -120, 0, 18)
    title.BackgroundTransparency = 1
    title.Font = Enum.Font.GothamBold
    title.TextSize = 12
    title.TextColor3 = Theme.Text
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.Text = "HOTKEYS"
    local subtitle = Instance.new("TextLabel", header)
    subtitle.Position = UDim2.fromOffset(56, 23)
    subtitle.Size = UDim2.new(1, -120, 0, 12)
    subtitle.BackgroundTransparency = 1
    subtitle.Font = Enum.Font.GothamMedium
    subtitle.TextSize = 8
    subtitle.TextColor3 = Theme.TextDark
    subtitle.TextXAlignment = Enum.TextXAlignment.Left
    subtitle.Text = "ACTIVE BINDS"

    local counterBg = Instance.new("Frame", header)
    counterBg.Name = "Counter"
    counterBg.AnchorPoint = Vector2.new(1, 0.5)
    counterBg.Position = UDim2.new(1, -34, 0.5, 0)
    counterBg.Size = UDim2.fromOffset(30, 18)
    counterBg.BackgroundColor3 = Theme.BloodRed
    counterBg.BackgroundTransparency = 0.78
    counterBg.BorderSizePixel = 0
    counterBg.ZIndex = 2
    Instance.new("UICorner", counterBg).CornerRadius = UDim.new(0, 6)
    local counter = Instance.new("TextLabel", counterBg)
    counter.Size = UDim2.new(1, 0, 1, 0)
    counter.BackgroundTransparency = 1
    counter.Font = Enum.Font.GothamBold
    counter.TextSize = 10
    counter.TextColor3 = Theme.Text
    counter.Text = "0"

    local chev = Instance.new("TextButton", header)
    chev.Name = "Chevron"
    chev.AnchorPoint = Vector2.new(1, 0.5)
    chev.Position = UDim2.new(1, -12, 0.5, 0)
    chev.Size = UDim2.fromOffset(16, 16)
    chev.BackgroundTransparency = 1
    chev.Text = "▲"
    chev.Font = Enum.Font.GothamBold
    chev.TextSize = 9
    chev.TextColor3 = Theme.TextDark
    chev.AutoButtonColor = false
    chev.Rotation = 180

    local separator = Instance.new("Frame", panel)
    separator.Position = UDim2.fromOffset(12, headerHeight - 1)
    separator.Size = UDim2.new(1, -24, 0, 1)
    separator.BackgroundColor3 = Theme.BloodRed
    separator.BackgroundTransparency = 0.55
    separator.BorderSizePixel = 0
    local sepG = Instance.new("UIGradient", separator)
    sepG.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 1),
        NumberSequenceKeypoint.new(0.2, 0.15),
        NumberSequenceKeypoint.new(0.8, 0.15),
        NumberSequenceKeypoint.new(1, 1),
    })

    local list = Instance.new("ScrollingFrame", panel)
    list.Name = "ActiveBinds"
    list.Position = UDim2.fromOffset(10, headerHeight + 4)
    list.Size = UDim2.new(1, -20, 1, -headerHeight - 10)
    list.BackgroundTransparency = 1
    list.BorderSizePixel = 0
    list.ScrollBarThickness = 2
    list.ScrollBarImageColor3 = Theme.BloodRed
    list.ScrollingDirection = Enum.ScrollingDirection.Y
    list.CanvasSize = UDim2.fromOffset(0, 0)
    local layout = Instance.new("UIListLayout", list)
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, 4)

    local records = {}
    local currentPalette = nil
    local lastCount = -1

    local function applyHotkeyTheme(p)
        if not p or not panel.Parent then return end
        currentPalette = p
        panel.BackgroundColor3 = p.Background
        border.Color = p.BloodRed
        tick.BackgroundColor3 = p.BloodRed
        keyBorder.Color = p.BloodRed
        for _, dot in ipairs(keyDots) do dot.BackgroundColor3 = p.BloodRed end
        title.TextColor3 = p.Text
        subtitle.TextColor3 = p.TextDark
        counterBg.BackgroundColor3 = p.BloodRed
        counter.TextColor3 = p.Text
        chev.TextColor3 = p.TextDark
        separator.BackgroundColor3 = p.BloodRed
        list.ScrollBarImageColor3 = p.BloodRed
        for _, row in pairs(records) do
            row.caption.TextColor3 = p.Text
            row.dot.BackgroundColor3 = p.BloodRed
            row.badge.BackgroundColor3 = p.ElementHover
            row.badge.TextColor3 = p.Text
        end
    end
    if Theme.Runtime and Theme.Runtime.Subscribe then Theme.Runtime.Subscribe(applyHotkeyTheme) end
    if not currentPalette then applyHotkeyTheme(Theme) end

    local function rowFor(identity, name, key, order, canToggle)
        local row = records[identity]
        if not row then
            local button = Instance.new("TextButton", list)
            button.Name = "ActiveHotkey"
            button.Size = UDim2.new(1, -2, 0, rowHeight - 4)
            button.BackgroundColor3 = Theme.Element
            button.BackgroundTransparency = 0.55
            button.Text = ""
            button.AutoButtonColor = false
            button.BorderSizePixel = 0
            Instance.new("UICorner", button).CornerRadius = UDim.new(0, 8)
            local rowStroke = Instance.new("UIStroke", button)
            rowStroke.Color = Theme.Stroke
            rowStroke.Thickness = 1
            rowStroke.Transparency = 0.85

            local dot = Instance.new("Frame", button)
            dot.Name = "Dot"
            dot.AnchorPoint = Vector2.new(0, 0.5)
            dot.Position = UDim2.new(0, 8, 0.5, 0)
            dot.Size = UDim2.fromOffset(5, 5)
            dot.BackgroundColor3 = Theme.BloodRed
            dot.BorderSizePixel = 0
            dot.ZIndex = 2
            Instance.new("UICorner", dot).CornerRadius = UDim.new(1, 0)

            local caption = Instance.new("TextLabel", button)
            caption.Name = "Name"
            caption.Position = UDim2.fromOffset(22, 0)
            caption.Size = UDim2.new(1, -84, 1, 0)
            caption.BackgroundTransparency = 1
            caption.Font = Enum.Font.GothamMedium
            caption.TextSize = 11
            caption.TextColor3 = Theme.Text
            caption.TextXAlignment = Enum.TextXAlignment.Left
            caption.TextTruncate = Enum.TextTruncate.AtEnd

            local badge = Instance.new("TextLabel", button)
            badge.Name = "Key"
            badge.AnchorPoint = Vector2.new(1, 0.5)
            badge.Position = UDim2.new(1, -7, 0.5, 0)
            badge.Size = UDim2.fromOffset(46, 18)
            badge.BackgroundColor3 = Theme.ElementHover
            badge.BackgroundTransparency = 0.35
            badge.BorderSizePixel = 0
            badge.Font = Enum.Font.GothamBold
            badge.TextSize = 9
            badge.TextColor3 = Theme.Text
            badge.TextTruncate = Enum.TextTruncate.AtEnd
            Instance.new("UICorner", badge).CornerRadius = UDim.new(0, 6)
            local badgeStroke = Instance.new("UIStroke", badge)
            badgeStroke.Color = Theme.BloodRed
            badgeStroke.Thickness = 1
            badgeStroke.Transparency = 0.65

            track(button.MouseEnter:Connect(function()
                UITween(button, {BackgroundTransparency = 0.32}, 0.12)
                UITween(rowStroke, {Transparency = 0.5, Color = Theme.BloodRed}, 0.12)
            end))
            track(button.MouseLeave:Connect(function()
                UITween(button, {BackgroundTransparency = 0.55}, 0.14)
                UITween(rowStroke, {Transparency = 0.85, Color = Theme.Stroke}, 0.14)
            end))
            track(button.MouseButton1Click:Connect(function()
                if type(identity) == "table" and identity.toggle then pcall(identity.toggle) end
            end))

            row = { button = button, caption = caption, badge = badge, dot = dot, identity = identity }
            records[identity] = row
        end
        if currentPalette then
            row.caption.TextColor3 = currentPalette.Text
            row.dot.BackgroundColor3 = currentPalette.BloodRed
            row.badge.BackgroundColor3 = currentPalette.ElementHover
            row.badge.TextColor3 = currentPalette.Text
        end
        row.button.Visible = true
        row.button.LayoutOrder = order
        row.caption.Text = tostring(name)
        row.badge.Text = key and key.Name or ""
    end

    local visible = true
    local function setVisible(state)
        visible = state == true
        gui.Enabled = visible
    end
    Theme.KeyPanel = {
        toggle = function() setVisible(not visible) end,
        show = function() setVisible(true) end,
        hide = function() setVisible(false) end,
        isOpen = function() return visible end,
    }

    -- сворачивание списка по клику на шапку (не срабатывает при перетаскивании)
    local dragMoved = false
    local collapsed = false
    track(header.MouseButton1Click:Connect(function()
        if dragMoved then return end
        collapsed = not collapsed
        chev.Rotation = collapsed and 0 or 180
        if collapsed then
            TweenService:Create(panel, TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Size = UDim2.fromOffset(width, headerHeight),
            }):Play()
        else
            local rows = 0
            for _, r in pairs(records) do
                if r.button.Visible then rows = rows + 1 end
            end
            local listHeight = math.min(math.max(rows, 1), maxRows) * rowHeight
            TweenService:Create(panel, TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Size = UDim2.fromOffset(width, headerHeight + listHeight + 12),
            }):Play()
        end
    end))

    local elapsed = 0
    local lastAccentColor = nil
    track(RunService.Heartbeat:Connect(function(dt)
        if Unloaded then return end
        elapsed = elapsed + dt
        if elapsed < 0.1 then return end
        elapsed = 0
        -- Перекрашиваем только при реальной смене акцента, а не 10 раз в секунду.
        if lastAccentColor ~= Theme.BloodRed then
            lastAccentColor = Theme.BloodRed
            keyBorder.Color = lastAccentColor
            tick.BackgroundColor3 = lastAccentColor
            separator.BackgroundColor3 = lastAccentColor
            list.ScrollBarImageColor3 = lastAccentColor
            for _, dot in ipairs(keyDots) do dot.BackgroundColor3 = lastAccentColor end
        end
        for _, row in pairs(records) do row.button.Visible = false end
        local count = 0
        for _, entry in ipairs(Theme.Bindables or {}) do
            if type(entry) == "table" and entry.name and entry.getBind and entry.getState then
                local okBind, key = pcall(entry.getBind)
                local okState, active = pcall(entry.getState)
                if okBind and key and okState and active then
                    count = count + 1
                    rowFor(entry, entry.name, key, count, true)
                end
            end
        end
        -- The legacy Model Face Lock has its own T binding, outside the toggle registry.
        if aimbotEnabled and isAimingAtTarget and aimLockKey then
            count = count + 1
            rowFor("Model Lock", "Model Lock", aimLockKey, count, false)
        end
        counter.Text = tostring(count)
        if not collapsed and count ~= lastCount then
            lastCount = count
            local listHeight = math.min(count, maxRows) * rowHeight
            TweenService:Create(panel, TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Size = UDim2.fromOffset(width, headerHeight + (count > 0 and listHeight + 12 or 0)),
            }):Play()
        end
        if count == 0 then lastCount = 0 end
        list.CanvasSize = UDim2.fromOffset(0, count * (rowHeight + 4))
    end))

    local dragging, startInput, startPosition = false, nil, nil
    track(header.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            dragMoved = false
            startInput = input.Position
            startPosition = panel.Position
        end
    end))
    track(UserInputService.InputChanged:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            local delta = input.Position - startInput
            if math.abs(delta.X) + math.abs(delta.Y) > 6 then dragMoved = true end
            panel.Position = UDim2.new(startPosition.X.Scale, startPosition.X.Offset + delta.X, startPosition.Y.Scale, startPosition.Y.Offset + delta.Y)
        end
    end))
    track(UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then dragging = false end
    end))
end

local ok, err = pcall(initCompactHotkeys)
if not ok then warn("[Satanic UI] Hotkeys: " .. tostring(err)) end
end

-- ===================== ФИНАЛЬНЫЙ ПОРЯДОК КАТЕГОРИЙ (нижняя навигация) =====================
-- CONFIGS стала отдельной категорией, а MISC получила вкладку BINDS, поэтому
-- порядок кнопок пересобирается один раз после создания всех вкладок.
do
    local desired = {"PvP", "Movement", "VISUALS", "MISC", "CUSTOMIZATION", "TAB", "CONFIGS"}
    local ordered, used = {}, {}
    for _, name in ipairs(desired) do
        if Nav.categories[name] then
            ordered[#ordered + 1] = name
            used[name] = true
        end
    end
    for _, name in ipairs(Nav.categoryOrder) do
        if not used[name] and Nav.categories[name] then
            ordered[#ordered + 1] = name
            used[name] = true
        end
    end
    Nav.categoryOrder = ordered
    for index, name in ipairs(ordered) do
        local ref = Nav.categories[name]
        if ref and ref.btn then ref.btn.LayoutOrder = index end
    end
    local function relayout()
        if Nav.layoutCategories then pcall(Nav.layoutCategories) end
    end
    relayout()
    task.defer(relayout)
    task.delay(0.8, relayout)
    task.delay(2.5, relayout)
end

-- Compact notification stack: only explicit key actions / capture feedback.
do
    local holder = Instance.new("Frame", ScreenGui)
    holder.Name = "FaceLessNotifications"
    holder.AnchorPoint = Vector2.new(1, 1)
    holder.Position = UDim2.new(1, -18, 1, -18)
    holder.Size = UDim2.fromOffset(240, 210)
    holder.BackgroundTransparency = 1
    holder.ZIndex = 600
    local layout = Instance.new("UIListLayout", holder)
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.VerticalAlignment = Enum.VerticalAlignment.Bottom
    layout.Padding = UDim.new(0, 6)
    local serial = 0
    Theme.Notify = function(title, message)
        if Unloaded or not holder.Parent then return end
        serial = serial + 1
        local notice = Instance.new("Frame")
        notice.Name = "Notice"
        notice.Size = UDim2.fromOffset(240, 46)
        notice.BackgroundColor3 = Theme.Background
        notice.BackgroundTransparency = 0.22
        notice.BorderSizePixel = 0
        notice.ZIndex = 600
        notice.LayoutOrder = serial
        notice.Parent = holder
        Instance.new("UICorner", notice).CornerRadius = UDim.new(0, 10)
        local edge = Instance.new("UIStroke", notice)
        edge.Color = Theme.BloodRed
        edge.Transparency = 0.55
        local top = Instance.new("TextLabel", notice)
        top.Position = UDim2.fromOffset(12, 6)
        top.Size = UDim2.new(1, -24, 0, 17)
        top.BackgroundTransparency = 1
        top.Text = tostring(title)
        top.TextTruncate = Enum.TextTruncate.AtEnd
        top.Font = Enum.Font.GothamBold
        top.TextSize = 11
        top.TextColor3 = Theme.Text
        top.TextXAlignment = Enum.TextXAlignment.Left
        top.ZIndex = 601
        local sub = Instance.new("TextLabel", notice)
        sub.Position = UDim2.fromOffset(12, 23)
        sub.Size = UDim2.new(1, -24, 0, 14)
        sub.BackgroundTransparency = 1
        sub.Text = tostring(message)
        sub.Font = Enum.Font.GothamMedium
        sub.TextSize = 10
        sub.TextColor3 = Theme.TextDark
        sub.TextXAlignment = Enum.TextXAlignment.Left
        sub.ZIndex = 601
        local children = {}
        for _, child in ipairs(holder:GetChildren()) do
            if child:IsA("Frame") then table.insert(children, child) end
        end
        table.sort(children, function(a, b) return a.LayoutOrder < b.LayoutOrder end)
        while #children > 4 do local old = table.remove(children, 1); old:Destroy() end
        task.delay(2.4, function() if notice.Parent then notice:Destroy() end end)
    end
end

-- Nebula glass shell: purely decorative, original controls and bindings stay intact.
do
    local title = Main:FindFirstChild("TitleBadge")
    if title then
        local pill = Instance.new("Frame")
        pill.Name = "SatanicProfile"
        pill.AnchorPoint = Vector2.new(1, 0)
        pill.Position = UDim2.new(1, -66, 0, 26)
        pill.Size = UDim2.fromOffset(180, 64)
        pill.BackgroundColor3 = Color3.fromRGB(44, 33, 34)
        pill.BackgroundTransparency = 0.35
        pill.BorderSizePixel = 0
        pill.ZIndex = 53
        pill.Parent = Main
        Instance.new("UICorner", pill).CornerRadius = UDim.new(0, 18)
        local outline = Instance.new("UIStroke", pill)
        outline.Color = Color3.fromRGB(255,190,185); outline.Transparency = 0.84
        local label = Instance.new("TextLabel", pill)
        label.Position = UDim2.fromOffset(8, 13); label.Size = UDim2.new(1, -54, 0, 19)
        label.BackgroundTransparency = 1; label.Font = Enum.Font.GothamBold; label.TextSize = 12
        label.TextColor3 = Color3.fromRGB(244,239,233); label.TextXAlignment = Enum.TextXAlignment.Right
        label.TextTruncate = Enum.TextTruncate.AtEnd; label.Text = LocalPlayer.DisplayName; label.ZIndex = 55
        local subtitle = Instance.new("TextLabel", pill)
        subtitle.Position = UDim2.fromOffset(8, 33); subtitle.Size = UDim2.new(1, -54, 0, 13)
        subtitle.BackgroundTransparency = 1; subtitle.Font = Enum.Font.GothamMedium; subtitle.TextSize = 9
        subtitle.TextColor3 = Color3.fromRGB(168,159,151); subtitle.TextXAlignment = Enum.TextXAlignment.Right
        subtitle.Text = "ONLINE"; subtitle.ZIndex = 55
        local status = Instance.new("Frame", pill)
        status.Name = "OnlineDot"
        status.AnchorPoint = Vector2.new(1, 0.5)
        status.Position = UDim2.new(1, -103, 0, 39)
        status.Size = UDim2.fromOffset(5, 5)
        status.BackgroundColor3 = Color3.fromRGB(123, 222, 168)
        status.BorderSizePixel = 0
        status.ZIndex = 56
        Instance.new("UICorner", status).CornerRadius = UDim.new(1, 0)
        local avatar = Instance.new("ImageLabel", pill)
        avatar.AnchorPoint = Vector2.new(1, 0.5); avatar.Position = UDim2.new(1,-5,0.5,0)
        avatar.Size = UDim2.fromOffset(38,38); avatar.BackgroundColor3 = Color3.fromRGB(58,48,48); avatar.BackgroundTransparency = 0.55
        avatar.Image = "rbxthumb://type=AvatarHeadShot&id=" .. LocalPlayer.UserId .. "&w=150&h=150"
        -- GetUserThumbnailAsync is the Roblox-supported way to obtain the actual headshot.
        task.spawn(function()
            local ok, image = pcall(function()
                return Players:GetUserThumbnailAsync(LocalPlayer.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size150x150)
            end)
            if ok and avatar.Parent and type(image) == "string" and image ~= "" then avatar.Image = image end
        end)
        avatar.ZIndex = 56; Instance.new("UICorner", avatar).CornerRadius = UDim.new(1,0)
        local avatarBorder = Instance.new("UIStroke", avatar)
        avatarBorder.Color = Color3.fromRGB(231, 149, 146)
        avatarBorder.Thickness = 1
        avatarBorder.Transparency = 0.45
        local overlay = Instance.new("TextButton", pill)
        overlay.Name = "OpenOwnProfile"
        overlay.Size = UDim2.fromScale(1, 1)
        overlay.BackgroundTransparency = 1
        overlay.Text = ""
        overlay.AutoButtonColor = false
        overlay.ZIndex = 57
        track(overlay.MouseButton1Click:Connect(function()
            local ok, err = pcall(function() game:GetService("GuiService"):InspectPlayerFromUserId(LocalPlayer.UserId) end)
            if not ok then warn("[FaceLess] Не удалось открыть профиль: " .. tostring(err)) end
        end))
