                pill.BackgroundColor3 = palette.Section
                outline.Color = palette.Stroke
                avatar.BackgroundColor3 = palette.Element
                avatarBorder.Color = palette.BloodRed
                label.TextColor3 = palette.Text
                subtitle.TextColor3 = palette.TextDark
            end)
        end
    end
end

