-- Global teardown for reruns. Without this, destroying only ScreenGui leaves old game loops
-- alive; repeated executions can stack dozens of updates and halve the frame rate.
local function cleanupCurrentRuntime()
    if Unloaded then return end
    Unloaded = true
    for i = #RuntimeControl.CleanupCallbacks, 1, -1 do
        pcall(RuntimeControl.CleanupCallbacks[i])
    end
    pcall(function()
        if Theme and Theme.Runtime and Theme.Runtime.Cleanup then Theme.Runtime.Cleanup() end
    end)
    pcall(function()
        if Theme and Theme.CustomSkyBoxState and Theme.CustomSkyBoxState.Cleanup then Theme.CustomSkyBoxState.Cleanup() end
    end)
    pcall(function()
        if fogEnabled then fogEnabled = false end
        if fogBackup then restoreFog() end
    end)
    pcall(function()
        if WeatherState then
            WeatherState.enabled = false
            if WeatherState.apply then WeatherState.apply() end
        end
    end)
    pcall(function() customHatEnabled = false; updateHat(); applyHatBloom() end)
    pcall(function() chamsEnabled = false; chamsDestroyAll() end)
    pcall(function() korbloxEnabled = false; applyKorblox() end)
    pcall(function() headlessEnabled = false; applyHeadless() end)
    pcall(function() restoreTSBCleanup() end)
    for _, connection in ipairs(Connections) do
        pcall(function() connection:Disconnect() end)
    end
    table.clear(Connections)
    pcall(function() if blur and blur.Parent then blur:Destroy() end end)
    pcall(function()
        if Nav and Nav.bottomCats then Nav.bottomCats:Destroy() end
        if Nav and Nav.bottomCatsGlow then Nav.bottomCatsGlow:Destroy() end
        local g = ScreenGui and ScreenGui:FindFirstChild("BottomCatsGlow")
        if g then g:Destroy() end
        local b = ScreenGui and ScreenGui:FindFirstChild("BottomCats")
        if b then b:Destroy() end
    end)
    pcall(function() if ScreenGui and ScreenGui.Parent then ScreenGui:Destroy() end end)
    pcall(function()
        local character = LocalPlayer and LocalPlayer.Character
        local oldRig = character and character:FindFirstChild("SatanicSandevistanRig")
        if oldRig then oldRig:Destroy() end
    end)
    for _, name in ipairs({"SatanicWeather", "WorldWeatherGeometry", "CustomHatEffect", "CustomWingsEffect", "SatanicCinematicFX", "SatanicSandevistanFX"}) do
        pcall(function()
            local obj = workspace:FindFirstChild(name)
            if obj then obj:Destroy() end
        end)
    end
    if RuntimeControl.Environment and RuntimeControl.Environment.__SATANIC_RUNTIME_CLEANUP == cleanupCurrentRuntime then
        RuntimeControl.Environment.__SATANIC_RUNTIME_CLEANUP = nil
    end
end
-- Кнопка «Unload menu» в MISC → OTHER (модули выполняются раньше определения).
Theme.Unload = cleanupCurrentRuntime
if RuntimeControl.Environment then RuntimeControl.Environment.__SATANIC_RUNTIME_CLEANUP = cleanupCurrentRuntime end

-- ===================== FACELESS / POST FX =====================
-- Independent, opt-in local effects: the game's own Lighting instances are never modified.
do
    local function initFaceLessPostFX()
        local card = createSection(visualTab.Left, "Post Processing", "FaceLess/Visuals/Post Processing")
        local states = {}
        local function update(name, className, enabled, activeProps, neutralProps)
            local entry = states[name]
            if not entry then entry = {revision = 0}; states[name] = entry end
            entry.revision = entry.revision + 1
            local revision = entry.revision
            if entry.tween then pcall(function() entry.tween:Cancel() end); entry.tween = nil end
            if enabled then
                if not entry.object or not entry.object.Parent then
                    local effect = Instance.new(className)
                    effect.Name = "FaceLessPost_" .. name
                    for property, value in pairs(neutralProps) do effect[property] = value end
                    effect.Parent = Lighting
                    entry.object = effect
                end
                local effect = entry.object
                local ok, tween = pcall(function()
                    return TweenService:Create(effect, TweenInfo.new(0.28, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), activeProps)
                end)
                if ok and tween then entry.tween = tween; tween:Play() end
            elseif entry.object then
                local object = entry.object
                local ok, tween = pcall(function()
                    return TweenService:Create(object, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), neutralProps)
                end)
                if ok and tween then entry.tween = tween; tween:Play() end
                task.delay(0.23, function()
                    if entry.revision ~= revision then return end
                    pcall(function() object:Destroy() end)
                    if entry.object == object then entry.object = nil end
                    entry.tween = nil
                end)
            end
        end
        registerCleanup(function()
            for _, entry in pairs(states) do
                entry.revision = entry.revision + 1
                if entry.tween then pcall(function() entry.tween:Cancel() end) end
                if entry.object then pcall(function() entry.object:Destroy() end) end
            end
        end)
        local onGlow, glow = false, 35
        local function renderGlow()
            update("Glow", "BloomEffect", onGlow,
                {Intensity = glow / 100, Size = 32, Threshold = 1},
                {Intensity = 0, Size = 32, Threshold = 1})
        end
        card:AddToggle("Soft Glow", false, function(on) onGlow = on; renderGlow() end, function(api)
            api:AddSlider("Glow intensity", 0, 100, glow, function(v) glow = v; if onGlow then renderGlow() end end)
        end)
        local onTone, tone = false, 25
        local function renderTone()
            update("ColorGrade", "ColorCorrectionEffect", onTone,
                {Contrast = tone / 250, Saturation = tone / 125, Brightness = 0},
                {Contrast = 0, Saturation = 0, Brightness = 0})
        end
        card:AddToggle("Vivid Color", false, function(on) onTone = on; renderTone() end, function(api)
            api:AddSlider("Color intensity", 0, 100, tone, function(v) tone = v; if onTone then renderTone() end end)
        end)
        local onFilm, film = false, 35
        local function renderFilm()
            update("FilmFade", "ColorCorrectionEffect", onFilm,
                {Saturation = -film / 125, Contrast = film / 350, Brightness = 0},
                {Saturation = 0, Contrast = 0, Brightness = 0})
        end
        card:AddToggle("Film Fade", false, function(on) onFilm = on; renderFilm() end, function(api)
            api:AddSlider("Film strength", 0, 100, film, function(v) film = v; if onFilm then renderFilm() end end)
        end)
    end
    local ok, err = pcall(initFaceLessPostFX)
    if not ok then warn("[FaceLess] Post Processing: " .. tostring(err)) end
    if ok and Theme.Runtime and Theme.Runtime.Rebuild then pcall(Theme.Runtime.Rebuild) end
end

-- ===================== FACELESS / FIELD TOOLS =====================
-- Local visual and quality-of-life tools. Disabled by default and independently cleaned up.
do
    local function initFieldTools()
        local visual = createSection(visualTab.Right, "Character Lighting", "FaceLess/Visuals/Character Lighting")
        local S = {light = false, lightLevel = 30, outline = false}
        local light, selfOutline
        local function clearLight()
            if light then pcall(function() light:Destroy() end); light = nil end
        end
        local function updateLight()
            local char = LocalPlayer.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if not S.light or not root then clearLight(); return end
            if not light or light.Parent ~= root then
                clearLight()
                light = Instance.new("PointLight")
                light.Name = "FaceLessCharacterLight"
                light.Shadows = false
                light.Parent = root
            end
            light.Color = Theme.BloodRed
            light.Brightness = S.lightLevel / 100
            light.Range = 8
        end
        local function clearSelfOutline()
            if selfOutline then pcall(function() selfOutline:Destroy() end); selfOutline = nil end
        end
        local function updateSelfOutline()
            local char = LocalPlayer.Character
            if not S.outline or not char then clearSelfOutline(); return end
            if not selfOutline or selfOutline.Parent ~= char then
                clearSelfOutline()
                selfOutline = Instance.new("Highlight")
                selfOutline.Name = "FaceLessSelfOutline"
                selfOutline.Adornee = char
                selfOutline.FillTransparency = 1
                selfOutline.OutlineTransparency = 0.4
                selfOutline.DepthMode = Enum.HighlightDepthMode.Occluded
                selfOutline.Parent = char
            end
            selfOutline.OutlineColor = Theme.BloodRed
        end
        registerCleanup(function()
            clearLight(); clearSelfOutline()
        end)
        visual:AddToggle("Accent Light", false, function(v) S.light = v; updateLight() end, function(api)
            api:AddSlider("Light strength", 0, 100, S.lightLevel, function(v) S.lightLevel = v; updateLight() end)
        end)
        visual:AddToggle("Self Outline", false, function(v) S.outline = v; updateSelfOutline() end)
        track(LocalPlayer.CharacterRemoving:Connect(function()
            clearLight(); clearSelfOutline()
        end))
        track(LocalPlayer.CharacterAdded:Connect(function(char)
            if Unloaded or LocalPlayer.Character ~= char then return end
            updateSelfOutline()
            char:WaitForChild("HumanoidRootPart", 10)
            if not Unloaded and LocalPlayer.Character == char then updateLight() end
        end))
        if Theme.Runtime and Theme.Runtime.Subscribe then
            Theme.Runtime.Subscribe(function(palette)
                if light and light.Parent then light.Color = palette.BloodRed end
                if selfOutline and selfOutline.Parent then selfOutline.OutlineColor = palette.BloodRed end
            end)
        end
        local timer = 0
        track(RunService.Heartbeat:Connect(function(dt)
            if Unloaded then return end
            timer = timer + dt
            if timer < 0.15 then return end
            timer = timer % 0.15
            if S.light then updateLight() elseif light then clearLight() end
            if S.outline then updateSelfOutline() elseif selfOutline then clearSelfOutline() end
        end))
    end
    local ok, err = pcall(initFieldTools)
    if not ok then warn("[FaceLess] Field Tools: " .. tostring(err)) end
    if ok and Theme.Runtime and Theme.Runtime.Rebuild then pcall(Theme.Runtime.Rebuild) end
end


-- ===================== AUTONOMOUS TSB PRO COMBAT BOT + REAL-TIME RECORDING MEMORY =====================
-- Fixes skill-air-spam via strict Hit-Confirm & range/facing validation, and adds 'Record for Bot':
-- records player state -> action -> combo chains -> outcome reward (+HP dealt / blocked vs whiffed),
-- stores patterns in memory (persisted via JSON when writefile exists), and replays user playstyle in real time.
do
    local function initCombatBot()
        local WS = game:GetService("Workspace")
        local PathfindingService = game:GetService("PathfindingService")
        local HttpService = game:GetService("HttpService")
        local StatsService = pcall(function() return game:GetService("Stats") end) and game:GetService("Stats") or nil
        local VIM = nil
        pcall(function() VIM = game:GetService("VirtualInputManager") end)
        local VU = nil
        if not VIM then pcall(function() VU = game:GetService("VirtualUser") end) end

        local previousCategory = Nav.currentCategory
        Nav.currentCategory = "PvP"
        Nav.subtitles["Combat Bot"] = "Pro TSB AI + Record for Bot real-time imitation learning (110ms tuned)"
        local botPage = createTab("Combat Bot", "", "FaceLess/CombatBot")
        Nav.currentCategory = previousCategory
        if TabButtons and TabButtons["Combat Bot"] then
            local inActiveCat = ActiveTab and Nav.tabCategory[ActiveTab] == "PvP"
            TabButtons["Combat Bot"].Visible = inActiveCat == true
        end
        if not botPage then return end

        local secMaster = createSection(botPage.Left,  "Bot Master & Target",       "FaceLess/CombatBot/Master")
        local secCombat = createSection(botPage.Right, "Combat · Block · Movement", "FaceLess/CombatBot/Combat")
        local secTechs  = createSection(botPage.Right, "Bot Autonomous Techs",      "FaceLess/CombatBot/Techs")

        local SLOT_KEYS = {
            Enum.KeyCode.One,
            Enum.KeyCode.Two,
            Enum.KeyCode.Three,
            Enum.KeyCode.Four,
        }
        local ROT_BIND_NAME = "FaceLessCombatBotModelRot"
        local MOVE_BIND_NAME = "FaceLessCombatBotMove"
        local MEMORY_FILE = "FaceLess_CombatBot_Memory.json"
        local CALIBRATED_PING_MS = 110

        local BotCfg = {
            enabled = false,
            recordEnabled = false,
            useLearnedMemory = true,
            memoryInfluence = 82,
            tier = "Pro Streamer",
            autoRespawn = true,
            autoEvasive = true,
            usePathfinding = true,
            autoJump = true,
            autoUlt = false,

            targetMode = "Smart Pro",
            maxRange = 150,
            ignoreFriends = false,
            targetDummies = true,
            skipProtected = true,
            showStatusHud = true,

            -- Defense & Punish
            autoBlock = true,
            blockRange = 17,
            blockHoldMs = 350,
            counterAfterBlock = true,
            blockBreakSideDash = true,
            dashPunish = true,

            -- Pro Offense
            autoM1 = true,
            useSkills = true,
            milk3M1 = true,
            finisherStyle = "Pro Mix",
            antiBlockFlank = true,
            trackEnemyEvasive = true,

            -- Human Movement & Feints
            autoDash = true,
            dashEngageRange = 38,
            circleStrafe = true,
            strafeBias = 0.72,
            humanFeints = true,
            smoothTurnSpeed = 19,

            -- 110ms Ping Calibration
            autoPing = true,
            basePingMs = 110,
            pingLead = true,
            leadPercent = 65,
            globalOffsetMs = 0,
            curveSideMode = "Smart (Target Side)",

            -- Autonomous Techs
            autoTechs = true,
            techLoopOreo = true,
            techSupaTwisted = true,
            techM1Reset = true,
            techBackdashCancel = true,
            techKyoto = true,
            tech180Flicks = true,
        }

        local BotState = {
            runningToken = 0,
            status = "IDLE",
            detail = "Waiting",
            targetChar = nil,
            targetRoot = nil,
            targetHum = nil,
            targetName = "None",
            targetHp = 0,

            m1Count = 0,
            lastM1At = 0,
            nextM1At = 0,
            justLanded4thAt = 0,
            lastHitLandedAt = 0,

            lastFrontDashAt = 0,
            lastSideDashAt = 0,
            lastBackdashAt = 0,
            lastBackdashOpenerAt = 0,
            lastEvasiveAt = 0,
            skillCdUntil = {0, 0, 0, 0},
            nextSkillAt = 0,

            blocking = false,
            blockUntil = 0,
            blockCooldownUntil = 0,
            blockedThreatWasDash = false,
            lastKnownHp = nil,
            lastDamagedAt = 0,

            enemyIntel = {},
            nextHopAt = 0,
            strafeSign = 1,
            nextStrafeFlipAt = 0,
            stuckTime = 0,
            lastPos = nil,
            lastPosAt = 0,
            sidestepUntil = 0,
            sidestepDir = nil,

            waypoints = nil,
            wpIndex = 2,
            lastPathAt = 0,
            lastPathGoal = nil,
            activeTechName = nil,
            techBusyUntil = 0,
            lastBotAction = "NONE",
            lastBotActionAt = 0,
        }

        Theme._BotSynthMap = Theme._BotSynthMap or {}
        local smoothedPingMs = 110
        local lastPingSampleAt = 0

        local function getPingMs()
            if not BotCfg.autoPing or not StatsService then
                return BotCfg.basePingMs
            end
            local now = os.clock()
            if now - lastPingSampleAt > 0.12 then
                lastPingSampleAt = now
                local ok, val = pcall(function()
                    return StatsService.Network.ServerStatsItem["Data Ping"]:GetValue()
                end)
                if ok and type(val) == "number" and val == val and val > 5 then
                    smoothedPingMs = smoothedPingMs * 0.65 + math.clamp(val, 15, 350) * 0.35
                else
                    smoothedPingMs = BotCfg.basePingMs
                end
            end
            return smoothedPingMs
        end

        local function pingWaitSec(base110Sec, scale)
            local sc = (scale == true) and 0.4 or (tonumber(scale) or 0)
            local deltaSec = sc * ((getPingMs() - CALIBRATED_PING_MS) / 1000)
            return math.max(0.015, base110Sec + (BotCfg.globalOffsetMs / 1000) + math.clamp(deltaSec, -0.055, 0.085))
        end

        local function getCharParts()
            local char = LocalPlayer and LocalPlayer.Character
            if not char then return nil, nil, nil end
            local hum = char:FindFirstChildOfClass("Humanoid")
            local root = char:FindFirstChild("HumanoidRootPart")
            if not hum or not root or hum.Health <= 0 then return nil, nil, nil end
            return char, hum, root
        end

        local function flatVec(v)
            local f = Vector3.new(v.X, 0, v.Z)
            if f.Magnitude < 1e-4 then return nil end
            return f.Unit
        end

        local function yawVec(dir, deg)
            if math.abs(deg) < 1e-4 then return dir end
            local r = math.rad(deg)
            local c, s = math.cos(r), math.sin(r)
            return Vector3.new(dir.X * c - dir.Z * s, 0, dir.X * s + dir.Z * c).Unit
        end

        -- ======================== INPUT & MOVEMENT LAYER ========================
        local heldKeys, mouseHeld = {}, false
        local Input = {}
        local BotMove = { dir = nil, bound = false }

        local function ensureMoveLoop()
            if BotMove.bound then return end
            BotMove.bound = true
            pcall(function() RunService:UnbindFromRenderStep(MOVE_BIND_NAME) end)
            RunService:BindToRenderStep(MOVE_BIND_NAME, Enum.RenderPriority.Input.Value + 55, function()
                if Unloaded or not BotCfg.enabled or not BotMove.dir then return end
                local _, hum = getCharParts()
                if hum then
                    pcall(function() LocalPlayer:Move(BotMove.dir, false) end)
                    pcall(function() hum:Move(BotMove.dir, false) end)
                end
            end)
        end

        track(RunService.Stepped:Connect(function()
            if Unloaded or not BotCfg.enabled or not BotMove.dir then return end
            local _, hum = getCharParts()
            if hum then
                pcall(function() LocalPlayer:Move(BotMove.dir, false) end)
                pcall(function() hum:Move(BotMove.dir, false) end)
            end
        end))

        function BotMove.set(worldDir)
            local f = flatVec(worldDir)
            if not f then BotMove.stop(); return end
            ensureMoveLoop()
            BotMove.dir = f
            local _, hum = getCharParts()
            if hum then
                pcall(function() LocalPlayer:Move(f, false) end)
                pcall(function() hum:Move(f, false) end)
            end
        end

        function BotMove.stop()
            local had = BotMove.dir ~= nil
            BotMove.dir = nil
            if had then
                local _, hum = getCharParts()
                if hum then
                    pcall(function() LocalPlayer:Move(Vector3.zero, false) end)
                    pcall(function() hum:Move(Vector3.zero, false) end)
                end
            end
        end

        function BotMove.unbind()
            BotMove.stop()
            if BotMove.bound then
                BotMove.bound = false
                pcall(function() RunService:UnbindFromRenderStep(MOVE_BIND_NAME) end)
            end
        end

        function Input.keyDown(key)
            if not key then return end
            Theme._BotSynthMap[key] = os.clock() + 0.14
            if heldKeys[key] then return end
            heldKeys[key] = true
            if VIM then
                pcall(function() VIM:SendKeyEvent(true, key, false, game) end)
            elseif type(keypress) == "function" then
                pcall(keypress, key.Value)
            end
        end

        function Input.keyUp(key)
            if not key then return end
            Theme._BotSynthMap[key] = os.clock() + 0.09
            if not heldKeys[key] then return end
            heldKeys[key] = nil
            if VIM then
                pcall(function() VIM:SendKeyEvent(false, key, false, game) end)
            elseif type(keyrelease) == "function" then
                pcall(keyrelease, key.Value)
            end
        end

        function Input.mouseDown()
            if mouseHeld then return end
            mouseHeld = true
            if VIM then
                local m = UserInputService:GetMouseLocation()
                pcall(function() VIM:SendMouseButtonEvent(m.X, m.Y, 0, true, game, 0) end)
            elseif type(mouse1press) == "function" then
                pcall(mouse1press)
            elseif VU then
                pcall(function() VU:Button1Down(Vector2.new(0, 0)) end)
            end
        end

        function Input.mouseUp()
            if not mouseHeld then return end
            mouseHeld = false
            if VIM then
                local m = UserInputService:GetMouseLocation()
                pcall(function() VIM:SendMouseButtonEvent(m.X, m.Y, 0, false, game, 0) end)
            elseif type(mouse1release) == "function" then
                pcall(mouse1release)
            elseif VU then
                pcall(function() VU:Button1Up(Vector2.new(0, 0)) end)
            end
        end

        function Input.setBlock(wantBlock)
            if wantBlock then
                if not BotState.blocking then
                    BotState.blocking = true
                    Input.mouseUp()
                    Input.keyDown(Enum.KeyCode.F)
                end
            else
                if BotState.blocking or heldKeys[Enum.KeyCode.F] then
                    BotState.blocking = false
                    Input.keyUp(Enum.KeyCode.F)
                end
            end
        end

        function Input.stopMove()
            BotMove.stop()
        end

        function Input.releaseAll()
            BotState.blocking = false
            for k, _ in pairs(heldKeys) do
                heldKeys[k] = nil
                Theme._BotSynthMap[k] = os.clock() + 0.09
                if VIM then
                    pcall(function() VIM:SendKeyEvent(false, k, false, game) end)
                elseif type(keyrelease) == "function" then
                    pcall(keyrelease, k.Value)
                end
            end
            if mouseHeld then Input.mouseUp() end
            BotMove.stop()
        end

        -- ======================== MODEL-ONLY ROTATION ========================
        local ModelRot = {
            active = false,
            savedAutoRotate = nil,
            savedHum = nil,
            dir = Vector3.new(0, 0, -1),
            steerDash = false,
            dashDir = nil,
            smooth = true,
        }

        local function steerDodgeVelocity(root, wantedDir)
            if not root or not wantedDir then return end
            for _, child in ipairs(root:GetChildren()) do
                if child.Name == "dodgevelocity" then
                    if child:IsA("BodyVelocity") then
                        local v = child.Velocity
                        local spd = Vector3.new(v.X, 0, v.Z).Magnitude
                        if spd > 1 then
                            child.Velocity = Vector3.new(wantedDir.X * spd, v.Y, wantedDir.Z * spd)
                        end
                    elseif child:IsA("LinearVelocity") then
                        local v = child.VectorVelocity
                        local spd = Vector3.new(v.X, 0, v.Z).Magnitude
                        if spd > 1 then
                            child.VectorVelocity = Vector3.new(wantedDir.X * spd, v.Y, wantedDir.Z * spd)
                        end
                    end
                end
            end
        end

        local function applyRootYaw(rNow, d, dt, smooth)
            if not d or d.Magnitude < 1e-4 then return end
            local pos = rNow.Position
            local targetCF = CFrame.lookAt(pos, Vector3.new(pos.X + d.X, pos.Y, pos.Z + d.Z))
            if smooth and BotCfg.smoothTurnSpeed < 45 then
                local curCF = rNow.CFrame
                local alpha = math.clamp((dt or 0.016) * BotCfg.smoothTurnSpeed, 0.14, 0.85)
                local lerped = curCF:Lerp(targetCF, alpha)
                rNow.CFrame = (lerped - lerped.Position) + pos
            else
                rNow.CFrame = targetCF
            end
        end

        function ModelRot.start(initialDir, steerDash, smooth)
            local _, hum, root = getCharParts()
            if not hum or not root then return end
            local useSmooth = (smooth == nil) and true or smooth
            if not ModelRot.active then
                ModelRot.savedHum = hum
                ModelRot.savedAutoRotate = hum.AutoRotate
                hum.AutoRotate = false
                ModelRot.active = true
                pcall(function() RunService:UnbindFromRenderStep(ROT_BIND_NAME) end)
                RunService:BindToRenderStep(ROT_BIND_NAME, Enum.RenderPriority.Character.Value + 80, function(dt)
                    if not ModelRot.active or Unloaded then return end
                    local _, hNow, rNow = getCharParts()
                    if not hNow or not rNow then ModelRot.stop(); return end
                    if hNow.AutoRotate ~= false then hNow.AutoRotate = false end
                    applyRootYaw(rNow, ModelRot.dir, dt, ModelRot.smooth)
                    if ModelRot.steerDash then
                        steerDodgeVelocity(rNow, ModelRot.dashDir or ModelRot.dir)
                    end
                end)
            end
            if initialDir then ModelRot.dir = flatVec(initialDir) or ModelRot.dir end
            ModelRot.steerDash = steerDash == true
            ModelRot.smooth = useSmooth
            ModelRot.dashDir = nil
            if ModelRot.dir and not useSmooth then
                applyRootYaw(root, ModelRot.dir, 0.05, false)
            end
        end

        function ModelRot.setDir(dir, dashDir, instant)
            local f = flatVec(dir)
            if f then ModelRot.dir = f end
            ModelRot.dashDir = dashDir and flatVec(dashDir) or nil
            if instant ~= nil then ModelRot.smooth = not instant end
            local _, _, root = getCharParts()
            if ModelRot.active and root and ModelRot.dir then
                if instant or not ModelRot.smooth then
                    applyRootYaw(root, ModelRot.dir, 0.05, false)
                end
                if ModelRot.steerDash then steerDodgeVelocity(root, ModelRot.dashDir or ModelRot.dir) end
            end
        end

        function ModelRot.stop()
            if not ModelRot.active then return end
            ModelRot.active = false
            ModelRot.steerDash = false
            ModelRot.dashDir = nil
            ModelRot.smooth = true
            pcall(function() RunService:UnbindFromRenderStep(ROT_BIND_NAME) end)
            if ModelRot.savedHum and ModelRot.savedHum.Parent then
                local restore = ModelRot.savedAutoRotate
                if restore == nil then restore = true end
                pcall(function() ModelRot.savedHum.AutoRotate = restore end)
            end
            ModelRot.savedHum = nil
            ModelRot.savedAutoRotate = nil
        end

        -- ======================== STATUS HUD PILL ========================
        local statusGui = Instance.new("Frame", ScreenGui)
        statusGui.Name = "CombatBotStatusPill"
        statusGui.Size = UDim2.new(0, 355, 0, 38)
        statusGui.Position = UDim2.new(0.5, -177, 0.06, 0)
        statusGui.BackgroundColor3 = Color3.fromRGB(14, 10, 20)
        statusGui.BackgroundTransparency = 0.18
        statusGui.BorderSizePixel = 0
        statusGui.Visible = false
        statusGui.ZIndex = 48
        statusGui.Active = true
        Instance.new("UICorner", statusGui).CornerRadius = UDim.new(0, 7)
        local stStroke = Instance.new("UIStroke", statusGui)
        stStroke.Color = Theme.BloodRed; stStroke.Thickness = 1.2; stStroke.Transparency = 0.25
        local stLabel = Instance.new("TextLabel", statusGui)
        stLabel.Size = UDim2.new(1, -16, 1, 0); stLabel.Position = UDim2.new(0, 8, 0, 0)
        stLabel.BackgroundTransparency = 1; stLabel.Font = Enum.Font.GothamBold
        stLabel.TextSize = 11; stLabel.TextColor3 = Theme.Text
        stLabel.TextXAlignment = Enum.TextXAlignment.Left; stLabel.ZIndex = 49
        stLabel.Text = "BOT: IDLE"

        do
            local drag, dragStart, startPos = false, nil, nil
            track(statusGui.InputBegan:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
                    drag = true; dragStart = inp.Position; startPos = statusGui.Position
                end
            end))
            track(UserInputService.InputEnded:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then drag = false end
            end))
            track(UserInputService.InputChanged:Connect(function(inp)
                if drag and (inp.UserInputType == Enum.UserInputType.MouseMovement or inp.UserInputType == Enum.UserInputType.Touch) then
                    local d = inp.Position - dragStart
                    statusGui.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
                end
            end))
        end

        -- ======================== IMITATION LEARNING MEMORY ENGINE ('RECORD FOR BOT') ========================
        local BotMem = {
            states = {}, -- [stateKey] = { [actionName] = { score = num, count = int, lastSeen = t } }
            chains = {}, -- [prevAction] = { [nextAction] = { score = num, count = int, avgDelay = sec } }
            totalSamples = 0,
            totalChains = 0,
            pending = {},
            recPrevAction = nil,
            recPrevAt = 0,
            recM1Count = 0,
            recLastM1At = 0,
            recLastBlockAt = 0,
            lastSaveAt = 0,
        }

        function BotMem.save()
            if type(writefile) ~= "function" then return false end
            local ok = pcall(function()
                local payload = {
                    states = BotMem.states,
                    chains = BotMem.chains,
                    totalSamples = BotMem.totalSamples,
                    totalChains = BotMem.totalChains,
                }
                writefile(MEMORY_FILE, HttpService:JSONEncode(payload))
            end)
            return ok
        end

        function BotMem.load()
            if type(readfile) ~= "function" then return end
            pcall(function()
                if type(isfile) == "function" and not isfile(MEMORY_FILE) then return end
                local raw = readfile(MEMORY_FILE)
                if type(raw) == "string" and #raw > 2 then
                    local data = HttpService:JSONDecode(raw)
                    if type(data) == "table" then
                        if type(data.states) == "table" then BotMem.states = data.states end
                        if type(data.chains) == "table" then BotMem.chains = data.chains end
                        BotMem.totalSamples = tonumber(data.totalSamples) or 0
                        BotMem.totalChains = tonumber(data.totalChains) or 0
                    end
                end
            end)
        end

        function BotMem.clear()
            BotMem.states = {}
            BotMem.chains = {}
            BotMem.totalSamples = 0
            BotMem.totalChains = 0
            BotMem.pending = {}
            BotMem.recPrevAction = nil
            BotMem.save()
        end

        function BotMem.buildStateKey(dist, dy, tBlocking, tStunned, tAirborne, tDashing, tAttacking, m1Step, noEv)
            local db
            if dist <= 6.5 then db = "melee"
            elseif dist <= 12.5 then db = "close"
            elseif dist <= 24 then db = "mid"
            else db = "far" end

            local es = "neutral"
            if tBlocking then es = "block"
            elseif tStunned then es = "stun"
            elseif tAirborne and dy >= 2.0 then es = "air"
            elseif tDashing then es = "dash"
            elseif tAttacking then es = "atk" end

            local mb = (m1Step >= 3) and "m3" or ((m1Step >= 1) and "m12" or "m0")
            local eb = noEv and "noEv" or "ev"
            return db .. ":" .. es .. ":" .. mb .. ":" .. eb
        end

        function BotMem.commitSample(stateKey, actionName, reward, prevAct, chainDt)
            local st = BotMem.states[stateKey]
            if not st then st = {}; BotMem.states[stateKey] = st end
            local entry = st[actionName]
            if not entry then
                entry = { score = 0, count = 0 }
                st[actionName] = entry
            end
            entry.count = entry.count + 1
            entry.score = math.clamp(entry.score * 0.88 + reward, -4, 12)
            BotMem.totalSamples = BotMem.totalSamples + 1

            if prevAct and chainDt and chainDt >= 0.08 and chainDt <= 2.9 and reward > 0 then
                local ch = BotMem.chains[prevAct]
                if not ch then ch = {}; BotMem.chains[prevAct] = ch end
                local ce = ch[actionName]
                if not ce then
                    ce = { score = 0, count = 0, avgDelay = chainDt }
                    ch[actionName] = ce
                    BotMem.totalChains = BotMem.totalChains + 1
                end
                ce.count = ce.count + 1
                ce.score = math.clamp(ce.score * 0.85 + reward, 0, 12)
                ce.avgDelay = ce.avgDelay * 0.7 + chainDt * 0.3
            end
        end

        function BotMem.chooseAction(stateKey, prevAction, dtSincePrev, allowSkillSlots, canFrontDash, canSideDash, canBackdash)
            if not BotCfg.useLearnedMemory or BotMem.totalSamples < 3 then return nil end
            local st = BotMem.states[stateKey]
            local ch = prevAction and BotMem.chains[prevAction] or nil
            if not st and not ch then return nil end

            local scores = {}
            if st then
                for act, e in pairs(st) do
                    if e.count >= 2 and e.score > 0.7 then
                        scores[act] = e.score
                    end
                end
            end
            if ch and dtSincePrev and dtSincePrev <= 3.0 then
                for act, ce in pairs(ch) do
                    if ce.count >= 1 and ce.score > 0.9 and math.abs(dtSincePrev - ce.avgDelay) <= 0.45 then
                        scores[act] = (scores[act] or 0) + ce.score * 1.15
                    end
                end
            end

            local bestAct, bestScore = nil, 0
            local infl = BotCfg.memoryInfluence / 100
            for act, sc in pairs(scores) do
                local ok = true
                if act == "FrontDash" and not canFrontDash then ok = false
                elseif (act == "SideDashL" or act == "SideDashR") and not canSideDash then ok = false
                elseif act == "Backdash" and not canBackdash then ok = false
                elseif string.sub(act, 1, 5) == "Skill" then
                    local slot = tonumber(string.sub(act, 6, 6))
                    if not slot or not allowSkillSlots[slot] then ok = false end
                end
                if ok and sc * infl > bestScore then
                    bestScore = sc * infl
                    bestAct = act
                end
            end
            if bestScore >= 1.1 then
                return bestAct
            end
            return nil
        end

        BotMem.load()

        local function setStatus(stateTag, detailText)
            BotState.status = stateTag
            BotState.detail = detailText or ""
            if BotCfg.recordEnabled and not BotCfg.enabled then
                stStroke.Color = Color3.fromRGB(255, 85, 85)
                statusGui.Visible = BotCfg.showStatusHud
                stLabel.Text = string.format("REC [LEARNING]: %s | Mem: %d pts / %d chains", BotState.detail, BotMem.totalSamples, BotMem.totalChains)
            elseif BotCfg.enabled and BotCfg.showStatusHud then
                stStroke.Color = Theme.BloodRed
                statusGui.Visible = true
                local intel = BotState.targetChar and BotState.enemyIntel[BotState.targetChar]
                local evTag = (intel and os.clock() < (intel.evasiveCdUntil or 0)) and " [NO EV]" or ""
                local memTag = (BotCfg.useLearnedMemory and BotMem.totalSamples > 0) and (" [M:" .. tostring(BotMem.totalSamples) .. "]") or ""
                local tPart = BotState.targetChar and (" | " .. tostring(BotState.targetName) .. " " .. tostring(math.floor(BotState.targetHp + 0.5)) .. "HP" .. evTag) or " | No Target"
                stLabel.Text = string.format("PRO [%s]%s: %s%s", stateTag, memTag, BotState.detail, tPart)
            else
                statusGui.Visible = false
            end
        end

        -- ======================== TARGET & PRO INTEL SENSORS ========================
        local function isCharProtected(char)
            if not char then return true end
            if char:FindFirstChildOfClass("ForceField") then return true end
            if BotCfg.skipProtected then
                if char:FindFirstChild("SafeZone") or char:GetAttribute("SafeZone") or char:GetAttribute("Protected") then
                    return true
                end
            end
            return false
        end

        local function isCharBlocking(char)
            if not char then return false end
            if char:FindFirstChild("Blocking") or char:FindFirstChild("Block") or char:GetAttribute("Blocking") then
                return true
            end
            local hum = char:FindFirstChildOfClass("Humanoid")
            local anim = hum and hum:FindFirstChildOfClass("Animator")
            if anim then
                for _, tr in ipairs(anim:GetPlayingAnimationTracks()) do
                    local id = tr.Animation and tostring(tr.Animation.AnimationId) or ""
                    local nm = tr.Animation and string.lower(tr.Animation.Name or "") or ""
                    if string.find(nm, "block", 1, true) or string.find(id, "10470389827", 1, true) or string.find(id, "15290930205", 1, true) then
                        return true
                    end
                end
            end
            return false
        end

        local function isCharRagdolledOrStunned(char)
            if not char then return false end
            if char:FindFirstChild("Ragdoll") or char:FindFirstChild("Stunned") or char:FindFirstChild("Freeze") or char:FindFirstChild("NoAttack") then
                return true
            end
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                if hum.PlatformStand then return true end
                local st = hum:GetState()
                if st == Enum.HumanoidStateType.Physics or st == Enum.HumanoidStateType.FallingDown or st == Enum.HumanoidStateType.Ragdoll then
                    return true
                end
            end
            return false
        end

        local function isCharAttacking(char, root, hum, myRoot)
            if not char or not root or not hum or not myRoot then return false, false, false end
            local dVec = myRoot.Position - root.Position
            local dist = dVec.Magnitude
            if dist > 23 then return false, false, false end
            local toMe = flatVec(dVec) or Vector3.new(0, 0, -1)
            local enemyFwd = flatVec(root.CFrame.LookVector) or Vector3.new(0, 0, -1)
            local facingMe = enemyFwd:Dot(toMe) > 0.35

            local dv = root:FindFirstChild("dodgevelocity")
            if dv then
                local v = dv:IsA("BodyVelocity") and dv.Velocity or (dv:IsA("LinearVelocity") and dv.VectorVelocity or root.AssemblyLinearVelocity)
                local hVel = Vector3.new(v.X, 0, v.Z)
                if hVel:Dot(toMe) > 13 and dist <= 22 then
                    return true, false, true
                end
            end

            if dist <= 13 and facingMe and not isCharRagdolledOrStunned(char) and not isCharBlocking(char) then
                if char:FindFirstChild("M1ing") or char:FindFirstChild("Attacking") or char:FindFirstChild("Swing") or char:FindFirstChild("Combat") then
                    return true, false, false
                end
                local anim = hum:FindFirstChildOfClass("Animator")
                if anim then
                    for _, tr in ipairs(anim:GetPlayingAnimationTracks()) do
                        local nm = tr.Animation and string.lower(tr.Animation.Name or "") or ""
                        if string.find(nm, "punch", 1, true) or string.find(nm, "m1", 1, true) or string.find(nm, "slash", 1, true) or string.find(nm, "attack", 1, true) or string.find(nm, "kick", 1, true) or string.find(nm, "dash", 1, true) then
                            return true, (string.find(nm, "heavy", 1, true) ~= nil or string.find(nm, "smash", 1, true) ~= nil or string.find(nm, "slam", 1, true) ~= nil), false
                        end
                        if dist <= 11.5 and tr.Priority ~= Enum.AnimationPriority.Core and tr.Priority ~= Enum.AnimationPriority.Movement and tr.Priority ~= Enum.AnimationPriority.Idle then
                            if tr.Length <= 0 or tr.TimePosition < tr.Length * 0.85 then
                                return true, (tr.Priority == Enum.AnimationPriority.Action3 or tr.Priority == Enum.AnimationPriority.Action4), false
                            end
                        end
                    end
                end
            end
            return false, false, false
        end

        local function updateEnemyIntel(char, root, hum, myRoot)
            if not char or not root or not hum then return nil end
            local now = os.clock()
            local intel = BotState.enemyIntel[char]
            if not intel then
                intel = { wasRagdoll = false, ragdollAt = 0, evasiveCdUntil = 0, hadDash = false, dashPunishUntil = 0, lastHp = hum.Health, lastDamagedAt = 0 }
                BotState.enemyIntel[char] = intel
            end

            if hum.Health < intel.lastHp - 0.5 then
                intel.lastDamagedAt = now
                if char == BotState.targetChar then
                    BotState.lastHitLandedAt = now
                end
            end
            intel.lastHp = hum.Health

            local isRag = char:FindFirstChild("Ragdoll") ~= nil
            if isRag and not intel.wasRagdoll then
                intel.wasRagdoll = true
                intel.ragdollAt = now
            elseif not isRag and intel.wasRagdoll then
                intel.wasRagdoll = false
                if (now - intel.ragdollAt < 0.85) or root:FindFirstChild("dodgevelocity") ~= nil then
                    intel.evasiveCdUntil = now + 28.0
                end
            end

            local hasDash = root:FindFirstChild("dodgevelocity") ~= nil
            if hasDash then
                intel.hadDash = true
            elseif intel.hadDash then
                intel.hadDash = false
                if myRoot and (root.Position - myRoot.Position).Magnitude <= 14 and not isCharRagdolledOrStunned(char) then
                    intel.dashPunishUntil = now + 0.45
                end
            end
            return intel
        end

        local function getPredictedTargetPos(targetRoot)
            if not targetRoot then return nil end
            local pos = targetRoot.Position
            if not BotCfg.pingLead then return pos end
            local vel = targetRoot.AssemblyLinearVelocity
            local horiz = Vector3.new(vel.X, 0, vel.Z)
            if horiz.Magnitude < 2 then return pos end
            local leadSec = math.clamp((getPingMs() / 1000) * (BotCfg.leadPercent / 100), 0, 0.14)
            local off = horiz * leadSec
            if off.Magnitude > 6.5 then off = off.Unit * 6.5 end
            return pos + off
        end

        local function getBaseForward(targetRoot, myRoot)
            if targetRoot and myRoot then
                local aim = getPredictedTargetPos(targetRoot) or targetRoot.Position
                local toT = flatVec(aim - myRoot.Position)
                if toT then return toT end
            end
            if myRoot then return flatVec(myRoot.CFrame.LookVector) or Vector3.new(0, 0, -1) end
            return Vector3.new(0, 0, -1)
        end

        local function resolveCurveSign(targetRoot, myRoot)
            if BotCfg.curveSideMode == "Left (-Yaw)" then return -1 end
            if BotCfg.curveSideMode == "Right (+Yaw)" then return 1 end
            if targetRoot and myRoot then
                local aim = getPredictedTargetPos(targetRoot) or targetRoot.Position
                return ((aim - myRoot.Position):Dot(myRoot.CFrame.RightVector) >= 0) and 1 or -1
            end
            return BotState.strafeSign
        end

        local function scanAllEnemies(myChar, myRoot)
            local playerByChar = {}
            for _, p in ipairs(Players:GetPlayers()) do
                if p.Character then playerByChar[p.Character] = p end
            end
            local candidates = {}
            local seen = {}
            local function checkModel(m)
                if not m or m == myChar or seen[m] or not m:IsA("Model") then return end
                seen[m] = true
                local hum = m:FindFirstChildOfClass("Humanoid")
                local root = m:FindFirstChild("HumanoidRootPart")
                if not hum or not root or hum.Health <= 0 then return end
                if isCharProtected(m) then return end
                local plr = playerByChar[m]
                if not plr and not BotCfg.targetDummies then return end
                if plr and BotCfg.ignoreFriends and LocalPlayer:IsFriendsWith(plr.UserId) then return end
                local d = (root.Position - myRoot.Position).Magnitude
                if d <= BotCfg.maxRange then
                    updateEnemyIntel(m, root, hum, myRoot)
                    table.insert(candidates, {char = m, root = root, hum = hum, dist = d, plr = plr})
                end
            end

            local live = WS:FindFirstChild("Live")
            if live then
                for _, ch in ipairs(live:GetChildren()) do checkModel(ch) end
            end
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and p.Character then checkModel(p.Character) end
            end
            return candidates
        end

        local function selectTarget(myChar, myRoot)
            if BotCfg.targetMode == "Face Lock Target" and Theme.PvP and Theme.PvP.lockedTarget then
                local t = Theme.PvP.lockedTarget
                local tc = t:IsA("Model") and t or t.Character
                local th = tc and tc:FindFirstChildOfClass("Humanoid")
                local tr = tc and tc:FindFirstChild("HumanoidRootPart")
                if tc and tc ~= myChar and th and tr and th.Health > 0 and not isCharProtected(tc) then
                    if (tr.Position - myRoot.Position).Magnitude <= BotCfg.maxRange * 1.4 then
                        updateEnemyIntel(tc, tr, th, myRoot)
                        return tc, tr, th, tc.Name, nil, 1
                    end
                end
            end

            local list = scanAllEnemies(myChar, myRoot)
            if #list == 0 then return nil, nil, nil, "None", nil, 0 end

            local closestThreatChar, closestThreatRoot, threatHeavy, threatIsDash = nil, nil, false, false
            local closestThreatDist, closeAttackers = math.huge, 0
            for _, e in ipairs(list) do
                if e.dist <= 13 then closeAttackers = closeAttackers + 1 end
                if e.dist <= BotCfg.blockRange + 6 then
                    local atk, heavy, isDash = isCharAttacking(e.char, e.root, e.hum, myRoot)
                    if atk and e.dist < closestThreatDist then
                        closestThreatDist = e.dist
                        closestThreatChar, closestThreatRoot, threatHeavy, threatIsDash = e.char, e.root, heavy, isDash
                    end
                end
            end

            local threatInfo = closestThreatChar and {char = closestThreatChar, root = closestThreatRoot, heavy = threatHeavy, isDash = threatIsDash} or nil

            if BotState.targetChar and BotState.targetChar.Parent and BotState.targetHum and BotState.targetHum.Health > 0 and BotState.targetRoot and BotState.targetRoot.Parent then
                local curD = (BotState.targetRoot.Position - myRoot.Position).Magnitude
                if curD <= BotCfg.maxRange and not isCharProtected(BotState.targetChar) then
                    if not (closestThreatChar and closestThreatChar ~= BotState.targetChar and closestThreatDist < 10 and curD > 16) then
                        return BotState.targetChar, BotState.targetRoot, BotState.targetHum, BotState.targetName, threatInfo, closeAttackers
                    end
                end
            end

            local cam = WS.CurrentCamera
            local mLoc = (BotCfg.targetMode == "Closest to Crosshair" and cam) and UserInputService:GetMouseLocation() or nil
            local best, bestScore = nil, math.huge
            for _, e in ipairs(list) do
                local score = e.dist
                if BotCfg.targetMode == "Smart Pro" then
                    score = e.dist * 1.0 + e.hum.Health * 0.45
                    local intel = BotState.enemyIntel[e.char]
                    if intel and os.clock() < (intel.evasiveCdUntil or 0) then score = score - 14 end
                    if isCharRagdolledOrStunned(e.char) and e.dist < 22 then score = score - 18 end
                elseif BotCfg.targetMode == "Lowest HP" then
                    score = e.hum.Health * 1.8 + e.dist * 0.45
                elseif BotCfg.targetMode == "Closest to Crosshair" and cam and mLoc then
                    local sp, onScr = cam:WorldToViewportPoint(e.root.Position)
                    score = (onScr and (Vector2.new(sp.X, sp.Y) - mLoc).Magnitude or 9999) + e.dist * 1.4
                end
                if not e.plr then score = score + 28 end
                if score < bestScore then
                    bestScore = score
                    best = e
                end
            end
            if not best then return nil, nil, nil, "None", threatInfo, closeAttackers end
            local dName = best.plr and best.plr.DisplayName or best.char.Name
            return best.char, best.root, best.hum, dName, threatInfo, closeAttackers
        end

        -- ======================== SKILL ROLE CLASSIFIER & STRICT VALIDATION ========================
        local function classifySkill(sName)
            if sName == "" then return "extender" end
            if string.find(sName, "prey", 1, true) or string.find(sName, "split", 1, true) or string.find(sName, "counter", 1, true) then
                return "counter"
            elseif string.find(sName, "lethal", 1, true) or string.find(sName, "vanishing", 1, true) or string.find(sName, "flash", 1, true) or string.find(sName, "rise", 1, true) or string.find(sName, "crushing", 1, true) or string.find(sName, "homing", 1, true) then
                return "catcher"
            elseif string.find(sName, "normal", 1, true) or string.find(sName, "ignition", 1, true) or string.find(sName, "jet dive", 1, true) or string.find(sName, "atmos", 1, true) or string.find(sName, "bullet", 1, true) or string.find(sName, "quick slice", 1, true) or string.find(sName, "grand", 1, true) or string.find(sName, "shockwave", 1, true) then
                return "finisher"
            end
            return "extender"
        end

        local function getHotbarSkillState(myChar)
            local available = {false, false, false, false}
            local names = {"", "", "", ""}
            local roles = {"extender", "extender", "extender", "extender"}
            local tools = {}
            for _, c in ipairs(myChar:GetChildren()) do
                if c:IsA("Tool") then table.insert(tools, c) end
            end
            local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
            if bp then
                for _, c in ipairs(bp:GetChildren()) do
                    if c:IsA("Tool") then table.insert(tools, c) end
                end
            end
            for i = 1, math.min(4, #tools) do
                names[i] = string.lower(tools[i].Name or "")
                roles[i] = classifySkill(names[i])
                available[i] = (os.clock() >= (BotState.skillCdUntil[i] or 0))
            end

            pcall(function()
                local pg = LocalPlayer:FindFirstChild("PlayerGui")
                local hb = pg and pg:FindFirstChild("Hotbar")
                local bpFrame = hb and hb:FindFirstChild("Backpack") and hb.Backpack:FindFirstChild("Hotbar")
                if bpFrame then
                    for i = 1, 4 do
                        local slot = bpFrame:FindFirstChild(tostring(i))
                        local base = slot and slot:FindFirstChild("Base")
                        if base then
                            local tn = base:FindFirstChild("ToolName")
                            if tn and tn:IsA("TextLabel") and tn.Text ~= "" then
                                names[i] = string.lower(tn.Text)
                                roles[i] = classifySkill(names[i])
                                available[i] = (os.clock() >= (BotState.skillCdUntil[i] or 0))
                            end
                            local cd = base:FindFirstChild("Cooldown")
                            if cd and cd:IsA("GuiObject") and cd.Visible and cd.Size.Y.Scale > 0.02 then
                                available[i] = false
                            end
                        end
                    end
                end
            end)
            return available, names, roles
        end

        local function pickBestSkillSlot(avail, roles, dist, dy, targetStunned, targetAirborne, targetHp, hitConfirmed, myRoot, tRoot)
            -- STRICT ANTI-AIR-SPAM GUARD: must face target closely and be within genuine skill range!
            if not myRoot or not tRoot then return nil end
            local toT = flatVec(tRoot.Position - myRoot.Position)
            local myFwd = flatVec(myRoot.CFrame.LookVector)
            if toT and myFwd and myFwd:Dot(toT) < 0.45 then return nil end
            if math.abs(dy) > 5.2 and not targetAirborne then return nil end

            local wantRole
            if targetAirborne and dist <= 9.5 and hitConfirmed then
                wantRole = "catcher"
            elseif (targetStunned or targetHp <= 32) and dist <= 7.0 then
                wantRole = "finisher"
            else
                wantRole = "extender"
            end

            for i = 1, 4 do
                if avail[i] and roles[i] == wantRole then
                    local maxD = (roles[i] == "catcher") and 9.5 or 6.2
                    if dist <= maxD then return i end
                end
            end
            if hitConfirmed or targetStunned then
                for i = 1, 4 do
                    if avail[i] and roles[i] ~= "counter" then
                        local maxD = (roles[i] == "catcher" or roles[i] == "finisher") and 7.2 or 5.8
                        if dist <= maxD then return i end
                    end
                end
            end
            return nil
        end

        -- ======================== RECORD FOR BOT: REAL-TIME GAMEPLAY CAPTURE ========================
        local function recordPlayerAction(actionName)
            if not BotCfg.recordEnabled or BotCfg.enabled or Unloaded then return end
            local myChar, myHum, myRoot = getCharParts()
            if not myChar or not myHum or not myRoot then return end
            local tChar, tRoot, tHum = selectTarget(myChar, myRoot)
            if not tChar or not tRoot or not tHum then return end
            local dist = (tRoot.Position - myRoot.Position).Magnitude
            if dist > 48 then return end

            local now = os.clock()
            local dy = tRoot.Position.Y - myRoot.Position.Y
            local tBlock = isCharBlocking(tChar)
            local tStun = isCharRagdolledOrStunned(tChar)
            local tAir = (tHum.FloorMaterial == Enum.Material.Air and dy >= 2.0) or (dy >= 2.5)
            local tDash = tRoot:FindFirstChild("dodgevelocity") ~= nil
            local tAtk = isCharAttacking(tChar, tRoot, tHum, myRoot)
            local intel = BotState.enemyIntel[tChar]
            local noEv = intel and (now < (intel.evasiveCdUntil or 0)) or false

            local sKey = BotMem.buildStateKey(dist, dy, tBlock, tStun, tAir, tDash, tAtk, BotMem.recM1Count, noEv)
            local prevAct = BotMem.recPrevAction
            local chainDt = prevAct and (now - BotMem.recPrevAt) or nil
            BotMem.recPrevAction = actionName
            BotMem.recPrevAt = now

            table.insert(BotMem.pending, {
                stateKey = sKey,
                action = actionName,
                prevAct = prevAct,
                chainDt = chainDt,
                evalAt = now + 0.55,
                tChar = tChar,
                tHum = tHum,
                startEnemyHp = tHum.Health,
                startMyHp = myHum.Health,
                myHum = myHum,
            })
            setStatus("REC", "Captured " .. actionName)
        end

        track(UserInputService.InputBegan:Connect(function(inp, gp)
            if Unloaded or gp or not BotCfg.recordEnabled or BotCfg.enabled then return end
            if Theme._BotSynthMap and (Theme._BotSynthMap[inp.KeyCode] or 0) > os.clock() then return end
            local now = os.clock()
            if inp.UserInputType == Enum.UserInputType.MouseButton1 then
                if now - BotMem.recLastM1At > 1.1 then BotMem.recM1Count = 0 end
                BotMem.recM1Count = BotMem.recM1Count + 1
                BotMem.recLastM1At = now
                local act = "M1"
                if BotMem.recM1Count >= 4 then
                    BotMem.recM1Count = 0
                    local _, myHum = getCharParts()
                    if UserInputService:IsKeyDown(Enum.KeyCode.Space) then
                        act = "MiniUppercut"
                    elseif myHum and myHum.FloorMaterial == Enum.Material.Air then
                        act = "Downslam"
                    end
                end
                recordPlayerAction(act)
            elseif inp.KeyCode == Enum.KeyCode.Q then
                if UserInputService:IsKeyDown(Enum.KeyCode.A) then
                    recordPlayerAction("SideDashL")
                elseif UserInputService:IsKeyDown(Enum.KeyCode.D) then
                    recordPlayerAction("SideDashR")
                elseif UserInputService:IsKeyDown(Enum.KeyCode.S) then
                    recordPlayerAction("Backdash")
                else
                    recordPlayerAction("FrontDash")
                end
            elseif inp.KeyCode == Enum.KeyCode.F then
                if now - BotMem.recLastBlockAt > 0.35 then
                    BotMem.recLastBlockAt = now
                    recordPlayerAction("Block")
                end
            elseif inp.KeyCode == Enum.KeyCode.One then recordPlayerAction("Skill1")
            elseif inp.KeyCode == Enum.KeyCode.Two then recordPlayerAction("Skill2")
            elseif inp.KeyCode == Enum.KeyCode.Three then recordPlayerAction("Skill3")
            elseif inp.KeyCode == Enum.KeyCode.Four then recordPlayerAction("Skill4")
            end
        end))

        -- ======================== WHISKER OBSTACLE AVOIDANCE & NAVIGATION ========================
        local function makeExcludeParams(myChar, tChar)
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            pcall(function() params.RespectCanCollide = true end)
            local excl = {myChar}
            if tChar then table.insert(excl, tChar) end
            local thrown = WS:FindFirstChild("Thrown")
            if thrown then table.insert(excl, thrown) end
            local live = WS:FindFirstChild("Live")
            if live then table.insert(excl, live) end
            params.FilterDescendantsInstances = excl
            return params
        end

        local function hasClearLOS(fromPos, toPos, myChar, tChar)
            local diff = toPos - fromPos
            local dist = diff.Magnitude
            if dist < 2 then return true end
            local params = makeExcludeParams(myChar, tChar)
            local res = WS:Raycast(fromPos + Vector3.new(0, 0.5, 0), diff.Unit * math.min(dist - 1.5, 45), params)
            if not res then return true end
            if tChar and res.Instance:IsDescendantOf(tChar) then return true end
            return false
        end

        local function whiskerSteer(myRoot, dir, myChar, tChar)
            local params = makeExcludeParams(myChar, tChar)
            local origin = myRoot.Position + Vector3.new(0, 0.3, 0)
            local hitCenter = WS:Raycast(origin, dir * 5.2, params)
            if not hitCenter then return dir end
            local leftDir = yawVec(dir, -42)
            local rightDir = yawVec(dir, 42)
            local hitL = WS:Raycast(origin, leftDir * 6.0, params)
            local hitR = WS:Raycast(origin, rightDir * 6.0, params)
            if not hitL and hitR then return leftDir end
            if not hitR and hitL then return rightDir end
            if not hitL and not hitR then return (BotState.strafeSign > 0) and rightDir or leftDir end
            return yawVec(dir, 75 * BotState.strafeSign)
        end

        local function navigateToward(myChar, myHum, myRoot, tChar, tRoot, dist, targetBlocking, targetStunned)
            local now = os.clock()
            local goalPos = getPredictedTargetPos(tRoot) or tRoot.Position
            local direct = flatVec(goalPos - myRoot.Position)
            if not direct then BotMove.stop(); return end

            if BotState.lastPos and now - BotState.lastPosAt >= 0.42 then
                local moved = Vector3.new(myRoot.Position.X - BotState.lastPos.X, 0, myRoot.Position.Z - BotState.lastPos.Z).Magnitude
                if moved < 1.0 and dist > 6.5 then
                    BotState.stuckTime = BotState.stuckTime + (now - BotState.lastPosAt)
                    if BotState.stuckTime >= 0.42 then
                        if BotCfg.autoJump then myHum.Jump = true end
                        BotState.sidestepDir = yawVec(direct, 68 * BotState.strafeSign)
                        BotState.sidestepUntil = now + 0.34
                        BotState.stuckTime = 0
                    end
                else
                    BotState.stuckTime = 0
                end
                BotState.lastPos = myRoot.Position
                BotState.lastPosAt = now
            elseif not BotState.lastPos then
                BotState.lastPos = myRoot.Position
                BotState.lastPosAt = now
            end

            if now < BotState.sidestepUntil and BotState.sidestepDir then
                BotMove.set(BotState.sidestepDir)
                return
            end

            if dist <= 14.5 and math.abs(tRoot.Position.Y - myRoot.Position.Y) < 6 then
                if now >= BotState.nextStrafeFlipAt then
                    BotState.strafeSign = -BotState.strafeSign
                    BotState.nextStrafeFlipAt = now + 0.38 + math.random() * 0.55
                end
                if BotCfg.humanFeints and BotState.m1Count == 0 and not targetStunned and dist >= 7.5 and dist <= 13.5 and now >= BotState.nextHopAt then
                    BotState.nextHopAt = now + 1.8 + math.random() * 1.9
                    if math.random() < 0.45 then myHum.Jump = true end
                end
                if targetBlocking and dist <= 7.5 then
                    local enemyFwd = flatVec(tRoot.CFrame.LookVector) or direct
                    local flankTarget = tRoot.Position - enemyFwd * 3.8 + yawVec(enemyFwd, 90 * BotState.strafeSign) * 1.8
                    local toFlank = flatVec(flankTarget - myRoot.Position)
                    if toFlank then BotMove.set(toFlank); return end
                end

                local moveVec = direct
                local idealMin = (BotCfg.tier == "Balanced") and 3.8 or 2.8
                local idealMax = (BotCfg.tier == "Balanced") and 5.4 or 4.7
                if dist < idealMin then
                    moveVec = flatVec(-direct * 0.65 + yawVec(direct, 90 * BotState.strafeSign) * 0.72) or direct
                elseif dist <= idealMax then
                    local side = yawVec(direct, 84 * BotState.strafeSign)
                    moveVec = BotCfg.circleStrafe and (flatVec(side * BotCfg.strafeBias + direct * 0.38) or direct) or Vector3.zero
                elseif BotCfg.circleStrafe then
                    local ang = (dist <= 8.5) and 32 or 18
                    moveVec = yawVec(direct, ang * BotState.strafeSign)
                end
                if moveVec.Magnitude > 0.05 then
                    BotMove.set(whiskerSteer(myRoot, moveVec, myChar, tChar))
                else
                    BotMove.stop()
                end
                return
            end

            if hasClearLOS(myRoot.Position, goalPos, myChar, tChar) or not BotCfg.usePathfinding then
                BotMove.set(whiskerSteer(myRoot, direct, myChar, tChar))
                if BotCfg.autoJump and (tRoot.Position.Y - myRoot.Position.Y > 3.5) and dist < 18 then
                    myHum.Jump = true
                end
                return
            end

            if not BotState.waypoints or (now - BotState.lastPathAt > 0.42) or (BotState.lastPathGoal and (BotState.lastPathGoal - goalPos).Magnitude > 9) then
                BotState.lastPathAt = now
                BotState.lastPathGoal = goalPos
                local p = PathfindingService:CreatePath({AgentRadius = 2.4, AgentHeight = 5.5, AgentCanJump = true})
                local ok = pcall(function() p:ComputeAsync(myRoot.Position, goalPos) end)
                if ok and p.Status == Enum.PathStatus.Success then
                    BotState.waypoints = p:GetWaypoints()
                    BotState.wpIndex = 2
                else
                    BotState.waypoints = nil
                end
            end

            if BotState.waypoints and BotState.wpIndex <= #BotState.waypoints then
                while BotState.wpIndex < #BotState.waypoints do
                    local wpCheck = BotState.waypoints[BotState.wpIndex]
                    local dWp = Vector3.new(wpCheck.Position.X - myRoot.Position.X, 0, wpCheck.Position.Z - myRoot.Position.Z).Magnitude
                    if dWp < 4.0 then
                        BotState.wpIndex = BotState.wpIndex + 1
                    else
                        break
                    end
                end
                local wp = BotState.waypoints[BotState.wpIndex]
                if wp.Action == Enum.PathWaypointAction.Jump and BotCfg.autoJump then
                    myHum.Jump = true
                end
                local stepDir = flatVec(wp.Position - myRoot.Position) or direct
                BotMove.set(stepDir)
            else
                BotMove.set(whiskerSteer(myRoot, direct, myChar, tChar))
            end
        end

        -- ======================== ASYNC PRO TECH & COMBAT COROUTINE ========================
        local function waitBot(tok, sec)
            local deadline = os.clock() + math.max(0.008, sec)
            while os.clock() < deadline do
                if Unloaded or not BotCfg.enabled or tok ~= BotState.runningToken then return false end
                local _, hum, root = getCharParts()
                if not hum or not root then return false end
                RunService.Heartbeat:Wait()
            end
            return BotCfg.enabled and tok == BotState.runningToken
        end

        local function tapBotKey(tok, key, holdSec)
            Input.keyDown(key)
            local ok = waitBot(tok, holdSec or 0.04)
            Input.keyUp(key)
            return ok
        end

        local function tapBotM1(tok, holdSec)
            Input.mouseDown()
            local ok = waitBot(tok, holdSec or 0.042)
            Input.mouseUp()
            return ok
        end

        local function triggerFrontDash(tok)
            Input.keyUp(Enum.KeyCode.A); Input.keyUp(Enum.KeyCode.D); Input.keyUp(Enum.KeyCode.S)
            BotState.lastFrontDashAt = os.clock()
            return tapBotKey(tok, Enum.KeyCode.Q, 0.042)
        end

        local function triggerSideDash(tok, rightSide, dashAngleDeg)
            if ModelRot.active and ModelRot.steerDash and ModelRot.dir then
                ModelRot.dashDir = yawVec(ModelRot.dir, (rightSide and 1 or -1) * (dashAngleDeg or 76))
            end
            BotState.lastSideDashAt = os.clock()
            local dirKey = rightSide and Enum.KeyCode.D or Enum.KeyCode.A
            Input.keyUp(rightSide and Enum.KeyCode.A or Enum.KeyCode.D)
            Input.keyUp(Enum.KeyCode.S); Input.keyUp(Enum.KeyCode.W)
            Input.keyDown(dirKey)
            if not waitBot(tok, 0.026) then Input.keyUp(dirKey); return false end
            Input.keyDown(Enum.KeyCode.Q)
            local ok = waitBot(tok, 0.044)
            Input.keyUp(Enum.KeyCode.Q)
            waitBot(tok, 0.022)
            Input.keyUp(dirKey)
            return ok
        end

        local function triggerBackdash(tok)
            BotState.lastBackdashAt = os.clock()
            Input.keyUp(Enum.KeyCode.W); Input.keyUp(Enum.KeyCode.A); Input.keyUp(Enum.KeyCode.D)
            Input.keyDown(Enum.KeyCode.S)
            if not waitBot(tok, 0.026) then Input.keyUp(Enum.KeyCode.S); return false end
            Input.keyDown(Enum.KeyCode.Q)
            local ok = waitBot(tok, 0.042)
            Input.keyUp(Enum.KeyCode.Q)
            return ok
        end

        local function markBotAction(name)
            BotState.lastBotAction = name
            BotState.lastBotActionAt = os.clock()
        end

        local function runTechCoroutine(techName, tChar, tRoot, slotIndex, extraRight)
            local myToken = BotState.runningToken
            BotState.activeTechName = techName
            BotState.techBusyUntil = os.clock() + 1.6
            Input.setBlock(false)
            if techName ~= "GapDash" then BotMove.stop() end

            local ok, err = pcall(function()
                local _, myHum, myRoot = getCharParts()
                if not myHum or not myRoot then return end
                local fwd = getBaseForward(tRoot, myRoot)
                local sgn = (extraRight ~= nil) and (extraRight and 1 or -1) or resolveCurveSign(tRoot, myRoot)

                if techName == "GapDash" then
                    markBotAction("FrontDash")
                    setStatus("CHASE", "Gap-Close Dash")
                    ModelRot.start(fwd, true, false)
                    BotMove.set(fwd)
                    if not triggerFrontDash(myToken) then return end
                    local dur = pingWaitSec(0.28, 0.3)
                    local t0 = os.clock()
                    while os.clock() - t0 < dur do
                        if Unloaded or not BotCfg.enabled or myToken ~= BotState.runningToken then return end
                        local _, _, rn = getCharParts()
                        if not rn then return end
                        local face = getBaseForward(tRoot, rn)
                        if tChar and isCharBlocking(tChar) then
                            local curve = yawVec(face, sgn * 72)
                            ModelRot.setDir(curve, curve, true)
                        else
                            ModelRot.setDir(face, face, true)
                        end
                        BotMove.set(face)
                        local dNow = (tRoot and tRoot.Parent) and (tRoot.Position - rn.Position).Magnitude or 99
                        if dNow <= 5.5 then break end
                        RunService.Heartbeat:Wait()
                    end

                elseif techName == "LoopDash" or techName == "OreoDash" then
                    markBotAction("FrontDash")
                    setStatus("TECH", techName == "LoopDash" and "Loop Dash" or "Oreo Dash")
                    ModelRot.start(fwd, true, false)
                    if techName == "OreoDash" then
                        local stepEnd = os.clock() + pingWaitSec(0.105, 0.25)
                        while os.clock() < stepEnd do
                            if not waitBot(myToken, 0.012) then return end
                            local _, _, rNow = getCharParts()
                            if rNow then
                                local f = getBaseForward(tRoot, rNow)
                                BotMove.set(yawVec(f, sgn * 36))
                                ModelRot.setDir(f, nil, true)
                            end
                        end
                        BotMove.stop()
                    end
                    local sweep = (techName == "LoopDash") and 228 or 190
                    local dur = pingWaitSec((techName == "LoopDash") and 0.345 or 0.285, 0.45)
                    ModelRot.setDir(yawVec(fwd, sgn * 22), yawVec(fwd, sgn * 22), true)
                    if not triggerFrontDash(myToken) then return end
                    local t0 = os.clock()
                    while os.clock() - t0 < dur do
                        if Unloaded or not BotCfg.enabled or myToken ~= BotState.runningToken then return end
                        local _, _, rn = getCharParts()
                        if not rn then return end
                        local el = os.clock() - t0
                        local p = math.clamp(el / dur, 0, 1)
                        local aimPos = (tRoot and tRoot.Parent) and (getPredictedTargetPos(tRoot) or tRoot.Position) or nil
                        local toT = aimPos and flatVec(aimPos - rn.Position) or fwd
                        local dNow = aimPos and (aimPos - rn.Position).Magnitude or 99
                        if el >= dur * 0.52 and (dNow <= 5.5 or not rn:FindFirstChild("dodgevelocity")) then
                            ModelRot.setDir(toT, toT, true); break
                        end
                        local ang
                        if techName == "LoopDash" then
                            ang = (p < 0.36) and (sgn * (18 + (p / 0.36) * (sweep * 0.42))) or ((p < 0.72) and (sgn * (18 + sweep * 0.42 + ((p - 0.36) / 0.36) * (sweep * 0.48))) or (sgn * (18 + sweep * 0.90) * (1 - (p - 0.72) / 0.28)))
                        else
                            ang = (p < 0.36) and (sgn * (28 - p * 45)) or (sgn * (11 - ((p - 0.36) / 0.64) * 185))
                        end
                        local dir = yawVec(toT, ang)
                        ModelRot.setDir(dir, dir, true)
                        RunService.Heartbeat:Wait()
                    end
                    local _, _, rEnd = getCharParts()
                    if rEnd and tRoot and tRoot.Parent then
                        ModelRot.setDir(getBaseForward(tRoot, rEnd), nil, true)
                        if (tRoot.Position - rEnd.Position).Magnitude <= 7.0 and not (tChar and isCharBlocking(tChar)) then
                            tapBotM1(myToken, 0.04)
                        end
                    end

                elseif techName == "SupaDash" or techName == "TwistedDash" then
                    markBotAction("FrontDash")
                    setStatus("TECH", techName == "SupaDash" and "Supa Dash" or "Twisted Dash")
                    ModelRot.start(fwd, true, false)
                    local stepDur = pingWaitSec((techName == "SupaDash") and 0.09 or 0.115, 0.2)
                    local tEnd = os.clock() + stepDur
                    while os.clock() < tEnd do
                        if not waitBot(myToken, 0.012) then return end
                        local _, _, rNow = getCharParts()
                        if rNow then
                            local f = getBaseForward(tRoot, rNow)
                            BotMove.set(yawVec(-f, (techName == "SupaDash") and (sgn * 24) or 0))
                            ModelRot.setDir(f, nil, true)
                        end
                    end
                    BotMove.stop()
                    local _, _, r1 = getCharParts()
                    local intoT = getBaseForward(tRoot, r1)
                    ModelRot.setDir(intoT, intoT, true)
                    if not triggerFrontDash(myToken) then return end
                    if techName == "SupaDash" then
                        if not waitBot(myToken, pingWaitSec(0.158, 0.4)) then return end
                        ModelRot.setDir(-intoT, intoT, true)
                        waitBot(myToken, 0.085)
                    else
                        local dur = pingWaitSec(0.24, 0.35)
                        local t0 = os.clock()
                        while os.clock() - t0 < dur do
                            if Unloaded or not BotCfg.enabled or myToken ~= BotState.runningToken then return end
                            local _, _, rn = getCharParts()
                            if not rn then return end
                            local p = math.clamp((os.clock() - t0) / dur, 0, 1)
                            local toT = getBaseForward(tRoot, rn)
                            local d = yawVec(toT, sgn * 38 * (1 - p))
                            ModelRot.setDir(d, d, true)
                            RunService.Heartbeat:Wait()
                        end
                    end
                    local _, _, r2 = getCharParts()
                    if r2 and tRoot and tRoot.Parent then
                        ModelRot.setDir(getBaseForward(tRoot, r2), nil, true)
                        if (tRoot.Position - r2.Position).Magnitude <= 7.0 and not (tChar and isCharBlocking(tChar)) then
                            tapBotM1(myToken, 0.04)
                        end
                    end

                elseif techName == "M1Reset" then
                    markBotAction("SideDashR")
                    setStatus("TECH", "M1 Reset")
                    ModelRot.start(fwd, true, false)
                    if not triggerSideDash(myToken, sgn > 0, 80) then return end
                    if not waitBot(myToken, pingWaitSec(0.105, 0.35)) then return end
                    local _, hNow, rNow = getCharParts()
                    if rNow then
                        for _, dv in ipairs(rNow:GetChildren()) do
                            if dv.Name == "dodgevelocity" then pcall(function() dv:Destroy() end) end
                        end
                    end
                    if hNow then
                        local anim = hNow:FindFirstChildOfClass("Animator")
                        if anim then
                            for _, tr in ipairs(anim:GetPlayingAnimationTracks()) do
                                local id = tr.Animation and tostring(tr.Animation.AnimationId) or ""
                                if string.find(id, "10480793962", 1, true) or string.find(id, "10480796021", 1, true) then
                                    pcall(function() tr:Stop(0) end)
                                end
                            end
                        end
                    end
                    if not rNow or not rNow.Parent then return end
                    ModelRot.setDir(getBaseForward(tRoot, rNow), nil, true)
                    local cNow = LocalPlayer and LocalPlayer.Character
                    if cNow and not cNow:FindFirstChild("UsedDash") and waitBot(myToken, 0.018) then
                        triggerFrontDash(myToken)
                        waitBot(myToken, pingWaitSec(0.185, 0.3))
                    end
                    local _, _, rEnd = getCharParts()
                    if rEnd and tRoot and tRoot.Parent and (tRoot.Position - rEnd.Position).Magnitude <= 6.8 and not (tChar and isCharBlocking(tChar)) then
                        tapBotM1(myToken, 0.04)
                    end

                elseif techName == "BackdashCancel" then
                    markBotAction("Backdash")
                    setStatus("TECH", "Backdash Cancel")
                    ModelRot.start(fwd, false, false)
                    if not triggerBackdash(myToken) then Input.keyUp(Enum.KeyCode.S); return end
                    waitBot(myToken, pingWaitSec(0.082, 0.3))
                    Input.keyUp(Enum.KeyCode.S)
                    local _, _, rn = getCharParts()
                    if rn then ModelRot.setDir(getBaseForward(tRoot, rn), nil, true) end
                    if slotIndex and rn and tRoot and tRoot.Parent and (tRoot.Position - rn.Position).Magnitude <= 11.5 then
                        local slot = slotIndex
                        BotState.skillCdUntil[slot] = os.clock() + 13.5
                        BotState.nextSkillAt = os.clock() + 1.1
                        tapBotKey(myToken, SLOT_KEYS[slot], 0.044)
                        waitBot(myToken, 0.42)
                    end

                elseif techName == "SideFlank" then
                    markBotAction((sgn > 0) and "SideDashR" or "SideDashL")
                    setStatus("TECH", "Side Dash Flank")
                    ModelRot.start(fwd, true, false)
                    if not triggerSideDash(myToken, sgn > 0, 78) then return end
                    local t0 = os.clock()
                    local w = pingWaitSec(0.185, 0.4)
                    while os.clock() - t0 < w do
                        if Unloaded or not BotCfg.enabled or myToken ~= BotState.runningToken then return end
                        local _, _, rn = getCharParts()
                        if rn then ModelRot.setDir(getBaseForward(tRoot, rn), nil, true) end
                        RunService.Heartbeat:Wait()
                    end
                    local _, _, rEnd = getCharParts()
                    if rEnd and tRoot and tRoot.Parent and (tRoot.Position - rEnd.Position).Magnitude <= 6.8 then
                        tapBotM1(myToken, 0.04)
                    end

                elseif techName == "MiniUppercut" then
                    markBotAction("MiniUppercut")
                    setStatus("COMBO", "Mini Uppercut (4th)")
                    ModelRot.start(fwd, false, false)
                    Input.keyDown(Enum.KeyCode.Space)
                    if not waitBot(myToken, pingWaitSec(0.068, 0.25)) then Input.keyUp(Enum.KeyCode.Space); return end
                    tapBotM1(myToken, 0.042)
                    waitBot(myToken, pingWaitSec(0.095, 0.25))
                    Input.keyUp(Enum.KeyCode.Space)

                elseif techName == "Downslam" then
                    markBotAction("Downslam")
                    setStatus("COMBO", "True Downslam (4th)")
                    ModelRot.start(fwd, false, false)
                    if not tapBotKey(myToken, Enum.KeyCode.Space, 0.044) then return end
                    if not waitBot(myToken, pingWaitSec(0.165, 0.35)) then return end
                    local _, _, rn = getCharParts()
                    if rn then ModelRot.setDir(getBaseForward(tRoot, rn), nil, true) end
                    tapBotM1(myToken, 0.044)

                elseif techName == "SkillCast" then
                    local slot = slotIndex or 1
                    markBotAction("Skill" .. tostring(slot))
                    setStatus("SKILL", "Cast Slot " .. tostring(slot))
                    -- Face target squarely first before releasing skill
                    ModelRot.start(fwd, false, false)
                    waitBot(myToken, 0.025)
                    local _, myC, rn0 = getCharParts()
                    if not myC or not rn0 then return end
                    -- Double-check target didn't dash far away during the 25ms align!
                    if not tRoot or not tRoot.Parent or (tRoot.Position - rn0.Position).Magnitude > 11.5 then
                        return
                    end
                    local _, sNames = getHotbarSkillState(myC)
                    local sName = sNames[slot] or ""
                    local isBackCast = BotCfg.tech180Flicks and (string.find(sName, "ignition", 1, true) or string.find(sName, "quick slice", 1, true))
                    if isBackCast then ModelRot.setDir(-getBaseForward(tRoot, rn0), nil, true) end
                    BotState.skillCdUntil[slot] = os.clock() + 13.5
                    BotState.nextSkillAt = os.clock() + 1.05
                    tapBotKey(myToken, SLOT_KEYS[slot], 0.044)
                    if isBackCast then
                        waitBot(myToken, pingWaitSec(0.22, 0.45))
                        local _, _, rn = getCharParts()
                        if rn then ModelRot.setDir(getBaseForward(tRoot, rn), nil, true) end
                    elseif BotCfg.techKyoto and slot == 1 and string.find(sName, "flowing", 1, true) and (os.clock() + 2.2 >= (BotState.skillCdUntil[2] or 0)) then
                        BotState.techBusyUntil = os.clock() + 2.8
                        if waitBot(myToken, pingWaitSec(2.14, 0.4)) and tRoot and tRoot.Parent then
                            local _, _, rn = getCharParts()
                            if rn and (tRoot.Position - rn.Position).Magnitude <= 34 then
                                setStatus("TECH", "Kyoto Catch (Dash + 2)")
                                ModelRot.start(getBaseForward(tRoot, rn), true, false)
                                if triggerSideDash(myToken, sgn > 0, 8) then
                                    waitBot(myToken, pingWaitSec(0.072, 0.2))
                                    local _, _, r2 = getCharParts()
                                    if r2 then ModelRot.setDir(getBaseForward(tRoot, r2), nil, true) end
                                    BotState.skillCdUntil[2] = os.clock() + 14
                                    tapBotKey(myToken, Enum.KeyCode.Two, 0.044)
                                end
                            end
                        end
                    elseif BotCfg.tech180Flicks and (string.find(sName, "water stream", 1, true) or string.find(sName, "peril", 1, true) or string.find(sName, "swift", 1, true) or string.find(sName, "fourfold", 1, true)) then
                        if waitBot(myToken, pingWaitSec(0.45, 0.3)) then
                            local _, _, rn = getCharParts()
                            if rn then ModelRot.setDir(-getBaseForward(tRoot, rn), nil, true) end
                            waitBot(myToken, pingWaitSec(0.255, 0.5))
                            local _, _, r2 = getCharParts()
                            if r2 then ModelRot.setDir(getBaseForward(tRoot, r2), nil, true) end
                        end
                    else
                        -- Wait cleanly until skill animation settles (min 0.45s, max 0.95s) so bot doesn't chain-spam skills
                        local sStart = os.clock()
                        while os.clock() - sStart < 0.95 do
                            if not waitBot(myToken, 0.05) then return end
                            local cCheck = LocalPlayer and LocalPlayer.Character
                            if os.clock() - sStart >= 0.45 and cCheck and not cCheck:FindFirstChild("NoAttack") and not cCheck:FindFirstChild("UsingMove") then
                                break
                            end
                        end
                    end
                end
            end)

            if not ok then warn("[FaceLess CombatBot] " .. tostring(techName) .. ": " .. tostring(err)) end
            BotMove.stop()
            BotState.activeTechName = nil
            BotState.techBusyUntil = 0
        end

        -- ======================== MAIN PRO AI HEARTBEAT BRAIN ========================
        local function stopBot()
            BotState.runningToken = BotState.runningToken + 1
            BotState.activeTechName = nil
            BotState.techBusyUntil = 0
            BotState.m1Count = 0
            BotState.lastKnownHp = nil
            BotState.waypoints = nil
            BotMove.unbind()
            Input.releaseAll()
            ModelRot.stop()
            if not BotCfg.recordEnabled then
                statusGui.Visible = false
            else
                setStatus("REC", "Watching")
            end
        end

        track(RunService.Heartbeat:Connect(function()
            if Unloaded then return end
            local now = os.clock()

            -- Evaluate pending recorded user actions (reinforcement outcome check!)
            if #BotMem.pending > 0 then
                for i = #BotMem.pending, 1, -1 do
                    local item = BotMem.pending[i]
                    if now >= item.evalAt then
                        table.remove(BotMem.pending, i)
                        local dealt = (item.tHum and item.tHum.Parent) and math.max(0, item.startEnemyHp - item.tHum.Health) or 0
                        local took = (item.myHum and item.myHum.Parent) and math.max(0, item.startMyHp - item.myHum.Health) or 0
                        local reward = 0.2
                        if dealt >= 2 then
                            reward = 2.5 + math.min(2.0, dealt * 0.08)
                        elseif item.action == "Block" and took < 1 then
                            reward = 1.8
                        elseif string.find(item.action, "Dash", 1, true) and took < 1 then
                            reward = 1.2
                        elseif dealt == 0 and (string.sub(item.action, 1, 5) == "Skill" or item.action == "M1") then
                            reward = -0.6 -- whiffed attack into thin air: penalize so bot doesn't copy misclicks!
                        end
                        if took > 5 and item.action ~= "Block" then
                            reward = reward - 0.5
                        end
                        BotMem.commitSample(item.stateKey, item.action, reward, item.prevAct, item.chainDt)
                        if now - BotMem.lastSaveAt > 4.0 then
                            BotMem.lastSaveAt = now
                            BotMem.save()
                        end
                    end
                end
            end

            if BotCfg.recordEnabled and not BotCfg.enabled then
                local mc, _, mr = getCharParts()
                if mc and mr then selectTarget(mc, mr) end
                setStatus("REC", "Observing your fights")
                return
            end

            if not BotCfg.enabled then return end
            if BotState.activeTechName then
                if now > BotState.techBusyUntil then
                    BotState.activeTechName = nil
                else
                    return
                end
            end

            local myChar, myHum, myRoot = getCharParts()
            if not myChar or not myHum or not myRoot then
                Input.releaseAll()
                ModelRot.stop()
                BotState.lastKnownHp = nil
                setStatus("WAIT", "Respawning...")
                return
            end

            if BotState.lastKnownHp and myHum.Health < BotState.lastKnownHp - 1 then
                BotState.lastDamagedAt = now
            end
            BotState.lastKnownHp = myHum.Health

            if BotCfg.autoUlt and myHum.Health <= 38 then
                pcall(function()
                    local ultVal = LocalPlayer:FindFirstChild("Ult") or myChar:FindFirstChild("Ult")
                    if ultVal and ultVal:IsA("NumberValue") and ultVal.Value >= 100 then
                        task.spawn(tapBotKey, BotState.runningToken, Enum.KeyCode.G, 0.05)
                    end
                end)
            end

            if myChar:FindFirstChild("Ragdoll") ~= nil then
                Input.setBlock(false)
                BotMove.stop()
                ModelRot.stop()
                setStatus("EVASIVE", "Ragdoll Cancel")
                if BotCfg.autoEvasive and (now - BotState.lastEvasiveAt > 3.2) then
                    BotState.lastEvasiveAt = now
                    task.spawn(function() tapBotKey(BotState.runningToken, Enum.KeyCode.Q, 0.045) end)
                end
                return
            end

            if isCharRagdolledOrStunned(myChar) then
                Input.setBlock(false)
                BotMove.stop()
                setStatus("STUNNED", "Recovering")
                return
            end

            local tChar, tRoot, tHum, tName, threat, closeCount = selectTarget(myChar, myRoot)
            BotState.targetChar, BotState.targetRoot, BotState.targetHum, BotState.targetName = tChar, tRoot, tHum, tName
            BotState.targetHp = tHum and tHum.Health or 0

            if not tChar or not tRoot or not tHum then
                Input.setBlock(false)
                BotMove.stop()
                ModelRot.stop()
                setStatus("SCAN", "Searching...")
                return
            end

            local dist = (tRoot.Position - myRoot.Position).Magnitude
            local dy = tRoot.Position.Y - myRoot.Position.Y
            local targetBlocking = isCharBlocking(tChar)
            local targetStunned = isCharRagdolledOrStunned(tChar)
            local targetAirborne = (tHum.FloorMaterial == Enum.Material.Air and dy >= 2.2) or (dy >= 2.6)
            local intel = BotState.enemyIntel[tChar]
            local enemyHasNoEvasive = BotCfg.trackEnemyEvasive and intel and (now < (intel.evasiveCdUntil or 0))
            local whiffPunishReady = BotCfg.dashPunish and intel and (now < (intel.dashPunishUntil or 0))
            local hitConfirmed = (now - BotState.lastHitLandedAt < 1.35) or (intel and (now - (intel.lastDamagedAt or 0) < 1.35))

            local canFrontDash = (not myChar:FindFirstChild("UsedDash")) and (now - BotState.lastFrontDashAt > 1.2)
            local canSideDash = (not myRoot:FindFirstChild("dodgevelocity")) and (now - BotState.lastSideDashAt > 2.25)
            local canBackdash = (not myChar:FindFirstChild("UsedDash")) and (now - BotState.lastBackdashAt > 2.2)

            if dist <= 14.5 or (threat and threat.char ~= nil) then
                ModelRot.start(getBaseForward(tRoot, myRoot), false, true)
            else
                ModelRot.stop()
            end

            -- 3. Auto Block + Whiff Punish + Outnumbered Peel
            local recentlyHitClose = (now - BotState.lastDamagedAt < 0.28) and dist <= 13
            local activeThreat = (threat and threat.char ~= nil) or (recentlyHitClose and not targetStunned)

            if closeCount >= 2 and canSideDash and not BotState.blocking and now >= BotState.blockCooldownUntil and (threat and threat.char ~= nil) then
                task.spawn(runTechCoroutine, "SideFlank", tChar, tRoot, nil, math.random() < 0.5)
                return
            end

            if BotCfg.autoBlock and activeThreat and now >= BotState.blockCooldownUntil and not targetStunned then
                local threatRoot = (threat and threat.root) or tRoot
                ModelRot.start(getBaseForward(threatRoot, myRoot), false, false)

                if threat and threat.heavy and BotCfg.blockBreakSideDash and canSideDash then
                    Input.setBlock(false)
                    BotState.blockCooldownUntil = now + 0.45
                    task.spawn(runTechCoroutine, "SideFlank", tChar, tRoot, nil, math.random() < 0.5)
                    return
                end

                if threat and threat.isDash and BotCfg.tier == "Pro Streamer" and canSideDash and dist <= 11 and math.random() < 0.35 then
                    Input.setBlock(false)
                    task.spawn(runTechCoroutine, "SideFlank", tChar, tRoot, nil, math.random() < 0.5)
                    return
                end

                if BotCfg.useSkills and BotCfg.tier == "Pro Streamer" and dist <= 10.0 and now >= BotState.nextSkillAt and math.random() < 0.35 then
                    local avail, _, roles = getHotbarSkillState(myChar)
                    for slot = 1, 4 do
                        if avail[slot] and roles[slot] == "counter" then
                            Input.setBlock(false)
                            task.spawn(runTechCoroutine, "SkillCast", tChar, tRoot, slot)
                            return
                        end
                    end
                end

                BotMove.stop()
                Input.setBlock(true)
                BotState.blockedThreatWasDash = (threat and threat.isDash) == true
                if BotState.blockUntil <= now then
                    BotState.blockUntil = now + (BotCfg.blockHoldMs / 1000) + ((BotCfg.tier == "Balanced") and 0.08 or 0)
                end
                setStatus("BLOCK", BotState.blockedThreatWasDash and "Guarding Dash" or "Guarding Combo")
                return
            elseif BotState.blocking then
                if now < BotState.blockUntil and (threat and threat.char ~= nil) then
                    BotMove.stop()
                    ModelRot.setDir(getBaseForward(threat.root or tRoot, myRoot), nil, true)
                    setStatus("BLOCK", "Holding Guard")
                    return
                end
                local wasDashBlock = BotState.blockedThreatWasDash
                BotState.blockedThreatWasDash = false
                Input.setBlock(false)
                BotState.blockUntil = 0
                BotState.blockCooldownUntil = now + ((BotCfg.tier == "Balanced") and 0.18 or 0.30)

                if wasDashBlock and dist <= 8.5 and BotCfg.dashPunish then
                    if targetBlocking and canSideDash then
                        task.spawn(runTechCoroutine, "SideFlank", tChar, tRoot, nil, math.random() < 0.5)
                    else
                        BotState.nextM1At = 0
                    end
                elseif BotCfg.counterAfterBlock and canSideDash and dist <= 12 then
                    task.spawn(runTechCoroutine, "SideFlank", tChar, tRoot, nil, math.random() < 0.5)
                    return
                end
            end

            -- 4. Learned Memory Decision Overlay (Replays User's Recorded Style & Chains Safely)
            if BotCfg.useLearnedMemory and BotMem.totalSamples >= 3 and dist <= 34 and (now - BotState.lastBotActionAt >= 0.45) then
                local avail, _, _ = getHotbarSkillState(myChar)
                local sk = BotMem.buildStateKey(dist, dy, targetBlocking, targetStunned, targetAirborne, (tRoot:FindFirstChild("dodgevelocity") ~= nil), activeThreat, BotState.m1Count, enemyHasNoEvasive)
                local learned = BotMem.chooseAction(sk, BotState.lastBotAction, now - BotState.lastBotActionAt, avail, canFrontDash, canSideDash, canBackdash)
                if learned and not (learned == BotState.lastBotAction and now - BotState.lastBotActionAt < 1.1) then
                    if learned == "SideDashL" and canSideDash and dist <= 13.5 then
                        task.spawn(runTechCoroutine, "SideFlank", tChar, tRoot, nil, false); return
                    elseif learned == "SideDashR" and canSideDash and dist <= 13.5 then
                        task.spawn(runTechCoroutine, "SideFlank", tChar, tRoot, nil, true); return
                    elseif learned == "FrontDash" and canFrontDash and ((targetAirborne and (hitConfirmed or targetStunned) and dist >= 4.5) or dist >= 9.0) and dist <= 32 then
                        task.spawn(runTechCoroutine, targetAirborne and "LoopDash" or "GapDash", tChar, tRoot, nil); return
                    elseif learned == "MiniUppercut" and dist <= 5.8 and now >= BotState.nextM1At and (BotState.m1Count >= 3 or hitConfirmed) then
                        BotState.m1Count = 0; task.spawn(runTechCoroutine, "MiniUppercut", tChar, tRoot, nil); return
                    elseif learned == "Downslam" and dist <= 5.8 and now >= BotState.nextM1At and (BotState.m1Count >= 3 or hitConfirmed) then
                        BotState.m1Count = 0; task.spawn(runTechCoroutine, "Downslam", tChar, tRoot, nil); return
                    elseif string.sub(learned, 1, 5) == "Skill" and BotCfg.useSkills and now >= BotState.nextSkillAt and dist <= 6.5 and math.abs(dy) < 5.0 and (hitConfirmed or targetStunned or dist <= 5.4) then
                        local slot = tonumber(string.sub(learned, 6, 6))
                        if slot and avail[slot] then
                            BotState.m1Count = 0
                            task.spawn(runTechCoroutine, "SkillCast", tChar, tRoot, slot); return
                        end
                    end
                end
            end

            -- 5. Hit-Confirm Abort on Enemy Block
            if targetBlocking and dist <= 12.5 then
                BotState.m1Count = 0
                if BotCfg.antiBlockFlank and canSideDash then
                    task.spawn(runTechCoroutine, "SideFlank", tChar, tRoot, nil, math.random() < 0.5)
                    return
                end
            end

            -- 6. Autonomous Techs (Air Catch ONLY after real hit/stun; 4th M1 chase)
            if BotCfg.autoTechs then
                if BotCfg.techLoopOreo and targetAirborne and (hitConfirmed or targetStunned) and dist >= 4.5 and dist <= 22 and canFrontDash then
                    local pick = (math.random() < 0.55) and "LoopDash" or "OreoDash"
                    task.spawn(runTechCoroutine, pick, tChar, tRoot, nil)
                    return
                end
                if BotCfg.techSupaTwisted and (now - BotState.justLanded4thAt < 0.65) and dist >= 7.5 and dist <= 25 and canFrontDash then
                    BotState.justLanded4thAt = 0
                    local pick = (math.random() < 0.55) and "TwistedDash" or "SupaDash"
                    task.spawn(runTechCoroutine, pick, tChar, tRoot, nil)
                    return
                end
            end

            -- 7. Walk / Footsies / Gap-Close Dash
            navigateToward(myChar, myHum, myRoot, tChar, tRoot, dist, targetBlocking, targetStunned)

            if BotCfg.autoDash and dist >= 17 and dist <= BotCfg.dashEngageRange and canFrontDash and math.abs(dy) < 9 then
                if not targetBlocking or dist >= 22 then
                    task.spawn(runTechCoroutine, "GapDash", tChar, tRoot, nil)
                    return
                end
            end

            -- 8. Melee Combat & Strict-Range Hit-Confirmed Skills
            if dist <= 6.0 and math.abs(dy) < 5.2 then
                if now - BotState.lastM1At > 1.1 then
                    BotState.m1Count = 0
                end

                local readyForSkill = (not BotCfg.milk3M1) or (BotState.m1Count >= 3) or targetStunned or (hitConfirmed and dist <= 5.8) or whiffPunishReady
                if BotCfg.useSkills and not targetBlocking and now >= BotState.nextSkillAt and readyForSkill then
                    local avail, _, roles = getHotbarSkillState(myChar)
                    local slot = pickBestSkillSlot(avail, roles, dist, dy, targetStunned, targetAirborne, tHum.Health, hitConfirmed, myRoot, tRoot)
                    if slot then
                        BotState.m1Count = 0
                        task.spawn(runTechCoroutine, "SkillCast", tChar, tRoot, slot)
                        return
                    end
                end

                if BotCfg.autoM1 and not targetBlocking and now >= BotState.nextM1At then
                    BotState.m1Count = BotState.m1Count + 1
                    BotState.lastM1At = now
                    local jitter = (math.random() - 0.5) * 0.03
                    BotState.nextM1At = now + pingWaitSec(0.222, 0.25) + jitter

                    if BotState.m1Count == 3 and BotCfg.autoTechs and BotCfg.techM1Reset and canSideDash and hitConfirmed and (enemyHasNoEvasive or math.random() < 0.55) then
                        BotState.m1Count = 0
                        task.spawn(runTechCoroutine, "M1Reset", tChar, tRoot, nil)
                        return
                    end

                    if BotState.m1Count >= 4 then
                        BotState.m1Count = 0
                        BotState.justLanded4thAt = now + 0.14
                        local style = BotCfg.finisherStyle
                        if style == "Pro Mix" then
                            if enemyHasNoEvasive and BotCfg.techLoopOreo and canFrontDash then
                                style = (math.random() < 0.65) and "Mini Uppercut" or "Downslam"
                            elseif BotCfg.useSkills then
                                style = (math.random() < 0.7) and "Downslam" or "Mini Uppercut"
                            else
                                style = (math.random() < 0.5) and "Downslam" or "Mini Uppercut"
                            end
                        end
                        if style == "Mini Uppercut" then
                            task.spawn(runTechCoroutine, "MiniUppercut", tChar, tRoot, nil)
                            return
                        elseif style == "Downslam" then
                            task.spawn(runTechCoroutine, "Downslam", tChar, tRoot, nil)
                            return
                        end
                    end

                    markBotAction("M1")
                    setStatus("FIGHT", whiffPunishReady and "Dash Punish M1!" or ("M1 #" .. tostring(BotState.m1Count)))
                    task.spawn(function() tapBotM1(BotState.runningToken, 0.04) end)
                else
                    setStatus("FIGHT", targetBlocking and "Flanking Block" or "Footsies")
                end
            else
                -- Safe Backdash Cancel only on rare close rush (5s cooldown, never spam!)
                if BotCfg.autoTechs and BotCfg.techBackdashCancel and BotCfg.useSkills and canBackdash and (now - BotState.lastBackdashOpenerAt > 5.0) and dist >= 7.0 and dist <= 9.5 and activeThreat and not targetBlocking then
                    local avail, _, roles = getHotbarSkillState(myChar)
                    local s = pickBestSkillSlot(avail, roles, dist, dy, false, false, tHum.Health, false, myRoot, tRoot)
                    if s and roles[s] == "finisher" then
                        BotState.lastBackdashOpenerAt = now
                        task.spawn(runTechCoroutine, "BackdashCancel", tChar, tRoot, s)
                        return
                    end
                end
                setStatus("CHASE", string.format("%.0f st", dist))
            end
        end))

        -- ======================== UI CARDS (3 BALANCED COLUMNS) ========================
        local masterCtrl
        masterCtrl = secMaster:AddToggle("Enable Combat Bot", false, function(on)
            if Theme.ConfigRegistry and Theme.ConfigRegistry.applying and on then
                task.defer(function()
                    if masterCtrl and masterCtrl.Get and masterCtrl.Get() then pcall(function() masterCtrl.Set(false) end) end
                end)
                return
            end
            BotCfg.enabled = on
            if not on then
                stopBot()
            else
                BotState.runningToken = BotState.runningToken + 1
                setStatus("ACTIVE", "Pro AI Online")
            end
        end, function(api)
            api:AddDropdown("Bot Skill Tier", {
                {name = "Pro Streamer", color = Theme.BloodRed},
                {name = "Aggressive", color = Theme.BloodGlow},
                {name = "Balanced", color = Color3.fromRGB(130, 210, 185)},
            }, 1, function(ch) BotCfg.tier = ch end)
            api:AddToggle("Auto Respawn Resume", BotCfg.autoRespawn, function(v) BotCfg.autoRespawn = v end)
            api:AddToggle("Auto Evasive (Ragdoll)", BotCfg.autoEvasive, function(v) BotCfg.autoEvasive = v end)
            api:AddToggle("Use Pathfinding", BotCfg.usePathfinding, function(v) BotCfg.usePathfinding = v end)
            api:AddToggle("Auto Jump & Whiskers", BotCfg.autoJump, function(v) BotCfg.autoJump = v end)
            api:AddToggle("Auto Awakening (G at Low HP)", BotCfg.autoUlt, function(v) BotCfg.autoUlt = v end)
        end)

        secMaster:AddToggle("Record for Bot", false, function(on)
            BotCfg.recordEnabled = on
            if not on then
                BotMem.save()
                if not BotCfg.enabled then statusGui.Visible = false end
            else
                setStatus("REC", "Watching your gameplay")
            end
        end, function(api)
            api:AddToggle("Use Learned Memory", BotCfg.useLearnedMemory, function(v) BotCfg.useLearnedMemory = v end)
            api:AddSlider("Memory Influence (%)", 0, 100, BotCfg.memoryInfluence, function(v) BotCfg.memoryInfluence = v end)
        end)

        local clearMemCtrl
        clearMemCtrl = secMaster:AddToggle("Clear Bot Memory", false, function(on)
            if not on then return end
            BotMem.clear()
            if Theme.Notify then Theme.Notify("Combat Bot", "Learned memory cleared!") end
            task.defer(function()
                if clearMemCtrl and clearMemCtrl.Get and clearMemCtrl.Get() then clearMemCtrl.Set(false) end
            end)
        end)

        secMaster:AddDropdown("Target Selection", {
            {name = "Smart Pro", color = Theme.BloodRed},
            {name = "Nearest", color = Theme.BloodGlow},
            {name = "Lowest HP", color = Color3.fromRGB(230, 175, 110)},
            {name = "Closest to Crosshair", color = Color3.fromRGB(130, 210, 185)},
            {name = "Face Lock Target", color = Color3.fromRGB(170, 150, 220)},
        }, 1, function(ch) BotCfg.targetMode = ch end)

        secMaster:AddSlider("Max Engage Range", 25, 250, BotCfg.maxRange, function(v)
            BotCfg.maxRange = v
        end)

        secMaster:AddToggle("Ignore Friends", BotCfg.ignoreFriends, function(v)
            BotCfg.ignoreFriends = v
        end)

        secMaster:AddToggle("Target Dummies", BotCfg.targetDummies, function(v)
            BotCfg.targetDummies = v
        end)

        secMaster:AddToggle("Skip Protected / SafeZone", BotCfg.skipProtected, function(v)
            BotCfg.skipProtected = v
        end)

        secMaster:AddToggle("Bot Status HUD", BotCfg.showStatusHud, function(v)
            BotCfg.showStatusHud = v
            if not v then statusGui.Visible = false end
        end)

        local panicCtrl
        panicCtrl = secMaster:AddToggle("Panic Stop Bot", false, function(on)
            if not on then return end
            BotCfg.enabled = false
            stopBot()
            if masterCtrl and masterCtrl.Get and masterCtrl.Get() then pcall(function() masterCtrl.Set(false) end) end
            task.defer(function()
                if panicCtrl and panicCtrl.Get and panicCtrl.Get() then panicCtrl.Set(false) end
            end)
        end)

        -- Card 2: Combat · Block · Movement
        secCombat:AddToggle("Auto Block (F)", BotCfg.autoBlock, function(v)
            BotCfg.autoBlock = v
