            api:AddToggle("Cast Skills (1-4)", BotCfg.useSkills, function(v) BotCfg.useSkills = v end)
            api:AddToggle("3-M1 Before Extender", BotCfg.milk3M1, function(v) BotCfg.milk3M1 = v end)
            api:AddDropdown("4th M1 Finisher", {
                {name = "Pro Mix", color = Theme.BloodRed},
                {name = "Downslam", color = Theme.BloodGlow},
                {name = "Mini Uppercut", color = Color3.fromRGB(230, 175, 110)},
                {name = "Normal", color = Color3.fromRGB(160, 160, 180)},
