            api:AddToggle("Side Dash Anti-Block", BotCfg.antiBlockFlank, function(v) BotCfg.antiBlockFlank = v end)
            api:AddToggle("Track Enemy Evasive CD", BotCfg.trackEnemyEvasive, function(v) BotCfg.trackEnemyEvasive = v end)
        end)

        secCombat:AddToggle("Human Movement & Feints", BotCfg.autoDash, function(v)
            BotCfg.autoDash = v
        end, function(api)
            api:AddSlider("Dash Engage Range", 16, 55, BotCfg.dashEngageRange, function(v) BotCfg.dashEngageRange = v end)
            api:AddToggle("Circle Strafe", BotCfg.circleStrafe, function(v) BotCfg.circleStrafe = v end)
            api:AddSlider("Strafe Bias (%)", 10, 100, math.floor(BotCfg.strafeBias * 100), function(v) BotCfg.strafeBias = v / 100 end)
            api:AddToggle("Jump-Hop Feints", BotCfg.humanFeints, function(v) BotCfg.humanFeints = v end)
            api:AddSlider("Turn Smoothness", 8, 50, BotCfg.smoothTurnSpeed, function(v) BotCfg.smoothTurnSpeed = v end)
        end)

        secCombat:AddToggle("110ms Ping Calibration", BotCfg.autoPing, function(v)
            BotCfg.autoPing = v
        end, function(api)
            api:AddSlider("Base Ping (ms)", 20, 250, BotCfg.basePingMs, function(v) BotCfg.basePingMs = v end)
            api:AddToggle("Ping Velocity Lead", BotCfg.pingLead, function(v) BotCfg.pingLead = v end)
            api:AddSlider("Lead Strength (%)", 0, 110, BotCfg.leadPercent, function(v) BotCfg.leadPercent = v end)
            api:AddSlider("Timing Offset (ms)", -80, 150, BotCfg.globalOffsetMs, function(v) BotCfg.globalOffsetMs = v end)
        end)

        -- Card 3: Bot Autonomous Techs
        secTechs:AddToggle("Enable Auto Techs", BotCfg.autoTechs, function(v)
            BotCfg.autoTechs = v
        end)

        secTechs:AddToggle("Loop & Oreo Dash (Air Catch)", BotCfg.techLoopOreo, function(v)
            BotCfg.techLoopOreo = v
        end)

        secTechs:AddToggle("Supa & Twisted Dash", BotCfg.techSupaTwisted, function(v)
            BotCfg.techSupaTwisted = v
        end)

        secTechs:AddToggle("M1 Reset (Side -> Front)", BotCfg.techM1Reset, function(v)
            BotCfg.techM1Reset = v
        end)

        secTechs:AddToggle("Backdash Cancel (S+Q -> Skill)", BotCfg.techBackdashCancel, function(v)
            BotCfg.techBackdashCancel = v
        end)

        secTechs:AddToggle("Kyoto Auto-Chain (1 -> Dash+2)", BotCfg.techKyoto, function(v)
            BotCfg.techKyoto = v
        end)

        secTechs:AddToggle("180° Skill Flicks (Model Only)", BotCfg.tech180Flicks, function(v)
            BotCfg.tech180Flicks = v
        end)

        track(LocalPlayer.CharacterAdded:Connect(function()
            Input.releaseAll()
            ModelRot.stop()
            BotState.activeTechName = nil
            BotState.techBusyUntil = 0
            BotState.m1Count = 0
            BotState.lastKnownHp = nil
            BotState.waypoints = nil
            if BotCfg.enabled and not BotCfg.autoRespawn then
                BotCfg.enabled = false
                if masterCtrl and masterCtrl.Get and masterCtrl.Get() then pcall(function() masterCtrl.Set(false) end) end
                stopBot()
            end
        end))

        registerCleanup(function()
            BotMem.save()
            BotCfg.enabled = false
            BotCfg.recordEnabled = false
            stopBot()
            pcall(function() statusGui:Destroy() end)
        end)
    end

    local ok, err = pcall(initCombatBot)
    if not ok then warn("[FaceLess] Combat Bot: " .. tostring(err)) end
    if ok and Theme.Runtime and Theme.Runtime.Rebuild then pcall(Theme.Runtime.Rebuild) end
end

-- ================ VISUAL POLISH: аквариум меню + пульс ватермарки ================
-- Самодостаточный модуль. Частицы плавают под стеклом меню между фоном и карточками.
-- Акцентные цвета берутся из Theme.BloodRed/Theme.BloodGlow и автоматически
-- синхронизируются с темами (через Subscribe + пересоздание частиц).
-- Все циклы останавливаются вместе с меню (Unloaded / уничтоженные родители).
do
    local function initVisualPolish()
        -- 2) Пульс жизни ватермарки и мягкое вплывание на своё место при загрузке.
        do
            local dot = Instance.new("Frame")
            dot.Name = "LiveDot"
            dot.AnchorPoint = Vector2.new(0.5, 0.5)
            dot.Position = UDim2.new(0, 39, 0.5, 0)
            dot.Size = UDim2.fromOffset(4, 4)
            dot.BackgroundColor3 = Theme.BloodRed
            dot.BackgroundTransparency = 0.35
            dot.BorderSizePixel = 0
            dot.ZIndex = 103
            dot.Parent = Watermark
            Instance.new("UICorner", dot).CornerRadius = UDim.new(1, 0)
            task.spawn(function()
                while dot.Parent and not Unloaded do
                    TweenService:Create(dot, TweenInfo.new(1.1, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {BackgroundTransparency = 0.78}):Play()
                    task.wait(1.1)
                    if not dot.Parent or Unloaded then break end
                    TweenService:Create(dot, TweenInfo.new(1.1, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {BackgroundTransparency = 0.12}):Play()
                    task.wait(1.1)
                end
            end)
            local baseY = Watermark.Position.Y.Offset
            Watermark.Position = UDim2.new(Watermark.Position.X.Scale, Watermark.Position.X.Offset, Watermark.Position.Y.Scale, baseY - 16)
            UITween(Watermark, {Position = UDim2.new(Watermark.Position.X.Scale, Watermark.Position.X.Offset, Watermark.Position.Y.Scale, baseY)}, 0.7, Enum.EasingStyle.Quint)
        end
    end

    local okPolish, polishErr = pcall(initVisualPolish)
    if not okPolish then warn("[FaceLess] Visual polish: " .. tostring(polishErr)) end
end

-- ===================== ВОЛНЫ ФОНА МЕНЮ =====================
-- Точная копия волн из эталонного экзешника (его canvas-алгоритм):
-- 4 слоя — гребень из трёх синусоид, мягкая заливка-градиент вниз
-- и тонкая светящаяся кромка. Заливка — вертикальные полосы строго
-- встык: альфа по высоте совпадает у соседей, поэтому швов и палочек
-- нет. Всё внутри меню (на Main), в слое GUI.
do
    if Main then
        local WaveLayer = Instance.new("Frame")
        WaveLayer.Name = "WavesLayer"
        WaveLayer.BackgroundTransparency = 1
        WaveLayer.Size = UDim2.new(1, 0, 1, 0)
        WaveLayer.ZIndex = 1
        WaveLayer.ClipsDescendants = true
        WaveLayer.Active = false
        WaveLayer.Parent = Main

        local layerVisible = true
        local W, H = 1920, 1080
        pcall(function()
            W, H = Main.AbsoluteSize.X, Main.AbsoluteSize.Y
            if W < 50 or H < 50 then W, H = 1920, 1080 end
        end)

        local intensity = 0.55
        local k = 0.35 + intensity * 1.15
        local t = 0

        -- параметры слоёв — один в один из эталона
        local layers = {
            { i = 0, baseY = 0.72, amp = 46 * k, len = 0.0042, speed = 0.55, aF = 0.20 * intensity + 0.06 },
            { i = 1, baseY = 0.80, amp = 62 * k, len = 0.0031, speed = 0.42, aF = 0.16 * intensity + 0.05 },
            { i = 2, baseY = 0.90, amp = 34 * k, len = 0.0055, speed = 0.72, aF = 0.22 * intensity + 0.05 },
        }
        local NF, NS = 150, 40            -- полос заливки / сегментов кромки
        local segW = W / NF
        local nLev = 128                  -- уровней таблицы градиентов

        for _, L in ipairs(layers) do
            local yMid = H * L.baseY
            local denom = math.max(1, H - (yMid - L.amp * 2))
            L.yMin, L.yMax = yMid - L.amp * 2.05, yMid + L.amp * 2.05
            -- готовые градиенты: альфа линейна по высоте и одинакова
            -- у всех полос слоя — стыки невидимы
            L.seq = {}
            for lev = 1, nLev do
                local yt = L.yMin + (L.yMax - L.yMin) * (lev - 1) / (nLev - 1)
                local f0 = L.aF * (H - yt) / denom
                if f0 < 0 then f0 = 0 elseif f0 > L.aF then f0 = L.aF end
                local sEnd = (H - yt) / H
                if sEnd < 0.02 then sEnd = 0.02 elseif sEnd > 1 then sEnd = 1 end
                L.seq[lev] = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 1 - f0),
                    NumberSequenceKeypoint.new(sEnd, 1),
                    NumberSequenceKeypoint.new(1, 1),
                })
            end
            -- заливка: полосы строго встык, высота фиксирована
            L.fill = {}
            for j = 1, NF do
                local f = Instance.new("Frame", WaveLayer)
                f.AnchorPoint = Vector2.new(0, 0)
                f.Position = UDim2.fromOffset((j - 1) * segW, 0)
                f.Size = UDim2.fromOffset(segW, H)
                f.BorderSizePixel = 0
                f.BackgroundColor3 = Theme.BloodGlow
                f.ZIndex = 3 + L.i
                local g = Instance.new("UIGradient", f)
                g.Rotation = 90
                g.Transparency = L.seq[1]
                L.fill[j] = { f = f, g = g, lev = 1 }
            end
            -- кромка: тонкие повёрнутые сегменты по гребню
            L.stroke = {}
            for j = 1, NS do
                local s = Instance.new("Frame", WaveLayer)
                s.AnchorPoint = Vector2.new(0.5, 0.5)
                s.BorderSizePixel = 0
                s.BackgroundColor3 = Theme.BloodGlow
                s.BackgroundTransparency = 1 - math.min(1, L.aF * 2.4)
                s.ZIndex = 4 + L.i
                L.stroke[j] = s
            end
        end

        -- гребень слоя: три синусоиды, как в эталоне
        local function yAt(L, x)
            local a = x * L.len + t * L.speed + L.i * 1.7
            local b = x * L.len * 2.3 + t * L.speed * 1.6 + L.i
            local c = x * L.len * 0.6 - t * L.speed * 0.7
            return H * L.baseY + (math.sin(a) + math.sin(b) * 0.42 + math.sin(c) * 0.6) * L.amp
        end

        local acc = 0
        local diagAcc, espDrawAnnounced = 0, false
        track(RunService.Heartbeat:Connect(function(dt)
            if Unloaded or not layerVisible then return end
            if not WaveLayer.Parent then return end
            acc = acc + dt
            if acc < 1 / 30 then return end
            local step = acc
            acc = 0

            t = t + step * 0.96 * (0.6 + intensity)

            for _, L in ipairs(layers) do
                local yRange = L.yMax - L.yMin
                -- заливка
                for j = 1, NF do
                    local x = (j - 0.5) * segW
                    local yt = yAt(L, x) - 3
                    local fd = L.fill[j]
                    fd.f.Position = UDim2.fromOffset((j - 1) * segW, yt)
                    local lev = math.floor((yt - L.yMin) / yRange * (nLev - 1) + 0.5) + 1
                    if lev < 1 then lev = 1 elseif lev > nLev then lev = nLev end
                    if lev ~= fd.lev then
                        fd.lev = lev
                        fd.g.Transparency = L.seq[lev]
                    end
                end
                -- кромка
                local segWS = W / NS
                for j = 1, NS do
                    local x1 = (j - 1) * segWS
                    local x2 = j * segWS
                    local y1, y2 = yAt(L, x1), yAt(L, x2)
                    local dx, dy = x2 - x1, y2 - y1
                    local sd = L.stroke[j]
                    sd.Rotation = math.deg(math.atan2(dy, dx))
                    sd.Size = UDim2.fromOffset(math.sqrt(dx * dx + dy * dy) + 1, 2)
                    sd.Position = UDim2.fromOffset((x1 + x2) / 2, (y1 + y2) / 2)
                end
            end
        end))

        -- детализация меню: угловые скобки по краям стекла
        local cornerAccents = {}
        pcall(function()
            for _, c in ipairs({ { 0, 0 }, { 1, 0 }, { 0, 1 }, { 1, 1 } }) do
                local ax, ay = c[1], c[2]
                local ox = (ax == 1) and -12 or 12
                local oy = (ay == 1) and -12 or 12
                local h = Instance.new("Frame", Main)
                h.AnchorPoint = Vector2.new(ax, ay)
                h.Position = UDim2.new(ax, ox, ay, oy)
                h.Size = UDim2.fromOffset(16, 1.5)
                h.BackgroundColor3 = Theme.BloodGlow
                h.BackgroundTransparency = 0.7
                h.BorderSizePixel = 0
                h.ZIndex = 26
                cornerAccents[#cornerAccents + 1] = h
                local v = Instance.new("Frame", Main)
                v.AnchorPoint = Vector2.new(ax, ay)
                v.Position = UDim2.new(ax, ox, ay, oy)
                v.Size = UDim2.fromOffset(1.5, 16)
                v.BackgroundColor3 = Theme.BloodGlow
                v.BackgroundTransparency = 0.7
                v.BorderSizePixel = 0
                v.ZIndex = 26
                cornerAccents[#cornerAccents + 1] = v
            end
        end)

        track(Theme.Runtime.Subscribe(function()
            if Unloaded then return end
            local bg = Main:FindFirstChild("Bg")
            layerVisible = not (bg and bg.Visible)
            WaveLayer.Visible = layerVisible
            for _, b in ipairs(cornerAccents) do b.BackgroundColor3 = Theme.BloodGlow end
            for _, L in ipairs(layers) do
                for j = 1, NF do L.fill[j].f.BackgroundColor3 = Theme.BloodGlow end
                for j = 1, NS do L.stroke[j].BackgroundColor3 = Theme.BloodGlow end
            end
        end))

        track(Unloaded and Unloaded.Event and Unloaded.Event:Connect(function()
            pcall(function() WaveLayer:Destroy() end)
        end))
    end
end

-- ===================== ПАЗЛ-СБОРКА МЕНЮ =====================
-- При каждом показе меню оно «собирается» из плиток-частиц: разлетаются,
-- сходятся в сетку окна и растворяются, открывая меню. Чистые твины.
do
    local function playPuzzleAssemble()
        if Unloaded or not ScreenGui or not Main then return end
        local s = (uiScale and uiScale.Scale) or 1
        local w, h = 1050 * s, 690 * s
        local overlay = Instance.new("Frame")
        overlay.Name = "PuzzleIntro"
        overlay.AnchorPoint = Vector2.new(0.5, 0.5)
        overlay.Position = UDim2.new(0.5, 0, 0.5, 0)
        overlay.Size = UDim2.fromOffset(w, h)
        overlay.BackgroundTransparency = 1
        overlay.ZIndex = 200
        overlay.Active = false
        overlay.Parent = ScreenGui

        local COLS, ROWS = 8, 5
        local tw, th = w / COLS, h / ROWS
        local rng = Random.new(4242)
        for r = 1, ROWS do
            for c = 1, COLS do
                local tile = Instance.new("Frame")
                tile.AnchorPoint = Vector2.new(0.5, 0.5)
                tile.Size = UDim2.fromOffset(tw - 3, th - 3)
                tile.BackgroundColor3 = ((r + c) % 4 == 0) and Theme.BloodRed or Theme.Element
                tile.BackgroundTransparency = 0.55
                tile.BorderSizePixel = 0
                tile.Rotation = rng:NextNumber(-18, 18)
                tile.ZIndex = 200
                tile.Active = false
                Instance.new("UICorner", tile).CornerRadius = UDim.new(0, 6)
                local st = Instance.new("UIStroke", tile)
                st.Color = Theme.BloodGlow
                st.Transparency = 0.55
                st.Thickness = 1
                tile.Parent = overlay

                local tx, ty = (c - 0.5) * tw, (r - 0.5) * th
                local ang = rng:NextNumber(0, 6.28318)
                local dist = rng:NextNumber(300, 760)
                tile.Position = UDim2.fromOffset(tx + math.cos(ang) * dist, ty + math.sin(ang) * dist)
                local delayIn = (c - 1) * 0.026 + (r - 1) * 0.05 + rng:NextNumber(0, 0.1)
                TweenService:Create(tile, TweenInfo.new(0.55, Enum.EasingStyle.Quint, Enum.EasingDirection.Out, 0, false, delayIn), {
                    Position = UDim2.fromOffset(tx, ty),
                    Rotation = 0,
                    BackgroundTransparency = 0.22,
                }):Play()
                TweenService:Create(tile, TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0, false, delayIn + 0.62), {
                    BackgroundTransparency = 1,
                }):Play()
                TweenService:Create(st, TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0, false, delayIn + 0.62), {
                    Transparency = 1,
                }):Play()
            end
        end
        task.delay(1.7, function() pcall(function() overlay:Destroy() end) end)
    end

    local lastPlay = -10
    local function playGuarded()
        local now = os.clock()
        if now - lastPlay < 1.2 then return end
        lastPlay = now
        playPuzzleAssemble()
    end
    Theme.PuzzleIntro = playGuarded
    if Main and ScreenGui then
        track(Main:GetPropertyChangedSignal("Visible"):Connect(function()
            if Main.Visible and not Unloaded then task.defer(playGuarded) end
        end))
        if Main.Visible then task.defer(playGuarded) end
    end
end

-- ===================== ESP: ПЛАШКА, HP-ЛИНИЯ, СКОБКА =====================
-- Без боксов: стеклянная плашка с именем и дистанцией, горизонтальная
-- hp-линия со свечением и числом, боковая скобка роста, трассировщик снизу.
do
    local function initPlayerESP()
        if not (Drawing and Drawing.new) then
            warn("[FaceLess] ESP: Drawing API недоступна — рисование отключено")
            return
        end
        local ESP = { enabled = false, info = true, health = true, tracers = true, brackets = true }
        Theme.EspState = ESP
        local hot = Color3.fromRGB(255, 255, 255)

        local function newLine(thick, transp)
            local l = Drawing.new("Line")
            l.Thickness = thick
            l.Transparency = transp
            l.Visible = false
            return l
        end
        local function newText(size)
            local t = Drawing.new("Text")
            t.Size = size
            t.Center = true
            t.Outline = true
            t.OutlineColor = Color3.fromRGB(0, 0, 0)
            t.Color = Color3.fromRGB(232, 236, 255)
            t.Visible = false
            return t
        end
        -- Quad может отсутствовать в некоторых экзекуторах — тогда заглушка-таблица
        local function newQuad(filled)
            local ok, q = pcall(function()
                local q = Drawing.new("Quad")
                q.Filled = filled
                q.Thickness = 1
                q.Visible = false
                return q
            end)
            return ok and q or { Visible = false }
        end

        local pool = {}
        local function getObjs(player)
            local o = pool[player]
            if o then return o end
            o = {
                plate = newQuad(true), plateEdge = newQuad(false),
                name = newText(14),
                hpTrack = newLine(3, 0.65), hpGlow = newLine(6, 0.4), hpFill = newLine(3, 1),
                hpText = newText(11),
                brV = newLine(1.6, 0.85), brGlow = newLine(4, 0.25),
                brTop = newLine(1.6, 0.85), brBot = newLine(1.6, 0.85),
                tracerGlow = newLine(2.8, 0.22), tracer = newLine(1.1, 0.7),
            }
            pool[player] = o
            return o
        end
        local function hideObjs(o)
            for _, obj in pairs(o) do obj.Visible = false end
        end
        local function dropPlayer(player)
            local o = pool[player]
            if not o then return end
            for _, obj in pairs(o) do pcall(function() obj:Remove() end) end
            pool[player] = nil
        end
        track(Players.PlayerRemoving:Connect(dropPlayer))

        local function setQuad(q, x1, y1, x2, y2)
            q.PointA = Vector2.new(x1, y1)
            q.PointB = Vector2.new(x2, y1)
            q.PointC = Vector2.new(x2, y2)
            q.PointD = Vector2.new(x1, y2)
        end

        local acc = 0
        track(RunService.RenderStepped:Connect(function(dt)
        local okLoop, loopErr = pcall(function()
            if Unloaded then return end
            if not ESP.enabled then
                for _, o in pairs(pool) do hideObjs(o) end
                return
            end
            acc = acc + dt
            if acc < 1 / 30 then return end
            acc = 0
            local now = os.clock()
            local cam = workspace.CurrentCamera
            if not cam then return end
            local vs = cam.ViewportSize
            local accent = Theme.BloodGlow
            local nTotal, nDrawn = 0, 0
            for _, player in ipairs(Players:GetPlayers()) do
                local char = player.Character
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                local head = char and char:FindFirstChild("Head")
                local root = char and char:FindFirstChild("HumanoidRootPart")
                local valid = (player ~= LocalPlayer) and char and hum and head and root and (hum.Health > 0)
                if not valid then
                    if pool[player] then hideObjs(pool[player]) end
                else
                    local okT, topPos = pcall(function()
                        return cam:WorldToViewportPoint(head.Position + Vector3.new(0, head.Size.Y * 0.62, 0))
                    end)
                    local okB, botPos = pcall(function()
                        return cam:WorldToViewportPoint(root.Position - Vector3.new(0, 3.15, 0))
                    end)
                    if not (okT and okB) or topPos.Z <= 0 or botPos.Z <= 0 then
                        if pool[player] then hideObjs(pool[player]) end
                    else
                        local boxH = botPos.Y - topPos.Y
                        if boxH < 12 or boxH > 900 then
                            if pool[player] then hideObjs(pool[player]) end
                        else
                            local o = getObjs(player)
                            local cx = topPos.X
                            local topY = topPos.Y
                            local bottomY = topY + boxH
                            local dist = (root.Position - cam.CFrame.Position).Magnitude
                            local frac = math.clamp(hum.Health / math.max(1, hum.MaxHealth), 0, 1)
                            local shimmer = 0.82 + 0.16 * math.sin(now * 2.1 + (player.UserId % 37))
                            local hpCol = Color3.fromRGB(255 - 210 * frac, 40 + 190 * frac, 90)

                            -- стеклянная плашка с именем и дистанцией
                            local okD, dispName = pcall(function() return player.DisplayName end)
                            local nameStr = string.format("%s  [%dm]", (okD and dispName) or player.Name, math.floor(dist + 0.5))
                            o.name.Text = nameStr
                            local plateW = math.max(116, o.name.TextBounds.X + 24)
                            local plateX = cx - plateW / 2
                            local plateY = topY - 58
                            setQuad(o.plate, plateX, plateY, plateX + plateW, plateY + 22)
                            o.plate.Color = Color3.fromRGB(12, 12, 18)
                            o.plate.Transparency = 0.18
                            setQuad(o.plateEdge, plateX, plateY, plateX + plateW, plateY + 22)
                            o.plateEdge.Color = accent
                            o.plateEdge.Transparency = 0.42 + 0.12 * math.sin(now * 2 + (player.UserId % 29))
                            o.plateEdge.Thickness = 1.2
                            o.name.Position = Vector2.new(cx, plateY + 4)
                            o.plate.Visible = ESP.info
                            o.plateEdge.Visible = ESP.info
                            o.name.Visible = ESP.info

                            -- hp-линия под плашкой: трек, свечение, заливка и число
                            local hpY = plateY + 31
                            local hpX1, hpX2 = plateX + 10, plateX + plateW - 10
                            o.hpTrack.From = Vector2.new(hpX1, hpY)
                            o.hpTrack.To = Vector2.new(hpX2, hpY)
                            o.hpTrack.Color = Color3.fromRGB(18, 18, 26)
                            o.hpFill.From = Vector2.new(hpX1, hpY)
                            o.hpFill.To = Vector2.new(hpX1 + (hpX2 - hpX1) * frac, hpY)
                            o.hpFill.Color = hpCol
                            o.hpGlow.From = o.hpFill.From
                            o.hpGlow.To = o.hpFill.To
                            o.hpGlow.Color = hpCol
                            o.hpText.Text = string.format("%d", math.floor(hum.Health + 0.5))
                            o.hpText.Position = Vector2.new(hpX2 + 2, hpY - 6)
                            o.hpText.Color = hpCol:Lerp(hot, 0.35)
                            o.hpTrack.Visible = ESP.health
                            o.hpGlow.Visible = ESP.health
                            o.hpFill.Visible = ESP.health
                            o.hpText.Visible = ESP.health

                            -- боковая скобка роста слева от персонажа
                            local bx = cx - boxH * 0.28 - 12
                            o.brGlow.From = Vector2.new(bx, topY)
                            o.brGlow.To = Vector2.new(bx, bottomY)
                            o.brGlow.Color = accent
                            o.brV.From = Vector2.new(bx, topY)
                            o.brV.To = Vector2.new(bx, bottomY)
                            o.brV.Color = accent:Lerp(hot, 0.3)
                            o.brV.Transparency = shimmer
                            o.brTop.From = Vector2.new(bx, topY)
                            o.brTop.To = Vector2.new(bx + 9, topY)
                            o.brBot.From = Vector2.new(bx, bottomY)
                            o.brBot.To = Vector2.new(bx + 9, bottomY)
                            o.brTop.Color = o.brV.Color
                            o.brBot.Color = o.brV.Color
                            o.brTop.Transparency = shimmer
                            o.brBot.Transparency = shimmer
                            o.brGlow.Visible = ESP.brackets
                            o.brV.Visible = ESP.brackets
                            o.brTop.Visible = ESP.brackets
                            o.brBot.Visible = ESP.brackets

                            -- трассировщик от низа экрана к ногам
                            o.tracerGlow.From = Vector2.new(vs.X / 2, vs.Y - 24)
                            o.tracerGlow.To = Vector2.new(cx, bottomY)
                            o.tracerGlow.Color = accent
                            o.tracer.From = o.tracerGlow.From
                            o.tracer.To = o.tracerGlow.To
                            o.tracer.Color = accent:Lerp(hot, 0.3)
                            o.tracerGlow.Visible = ESP.tracers
                            o.tracer.Visible = ESP.tracers
                            nDrawn = nDrawn + 1
                        end
                    end
                end
            end
            diagAcc = diagAcc + dt
            if diagAcc >= 4 then
                diagAcc = 0
                FLLog.info("esp", string.format("целей %d | на экране %d", nTotal, nDrawn))
                if nDrawn > 0 and not espDrawAnnounced then
                    espDrawAnnounced = true
                    FLLog.announce("[FaceLess] ESP: рисование работает, объектов на экране: " .. nDrawn)
                end
            end
        end)
        if not okLoop then FLLog.push("error", "esp-loop", tostring(loopErr), "рендер ESP") end
        end))

        -- ---------------- управление в карточке Chams ----------------
        local secEsp
        pcall(function()
            secEsp = createSection(espTab and (espTab.Right or espTab.Left), "ESP Style")
        end)
        if not secEsp then secEsp = secChamsSettings end
        secEsp:AddToggle("Enable ESP", false, function(state)
            ESP.enabled = state == true
            if ESP.enabled then
                local drawingOk = (Drawing and Drawing.new) and true or false
                local n = 0
                for _, p2 in ipairs(Players:GetPlayers()) do
                    if p2 ~= LocalPlayer and p2.Character and p2.Character:FindFirstChildOfClass("Humanoid") then n = n + 1 end
                end
                FLLog.announce("[FaceLess] ESP включён | Drawing=" .. tostring(drawingOk) .. " | целей на сервере: " .. n)
                if not drawingOk then
                    FLLog.push("warn", "esp", "Drawing API недоступна — рисование невозможно", "инжектор не даёт Drawing.new")
                end
            end
        end)
        secEsp:AddToggle("Name Plate", true, function(state) ESP.info = state == true end)
        secEsp:AddToggle("Health Line", true, function(state) ESP.health = state == true end)
        secEsp:AddToggle("Side Bracket", true, function(state) ESP.brackets = state == true end)
        secEsp:AddToggle("Tracers", true, function(state) ESP.tracers = state == true end)
    end
    local okE, errE = pcall(initPlayerESP)
    if not okE then warn("[FaceLess] ESP: " .. tostring(errE)) end
end

-- Принудительный пересчёт сетки карточек: подёргивание размера контента
-- заставляет updateTabColumnLayout КАЖДОЙ вкладки — все карточки встают ровно.
pcall(function()
    local function gridFix()
        if not Nav.content then return end
        local s = Nav.content.Size
        Nav.content.Size = UDim2.new(s.X.Scale, s.X.Offset, s.Y.Scale, s.Y.Offset - 1)
        task.defer(function()
            if Nav.content then Nav.content.Size = s end
        end)
    end
    gridFix()
    task.delay(0.8, gridFix)
    task.delay(2.5, gridFix)
end)

-- ===================== метка сборки
pcall(function()
    local ver = "FaceLess | glass edition / cloud configs / potato graphics v2 / build 28"
    if type(getgenv) == "function" then pcall(function() getgenv().SatanicHubBuild = ver end) end
    FLLog.announce("[FaceLess] build " .. ver .. " — загрузка завершена")
end)
